/**
 * Ancho "natural" de una columna del PDF de pagos: el máximo entre su
 * encabezado y su contenido real, en puntos. Piso de 28pt para no llegar a
 * columnas absurdas con contenido muy corto (un código de 2 letras), techo
 * de 148pt para que un proveedor con nombre kilométrico no acapare media
 * página.
 */
function anchoNaturalColumnaPDF(columna, filas) {
  const largos = filas.map((f) => String(columna.get(f) ?? "").length);
  const max = Math.max(columna.label.length, ...(largos.length ? largos : [0]));
  // A 8 pt, cada carácter mide ~4.4 pt; más 8 pt de relleno por celda.
  return Math.min(Math.max(max * 4.4 + 8, 28), 148);
}

/**
 * Reparte el ancho disponible entre columnas según su contenido real.
 *
 * Antes se reservaba un mínimo fijo para Proveedor y Concepto, a costa de
 * lo que quedara para las demás — funcionaba para esas dos, pero cuando
 * había muchas columnas encendidas a la vez, la que perdía la apuesta
 * simplemente cambiaba (Solicitante, o hasta el propio encabezado de
 * "Forma de Pago"). Repartiendo PROPORCIONALMENTE, si la suma natural no
 * cabe en la página, TODAS ceden un poco por igual — nadie se queda con
 * el mínimo garantizado mientras otra se parte letra por letra.
 */
function anchosProporcionalesPDF(columnas, filas, disponible) {
  const natural = columnas.map((c) => anchoNaturalColumnaPDF(c, filas));
  const total = natural.reduce((s, w) => s + w, 0);
  const factor = total > disponible ? disponible / total : 1;
  return natural.map((w) => Math.round(w * factor));
}

function ReportePagosTab({ unidad, partidas, transacciones, transaccionesApi, proveedoresApi, cuentasApi, gruposZona = {} }) {
  const partidasUnidad = partidas.filter((p) => p.unidad === unidad);
  const proveedoresUnidad = proveedoresApi.rows.filter((p) => p.unidad === unidad);
  const transUnidad = transacciones.filter(
    (t) => partidasUnidad.some((p) => p.id === t.partida_id) || t.unidad_detectada === unidad
  );

  const filas = transUnidad.map((t) => {
    const partida = partidasUnidad.find((p) => p.id === t.partida_id);
    const proveedor = t.proveedor_id ? proveedoresUnidad.find((p) => p.id === t.proveedor_id) : null;
    const cuenta = t.cuenta_id ? cuentasApi.rows.find((c) => c.id === t.cuenta_id) : null;
    return {
      id: t.id,
      dia: t.dia || "",
      solicitante: t.solicitante || "",
      area: t.area || "",
      zona: t.zona || "",
      numero_solicitud: t.smi || partida?.smi || "",
      no_sae: proveedor?.id_sae || "",
      folio_compra_sae: t.folio_compra_sae || "",
      folio_factura: t.folio_factura || "",
      forma_pago: t.forma_pago || "",
      forma_pago_label: FORMAS_PAGO.find((f) => f.value === t.forma_pago)?.label || t.forma_pago || "",
      metodo_pago: t.metodo_pago || "",
      metodo_pago_label: METODOS_PAGO.find((m) => m.value === t.metodo_pago)?.label || t.metodo_pago || "",
      proveedor: proveedor?.nombre || t.proveedor || "",
      referencia_pago: t.referencia_pago || "",
      notas: proveedor?.notas || "",
      concepto: t.concepto_detallado || "",
      banco: cuenta?.banco || "",
      clabe: cuenta?.clabe || "",
      numero_cuenta: cuenta?.numero_cuenta || "",
      swift: cuenta?.swift || "",
      importe: Number(t.importe) || 0,
      moneda: t.moneda || "MXP",
      _vinculadoProveedor: !!proveedor,
      _vinculadoCuenta: !!cuenta,
    };
  });

  const [buscar, setBuscar] = useSessionState("ss-reporte-buscar", "");
  const [fechaDesde, setFechaDesde] = useSessionState("ss-reporte-desde", "");
  const [fechaHasta, setFechaHasta] = useSessionState("ss-reporte-hasta", "");
  const [panelExportRP, setPanelExportRP] = useState(false);
  const [sort, setSort] = usePrefState("pref-reporte-sort", { key: "dia", dir: "desc" }, sanearSort(["dia","solicitante","area","numero_solicitud","no_sae","folio_compra_sae","folio_factura","forma_pago","metodo_pago","proveedor","referencia_pago","concepto","banco","clabe","numero_cuenta","swift","importe","moneda","notas"]));
  const filasFiltradas = filas.filter((f) => {
    if (fechaDesde && (!f.dia || f.dia < fechaDesde)) return false;
    if (fechaHasta && (!f.dia || f.dia > fechaHasta)) return false;
    if (!buscar.trim()) return true;
    const q = buscar.trim().toLowerCase();
    return [f.solicitante, f.proveedor, f.concepto, f.folio_factura, f.folio_compra_sae, f.no_sae, f.referencia_pago]
      .some((v) => (v || "").toString().toLowerCase().includes(q));
  });
  const filtrosFechaActivos = fechaDesde || fechaHasta;
  const limpiarFechas = () => { setFechaDesde(""); setFechaHasta(""); };
  const filasOrdenadas = sortRows(filasFiltradas, sort, { importe: (r) => r.importe });

  /* Compartido entre el PDF y el Excel: antes cada uno lo calculaba por su
     cuenta (y el PDF ni siquiera tenía el resumen). Con una sola versión,
     el resumen del PDF y el del Excel están obligados a decir lo mismo. */
  /* Se agrupa por GRUPO de zona, no por la zona suelta: es como Dirección
     conoce el reporte. Mismo helper que ya usa el semanal oficial, para que
     los dos documentos partan igual y no haya dos criterios conviviendo.
     Una zona sin grupo asignado conserva su propio nombre, y las filas sin
     zona caen en "Sin zona" — antes se quedaban FUERA del detalle, porque el
     recorrido solo pasaba por zonas no vacías, y el total general sí las
     contaba: el documento no cuadraba consigo mismo. */
  const bloques = bloquesZonaMoneda(filasOrdenadas, gruposZona);
  const totGeneralRP = {};
  filasOrdenadas.forEach((f) => {
    const m = (f.moneda || "MXP") === "USD" ? "USD" : "MXP";
    totGeneralRP[m] = (totGeneralRP[m] || 0) + (Number(f.importe) || 0);
  });

  const colVisibility = useColumnVisibility("colv-reporte", COLUMNAS_REPORTE);
  const pdfVis = useVisibilidadColumnas("colv-reporte-pdf", COLUMNAS_PDF, PDF_OCULTAS_INICIAL);
  const columnasPDF = pdfVis.visibles;
  const excelVis = useVisibilidadColumnas("colv-reporte-excel", COLUMNAS_EXCEL);
  const columnasExcel = excelVis.visibles;
  const [previewPDF, setPreviewPDF] = useState(null);
  const colWidths = useColumnWidths("colw-reporte");
  const { ordered: columnas, moveColumn } = useColumnOrder("colo-reporte", colVisibility.visible);
  const dragKeyRef = useRef(null);
  const onColDragStart = (e, key) => { dragKeyRef.current = key; e.dataTransfer.effectAllowed = "move"; };
  const onColDragOver = (e) => e.preventDefault();
  const onColDrop = (e, targetKey) => { e.preventDefault(); if (dragKeyRef.current) { moveColumn(dragKeyRef.current, targetKey); dragKeyRef.current = null; } };

  const exportarExcel = async () => {
    // Resumen en vez de vista previa: renderizar una tabla que IMITE la hoja
    // sería una segunda implementación del layout, y en cuanto se desincronice
    // el preview estaría mintiendo. Esto responde la misma pregunta —¿va lo
    // que necesito?— con datos del archivo real.
    const ocultas = COLUMNAS_EXCEL.filter((c) => excelVis.hidden.has(c.key));
    const muestra = filasOrdenadas.slice(0, 3)
      .map((f, i) => `  ${i + 1}. ` + columnasExcel.slice(0, 5).map((c) => String(c.get(f) ?? "—")).join(" · "))
      .join("\n");
    const okExcel = confirm(
      `Se va a descargar un Excel con:\n\n` +
      `  ${filasOrdenadas.length} transacción(es)\n` +
      `  ${columnasExcel.length} de ${COLUMNAS_EXCEL.length} columnas\n` +
      (ocultas.length ? `  Fuera: ${ocultas.map((c) => c.header).join(", ")}\n` : "") +
      `\nPrimeras filas (5 columnas):\n${muestra}\n\n¿Descargar?`
    );
    if (!okExcel) return;

    const wbx = new ExcelJS.Workbook();
    const ws = wbx.addWorksheet("Reporte de pagos");
    ws.columns = columnasExcel.map((c) => ({ width: c.width }));

    const diasOrdenados = filasOrdenadas.map((f) => f.dia).filter(Boolean).sort();
    const inicio = fechaDesde || diasOrdenados[0] || "";
    const fin = fechaHasta || diasOrdenados[diasOrdenados.length - 1] || "";

    /* Mismo gris que ya usan los subtotales de cada bloque de zona más abajo
       en este mismo reporte (FFECEEF1), en vez de un tono aparte: el primer
       intento era tan tenue que casi no se distinguía del blanco.
       Y cada renglón se FUSIONA a lo ancho de la tabla — sin merge, el texto
       largo solo "flota" sobre la columna A sin verse contenido en nada. */
    const GRIS_RESUMEN_RP = "FFECEEF1";
    const anchoResumen = Math.max(columnasExcel.length, 4);

    let fila = 1;
    {
      const filaTitulo = fila;
      const tCell = ws.getCell(`A${fila}`);
      tCell.value = "RESUMEN — LO QUE SE VA A PAGAR";
      tCell.font = { bold: true, size: 11, name: "Calibri", color: { argb: "FF232A31" } };
      ws.getRow(fila).height = 20;
      fila += 1;

      bloques.forEach((b) => {
        const rCell = ws.getCell(`A${fila}`);
        rCell.value = `${b.grupo}   ·   ${b.moneda}   ·   ${b.filas.length} pago(s)   ·   $${numMx(b.total)}`;
        rCell.font = { name: "Calibri", size: 10.5 };
        ws.getRow(fila).height = 20;
        fila += 1;
      });

      const totCell = ws.getCell(`A${fila}`);
      totCell.value = Object.entries(totGeneralRP).map(([m, v]) => `TOTAL ${m}: $${numMx(v)}`).join("      ");
      totCell.font = { bold: true, size: 11.5, name: "Calibri" };
      ws.getRow(fila).height = 20;
      const filaTotal = fila;
      fila += 1;

      // Fusionar cada renglón a lo ancho, y aplicar el fondo sobre la celda
      // resultante (ExcelJS conserva el estilo de la celda superior-izquierda
      // al fusionar, así que basta con pintarla a ella).
      for (let r = filaTitulo; r <= filaTotal; r++) {
        ws.mergeCells(r, 1, r, anchoResumen);
        ws.getCell(`A${r}`).fill = { type: "pattern", pattern: "solid", fgColor: { argb: GRIS_RESUMEN_RP } };
      }

      fila += 2; // dos renglones en blanco antes del primer bloque de detalle
    }

    bloques.forEach((bq) => {
      {
        const { grupo, moneda, filas: filasGrupo } = bq;

        const tituloCell = ws.getCell(`B${fila}`);
        tituloCell.value = `Solicitud de Pagos del dia ${inicio} al dia ${fin} Compañía ${unidad} - ${moneda}`;
        tituloCell.font = { bold: true, size: 14, name: "Calibri" };
        fila += 1;

        const zonaCell = ws.getCell(`D${fila}`);
        zonaCell.value = grupo;
        zonaCell.font = { bold: true, size: 12, name: "Calibri" };
        fila += 2; // una fila en blanco, como en la plantilla

        const headerRow = ws.getRow(fila);
        columnasExcel.forEach((c, i) => {
          const cell = headerRow.getCell(i + 1);
          cell.value = c.header;
          cell.alignment = { horizontal: "center", vertical: "center", wrapText: true };
          cell.font = { name: "Calibri", size: 11, bold: true, color: { argb: "FFFFFFFF" } };
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF3E5C76" } };
        });
        headerRow.height = 22;
        fila += 1;

        filasGrupo.forEach((f) => {
          const row = ws.getRow(fila);
          columnasExcel.forEach((c, ci) => {
            const cell = row.getCell(ci + 1);
            cell.value = c.get(f);
            // Las cifras a la derecha, los textos largos a la izquierda con
            // ajuste: centrarlo todo obliga a leer cada celda para comparar.
            cell.alignment = {
              horizontal: c.money ? "right" : (["proveedor", "concepto", "notas"].includes(c.key) ? "left" : "center"),
              vertical: "top",
              wrapText: ["proveedor", "concepto", "notas"].includes(c.key),
            };
            cell.font = { name: "Calibri", size: 11 };
            if (c.money) cell.numFmt = '"$"#,##0.00';
          });
          fila += 1;
        });

        // Subtotal del bloque: cada zona y moneda cierra con su suma, que es
        // lo que Pagos necesita para cuadrar contra el banco.
        const idxImporte = columnasExcel.findIndex((c) => c.money);
        if (idxImporte !== -1) {
          const totRow = ws.getRow(fila);
          const etq = totRow.getCell(Math.max(idxImporte, 1));
          etq.value = `Total ${grupo} ${moneda}`;
          etq.font = { name: "Calibri", size: 11, bold: true };
          etq.alignment = { horizontal: "right" };
          const val = totRow.getCell(idxImporte + 1);
          val.value = filasGrupo.reduce((sum, f) => sum + (Number(f.importe) || 0), 0);
          val.numFmt = '"$"#,##0.00';
          val.font = { name: "Calibri", size: 11, bold: true };
          val.alignment = { horizontal: "right" };
          for (let i = 1; i <= columnasExcel.length; i++) {
            totRow.getCell(i).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFECEEF1" } };
          }
          fila += 1;
        }

        fila += 2; // espacio antes de la siguiente sección
      }
    });

    const buffer = await wbx.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Reporte de Pagos - ${unidad} - ${(!inicio ? "Sin periodo" : (inicio === fin ? inicio : `${inicio} a ${fin}`))}.xlsx`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const [generandoReporte, setGenerandoReporte] = useState(false);
  /**
   * Estima si la tabla cabe a lo ancho de la hoja. Ahora es solo la suma de
   * los anchos naturales — el mismo cálculo que reparte anchosProporcionalesPDF
   * al construir el documento, así que la advertencia y lo que realmente se
   * dibuja nunca pueden decir cosas distintas.
   */
  const anchoEstimadoPDF = () => {
    const disponible = 712; // carta horizontal son 792 pt; quedan ~712 descontando márgenes
    const usado = columnasPDF.reduce((suma, c) => suma + anchoNaturalColumnaPDF(c, filasOrdenadas), 0);
    return { usado: Math.round(usado), disponible, cabe: usado <= disponible };
  };

  /**
   * Construye el documento y lo devuelve SIN guardarlo. La vista previa y el
   * archivo final salen los dos de aquí: con dos generadores distintos, el
   * preview acabaría mostrando algo que no es lo que se descarga.
   */
  const construirPDF = () => {
      const diasOrdenados = filasOrdenadas.map((f) => f.dia).filter(Boolean).sort();
      const inicio = fechaDesde || diasOrdenados[0] || "";
      const fin = fechaHasta || diasOrdenados[diasOrdenados.length - 1] || "";

      const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "letter" });
      const alturaPagina = doc.internal.pageSize.getHeight();
      const margenInferior = 40;
      let cursorY = 30; // dónde va el próximo título — solo salta de página si de verdad no cabe

      /* Resumen ejecutivo, igual que el Excel y que el reporte semanal a
         Dirección: cuánto se va a pagar por zona y moneda, antes de entrar
         al detalle bloque por bloque. Usa los MISMOS bloques que ya
         calcula el Excel — un solo cálculo, no dos que puedan desalinearse. */
      if (bloques.length) {
        const altoResumen = 24 + bloques.length * 13 + 6;
        doc.setFillColor(236, 238, 241);
        doc.rect(30, cursorY, 732, altoResumen, "F");
        doc.setFontSize(9).setTextColor(107, 119, 133);
        doc.text("RESUMEN — LO QUE SE VA A PAGAR", 40, cursorY + 14);
        doc.setFontSize(9).setTextColor(35, 42, 49);
        let yb = cursorY + 28;
        bloques.forEach((b) => {
          doc.text(`${b.grupo}   ${b.moneda}`, 44, yb);
          doc.text(`${b.filas.length} pago(s)`, 300, yb);
          doc.setFont(undefined, "bold");
          doc.text(`$${numMx(b.total)}`, 420, yb, { align: "right" });
          doc.setFont(undefined, "normal");
          yb += 13;
        });
        doc.setFont(undefined, "bold").setFontSize(10);
        doc.text(
          Object.entries(totGeneralRP).map(([m, v]) => `TOTAL ${m}: $${numMx(v)}`).join("      "),
          762, cursorY + 14, { align: "right" }
        );
        doc.setFont(undefined, "normal");
        cursorY += altoResumen + 14;
      }

      // Se calcula UNA sola vez, con todas las filas del reporte — no por
      // bloque — para que las tablas de todas las zonas compartan el mismo
      // ancho de columna en vez de verse distintas entre sí.
      const anchosCols = anchosProporcionalesPDF(columnasPDF, filasOrdenadas, 712);

      bloques.forEach((bq) => {
        {
          const { grupo, moneda, filas: filasGrupo } = bq;

          // Espacio mínimo para el título + al menos una fila de la tabla —
          // si no cabe en lo que resta de la página, ahí sí se salta.
          const alturaMinima = 58 + 24 + 20;
          if (cursorY > 30 && cursorY + alturaMinima > alturaPagina - margenInferior) {
            doc.addPage();
            cursorY = 30;
          } else if (cursorY > 30) {
            cursorY += 26; // espacio entre un bloque y el siguiente en la misma página
          }

          doc.setFontSize(13);
          doc.setTextColor(0);
          doc.text(`Solicitud de Pagos del dia ${inicio} al dia ${fin} Compañía ${unidad} - ${moneda}`, 30, cursorY);
          doc.setFontSize(10);
          doc.setTextColor(120);
          doc.text(grupo, 30, cursorY + 16);

          autoTable(doc, {
            startY: cursorY + 28,
            head: [columnasPDF.map((c) => c.label)],
            body: filasGrupo.map((f) => columnasPDF.map((c) => c.get(f))),
            styles: { fontSize: 8, cellPadding: 4 },
            headStyles: { fillColor: [62, 92, 118], textColor: 255, halign: "center" },
            bodyStyles: { halign: "center" },
            // Los textos largos se alinean a la izquierda; lo demás centrado.
            // El ancho de cada columna viene de anchosCols — repartido
            // proporcionalmente según el contenido real de TODO el reporte,
            // no un mínimo fijo para un par de columnas a costa del resto.
            columnStyles: Object.fromEntries(
              columnasPDF.map((c, i) => [i, {
                halign: c.ancho === "left" ? "left" : "center",
                cellWidth: anchosCols[i],
              }])
            ),
            margin: { bottom: margenInferior },
          });

          cursorY = doc.lastAutoTable.finalY;
        }
      });

      return doc;
  };

  /**
   * Muestra el PDF real en un visor, sin guardarlo y —lo importante— sin
   * marcar nada como enviado a Pagos. Es para revisar antes de comprometerse.
   */
  const vistaPreviaPDF = () => {
    if (!filasOrdenadas.length) {
      alert("No hay transacciones en el filtro actual para previsualizar.");
      return;
    }
    try {
      const doc = construirPDF();
      const url = URL.createObjectURL(doc.output("blob"));
      setPreviewPDF({ url, paginas: doc.internal.getNumberOfPages(), ancho: anchoEstimadoPDF() });
    } catch (err) {
      alert("No se pudo generar la vista previa: " + (err.message || err));
    }
  };

  const cerrarPreviewPDF = () => {
    if (previewPDF) URL.revokeObjectURL(previewPDF.url);
    setPreviewPDF(null);
  };

  const generarReportePDF = async () => {
    if (!filasOrdenadas.length) {
      alert("No hay transacciones en el filtro actual para generar el reporte.");
      return;
    }
    const ancho = anchoEstimadoPDF();
    const aviso = ancho.cabe ? "" :
      `\n\nOJO: con ${columnasPDF.length} columnas la tabla se pasa del ancho de la hoja ` +
      `(~${ancho.usado} pt contra ${ancho.disponible} disponibles). Las columnas se van a apretar ` +
      `y el texto se va a partir. Considera quitar algunas en "Columnas del PDF".`;
    const confirmado = confirm(
      `Esto va a generar un PDF con las ${filasOrdenadas.length} transacción(es) que tienes filtradas ahora, y las va a marcar como "Enviadas a Pagos". ¿Continuar?${aviso}`
    );
    if (!confirmado) return;

    setGenerandoReporte(true);
    try {
      const doc = construirPDF();
      doc.save(`reporte-pagos-${unidad}-${new Date().toISOString().slice(0, 10)}.pdf`);
      cerrarPreviewPDF();

      for (const f of filasOrdenadas) {
        await transaccionesApi.update(f.id, { enviado_pagos_at: new Date().toISOString() });
      }
    } catch (err) {
      alert("No se pudo generar el reporte: " + (err.message || err));
    } finally {
      setGenerandoReporte(false);
    }
  };
  const totalMXN = filasOrdenadas.filter((f) => f.moneda === "MXP").reduce((s, f) => s + f.importe, 0);
  const totalUSD = filasOrdenadas.filter((f) => f.moneda === "USD").reduce((s, f) => s + f.importe, 0);
  const sinProveedorVinculado = filas.filter((f) => !f._vinculadoProveedor && f.proveedor).length;
  const sinCuentaVinculada = filas.filter((f) => f._vinculadoProveedor && !f._vinculadoCuenta).length;

  if (!transUnidad.length) {
    return (
      <EmptyState
        title="Sin transacciones para reportar"
        body={`Todavía no hay transacciones registradas para ${unidad}. Captúralas o impórtalas desde la pestaña Transacciones.`}
      />
    );
  }

  const hayAvisos = sinProveedorVinculado > 0 || sinCuentaVinculada > 0;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20, paddingBottom: hayAvisos ? 70 : 0 }}>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <KpiCard label="Transacciones" value={String(filasOrdenadas.length)} />
        <KpiCard label="Total MXP (filtrado)" value={money(totalMXN, "MXP")} />
        <KpiCard label="Total USD (filtrado)" value={money(totalUSD, "USD")} />
      </div>

      <AvisosFlotantes
        avisos={[
          {
            tone: "amber",
            texto: sinProveedorVinculado > 0
              ? `${sinProveedorVinculado} transacción(es) tienen proveedor en texto pero no están ligadas al Catálogo de proveedores — No. SAE, Banco y CLABE saldrán vacíos para esas filas hasta que se vinculen (edítalas en Transacciones y elige el proveedor del catálogo).`
              : "",
          },
          {
            tone: "amber",
            texto: sinCuentaVinculada > 0
              ? `${sinCuentaVinculada} transacción(es) tienen proveedor vinculado pero no una cuenta bancaria específica — Banco y CLABE saldrán vacíos hasta que elijas la cuenta (edítalas en Transacciones).`
              : "",
          },
        ]}
      />

      <Panel
        title={`Reporte de pagos — ${unidad}`}
        subtitle={`${filasOrdenadas.length} de ${filas.length} transacciones`}
        right={
          /* Tres botones decían "Columnas" y no había forma de saber cuál
             gobernaba qué. Cada selector se va junto a la salida que controla. */
          <div style={{ display: "flex", gap: 8 }}>
            <ColumnVisibilityControl
              columns={COLUMNAS_REPORTE}
              hidden={colVisibility.hidden}
              onToggle={colVisibility.toggle}
              onShowAll={colVisibility.showAll}
            />
            <Button variant={panelExportRP ? "primary" : "ghost"} onClick={() => setPanelExportRP(!panelExportRP)}>
              Exportar y reportes {panelExportRP ? "▲" : "▼"}
            </Button>
          </div>
        }
      >
        <div style={{ marginBottom: 14, display: "flex", gap: 10, flexWrap: "wrap", alignItems: "flex-end" }}>
          <Field label="Buscar">
            <TextInput
              value={buscar}
              onChange={(e) => setBuscar(e.target.value)}
              placeholder="Solicitante, proveedor, concepto, folio…"
              style={{ width: 280 }}
            />
          </Field>
          <Field label="Desde">
            <TextInput type="date" value={fechaDesde} onChange={(e) => setFechaDesde(e.target.value)} />
          </Field>
          <Field label="Hasta">
            <TextInput type="date" value={fechaHasta} onChange={(e) => setFechaHasta(e.target.value)} />
          </Field>
          {filtrosFechaActivos && <Button variant="ghost" onClick={limpiarFechas}>Limpiar fechas</Button>}
        </div>

        {panelExportRP && (
          <div style={{ background: T.panelAlt, border: `1px solid ${T.borderSoft}`, borderRadius: 8,
                        padding: 14, marginBottom: 16 }}>
            <div style={{ fontSize: 11.5, color: T.textFaint, marginBottom: 12 }}>
              Las salidas respetan los filtros de arriba — {filasOrdenadas.length} de {filas.length} transacciones.
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 12 }}>

              <div style={{ background: T.panel, border: `1px solid ${T.borderSoft}`, borderRadius: 8, padding: 13,
                            display: "flex", flexDirection: "column" }}>
                <div style={{ fontSize: 12.5, fontWeight: 700 }}>Reporte de Pagos (PDF)</div>
                <div style={{ fontSize: 11, color: T.textDim, marginTop: 3, minHeight: 46 }}>
                  El documento que va al área de Pagos, en bloques por zona y moneda.
                  Marca las transacciones como enviadas.
                </div>
                <div style={{ marginBottom: 10 }}>
                  <ColumnVisibilityControl
                    columns={COLUMNAS_PDF}
                    hidden={pdfVis.hidden} onToggle={pdfVis.toggle} onShowAll={pdfVis.showAll}
                    etiqueta="Columnas"
                  />
                </div>
                <div style={{ flex: 1 }} />
                <div style={{ display: "flex", gap: 6 }}>
                  {/* La vista previa NO marca nada como enviado: existe para
                      revisar antes de un paso que no se puede deshacer. */}
                  <Button variant="ghost" onClick={vistaPreviaPDF} disabled={generandoReporte} style={{ flex: 1 }}>
                    Vista previa
                  </Button>
                  <Button onClick={generarReportePDF} disabled={generandoReporte} style={{ flex: 1 }}>
                    {generandoReporte ? "Generando…" : "Generar"}
                  </Button>
                </div>
              </div>

              <div style={{ background: T.panel, border: `1px solid ${T.borderSoft}`, borderRadius: 8, padding: 13,
                            display: "flex", flexDirection: "column" }}>
                <div style={{ fontSize: 12.5, fontWeight: 700 }}>Exportar a Excel</div>
                <div style={{ fontSize: 11, color: T.textDim, marginTop: 3, minHeight: 46 }}>
                  Las mismas transacciones en hoja de cálculo, con subtotal por zona y moneda.
                  No marca nada como enviado.
                </div>
                <div style={{ marginBottom: 10 }}>
                  <ColumnVisibilityControl
                    columns={COLUMNAS_EXCEL}
                    hidden={excelVis.hidden} onToggle={excelVis.toggle} onShowAll={excelVis.showAll}
                    etiqueta="Columnas"
                  />
                </div>
                <div style={{ flex: 1 }} />
                <Button onClick={exportarExcel} style={{ width: "100%" }}>Generar Excel</Button>
              </div>
            </div>
          </div>
        )}

        <div style={{ overflowX: "auto" }}>
          <table style={{ ...tableStyle, tableLayout: "fixed" }}>
            <colgroup>
              {columnas.map((c) => <col key={c.key} style={{ width: colWidths.getWidth(c.key) }} />)}
            </colgroup>
            <thead>
              <tr>
                {columnas.map((c) => (
                  <SortableTh
                    key={c.key} label={c.label} sortKey={c.key} sort={sort} setSort={setSort}
                    width={colWidths.getWidth(c.key)} onResizeStart={(e) => colWidths.startResize(c.key, e)}
                    onDragStart={(e) => onColDragStart(e, c.key)} onDragOver={onColDragOver} onDrop={(e) => onColDrop(e, c.key)}
                    sumLabel={c.key === "importe" ? sumaPorMoneda(filasOrdenadas, "importe") : undefined}
                  />
                ))}
              </tr>
            </thead>
            <tbody>
              {filasOrdenadas.map((f) => (
                <tr key={f.id}>
                  {columnas.map((c) => (
                    <td
                      key={c.key}
                      style={c.key === "importe" ? { ...tdStyle, fontFamily: T.fontMono } : tdStyle}
                      title={c.key === "forma_pago" ? f.forma_pago_label : c.key === "metodo_pago" ? f.metodo_pago_label : undefined}
                    >
                      {c.key === "importe" ? money(f.importe, f.moneda) : (f[c.key] || "—")}
                    </td>
                  ))}
                </tr>
              ))}
              {!filasOrdenadas.length && (
                <tr><td colSpan={columnas.length} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>Ninguna transacción coincide con la búsqueda</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </Panel>
      {previewPDF && (
        <Modal onClose={cerrarPreviewPDF} width={1100}>
          <div style={{ display: "flex", flexDirection: "column", gap: 10, height: "80vh" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
              <div>
                <div style={{ fontSize: 14, fontWeight: 700 }}>Vista previa del reporte</div>
                <div style={{ fontSize: 11.5, color: T.textFaint }}>
                  {filasOrdenadas.length} transacción(es) · {columnasPDF.length} columnas · {previewPDF.paginas} página(s)
                  {" · "}Nada se ha marcado como enviado a Pagos todavía
                </div>
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <Button variant="ghost" onClick={cerrarPreviewPDF}>Cerrar</Button>
                <Button onClick={() => { cerrarPreviewPDF(); generarReportePDF(); }}>
                  Generar y marcar como enviado
                </Button>
              </div>
            </div>
            {!previewPDF.ancho.cabe && (
              <div style={{ borderLeft: `3px solid ${T.amber}`, background: "#FDF8EF", padding: "8px 12px", borderRadius: "0 6px 6px 0", fontSize: 12 }}>
                <b>La tabla se pasa del ancho de la hoja</b> (~{previewPDF.ancho.usado} pt contra {previewPDF.ancho.disponible} disponibles).
                Las columnas se aprietan y el texto se parte. Quita algunas en "Columnas del PDF".
              </div>
            )}
            <iframe
              title="Vista previa del reporte"
              src={previewPDF.url}
              style={{ flex: 1, width: "100%", border: `1px solid ${T.border}`, borderRadius: 6 }}
            />
          </div>
        </Modal>
      )}
    </div>
  );
}

/* ----------------------------------------------------------------------
   TAB: REPORTE DE PAGOS DIRECCIÓN
---------------------------------------------------------------------- */
// Cada columna lleva su forma de imprimirse en el PDF (`pdf`) junto a la
// etiqueta, para que el documento salga de la MISMA definición que la tabla.
// Antes el PDF tenía sus diez columnas fijas en el código y no había manera de
// que respetara lo elegido en "Columnas".
// Cada columna lleva junto todo lo que necesita: cómo se ve en pantalla
// (`label`), cómo se imprime en el PDF (`pdf`) y cómo se exporta a Excel
// (`xls` + `width`). Antes eran listas paralelas y el formato de moneda se
// aplicaba por índice fijo, así que al mover una columna el signo de pesos
// se quedaba en la anterior.
const COLUMNAS_REPORTE_DIRECCION = [
  { key: "dia", label: "Día", pdf: (f) => f.dia || "", xls: (f) => f.dia, width: 12 },
  { key: "solicitante", label: "Solicitante", pdf: (f) => f.solicitante || "", xls: (f) => f.solicitante, width: 18 },
  { key: "proyecto", label: "Proyecto", pdf: (f) => f.proyecto || "", xls: (f) => f.proyecto, width: 16 },
  { key: "zona", label: "Zona", pdf: (f) => f.zona || "", xls: (f) => f.zona, width: 14 },
  { key: "proveedor", label: "Proveedor", pdf: (f) => f.proveedor || "", izq: true, xls: (f) => f.proveedor, width: 30 },
  { key: "concepto", label: "Concepto", pdf: (f) => f.concepto || "", izq: true, xls: (f) => f.concepto, width: 38 },
  { key: "importe", label: "Importe", pdf: (f) => money(f.importe, f.moneda), xls: (f) => f.importe, width: 14, money: true },
  { key: "moneda", label: "Moneda", pdf: (f) => f.moneda || "", xls: (f) => f.moneda, width: 9 },
  { key: "a_partida", label: "A Partida", pdf: (f) => f.a_partida || "", xls: (f) => f.a_partida, width: 16 },
  { key: "status", label: "Status", pdf: (f) => f.status || "", xls: (f) => f.status, width: 12 },
];

function ReportePagosDireccionTab({ unidad, partidas, transacciones, transaccionesApi, proveedoresApi }) {
  const partidasUnidad = partidas.filter((p) => p.unidad === unidad);
  const proveedoresUnidad = proveedoresApi.rows.filter((p) => p.unidad === unidad);
  const transUnidad = transacciones.filter(
    (t) => partidasUnidad.some((p) => p.id === t.partida_id) || t.unidad_detectada === unidad
  );

  const filas = transUnidad.map((t) => {
    const partida = partidasUnidad.find((p) => p.id === t.partida_id);
    const proveedor = t.proveedor_id ? proveedoresUnidad.find((p) => p.id === t.proveedor_id) : null;
    return {
      id: t.id,
      dia: t.dia || "",
      solicitante: t.solicitante || "",
      proyecto: t.proyecto || "",
      zona: t.zona || "",
      proveedor: proveedor?.nombre || t.proveedor || "",
      concepto: t.concepto_detallado || "",
      importe: Number(t.importe) || 0,
      moneda: t.moneda || "MXP",
      a_partida: partida?.folio || "",
      status: t.status || "",
    };
  });

  const [buscar, setBuscar] = useSessionState("ss-reporte-direccion-buscar", "");
  const [fechaDesde, setFechaDesde] = useSessionState("ss-reporte-direccion-desde", "");
  const [fechaHasta, setFechaHasta] = useSessionState("ss-reporte-direccion-hasta", "");
  const [panelExportRD, setPanelExportRD] = useState(false);
  const [sort, setSort] = usePrefState("pref-reporte-direccion-sort", { key: "dia", dir: "desc" }, sanearSort(["dia","solicitante","proyecto","zona","proveedor","concepto","importe","moneda","a_partida","status"]));
  const filasFiltradas = filas.filter((f) => {
    if (fechaDesde && (!f.dia || f.dia < fechaDesde)) return false;
    if (fechaHasta && (!f.dia || f.dia > fechaHasta)) return false;
    if (!buscar.trim()) return true;
    const q = buscar.trim().toLowerCase();
    return [f.solicitante, f.proveedor, f.concepto, f.a_partida, f.proyecto, f.zona]
      .some((v) => (v || "").toString().toLowerCase().includes(q));
  });
  const filtrosFechaActivos = fechaDesde || fechaHasta;
  const limpiarFechas = () => { setFechaDesde(""); setFechaHasta(""); };
  const filasOrdenadas = sortRows(filasFiltradas, sort, { importe: (r) => r.importe });

  const colVisibility = useColumnVisibility("colv-reporte-direccion", COLUMNAS_REPORTE_DIRECCION);
  const colWidths = useColumnWidths("colw-reporte-direccion");
  const { ordered: columnas, moveColumn } = useColumnOrder("colo-reporte-direccion", colVisibility.visible);
  const dragKeyRef = useRef(null);
  const onColDragStart = (e, key) => { dragKeyRef.current = key; e.dataTransfer.effectAllowed = "move"; };
  const onColDragOver = (e) => e.preventDefault();
  const onColDrop = (e, targetKey) => { e.preventDefault(); if (dragKeyRef.current) { moveColumn(dragKeyRef.current, targetKey); dragKeyRef.current = null; } };

  const exportarExcel = async () => {
    if (!filasOrdenadas.length) {
      alert("No hay transacciones en el filtro actual para exportar.");
      return;
    }
    const colsXls = columnas.filter((c) => c.xls);

    /* El periodo sale de las fechas que REALMENTE contiene el reporte, no de
       los filtros: si el rango es amplio pero solo hay pagos de un día, el
       archivo debe decir ese día. */
    const diasOrdenados = filasOrdenadas.map((f) => f.dia).filter(Boolean).sort();
    const inicio = fechaDesde || diasOrdenados[0] || "";
    const fin = fechaHasta || diasOrdenados[diasOrdenados.length - 1] || "";
    const etiquetaPeriodo = !inicio ? "Sin periodo" : (inicio === fin ? inicio : `${inicio} a ${fin}`);

    const fmtTot = (m, v) =>
      `$${(Number(v) || 0).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${m}`;

    const wbx = new ExcelJS.Workbook();
    const nombreHoja = `${unidad} ${etiquetaPeriodo}`.replace(/[:\\/?*[\]]/g, "-").slice(0, 31);
    const ws = wbx.addWorksheet(nombreHoja);
    ws.columns = colsXls.map((c) => ({ width: c.width || 14 }));

    // --- Encabezado, con el mismo tratamiento que el Reporte Presupuestal ---
    const tit = ws.addRow([`Reporte de Pagos a Dirección — ${unidad} — ${etiquetaPeriodo}`]);
    tit.font = { bold: true, size: 14, name: "Calibri" };
    ws.mergeCells(tit.number, 1, tit.number, Math.max(colsXls.length, 2));

    // Los totales van en el subtítulo, no sueltos en celdas fijas: ahí se leen
    // junto al periodo que los explica, y dejan de romperse si cambian las
    // columnas visibles.
    const totales = [];
    if (totalMXN) totales.push(fmtTot("MXP", totalMXN));
    if (totalUSD) totales.push(fmtTot("USD", totalUSD));
    const sub = ws.addRow([`${filasOrdenadas.length} transacciones   ·   ${totales.join("   ·   ") || "sin importes"}`]);
    sub.font = { size: 10, color: { argb: "FF6B7785" }, name: "Calibri" };
    ws.mergeCells(sub.number, 1, sub.number, Math.max(colsXls.length, 2));
    ws.addRow([]);

    const hr = ws.addRow(colsXls.map((c) => c.label));
    hr.eachCell((cell) => {
      cell.font = { bold: true, color: { argb: "FFFFFFFF" }, name: "Calibri" };
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF3E5C76" } };
      cell.alignment = { horizontal: "center", vertical: "center", wrapText: true };
    });
    ws.getRow(hr.number).height = 22;

    filasOrdenadas.forEach((f) => {
      const row = ws.addRow(colsXls.map((c) => c.xls(f)));
      colsXls.forEach((c, ci) => {
        const cell = row.getCell(ci + 1);
        cell.font = { name: "Calibri", size: 11 };
        // Las cifras a la derecha: alineadas por el punto decimal se comparan
        // de un vistazo, que es para lo que sirve una columna de importes.
        cell.alignment = { horizontal: c.money ? "right" : (c.izq ? "left" : "center"), vertical: "top", wrapText: !!c.izq };
        if (c.money) cell.numFmt = '"$"#,##0.00';
      });
    });

    // --- Totales al pie, separados por moneda ---
    ws.addRow([]);
    [["MXP", totalMXN], ["USD", totalUSD]].forEach(([m, v]) => {
      if (!v) return;
      const row = ws.addRow([`TOTAL ${m}`, ...Array(Math.max(colsXls.length - 2, 0)).fill(""), v]);
      row.font = { bold: true, name: "Calibri" };
      const ult = row.getCell(colsXls.length);
      ult.numFmt = '"$"#,##0.00';
      row.eachCell((cell) => {
        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFECEEF1" } };
      });
    });

    // Encabezado congelado: con cien renglones, saber en qué columna se está
    // parado deja de ser evidente al hacer scroll.
    ws.views = [{ state: "frozen", ySplit: hr.number }];
    ws.autoFilter = { from: { row: hr.number, column: 1 }, to: { row: hr.number, column: colsXls.length } };

    const buffer = await wbx.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Reporte de Pagos Dirección - ${unidad} - ${etiquetaPeriodo}.xlsx`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const [generandoReporte, setGenerandoReporte] = useState(false);
  /**
   * Estima si la tabla cabe a lo ancho de la hoja. autoTable no falla al
   * desbordarse: aprieta las columnas y parte las palabras sin avisar, y el
   * resultado llega ilegible a Dirección.
   */
  const anchoEstimadoPDF = () => {
    const disponible = 712; // carta horizontal menos márgenes
    const usado = columnas.reduce((suma, c) => {
      const largos = filasOrdenadas.map((f) => String(c.pdf ? c.pdf(f) : "").length);
      const max = Math.max(c.label.length, ...(largos.length ? largos : [0]));
      return suma + Math.min(max * 4.2, 140) + 8;
    }, 0);
    return { usado: Math.round(usado), disponible, cabe: usado <= disponible };
  };

  const generarReportePDF = async () => {
    if (!filasOrdenadas.length) {
      alert("No hay transacciones en el filtro actual para generar el reporte.");
      return;
    }
    const ancho = anchoEstimadoPDF();
    const avisoAncho = ancho.cabe ? "" :
      `\n\nOJO: con ${columnas.length} columnas la tabla se pasa del ancho de la hoja ` +
      `(~${ancho.usado} pt contra ${ancho.disponible} disponibles). Se van a apretar y el texto se va a partir. ` +
      `Considera ocultar algunas en "Columnas".`;
    const confirmado = confirm(
      `Esto va a generar un PDF con las ${filasOrdenadas.length} transacción(es) que tienes filtradas ahora, ` +
      `con las ${columnas.length} columnas visibles, y las va a marcar como "Reportadas". ¿Continuar?${avisoAncho}`
    );
    if (!confirmado) return;

    setGenerandoReporte(true);
    try {
      const diasOrdenados = filasOrdenadas.map((f) => f.dia).filter(Boolean).sort();
      const inicio = fechaDesde || diasOrdenados[0] || "";
      const fin = fechaHasta || diasOrdenados[diasOrdenados.length - 1] || "";

      const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "letter" });
      doc.setFontSize(13);
      doc.text(`Reporte de pagos a realizar del dia ${inicio} al dia ${fin} Compañía ${unidad}`, 30, 30);
      doc.setFontSize(9);
      doc.setTextColor(120);
      doc.text(`Total a pagar MXP: ${money(totalMXN, "MXP")}   ·   Total a pagar USD: ${money(totalUSD, "USD")}`, 30, 46);

      // Las mismas columnas que están a la vista, y en el mismo orden: si el
      // PDF mostrara otras, la tabla dejaría de servir para revisar lo que se
      // va a enviar.
      autoTable(doc, {
        startY: 58,
        head: [columnas.map((c) => c.label)],
        body: filasOrdenadas.map((f) => columnas.map((c) => (c.pdf ? c.pdf(f) : ""))),
        styles: { fontSize: 7.5, cellPadding: 4 },
        headStyles: { fillColor: [62, 92, 118], textColor: 255, halign: "center" },
        bodyStyles: { halign: "center" },
        columnStyles: Object.fromEntries(
          columnas.map((c, i) => [i, { halign: c.izq ? "left" : "center" }])
        ),
      });

      doc.save(`reporte-pagos-direccion-${unidad}-${new Date().toISOString().slice(0, 10)}.pdf`);

      for (const f of filasOrdenadas) {
        await transaccionesApi.update(f.id, { reportado_at: new Date().toISOString() });
      }
    } catch (err) {
      alert("No se pudo generar el reporte: " + (err.message || err));
    } finally {
      setGenerandoReporte(false);
    }
  };
  const totalMXN = filasOrdenadas.filter((f) => f.moneda === "MXP").reduce((s, f) => s + f.importe, 0);
  const totalUSD = filasOrdenadas.filter((f) => f.moneda === "USD").reduce((s, f) => s + f.importe, 0);

  if (!transUnidad.length) {
    return (
      <EmptyState
        title="Sin transacciones para reportar"
        body={`Todavía no hay transacciones registradas para ${unidad}. Captúralas o impórtalas desde la pestaña Transacciones.`}
      />
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <KpiCard label="Transacciones" value={String(filasOrdenadas.length)} />
        <KpiCard label="Total MXP (filtrado)" value={money(totalMXN, "MXP")} />
        <KpiCard label="Total USD (filtrado)" value={money(totalUSD, "USD")} />
      </div>

      <Panel
        title={`Reporte de Pagos Dirección — ${unidad}`}
        subtitle={`${filasOrdenadas.length} de ${filas.length} transacciones`}
        right={
          <div style={{ display: "flex", gap: 8 }}>
            {/* El selector es UNO solo aquí: gobierna la tabla, el PDF y el
                Excel a la vez desde la v1.82, así que se queda a la mano. */}
            <ColumnVisibilityControl
              columns={COLUMNAS_REPORTE_DIRECCION}
              hidden={colVisibility.hidden}
              onToggle={colVisibility.toggle}
              onShowAll={colVisibility.showAll}
            />
            <Button variant={panelExportRD ? "primary" : "ghost"} onClick={() => setPanelExportRD(!panelExportRD)}>
              Exportar {panelExportRD ? "▲" : "▼"}
            </Button>
          </div>
        }
      >
        <div style={{ marginBottom: 14, display: "flex", gap: 10, flexWrap: "wrap", alignItems: "flex-end" }}>
          <Field label="Buscar">
            <TextInput
              value={buscar}
              onChange={(e) => setBuscar(e.target.value)}
              placeholder="Solicitante, proveedor, concepto, folio…"
              style={{ width: 280 }}
            />
          </Field>
          <Field label="Desde">
            <TextInput type="date" value={fechaDesde} onChange={(e) => setFechaDesde(e.target.value)} />
          </Field>
          <Field label="Hasta">
            <TextInput type="date" value={fechaHasta} onChange={(e) => setFechaHasta(e.target.value)} />
          </Field>
          {filtrosFechaActivos && <Button variant="ghost" onClick={limpiarFechas}>Limpiar fechas</Button>}
        </div>

        {panelExportRD && (
          <div style={{ background: T.panelAlt, border: `1px solid ${T.borderSoft}`, borderRadius: 8,
                        padding: 14, marginBottom: 16 }}>
            <div style={{ fontSize: 11.5, color: T.textFaint, marginBottom: 12 }}>
              Ambas salidas llevan las columnas visibles de la tabla —
              {filasOrdenadas.length} de {filas.length} transacciones.
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 12 }}>
              <div style={{ background: T.panel, border: `1px solid ${T.borderSoft}`, borderRadius: 8, padding: 13,
                            display: "flex", flexDirection: "column" }}>
                <div style={{ fontSize: 12.5, fontWeight: 700 }}>Reporte (PDF)</div>
                <div style={{ fontSize: 11, color: T.textDim, marginTop: 3, minHeight: 46 }}>
                  El documento que se envía a Dirección. Marca las transacciones como reportadas.
                </div>
                <div style={{ flex: 1 }} />
                <Button onClick={generarReportePDF} disabled={generandoReporte} style={{ width: "100%" }}>
                  {generandoReporte ? "Generando…" : "Generar PDF"}
                </Button>
              </div>
              <div style={{ background: T.panel, border: `1px solid ${T.borderSoft}`, borderRadius: 8, padding: 13,
                            display: "flex", flexDirection: "column" }}>
                <div style={{ fontSize: 12.5, fontWeight: 700 }}>Excel</div>
                <div style={{ fontSize: 11, color: T.textDim, marginTop: 3, minHeight: 46 }}>
                  Los mismos datos en hoja de cálculo, con totales por moneda.
                  No marca nada como reportado.
                </div>
                <div style={{ flex: 1 }} />
                <Button onClick={exportarExcel} style={{ width: "100%" }}>Generar Excel</Button>
              </div>
            </div>
          </div>
        )}

        <div style={{ overflowX: "auto" }}>
          <table style={{ ...tableStyle, tableLayout: "fixed" }}>
            <colgroup>
              {columnas.map((c) => <col key={c.key} style={{ width: colWidths.getWidth(c.key) }} />)}
            </colgroup>
            <thead>
              <tr>
                {columnas.map((c) => (
                  <SortableTh
                    key={c.key} label={c.label} sortKey={c.key} sort={sort} setSort={setSort}
                    width={colWidths.getWidth(c.key)} onResizeStart={(e) => colWidths.startResize(c.key, e)}
                    onDragStart={(e) => onColDragStart(e, c.key)} onDragOver={onColDragOver} onDrop={(e) => onColDrop(e, c.key)}
                    sumLabel={c.key === "importe" ? sumaPorMoneda(filasOrdenadas, "importe") : undefined}
                  />
                ))}
              </tr>
            </thead>
            <tbody>
              {filasOrdenadas.map((f) => (
                <tr key={f.id}>
                  {columnas.map((c) => (
                    <td key={c.key} style={c.key === "importe" ? { ...tdStyle, fontFamily: T.fontMono } : tdStyle}>
                      {c.key === "importe" ? money(f.importe, f.moneda) : (f[c.key] || "—")}
                    </td>
                  ))}
                </tr>
              ))}
              {!filasOrdenadas.length && (
                <tr><td colSpan={columnas.length} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>Ninguna transacción coincide con la búsqueda</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </Panel>
    </div>
  );
}

/**
 * Catálogo de zonas. Se pueden dar de alta, renombrar, desactivar y borrar.
 *
 * Desactivar y borrar no son lo mismo, y la diferencia importa:
 *   · Desactivar la saca del selector pero la deja como referencia.
 *   · Borrar la quita del catálogo — las transacciones que ya la usaban
 *     conservan el texto, porque `transacciones.zona` no es llave foránea.
 *     Por eso se avisa cuántas quedarían con una zona fuera de catálogo.
 */
function ZonasPanel({ zonasApi, transacciones = [], unidad }) {
  const [nueva, setNueva] = useState("");
  const [editandoId, setEditandoId] = useState(null);
  const [borradorGrupo, setBorradorGrupo] = useState("");
  const [borrador, setBorrador] = useState("");

  /* Solo las de esta compañía. Se toleran las que aún no tienen unidad para
     que el panel siga sirviendo si la migración no se ha corrido. */
  const zonas = [...zonasApi.rows.filter((z) => z.unidad === unidad || !z.unidad)].sort(
    (a, b) => (a.orden ?? 999) - (b.orden ?? 999) || String(a.nombre).localeCompare(String(b.nombre))
  );
  // El conteo también por compañía: sin esto las tres mostraban el mismo
  // número y parecía que la separación no había servido de nada.
  const transDeLaUnidad = transacciones.filter((t) => t.unidad_detectada === unidad);
  const usos = (nombre) => transDeLaUnidad.filter(
    (t) => String(t.zona || "").trim().toLowerCase() === String(nombre).trim().toLowerCase()
  ).length;

  // Zonas que aparecen en transacciones pero no están dadas de alta: llegan
  // por carga masiva o desde los correos, y sin esto pasarían inadvertidas.
  const enCatalogo = new Set(zonas.map((z) => String(z.nombre).trim().toLowerCase()));
  const huerfanas = [...new Set(
    transDeLaUnidad.map((t) => String(t.zona || "").trim()).filter(Boolean)
      .filter((z) => !enCatalogo.has(z.toLowerCase()))
  )].sort();

  const agregar = async () => {
    const nombre = nueva.trim();
    if (!nombre) return;
    if (enCatalogo.has(nombre.toLowerCase())) { alert(`"${nombre}" ya está en el catálogo.`); return; }
    try {
      // Sin `id`: lo genera la base. uid() cae en una cadena de ocho
      // caracteres cuando crypto.randomUUID no está, y Postgres la rechaza.
      await zonasApi.insert({ unidad, nombre, activa: true, orden: (zonas[zonas.length - 1]?.orden ?? zonas.length) + 1 });
      setNueva("");
    } catch (err) { alert("No se pudo agregar: " + (err.message || err)); }
  };

  const guardar = async (id) => {
    const nombre = borrador.trim();
    if (!nombre) return;
    try {
      await zonasApi.update(id, { nombre, grupo: borradorGrupo.trim() || null });
      setEditandoId(null);
    } catch (err) { alert("No se pudo actualizar: " + (err.message || err)); }
  };

  const alternarActiva = (z) =>
    zonasApi.update(z.id, { activa: z.activa === false })
      .catch((err) => alert("No se pudo actualizar: " + (err.message || err)));

  const borrar = (z) => {
    const n = usos(z.nombre);
    const aviso = n
      ? `\n\nOJO: ${n} transacción(es) usan esta zona. No se van a modificar —conservan el texto— pero quedarán con una zona que ya no existe en el catálogo. Si solo quieres sacarla del selector, mejor desactívala.`
      : "";
    if (!confirm(`¿Eliminar la zona "${z.nombre}"?${aviso}`)) return;
    zonasApi.remove(z.id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
  };

  return (
    <Panel
      title="Catálogo de zonas"
      subtitle={`${zonas.filter((z) => z.activa !== false).length} activas en ${unidad} — alimentan el selector de Zona al capturar transacciones`}
    >
      <div style={{ display: "flex", gap: 8, alignItems: "flex-end", marginBottom: 14, flexWrap: "wrap" }}>
        <Field label="Nueva zona">
          <TextInput
            value={nueva}
            onChange={(e) => setNueva(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") agregar(); }}
            placeholder="Nombre de la zona"
            style={{ width: 240 }}
          />
        </Field>
        <Button onClick={agregar} disabled={!nueva.trim()}>+ Agregar</Button>
      </div>

      {!zonasApi.rows.length && (
        <div style={{ borderLeft: `3px solid ${T.amber}`, background: "#FDF8EF", padding: "10px 13px", borderRadius: "0 6px 6px 0", fontSize: 12, marginBottom: 12 }}>
          <b>La tabla de zonas está vacía</b>
          Mientras tanto el selector usa la lista de respaldo. Corre la migración
          <code style={{ fontFamily: T.fontMono, margin: "0 4px" }}>06-catalogo-zonas.sql</code>
          para poblarla con las 11 originales.
        </div>
      )}

      {huerfanas.length > 0 && (
        <div style={{ borderLeft: `3px solid ${T.amber}`, background: "#FDF8EF", padding: "10px 13px", borderRadius: "0 6px 6px 0", fontSize: 12, marginBottom: 12 }}>
          <b>Zonas en uso que no están en el catálogo</b>
          Aparecen en transacciones pero nadie las dio de alta, así que no salen en el selector:
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 8 }}>
            {huerfanas.map((h) => (
              <Button key={h} variant="ghost" style={{ padding: "3px 9px", fontSize: 11 }}
                onClick={() => zonasApi.insert({ unidad, nombre: h, activa: true, orden: 900 })
                  .catch((err) => alert("No se pudo agregar: " + (err.message || err)))}>
                + {h} <span style={{ color: T.textFaint }}>({usos(h)})</span>
              </Button>
            ))}
          </div>
        </div>
      )}

      <table style={tableStyle}>
        <thead>
          <tr>
            <th style={thStyle}>Zona</th>
            <th style={thStyle}>Grupo (como lo ve Dirección)</th>
            <th style={thStyle}>Transacciones</th>
            <th style={thStyle}>Estado</th>
            <th style={thStyle}></th>
          </tr>
        </thead>
        <tbody>
          {zonas.map((z) => (
            <tr key={z.id} style={{ opacity: z.activa === false ? 0.55 : 1 }}>
              <td style={tdStyle}>
                {editandoId === z.id ? (
                  <TextInput value={borrador} onChange={(e) => setBorrador(e.target.value)}
                    onKeyDown={(e) => { if (e.key === "Enter") guardar(z.id); }} style={{ width: 220 }} />
                ) : z.nombre}
              </td>
              {/* El grupo es cómo Dirección conoce la zona en el reporte
                  mensual. Vacío significa que se reporta con su propio nombre. */}
              <td style={tdStyle}>
                {editandoId === z.id ? (
                  <TextInput value={borradorGrupo} onChange={(e) => setBorradorGrupo(e.target.value)}
                    onKeyDown={(e) => { if (e.key === "Enter") guardar(z.id); }}
                    placeholder="Zona Norte" style={{ width: 150 }} />
                ) : (z.grupo ? <Pill>{z.grupo}</Pill> : <span style={{ color: T.textFaint }}>propio nombre</span>)}
              </td>
              <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{usos(z.nombre) || "—"}</td>
              <td style={tdStyle}>
                <Pill tone={z.activa === false ? "amber" : "teal"}>{z.activa === false ? "Inactiva" : "Activa"}</Pill>
              </td>
              <td style={tdStyle}>
                <div style={{ display: "flex", gap: 4, justifyContent: "flex-end" }}>
                  {editandoId === z.id ? (
                    <>
                      <Button onClick={() => guardar(z.id)} style={{ padding: "4px 10px", fontSize: 11.5 }}>Guardar</Button>
                      <Button variant="ghost" onClick={() => setEditandoId(null)} style={{ padding: "4px 10px", fontSize: 11.5 }}>Cancelar</Button>
                    </>
                  ) : (
                    <>
                      <IconButton icon="✎" label="Renombrar" tone={T.accent}
                        onClick={() => { setEditandoId(z.id); setBorrador(z.nombre); setBorradorGrupo(z.grupo || ""); }} />
                      <IconButton icon={z.activa === false ? "◻" : "◼"}
                        label={z.activa === false ? "Activar" : "Desactivar"}
                        onClick={() => alternarActiva(z)} />
                      <IconButton icon="✕" label="Eliminar" tone={T.red} onClick={() => borrar(z)} />
                    </>
                  )}
                </div>
              </td>
            </tr>
          ))}
          {!zonas.length && (
            <tr><td colSpan={4} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>
              Todavía no hay zonas en el catálogo
            </td></tr>
          )}
        </tbody>
      </table>
    </Panel>
  );
}

/**
 * Catálogo de rubros y categorías.
 *
 * El punto delicado es RENOMBRAR. `partidas.rubro`, `partidas.categoria` y
 * `transacciones.categoria` guardan el TEXTO, no un id, así que cambiar el
 * nombre aquí dejaría a los registros existentes apuntando a algo que ya no
 * existe en el catálogo. Por eso al renombrar se propaga el cambio a los
 * registros en uso, en el mismo paso y avisando cuántos son.
 *
 * Se guarda el texto y no un id a propósito: así el histórico conserva cómo
 * se llamaba el rubro cuando se capturó, y borrar una categoría no deja
 * registros rotos.
 */
function RubrosPanel({ rubrosApi, categoriasApi, partidas = [], transacciones = [] }) {
  const [nuevoRubro, setNuevoRubro] = useState("");
  const [rubroSel, setRubroSel] = useState(null);
  const [nuevaCat, setNuevaCat] = useState("");

  const rubros = [...rubrosApi.rows].sort(
    (a, b) => (a.orden ?? 999) - (b.orden ?? 999) || String(a.nombre).localeCompare(String(b.nombre))
  );
  const catsDe = (rid) => categoriasApi.rows
    .filter((c) => c.rubro_id === rid)
    .sort((a, b) => (a.orden ?? 999) - (b.orden ?? 999) || String(a.nombre).localeCompare(String(b.nombre)));

  const igual = (a, b) => String(a || "").trim().toLowerCase() === String(b || "").trim().toLowerCase();
  const usosRubro = (nom) => partidas.filter((p) => igual(p.rubro, nom)).length;
  const usosCat = (nom) =>
    partidas.filter((p) => igual(p.categoria, nom)).length +
    transacciones.filter((t) => igual(t.categoria, nom)).length;

  const agregarRubro = async () => {
    const nombre = nuevoRubro.trim();
    if (!nombre) return;
    if (rubros.some((r) => igual(r.nombre, nombre))) { alert(`El rubro "${nombre}" ya existe.`); return; }
    try {
      const orden = (rubros[rubros.length - 1]?.orden ?? rubros.length) + 1;
      await rubrosApi.insert({ id: uid(), nombre, orden, activo: true });
      // Nace SIN categorías, a propósito. Crearle una genérica invitaría a
      // usarla en vez de definir las que el rubro realmente necesita.
      setNuevoRubro("");
      alert(`Rubro "${nombre}" creado. Agrégale sus categorías: un rubro sin categorías no sirve para clasificar.`);
    } catch (err) { alert("No se pudo agregar: " + (err.message || err)); }
  };

  const renombrarRubro = async (r) => {
    const nombre = (prompt(`Nuevo nombre para el rubro "${r.nombre}":`, r.nombre) || "").trim();
    if (!nombre || igual(nombre, r.nombre)) return;
    if (rubros.some((x) => x.id !== r.id && igual(x.nombre, nombre))) { alert(`Ya existe un rubro "${nombre}".`); return; }
    const n = usosRubro(r.nombre);
    if (n && !confirm(`${n} partida(s) usan el rubro "${r.nombre}". Se les va a cambiar el nombre también, para que no queden apuntando a un rubro inexistente.\n\n¿Continuar?`)) return;
    try {
      await rubrosApi.update(r.id, { nombre });
      for (const p of partidas.filter((p) => igual(p.rubro, r.nombre))) {
        await supabase.from("partidas").update({ rubro: nombre }).eq("id", p.id);
      }
    } catch (err) { alert("No se pudo renombrar: " + (err.message || err)); }
  };

  const borrarRubro = (r) => {
    const n = usosRubro(r.nombre);
    if (n) { alert(`No se puede eliminar "${r.nombre}": ${n} partida(s) lo usan.\n\nSi ya no se debe usar, desactívalo — sale del selector pero el histórico se conserva.`); return; }
    if (!confirm(`¿Eliminar el rubro "${r.nombre}" y sus ${catsDe(r.id).length} categoría(s)?`)) return;
    rubrosApi.remove(r.id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
  };

  const agregarCat = async () => {
    const nombre = nuevaCat.trim();
    if (!nombre || !rubroSel) return;
    if (catsDe(rubroSel.id).some((c) => igual(c.nombre, nombre))) { alert(`"${nombre}" ya existe en ${rubroSel.nombre}.`); return; }
    // Se bloquea recrear el comodín: si vuelve a existir, vuelve a usarse.
    if (["diversos", "varios", "otros", "general", "generales"].includes(nombre.toLowerCase())) {
      alert(`No se permite "${nombre}" como categoría.\n\nUna opción genérica se vuelve el camino de menor resistencia y la clasificación se degrada: acaba respondiendo "en cosas" a la pregunta de en qué gastamos. Si un gasto no encaja, déjalo sin categoría — el hueco se ve y se corrige.`);
      return;
    }
    try {
      const cs = catsDe(rubroSel.id);
      await categoriasApi.insert({ id: uid(), rubro_id: rubroSel.id, nombre,
        orden: (cs[cs.length - 1]?.orden ?? cs.length) + 1, activa: true });
      setNuevaCat("");
    } catch (err) { alert("No se pudo agregar: " + (err.message || err)); }
  };

  const renombrarCat = async (c) => {
    const nombre = (prompt(`Nuevo nombre para la categoría "${c.nombre}":`, c.nombre) || "").trim();
    if (!nombre || igual(nombre, c.nombre)) return;
    const n = usosCat(c.nombre);
    if (n && !confirm(`${n} registro(s) usan la categoría "${c.nombre}". Se les va a cambiar el nombre también.\n\n¿Continuar?`)) return;
    try {
      await categoriasApi.update(c.id, { nombre });
      for (const p of partidas.filter((p) => igual(p.categoria, c.nombre))) {
        await supabase.from("partidas").update({ categoria: nombre }).eq("id", p.id);
      }
      for (const t of transacciones.filter((t) => igual(t.categoria, c.nombre))) {
        await supabase.from("transacciones").update({ categoria: nombre }).eq("id", t.id);
      }
    } catch (err) { alert("No se pudo renombrar: " + (err.message || err)); }
  };

  const borrarCat = (c) => {
    const n = usosCat(c.nombre);
    if (n) { alert(`No se puede eliminar "${c.nombre}": ${n} registro(s) la usan.\n\nDesactívala si ya no se debe usar.`); return; }
    if (!confirm(`¿Eliminar la categoría "${c.nombre}"?`)) return;
    categoriasApi.remove(c.id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
  };

  const activo = rubroSel && rubros.find((r) => r.id === rubroSel.id);

  return (
    <Panel
      title="Rubros y categorías"
      subtitle={`${rubros.length} rubros · ${categoriasApi.rows.length} categorías — alimentan Partidas y Transacciones`}
    >
      {!rubrosApi.rows.length && (
        <div style={{ borderLeft: `3px solid ${T.amber}`, background: "#FDF8EF", padding: "10px 13px", borderRadius: "0 6px 6px 0", fontSize: 12, marginBottom: 14 }}>
          <b>El catálogo de la base está vacío</b>
          Mientras tanto se usa la lista del código. Corre
          <code style={{ fontFamily: T.fontMono, margin: "0 4px" }}>16-catalogo-editable.sql</code>
          para poblarla con los 15 rubros y 122 categorías actuales.
        </div>
      )}

      <div style={{ display: "flex", gap: 18, alignItems: "flex-start", flexWrap: "wrap" }}>
        {/* Rubros */}
        <div style={{ flex: "1 1 340px", minWidth: 300 }}>
          <div style={{ display: "flex", gap: 8, alignItems: "flex-end", marginBottom: 10 }}>
            <Field label="Nuevo rubro">
              <TextInput value={nuevoRubro} onChange={(e) => setNuevoRubro(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter") agregarRubro(); }}
                placeholder="Nombre del rubro" style={{ width: 210 }} />
            </Field>
            <Button onClick={agregarRubro} disabled={!nuevoRubro.trim()}>+ Agregar</Button>
          </div>
          <table style={tableStyle}>
            <thead><tr><th style={thStyle}>Rubro</th><th style={thStyle}>Cats.</th><th style={thStyle}>Partidas</th><th style={thStyle}></th></tr></thead>
            <tbody>
              {rubros.map((r) => (
                <tr key={r.id}
                  onClick={() => setRubroSel(r)}
                  style={{ cursor: "pointer", opacity: r.activo === false ? 0.55 : 1,
                           background: rubroSel?.id === r.id ? T.panelAlt : "transparent" }}>
                  <td style={tdStyle}>{r.nombre}</td>
                  <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{catsDe(r.id).length}</td>
                  <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{usosRubro(r.nombre) || "—"}</td>
                  <td style={tdStyle}>
                    <div style={{ display: "flex", gap: 4, justifyContent: "flex-end" }}>
                      <IconButton icon="✎" label="Renombrar" tone={T.accent}
                        onClick={(e) => { e.stopPropagation(); renombrarRubro(r); }} />
                      <IconButton icon={r.activo === false ? "◻" : "◼"}
                        label={r.activo === false ? "Activar" : "Desactivar"}
                        onClick={(e) => { e.stopPropagation();
                          rubrosApi.update(r.id, { activo: r.activo === false })
                            .catch((err) => alert("No se pudo: " + (err.message || err))); }} />
                      <IconButton icon="✕" label="Eliminar" tone={T.red}
                        onClick={(e) => { e.stopPropagation(); borrarRubro(r); }} />
                    </div>
                  </td>
                </tr>
              ))}
              {!rubros.length && (
                <tr><td colSpan={4} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>Sin rubros en la base</td></tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Categorías del rubro elegido */}
        <div style={{ flex: "1 1 340px", minWidth: 300 }}>
          {!activo ? (
            <div style={{ color: T.textFaint, fontSize: 12.5, padding: "40px 0", textAlign: "center" }}>
              Elige un rubro de la izquierda para ver y editar sus categorías
            </div>
          ) : (
            <>
              <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 10 }}>
                Categorías de {activo.nombre}
              </div>
              <div style={{ display: "flex", gap: 8, alignItems: "flex-end", marginBottom: 10 }}>
                <Field label="Nueva categoría">
                  <TextInput value={nuevaCat} onChange={(e) => setNuevaCat(e.target.value)}
                    onKeyDown={(e) => { if (e.key === "Enter") agregarCat(); }}
                    placeholder="Nombre de la categoría" style={{ width: 210 }} />
                </Field>
                <Button onClick={agregarCat} disabled={!nuevaCat.trim()}>+ Agregar</Button>
              </div>
              <table style={tableStyle}>
                <thead><tr><th style={thStyle}>Categoría</th><th style={thStyle}>En uso</th><th style={thStyle}></th></tr></thead>
                <tbody>
                  {catsDe(activo.id).map((c) => (
                    <tr key={c.id} style={{ opacity: c.activa === false ? 0.55 : 1 }}>
                      <td style={tdStyle}>{c.nombre}</td>
                      <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{usosCat(c.nombre) || "—"}</td>
                      <td style={tdStyle}>
                        <div style={{ display: "flex", gap: 4, justifyContent: "flex-end" }}>
                          <IconButton icon="✎" label="Renombrar" tone={T.accent} onClick={() => renombrarCat(c)} />
                          <IconButton icon={c.activa === false ? "◻" : "◼"}
                            label={c.activa === false ? "Activar" : "Desactivar"}
                            onClick={() => categoriasApi.update(c.id, { activa: c.activa === false })
                              .catch((err) => alert("No se pudo: " + (err.message || err)))} />
                          <IconButton icon="✕" label="Eliminar" tone={T.red} onClick={() => borrarCat(c)} />
                        </div>
                      </td>
                    </tr>
                  ))}
                  {!catsDe(activo.id).length && (
                    <tr><td colSpan={3} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>Sin categorías</td></tr>
                  )}
                </tbody>
              </table>
            </>
          )}
        </div>
      </div>
    </Panel>
  );
}

/**
 * Ajustes por compañía. Hoy solo la numeración de las Solicitudes de Pago y
 * los datos que se repiten en todas ellas, escritos hasta ahora a mano.
 */
/**
 * Acepta el ID solo, o la URL completa de la hoja — la extrae en cualquier
 * caso, para no exigir que se copie el fragmento exacto entre /d/ y /edit.
 */
function extraerSheetId(texto) {
  const t = (texto || "").trim();
  const m = t.match(/\/d\/([a-zA-Z0-9_-]+)/);
  return m ? m[1] : t;
}

function ConfigCompaniaPanel({ unidad }) {
  const [cfg, setCfg] = useState(null);
  const [ultimoEmitido, setUltimoEmitido] = useState(0);
  const [guardando, setGuardando] = useState(false);

  useEffect(() => {
    let vivo = true;
    (async () => {
      const { data } = await supabase.from("config_companias").select("*").eq("compania", unidad).maybeSingle();
      const { data: max } = await supabase.from("solicitudes_pago").select("folio")
        .eq("compania", unidad).order("folio", { ascending: false }).limit(1);
      if (!vivo) return;
      setCfg(data || { compania: unidad, spp_ultimo: 0, spp_responsable: "", spp_lugar_adquisicion: "" });
      setUltimoEmitido((max && max[0]?.folio) || 0);
    })();
    return () => { vivo = false; };
  }, [unidad]);

  if (!cfg) return null;
  const siguiente = Math.max(Number(cfg.spp_ultimo) || 0, ultimoEmitido) + 1;

  const guardar = async () => {
    setGuardando(true);
    try {
      const { error } = await supabase.from("config_companias").upsert({
        compania: unidad,
        spp_ultimo: Number(cfg.spp_ultimo) || 0,
        spp_responsable: cfg.spp_responsable || "",
        spp_lugar_adquisicion: cfg.spp_lugar_adquisicion || "",
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally { setGuardando(false); }
  };

  return (
    <Panel title={`Solicitudes de Pago — ${unidad}`}
      subtitle="Numeración y datos que se repiten en todas las solicitudes de esta compañía">
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12, marginBottom: 12 }}>
        <Field label="Último folio usado">
          <TextInput type="number" value={cfg.spp_ultimo ?? 0}
            onChange={(e) => setCfg({ ...cfg, spp_ultimo: e.target.value })} />
        </Field>
        <Field label="Responsable de proyecto">
          <TextInput value={cfg.spp_responsable || ""}
            onChange={(e) => setCfg({ ...cfg, spp_responsable: e.target.value })}
            placeholder="Se precarga en cada solicitud" />
        </Field>
        <Field label="Lugar de adquisición">
          <TextInput value={cfg.spp_lugar_adquisicion || ""}
            onChange={(e) => setCfg({ ...cfg, spp_lugar_adquisicion: e.target.value })}
            placeholder="Queretaro" />
        </Field>
      </div>

      {/* El folio real es el mayor entre lo configurado y lo ya emitido: si
          se baja el número por error, no se reutilizan folios de solicitudes
          que ya salieron. */}
      <div style={{ fontSize: 12, color: T.textDim, marginBottom: 12 }}>
        La siguiente solicitud llevará el folio <b style={{ fontFamily: T.fontMono }}>{siguiente}</b>.
        {ultimoEmitido > (Number(cfg.spp_ultimo) || 0) && (
          <span style={{ color: T.amber }}>
            {" "}Ya se emitió el folio {ultimoEmitido}, así que la numeración continúa desde ahí
            aunque el valor configurado sea menor.
          </span>
        )}
      </div>

      <Button onClick={guardar} disabled={guardando}>
        {guardando ? "Guardando…" : "Guardar"}
      </Button>

      <ConfigHojasImportacion unidad={unidad} />
    </Panel>
  );
}

/**
 * Lista editable de hojas de Google Sheets configuradas como origen del
 * importador de Transacciones. Una compañía puede tener varias —ISE, por
 * ejemplo, una por zona— cada una con su propia etiqueta libre para
 * distinguirlas; el importador las lee todas juntas en una sola búsqueda.
 */
function ConfigHojasImportacion({ unidad }) {
  const [hojas, setHojas] = useState([]);
  const [cargando, setCargando] = useState(true);

  const cargar = async () => {
    setCargando(true);
    const { data } = await supabase.from("sheets_importacion_transacciones")
      .select("*").eq("compania", unidad).order("created_at");
    setHojas(data || []);
    setCargando(false);
  };
  useEffect(() => { cargar(); }, [unidad]);

  const agregar = async () => {
    const { error } = await supabase.from("sheets_importacion_transacciones")
      .insert({ compania: unidad, etiqueta: "Nueva hoja", google_sheet_id: "" });
    if (error) { alert("No se pudo agregar: " + error.message); return; }
    cargar();
  };
  const actualizar = async (id, cambios) => {
    setHojas((prev) => prev.map((h) => (h.id === id ? { ...h, ...cambios } : h))); // respuesta inmediata al escribir
    const { error } = await supabase.from("sheets_importacion_transacciones").update(cambios).eq("id", id);
    if (error) alert("No se pudo guardar: " + error.message);
  };
  const eliminar = async (h) => {
    if (!confirm(`¿Quitar "${h.etiqueta}" de las hojas de ${unidad}? Esto no borra nada de la hoja de Google, solo deja de leerla.`)) return;
    const { error } = await supabase.from("sheets_importacion_transacciones").delete().eq("id", h.id);
    if (error) { alert("No se pudo quitar: " + error.message); return; }
    cargar();
  };

  return (
    <div style={{ borderTop: `1px solid ${T.borderSoft}`, marginTop: 20, paddingTop: 16 }}>
      <div style={{ fontSize: 12.5, fontWeight: 700, marginBottom: 4 }}>Importador de Transacciones (Google Sheets)</div>
      <div style={{ fontSize: 11.5, color: T.textFaint, marginBottom: 10 }}>
        Las hojas de origen de {unidad} — puede haber más de una (por ejemplo, una por zona).
        El importador las busca todas juntas. Puedes pegar el ID o la URL completa, se extrae solo.
      </div>

      {cargando ? (
        <div style={{ fontSize: 12, color: T.textFaint }}>Cargando…</div>
      ) : (
        <>
          {hojas.map((h) => (
            <div key={h.id} style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
              <TextInput
                value={h.etiqueta}
                onChange={(e) => actualizar(h.id, { etiqueta: e.target.value })}
                placeholder="Etiqueta (ej. Poza Rica)"
                style={{ width: 160 }}
              />
              <TextInput
                value={h.google_sheet_id}
                onChange={(e) => actualizar(h.id, { google_sheet_id: extraerSheetId(e.target.value) })}
                placeholder="1xQCT022JBX1KpO5MzzLbQmvhj8dEovuZ"
                style={{ width: 320, fontFamily: T.fontMono }}
              />
              <label style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 11.5, color: T.textDim }}>
                <input type="checkbox" checked={h.activo} onChange={(e) => actualizar(h.id, { activo: e.target.checked })} />
                Activa
              </label>
              <IconButton icon="✕" label="Quitar esta hoja" tone={T.red} onClick={() => eliminar(h)} />
            </div>
          ))}
          <Button variant="ghost" onClick={agregar}>+ Agregar hoja</Button>
        </>
      )}
    </div>
  );
}

const SUBS_CATALOGO = [
  { id: "proyectos", label: "Proyectos" },
  { id: "rubros", label: "Rubros y categorías" },
  { id: "zonas", label: "Zonas" },
  { id: "proveedores", label: "Proveedores" },
  { id: "solicitudes", label: "Solicitudes de Pago" },
];

/**
 * Reportes oficiales a Dirección y bitácora de desviaciones.
 *
 * Separado de las exportaciones normales a propósito: un reporte oficial no
 * es un archivo más, es el acto que fija la línea base. Mezclarlo con los
 * botones de exportar invitaría a generarlo por costumbre y a versionar
 * envíos que nunca salieron.
 */
function ReportesDireccionTab({ unidad, partidas, transacciones, gruposZona = {} }) {
  const [sub, setSub] = useSessionState("ss-repdir-sub", "presupuesto");
  const [reportes, setReportes] = useState([]);
  const [reportado, setReportado] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [recarga, setRecarga] = useState(0);

  const hoy = new Date().toISOString().slice(0, 10);
  const [mesRep, setMesRep] = useState(MESES[new Date().getMonth()]);
  const [anioRep, setAnioRep] = useState(new Date().getFullYear());
  const [semanaRep, setSemanaRep] = useState(lunesDe(hoy));

  useEffect(() => {
    let vivo = true;
    (async () => {
      setCargando(true);
      const { data: reps } = await supabase.from("reportes_oficiales")
        .select("*").eq("compania", unidad).order("enviado_en", { ascending: false });
      const { data: base } = await supabase.from("v_reportado").select("*").eq("compania", unidad);
      if (!vivo) return;
      setReportes(reps || []);
      setReportado(base || []);
      setCargando(false);
    })();
    return () => { vivo = false; };
  }, [unidad, recarga]);

  const partidasUnidad = partidas.filter((p) => p.unidad === unidad);
  const transUnidad = transacciones.filter((t) => t.unidad_detectada === unidad);
  const partidaDe = (t) => partidas.find((p) => p.id === t.partida_id);

  // --- Presupuesto del mes elegido ---
  const partidasMes = partidasUnidad.filter((p) => p.mes === mesRep && Number(p.anio) === Number(anioRep));
  /* Una partida no tiene área: el área vive en la transacción. Se toma de
     sus transacciones, y si no tiene ninguna todavía, queda "Sin área" —
     que es honesto: aún no se sabe quién lo va a ejercer. */
  const areaDePartida = (p) => {
    const t = transUnidad.find((x) => x.partida_id === p.id && x.area);
    return t?.area || "Sin área";
  };
  const filasPresupuesto = partidasMes.map((p) => ({
    origen_id: p.id, folio: p.folio || "", area: areaDePartida(p),
    categoria: p.categoria || "", rubro: p.rubro || "", proyecto: p.proyecto || "",
    zona: p.zona || "", concepto: p.concepto || "", proveedor: null, solicitante: null,
    importe: Number(p.monto_estimado) || 0, moneda: p.moneda || "MXP", dia: null,
    // Solo para agrupar; no se guardan en el detalle congelado.
    _mes: p.mes, _anio: p.anio,
  }));

  // --- Transacciones de la semana elegida ---
  const finSemana = (() => { const d = new Date(`${semanaRep}T12:00:00`); d.setDate(d.getDate() + 6); return d.toISOString().slice(0, 10); })();
  const transSemana = transUnidad.filter((t) => t.dia && t.dia >= semanaRep && t.dia <= finSemana);
  const filasTrans = transSemana.map((t) => {
    const p = partidaDe(t);
    return {
      origen_id: t.id, folio: t.folio_transaccion || "", area: t.area || "Sin área",
      categoria: t.categoria || "", rubro: p?.rubro || "", proyecto: t.proyecto || p?.proyecto || "",
      zona: t.zona || "", concepto: t.concepto_detallado || "", proveedor: t.proveedor || "",
      solicitante: t.solicitante || "", importe: Number(t.importe) || 0,
      moneda: t.moneda || "MXP", dia: t.dia || null,
      _status: t.status || "", _rubro: p?.rubro || "", _proyecto: t.proyecto || p?.proyecto || "",
      _mes: p?.mes || "", _anio: p?.anio || null,
    };
  });

  const esPresupuesto = sub === "presupuesto";

  /* MISMA preferencia que la pestaña de origen —la clave de almacenamiento es
     la misma— así que agrupar en Partidas cambia también el reporte oficial.
     Se muestra aquí para que sea visible y ajustable en el momento de generar,
     en vez de depender de algo que se configuró en otra pantalla. */
  const filas = esPresupuesto ? filasPresupuesto : filasTrans;
  const periodo = esPresupuesto ? `${mesRep} ${anioRep}` : `Semana ${semanaRep}`;
  const yaEnviados = reportes.filter((r) => r.tipo === (esPresupuesto ? "presupuesto" : "transacciones") && r.periodo === periodo);

  const desviaciones = detectarDesviaciones(filas, reportado);

  /* Deshacer un registro. Una versión de más deja la línea base contando
     envíos que nunca salieron, y entonces gasto realmente imprevisto
     parecería reportado. */
  const deshacerVersion = async (r) => {
    if (!confirm(
      `¿Eliminar el registro de la versión ${r.version} de ${r.periodo}?\n\n` +
      `Úsalo solo si se generó por error y NO se envió a Dirección. ` +
      `Las combinaciones de área y categoría que aportaba dejarán de contar como reportadas.`
    )) return;
    const { error } = await supabase.from("reportes_oficiales").delete().eq("id", r.id);
    if (error) { alert("No se pudo eliminar: " + error.message); return; }
    setRecarga((x) => x + 1);
  };

  const descargarVersion = async (r) => {
    const { data, error } = await supabase.from("reportes_oficiales_detalle")
      .select("*").eq("reporte_id", r.id);
    if (error) { alert("No se pudo recuperar: " + error.message); return; }
    /* Se reconstruye con el MISMO formato con que se envió: si el semanal
       saliera aquí con el formato del presupuesto, la copia no coincidiría
       con la que Dirección tiene, y el archivo dejaría de servir de evidencia. */
    if (r.tipo === "transacciones") {
      generarPdfSemanal({ compania: r.compania, periodoIni: r.periodo_ini, periodoFin: r.periodo_fin,
        version: r.version, filas: data || [], gruposZona });
      await new Promise((res) => setTimeout(res, 900));
      await generarExcelSemanal({ compania: r.compania, periodoIni: r.periodo_ini, periodoFin: r.periodo_fin,
        version: r.version, filas: data || [], gruposZona });
    } else {
      generarPdfOficial({ compania: r.compania, tipo: r.tipo, periodo: r.periodo, version: r.version, filas: data || [] });
      await new Promise((res) => setTimeout(res, 900));
      // Sin hoja de transacciones al reconstruir: solo se congeló lo reportado,
      // y las transacciones de hoy no son las que existían entonces.
      await generarExcelOficial({ compania: r.compania, tipo: r.tipo, periodo: r.periodo,
        version: r.version, filas: data || [], transacciones: [] });
    }
  };



  // --- Desviaciones agrupadas por área, que es a quien se le pregunta ---
  const porArea = {};
  desviaciones.forEach((d) => {
    const a = d.area || "Sin área";
    if (!porArea[a]) porArea[a] = { area: a, cats: new Map(), n: 0 };
    porArea[a].n++;
    const c = porArea[a].cats;
    if (!c.has(d.categoria)) c.set(d.categoria, []);
    c.get(d.categoria).push(d);
  });
  const areas = Object.values(porArea).sort((a, b) => b.n - a.n);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, padding: 3, alignSelf: "flex-start" }}>
        {[{ id: "presupuesto", label: "Presupuesto mensual" }, { id: "transacciones", label: "Transacciones semanales" }].map((x) => (
          <button key={x.id} onClick={() => setSub(x.id)}
            style={{ padding: "7px 16px", borderRadius: 6, border: "none", cursor: "pointer",
                     background: sub === x.id ? T.accent : "transparent",
                     color: sub === x.id ? "#FFFFFF" : T.textDim,
                     fontWeight: 600, fontSize: 12.5, fontFamily: T.fontUI }}>
            {x.label}
          </button>
        ))}
      </div>

      <Panel
        title={`Versiones enviadas — ${unidad}`}
        subtitle="La generación vive en Partidas y Transacciones, junto a los datos. Aquí se consulta el historial y se vuelve a descargar lo enviado."
      >
        <div style={{ display: "flex", gap: 10, alignItems: "flex-end", marginBottom: 14, flexWrap: "wrap" }}>
          {esPresupuesto ? (
            <>
              <Field label="Mes"><Select value={mesRep} onChange={(e) => setMesRep(e.target.value)}>
                {MESES.map((m) => <option key={m}>{m}</option>)}</Select></Field>
              <Field label="Año"><TextInput type="number" value={anioRep} onChange={(e) => setAnioRep(e.target.value)} style={{ width: 100 }} /></Field>
            </>
          ) : (
            <Field label="Semana (lunes)">
              <TextInput type="date" value={semanaRep} onChange={(e) => setSemanaRep(lunesDe(e.target.value))} />
            </Field>
          )}
        </div>

        {!yaEnviados.length ? (
          <div style={{ fontSize: 12.5, color: T.textFaint, padding: "12px 0" }}>
            Sin envíos de {periodo}. Se generan desde {esPresupuesto ? "Partidas" : "Transacciones"},
            en el panel de exportación.
          </div>
        ) : (
          <div style={{ fontSize: 11.5, color: T.textDim }}>
            {yaEnviados.sort((a, b) => a.version - b.version).map((r) => (
              <span key={r.id} style={{ marginRight: 14, whiteSpace: "nowrap" }}>
                <button type="button" onClick={() => descargarVersion(r)}
                  title="Volver a descargar los documentos, tal como se enviaron"
                  style={{ background: "transparent", border: "none", padding: 0,
                           color: T.accent, cursor: "pointer", fontFamily: T.fontMono, fontSize: 11.5 }}>
                  v{r.version} ({new Date(r.enviado_en).toLocaleDateString("es-MX")}, {r.n_registros} reg.)
                </button>
                {/* Solo la ÚLTIMA se puede deshacer: borrar una intermedia
                    dejaría huecos y haría dudar si faltó un envío. */}
                {r.version === Math.max(...yaEnviados.map((x) => x.version)) && (
                  <button type="button" onClick={() => deshacerVersion(r)}
                    title="Eliminar este registro — solo si se generó por error"
                    style={{ background: "transparent", border: "none", padding: "0 0 0 5px",
                             color: T.textFaint, cursor: "pointer", fontSize: 12 }}>
                    ✕
                  </button>
                )}
              </span>
            ))}
          </div>
        )}
      </Panel>

      <Panel
        title="Gasto imprevisto"
        subtitle="Combinaciones de área y categoría que no aparecen en ningún reporte oficial — lo que hay que revisar con cada área"
      >
        {cargando ? (
          <div style={{ color: T.textFaint, fontSize: 12.5, padding: 20, textAlign: "center" }}>Cargando…</div>
        ) : !reportado.length ? (
          <div style={{ borderLeft: `3px solid ${T.amber}`, background: "#FDF8EF", padding: "10px 13px", borderRadius: "0 6px 6px 0", fontSize: 12 }}>
            <b>Todavía no hay línea base</b>
            Registra el primer reporte oficial para que la app pueda distinguir lo planeado de lo imprevisto.
            Antes de eso, todo sería imprevisto y no diría nada.
          </div>
        ) : !areas.length ? (
          <div style={{ color: T.teal, fontSize: 12.5, padding: 16, textAlign: "center" }}>
            Nada fuera de lo reportado en {periodo}.
          </div>
        ) : (
          <>
            <div style={{ fontSize: 11.5, color: T.textFaint, marginBottom: 12 }}>
              {desviaciones.length} de {filas.length} registros de {periodo} no estaban contemplados.
              Se compara por área: que otra área haya reportado la misma categoría no cuenta.
            </div>
            {areas.map((a) => (
              <div key={a.area} style={{ marginBottom: 14, border: `1px solid ${T.borderSoft}`, borderRadius: 8, overflow: "hidden" }}>
                <div style={{ background: T.panelAlt, padding: "9px 13px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontWeight: 700, fontSize: 13 }}>{a.area}</span>
                  <span style={{ fontSize: 11.5, color: T.textDim }}>
                    {a.cats.size} categoría(s) sin reportar · {a.n} registro(s)
                  </span>
                </div>
                {[...a.cats.entries()].map(([cat, items]) => (
                  <div key={cat} style={{ padding: "9px 13px", borderTop: `1px solid ${T.borderSoft}` }}>
                    <div style={{ display: "flex", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
                      <Pill tone="amber">{cat}</Pill>
                      <span style={{ fontSize: 11.5, color: T.textFaint }}>{items.length} registro(s)</span>
                    </div>
                    <div style={{ fontSize: 11.5, color: T.textDim, marginTop: 6 }}>
                      {items.slice(0, 4).map((x, i) => (
                        <div key={i}>
                          {x.dia ? `${x.dia} · ` : ""}{x.proveedor ? `${x.proveedor} · ` : ""}{x.concepto || "—"}
                          {x.solicitante ? ` · solicitó ${x.solicitante}` : ""}
                        </div>
                      ))}
                      {items.length > 4 && <div style={{ color: T.textFaint }}>y {items.length - 4} más…</div>}
                    </div>
                  </div>
                ))}
              </div>
            ))}
          </>
        )}
      </Panel>
    </div>
  );
}

const SUBS_CONTRATOS = [
  { id: "datos", label: "Datos recurrentes" },
  { id: "generador", label: "Diagnóstico" },
  { id: "clausulas", label: "Objeto y cláusulas" },
  { id: "expediente", label: "Expediente" },
];

/* Los datos legales de la empresa contratante. Cada campo declara a qué
   marcador de las plantillas alimenta: sin esa pista, quien captura no tiene
   forma de saber por qué un campo aparentemente menor importa, y los campos
   vacíos salen impresos en el Word como {{MARCADOR}}. */
const CAMPOS_DATOS_UNIDAD = [
  { key: "razon_social",          label: "Razón social",               req: true, marcador: "RAZON_SOCIAL_CONTRATANTE" },
  { key: "rfc",                   label: "RFC",                        req: true, upper: true, marcador: "RFC_CONTRATANTE" },
  { key: "domicilio",             label: "Domicilio fiscal",           req: true, ancho: 2, marcador: "DOMICILIO_CONTRATANTE" },
  { key: "representante",         label: "Representante legal",        req: true, marcador: "REPRESENTANTE_CONTRATANTE" },
  { key: "cargo_representante",   label: "Cargo del representante" },
  { key: "escritura",             label: "Escritura pública",          marcador: "ESCRITURA_CONTRATANTE" },
  { key: "notario",               label: "Notario",                    marcador: "NOTARIO_CONTRATANTE" },
  { key: "correo_notificaciones", label: "Correo de notificaciones",   marcador: "CORREO_CONTRATANTE" },
  { key: "correo_facturacion",    label: "Correo de facturación",      marcador: "CORREO_FACTURACION" },
  { key: "jurisdiccion",          label: "Jurisdicción",               req: true, marcador: "JURISDICCION" },
  { key: "lugar_suscripcion",     label: "Lugar de suscripción",       marcador: "LUGAR_SUSCRIPCION" },
];

const PERSONALIDADES = [
  { value: "Persona moral",                              moral: true  },
  { value: "Persona física con actividad empresarial",   moral: false },
  { value: "Persona física",                             moral: false },
];
const esMoral = (personalidad) =>
  (PERSONALIDADES.find((p) => p.value === personalidad) || PERSONALIDADES[0]).moral;
/* El RFC lo dice sin ambigüedad: 12 caracteres para moral, 13 para física. */
const moralPorRfc = (rfc) => normRfc(rfc).length === 12;

/* Los campos no son los mismos para una y otra. Una moral se constituye ante
   notario y comparece por representante; una física comparece por su propio
   derecho y lo que la identifica es la CURP. Pedir escritura y representante
   a una física no solo sobra: invita a inventarlos. */
const CAMPOS_PROVEEDOR_LEGAL = [
  { key: "rfc",           label: "RFC",                 req: true, upper: true, marcador: "RFC_PROVEEDOR" },
  { key: "razon_social",  label: "Razón social",        labelFisica: "Nombre completo",
    req: true, marcador: "RAZON_SOCIAL_PROVEEDOR" },
  { key: "personalidad",  label: "Personalidad",        marcador: "PERSONALIDAD_PROVEEDOR",
    opciones: PERSONALIDADES.map((p) => p.value) },
  { key: "curp",          label: "CURP",                upper: true, soloFisica: true },
  { key: "domicilio",     label: "Domicilio fiscal",    ancho: 2, marcador: "DOMICILIO_PROVEEDOR" },
  { key: "representante", label: "Representante legal", soloMoral: true, marcador: "REPRESENTANTE_PROVEEDOR" },
  { key: "escritura",     label: "Escritura constitutiva", soloMoral: true, marcador: "ESCRITURA_PROVEEDOR" },
  { key: "contacto",      label: "Contacto",            marcador: "CONTACTO_PROVEEDOR" },
  { key: "correo",        label: "Correo",              marcador: "CORREO_PROVEEDOR" },
];

/* Los parámetros, agrupados por para qué sirven. Los umbrales van aparte
   porque no son cláusula de ningún contrato: son las cifras que el generador
   muestra al preguntar, y el instrumento guarda con cuáles se decidió. */
const GRUPOS_PARAMETROS = [
  { grupo: "Umbrales de decisión", nota: "Cifras de referencia que el generador muestra al preguntar. No alimentan ninguna plantilla.", campos: [
    { key: "umbral_operacion", label: "Umbral por operación", tipo: "money", def: 50000 },
    { key: "umbral_acumulado", label: "Umbral acumulado",     tipo: "money", def: 200000 },
  ]},
  { grupo: "Penas y garantías", campos: [
    { key: "pena_diaria_pct",       label: "Pena convencional diaria",   tipo: "pct",   def: 1,  marcador: "PENA_PORCENTAJE" },
    { key: "pena_tope_pct",         label: "Tope de la pena",            tipo: "pct",   def: 10, marcador: "PENA_TOPE" },
    { key: "garantia_pct",          label: "Garantía de cumplimiento",   tipo: "pct",   def: 10, marcador: "GARANTIA_PORCENTAJE" },
    { key: "garantia_plazo_dias",   label: "Plazo para entregarla",      tipo: "dias",  def: 10, marcador: "PLAZO_GARANTIA_DIAS" },
    { key: "garantia_vicios_meses", label: "Garantía por vicios ocultos",tipo: "meses", def: 12, marcador: "GARANTIA_VICIOS_MESES" },
  ]},
  { grupo: "Plazos", campos: [
    { key: "plazo_pago_dias",        label: "Plazo de pago",            tipo: "dias", def: 30, marcador: "PLAZO_PAGO_DIAS" },
    { key: "plazo_aceptacion_dias",  label: "Plazo de aceptación",      tipo: "dias", def: 3,  marcador: "PLAZO_ACEPTACION_DIAS" },
    { key: "dias_rechazo",           label: "Días para rechazar",       tipo: "dias", def: 5,  marcador: "DIAS_RECHAZO" },
    { key: "aviso_terminacion_dias", label: "Aviso de terminación",     tipo: "dias", def: 15, marcador: "AVISO_TERMINACION_DIAS" },
    { key: "aviso_ajuste_dias",      label: "Aviso de ajuste de precios",tipo: "dias", def: 30, marcador: "AVISO_AJUSTE_DIAS" },
  ]},
  { grupo: "Vigencias de obligaciones", campos: [
    { key: "confidencialidad_anos", label: "Confidencialidad", tipo: "anos", def: 5, marcador: "CONFIDENCIALIDAD_ANOS" },
    { key: "auditoria_anos",        label: "Auditoría",        tipo: "anos", def: 5, marcador: "AUDITORIA_ANOS" },
  ]},
];
const CAMPOS_PARAMETROS = GRUPOS_PARAMETROS.flatMap((g) => g.campos);

const SENTIDOS_32D = [
  { value: "", label: "— sin registrar —" },
  { value: "positiva", label: "Positiva" },
  { value: "negativa", label: "Negativa" },
  { value: "sin_obligaciones", label: "Sin obligaciones" },
  { value: "suspendido", label: "Suspendido" },
];
const NIVELES_DD = [
  { value: "simplificada", label: "Simplificada" },
  { value: "estandar", label: "Estándar" },
  { value: "reforzada", label: "Reforzada" },
];

const hoyISO = () => new Date().toISOString().slice(0, 10);
const normRfc = (v) => String(v || "").trim().toUpperCase();

function sufijoParametro(tipo) {
  return tipo === "pct" ? "%" : tipo === "dias" ? "días" : tipo === "meses" ? "meses" : tipo === "anos" ? "años" : "";
}
function formatParametro(valor, tipo) {
  const n = Number(valor);
  if (!Number.isFinite(n)) return "—";
  if (tipo === "money") return `$${numMx(n)}`;
  const suf = sufijoParametro(tipo);
  return suf ? `${n} ${suf}` : String(n);
}

/* Etiqueta del marcador que alimenta un campo. Se muestra bajo el input en
   monoespaciado para que se lea como lo que es: el texto literal que va a
   quedar en el Word si el campo se deja vacío. */
function MarcadorHint({ marcador }) {
  if (!marcador) return null;
  return (
    <span style={{ fontSize: 10, color: T.textFaint, fontFamily: T.fontMono, marginTop: 3 }}>
      {"{{" + marcador + "}}"}
    </span>
  );
}

/**
 * Datos legales de la empresa contratante — una fila por unidad.
 *
 * No usa useCollection: esa tabla tiene a `unidad` como llave primaria y no
 * tiene columna `id`, que es de lo que dependen update() y remove(). Y de
 * todos modos no es una colección, es un formulario de un solo registro.
 */
function DatosUnidadPanel({ unidad, session }) {
  const vacio = Object.fromEntries(CAMPOS_DATOS_UNIDAD.map((c) => [c.key, ""]));
  const [form, setForm] = useState({ ...vacio, jurisdiccion: "Zapopan, Jalisco" });
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [existia, setExistia] = useState(false);
  const [guardadoEn, setGuardadoEn] = useState(null);
  const [error, setError] = useState("");

  useEffect(() => {
    let vivo = true;
    (async () => {
      setCargando(true);
      setError("");
      try {
        const { data, error: e } = await supabase
          .from("contratos_datos_unidad").select("*").eq("unidad", unidad).maybeSingle();
        if (e) throw e;
        if (!vivo) return;
        if (data) {
          setForm({ ...vacio, ...Object.fromEntries(CAMPOS_DATOS_UNIDAD.map((c) => [c.key, data[c.key] || ""])) });
          setExistia(true);
          setGuardadoEn(data.actualizado_en || null);
        } else {
          setForm({ ...vacio, jurisdiccion: "Zapopan, Jalisco" });
          setExistia(false);
          setGuardadoEn(null);
        }
      } catch (err) {
        if (vivo) setError(err.message || String(err));
      } finally {
        if (vivo) setCargando(false);
      }
    })();
    return () => { vivo = false; };
  }, [unidad]);

  const faltantes = CAMPOS_DATOS_UNIDAD.filter((c) => c.req && !String(form[c.key] || "").trim());

  const guardar = async () => {
    if (faltantes.length) {
      alert("Faltan campos obligatorios: " + faltantes.map((c) => c.label).join(", "));
      return;
    }
    setGuardando(true);
    setError("");
    try {
      const fila = { unidad, actualizado_en: new Date().toISOString() };
      CAMPOS_DATOS_UNIDAD.forEach((c) => {
        const v = String(form[c.key] || "").trim();
        fila[c.key] = c.upper ? v.toUpperCase() : v;
      });
      if (session?.user?.id) fila.actualizado_por = session.user.id;
      const { error: e } = await supabase
        .from("contratos_datos_unidad").upsert(fila, { onConflict: "unidad" });
      if (e) throw e;
      setExistia(true);
      setGuardadoEn(fila.actualizado_en);
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setGuardando(false);
    }
  };

  return (
    <Panel
      title={`Datos legales — ${unidad}`}
      subtitle="Quién contrata. Alimenta la mitad de los marcadores de las cinco plantillas."
      right={
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          {guardadoEn && <span style={{ fontSize: 11, color: T.textFaint }}>Guardado {formatFechaHora(guardadoEn)}</span>}
          <Button onClick={guardar} disabled={guardando || cargando}>
            {guardando ? "Guardando…" : existia ? "Guardar cambios" : "Crear registro"}
          </Button>
        </div>
      }
    >
      {cargando ? (
        <div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div>
      ) : (
        <>
          {!existia && (
            <div style={{ fontSize: 12, color: T.textDim, background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 6, padding: "10px 12px", marginBottom: 14 }}>
              {unidad} todavía no tiene datos legales capturados. Sin esta fila no se pueden crear parámetros,
              porque las dos tablas dependen de ella.
            </div>
          )}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 14 }}>
            {CAMPOS_DATOS_UNIDAD.map((c) => (
              <Field
                key={c.key}
                label={c.req ? `${c.label} *` : c.label}
                style={c.ancho === 2 ? { gridColumn: "span 2" } : undefined}
              >
                <TextInput
                  value={form[c.key] || ""}
                  onChange={(e) => setForm({ ...form, [c.key]: c.upper ? e.target.value.toUpperCase() : e.target.value })}
                />
                <MarcadorHint marcador={c.marcador} />
              </Field>
            ))}
          </div>
          {error && <div style={{ marginTop: 12, fontSize: 12, color: T.red }}>No se pudo guardar: {error}</div>}
        </>
      )}
    </Panel>
  );
}

/**
 * Parámetros versionados.
 *
 * Guardar NUNCA sobrescribe: inserta una fila con una fecha de vigencia
 * nueva. Los instrumentos ya emitidos guardan el id de la versión con la que
 * se generaron, así que cambiar un umbral hoy no reescribe lo que se firmó
 * el año pasado. La UI tenía que dejar eso evidente, no darlo por entendido.
 */
function ParametrosPanel({ unidad, parametrosApi, session, hayDatosUnidad }) {
  const versiones = parametrosApi.rows
    .filter((p) => p.unidad === unidad)
    .sort((a, b) => String(b.vigente_desde).localeCompare(String(a.vigente_desde)));
  const hoy = hoyISO();
  const vigente = versiones.find((v) => String(v.vigente_desde) <= hoy) || null;
  const futuras = versiones.filter((v) => String(v.vigente_desde) > hoy);

  const [abierto, setAbierto] = useState(false);
  const [guardando, setGuardando] = useState(false);
  const [desde, setDesde] = useState(hoy);
  const [form, setForm] = useState(() =>
    Object.fromEntries(CAMPOS_PARAMETROS.map((c) => [c.key, c.def])));

  const abrirEditor = () => {
    const base = vigente
      ? Object.fromEntries(CAMPOS_PARAMETROS.map((c) => [c.key, vigente[c.key] ?? c.def]))
      : Object.fromEntries(CAMPOS_PARAMETROS.map((c) => [c.key, c.def]));
    setForm(base);
    setDesde(hoy);
    setAbierto(true);
  };

  const cambiados = vigente
    ? CAMPOS_PARAMETROS.filter((c) => Number(form[c.key]) !== Number(vigente[c.key] ?? c.def))
    : [];

  const guardar = async () => {
    if (!desde) { alert("Indica desde cuándo rige esta versión."); return; }
    if (versiones.some((v) => String(v.vigente_desde) === desde)) {
      alert(`Ya existe una versión que rige desde el ${desde}. Elige otra fecha.`);
      return;
    }
    if (vigente && !cambiados.length) {
      alert("No hay ningún valor distinto al de la versión vigente. No tiene caso crear una versión igual.");
      return;
    }
    const resumen = vigente
      ? `Se va a crear una versión nueva vigente desde ${desde}, con ${cambiados.length} valor(es) distinto(s):\n\n` +
        cambiados.map((c) => `  ${c.label}: ${formatParametro(vigente[c.key] ?? c.def, c.tipo)} → ${formatParametro(form[c.key], c.tipo)}`).join("\n") +
        `\n\nLa versión anterior NO se borra: los instrumentos ya emitidos la conservan.\n\n¿Continuar?`
      : `Se va a crear la primera versión de parámetros de ${unidad}, vigente desde ${desde}.\n\n¿Continuar?`;
    if (!confirm(resumen)) return;

    setGuardando(true);
    try {
      const fila = { id: uid(), unidad, vigente_desde: desde };
      CAMPOS_PARAMETROS.forEach((c) => { fila[c.key] = Number(form[c.key]) || 0; });
      if (session?.user?.id) fila.creado_por = session.user.id;
      await parametrosApi.insert(fila);
      setAbierto(false);
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally {
      setGuardando(false);
    }
  };

  return (
    <Panel
      title="Parámetros"
      subtitle="Umbrales, penas y plazos. Versionados por fecha: guardar crea una versión, no sobrescribe la anterior."
      right={
        <Button onClick={abierto ? () => setAbierto(false) : abrirEditor} variant={abierto ? "ghost" : "primary"} disabled={!hayDatosUnidad}>
          {abierto ? "Cancelar" : vigente ? "Nueva versión" : "Crear primera versión"}
        </Button>
      }
    >
      {!hayDatosUnidad && (
        <div style={{ fontSize: 12, color: T.textDim, marginBottom: 12 }}>
          Captura primero los datos legales de {unidad}: los parámetros dependen de esa fila.
        </div>
      )}

      {hayDatosUnidad && !vigente && !abierto && (
        <EmptyState
          title={`${unidad} no tiene parámetros`}
          body="Sin una versión vigente, el generador no sabe qué umbrales mostrar ni con qué llenar las cláusulas de penas y plazos."
        />
      )}

      {vigente && !abierto && (
        <>
          <div style={{ fontSize: 11.5, color: T.textFaint, marginBottom: 12 }}>
            Rige desde {vigente.vigente_desde}
            {versiones.length > 1 ? ` · ${versiones.length} versiones en total` : ""}
          </div>
          {GRUPOS_PARAMETROS.map((g) => (
            <div key={g.grupo} style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 8 }}>{g.grupo}</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: 10 }}>
                {g.campos.map((c) => (
                  <div key={c.key} style={{ background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 6, padding: "9px 11px" }}>
                    <div style={{ fontSize: 11, color: T.textDim }}>{c.label}</div>
                    <div style={{ fontSize: 14, fontWeight: 700, color: T.text, marginTop: 3 }}>
                      {formatParametro(vigente[c.key], c.tipo)}
                    </div>
                    <MarcadorHint marcador={c.marcador} />
                  </div>
                ))}
              </div>
            </div>
          ))}
          {futuras.length > 0 && (
            <div style={{ fontSize: 12, color: T.textDim, background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 6, padding: "9px 11px" }}>
              Hay {futuras.length} versión(es) programada(s) a futuro: {futuras.map((v) => v.vigente_desde).join(", ")}.
            </div>
          )}
        </>
      )}

      {abierto && (
        <>
          <div style={{ display: "flex", alignItems: "flex-end", gap: 14, marginBottom: 16, flexWrap: "wrap" }}>
            <Field label="Rige desde *" style={{ maxWidth: 190 }}>
              <TextInput type="date" value={desde} onChange={(e) => setDesde(e.target.value)} />
            </Field>
            <div style={{ fontSize: 12, color: T.textDim, paddingBottom: 9 }}>
              {vigente
                ? `La versión del ${vigente.vigente_desde} se conserva intacta.`
                : "Primera versión de esta unidad."}
            </div>
          </div>
          {GRUPOS_PARAMETROS.map((g) => (
            <div key={g.grupo} style={{ marginBottom: 18 }}>
              <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim }}>{g.grupo}</div>
              {g.nota && <div style={{ fontSize: 11, color: T.textFaint, marginTop: 2, marginBottom: 8 }}>{g.nota}</div>}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 12, marginTop: g.nota ? 0 : 8 }}>
                {g.campos.map((c) => {
                  const distinto = vigente && Number(form[c.key]) !== Number(vigente[c.key] ?? c.def);
                  return (
                    <Field key={c.key} label={`${c.label}${sufijoParametro(c.tipo) ? ` (${sufijoParametro(c.tipo)})` : ""}`}>
                      <TextInput
                        type="number" step={c.tipo === "money" || c.tipo === "pct" ? "0.01" : "1"}
                        value={form[c.key] ?? ""}
                        onChange={(e) => setForm({ ...form, [c.key]: e.target.value })}
                        style={distinto ? { borderColor: T.accent } : undefined}
                      />
                      {distinto
                        ? <span style={{ fontSize: 10.5, color: T.accent, marginTop: 3 }}>antes {formatParametro(vigente[c.key] ?? c.def, c.tipo)}</span>
                        : <MarcadorHint marcador={c.marcador} />}
                    </Field>
                  );
                })}
              </div>
            </div>
          ))}
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            <Button onClick={guardar} disabled={guardando}>
              {guardando ? "Guardando…" : "Crear versión"}
            </Button>
            <Button variant="ghost" onClick={() => setAbierto(false)}>Cancelar</Button>
            {vigente && (
              <span style={{ fontSize: 12, color: cambiados.length ? T.accent : T.textFaint }}>
                {cambiados.length ? `${cambiados.length} valor(es) distinto(s)` : "Sin cambios respecto a la versión vigente"}
              </span>
            )}
          </div>
        </>
      )}

      {versiones.length > 1 && !abierto && (
        <div style={{ marginTop: 16, borderTop: `1px solid ${T.border}`, paddingTop: 12 }}>
          <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 8 }}>Historial</div>
          {versiones.map((v) => (
            <div key={v.id} style={{ display: "flex", gap: 12, alignItems: "center", fontSize: 12, color: T.textDim, padding: "5px 0" }}>
              <span style={{ fontFamily: T.fontMono }}>{v.vigente_desde}</span>
              {v.id === vigente?.id && <Pill>vigente</Pill>}
              {String(v.vigente_desde) > hoy && <Pill>programada</Pill>}
              <span style={{ color: T.textFaint }}>
                operación {formatParametro(v.umbral_operacion, "money")} · acumulado {formatParametro(v.umbral_acumulado, "money")}
              </span>
            </div>
          ))}
        </div>
      )}
    </Panel>
  );
}

/**
 * Datos legales del proveedor.
 *
 * La identidad del proveedor —razón social, domicilio, representante— es
 * suya, no nuestra: no cambia según a cuál de las tres compañías le facture,
 * y por eso vive una sola vez, indexada por RFC. Lo que sí es criterio
 * nuestro (nivel de debida diligencia) va por unidad, en otra tabla.
 */
/* ----------------------------------------------------------------------
   CONSTANCIA DE SITUACIÓN FISCAL
---------------------------------------------------------------------- */

const CSF_ETIQUETAS = [
  "RFC:", "CURP:", "Denominación/Razón Social:", "Régimen Capital:", "Nombre Comercial:",
  "Nombre (s):", "Primer Apellido:", "Segundo Apellido:",
  "Fecha inicio de operaciones:", "Estatus en el padrón:", "Fecha de último cambio de estado:",
  "Código Postal:", "Tipo de Vialidad:", "Nombre de Vialidad:", "Número Exterior:",
  "Número Interior:", "Nombre de la Colonia:", "Nombre de la Localidad:",
  "Nombre del Municipio o Demarcación Territorial:", "Nombre de la Entidad Federativa:",
  "Entre Calle:", "Y Calle:",
];

/* Encabezados de sección. No son campos, pero marcan dónde termina el valor
   del campo anterior: sin ellos, el último campo de cada bloque se traga todo
   hasta la siguiente etiqueta — "Y Calle" se llevaba las tres páginas, con
   obligaciones fiscales y sello digital incluidos. */
const CSF_CORTES = [
  "Datos de Identificación del Contribuyente:", "Datos del domicilio registrado",
  "Actividades Económicas:", "Regímenes:", "Obligaciones:", "Página",
  "Sus datos personales", "Cadena Original Sello:",
];

const sinAcentosMay = (s) =>
  String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase();

/**
 * El texto que devuelve el extractor de PDF no respeta el acomodo visual: el
 * CSF mete dos pares etiqueta:valor por renglón, y los espacios se pierden de
 * forma impredecible — "Estatusen elpadrón", "Nombre de laColonia",
 * "Nombre delMunicipioo Demarcación Territorial". Buscar las etiquetas como
 * texto literal falla en la mitad de los casos.
 *
 * Por eso la búsqueda corre sobre una copia sin espacios ni acentos, con un
 * mapa de vuelta a la posición original de cada carácter. El valor se recorta
 * del texto ORIGINAL, con sus espacios intactos, entre el fin de una etiqueta
 * y el inicio de la siguiente.
 */
function parsearCSF(texto) {
  const mapa = [];
  let compacto = "";
  for (let i = 0; i < texto.length; i++) {
    if (/\s/.test(texto[i])) continue;
    compacto += sinAcentosMay(texto[i]);
    mapa.push(i);
  }

  const hallazgos = [];
  const buscarTodas = (aguja, etiqueta) => {
    const a = sinAcentosMay(aguja).replace(/\s/g, "");
    let desde = 0, p;
    while ((p = compacto.indexOf(a, desde)) !== -1) {
      hallazgos.push({ etiqueta, ini: p, fin: p + a.length });
      desde = p + a.length;
    }
  };
  CSF_CORTES.forEach((c) => buscarTodas(c, null));
  CSF_ETIQUETAS.forEach((e) => buscarTodas(e, e));
  hallazgos.sort((a, b) => a.ini - b.ini);

  const campos = {};
  hallazgos.forEach((h, i) => {
    if (h.etiqueta === null) return;
    if (campos[h.etiqueta] !== undefined) return;   // se queda la primera aparición
    const sig = hallazgos[i + 1];
    const desde = mapa[h.fin];
    if (desde === undefined) return;
    const hasta = sig ? mapa[sig.ini] : texto.length;
    campos[h.etiqueta] = texto.slice(desde, hasta).replace(/\s+/g, " ").trim().slice(0, 200);
  });
  return campos;
}

/* El CSF escribe el régimen completo; un contrato lleva la abreviatura. */
const CSF_REGIMENES = [
  [/SOCIEDAD ANONIMA PROMOTORA DE INVERSION DE CAPITAL VARIABLE/, "S.A.P.I. DE C.V."],
  [/SOCIEDAD ANONIMA BURSATIL DE CAPITAL VARIABLE/, "S.A.B. DE C.V."],
  [/SOCIEDAD DE RESPONSABILIDAD LIMITADA DE CAPITAL VARIABLE/, "S. DE R.L. DE C.V."],
  [/SOCIEDAD ANONIMA DE CAPITAL VARIABLE/, "S.A. DE C.V."],
  [/SOCIEDAD DE RESPONSABILIDAD LIMITADA/, "S. DE R.L."],
  [/SOCIEDAD EN NOMBRE COLECTIVO/, "S. EN N.C."],
  [/SOCIEDAD ANONIMA/, "S.A."],
  [/SOCIEDAD CIVIL/, "S.C."],
  [/ASOCIACION CIVIL/, "A.C."],
];
function abreviarRegimen(r) {
  const t = sinAcentosMay(r);
  for (const [rx, ab] of CSF_REGIMENES) if (rx.test(t)) return ab;
  return "";
}

function datosDesdeCSF(texto) {
  const c = parsearCSF(texto);
  const rfc = String(c["RFC:"] || "").toUpperCase().replace(/[^A-Z0-9&Ñ]/g, "");
  if (!/^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/.test(rfc)) {
    throw new Error("No se encontró un RFC con forma válida. ¿El PDF es una Constancia de Situación Fiscal?");
  }
  const moral = rfc.length === 12;

  const nombreFisica = [c["Nombre (s):"], c["Primer Apellido:"], c["Segundo Apellido:"]]
    .filter(Boolean).join(" ").trim();
  const base = c["Denominación/Razón Social:"] || nombreFisica || "";
  const abrev = moral ? abreviarRegimen(c["Régimen Capital:"]) : "";

  const domicilio = [
    [c["Tipo de Vialidad:"], c["Nombre de Vialidad:"]].filter(Boolean).join(" "),
    c["Número Exterior:"] ? `NO. ${c["Número Exterior:"]}` : "",
    c["Número Interior:"] ? `INT. ${c["Número Interior:"]}` : "",
    c["Nombre de la Colonia:"] ? `COL. ${c["Nombre de la Colonia:"]}` : "",
    c["Nombre de la Localidad:"],
    c["Nombre del Municipio o Demarcación Territorial:"],
    c["Nombre de la Entidad Federativa:"],
    c["Código Postal:"] ? `C.P. ${c["Código Postal:"]}` : "",
  ].filter(Boolean).join(", ");

  /* El régimen aparece en la tabla de la página 2. Distingue a quien factura
     como actividad empresarial de quien no, que es lo que decide si el
     contrato puede pactar suministro o solo servicios. */
  const empresarial = /ACTIVIDADES?\s*EMPRESARIALES/.test(sinAcentosMay(texto));

  return {
    rfc,
    razon_social: abrev ? `${base}, ${abrev}` : base,
    personalidad: moral ? "Persona moral"
      : empresarial ? "Persona física con actividad empresarial" : "Persona física",
    curp: moral ? "" : String(c["CURP:"] || "").toUpperCase().replace(/[^A-Z0-9]/g, ""),
    domicilio,
    _estatus: c["Estatus en el padrón:"] || "",
  };
}

async function leerTextoPDF(archivo) {
  const buffer = await archivo.arrayBuffer();
  const doc = await pdfjsLib.getDocument({ data: buffer }).promise;
  let texto = "";
  for (let p = 1; p <= doc.numPages; p++) {
    const pagina = await doc.getPage(p);
    const contenido = await pagina.getTextContent();
    texto += contenido.items.map((i) => i.str).join(" ") + "\n";
  }
  return texto;
}

const CAMPOS_CSF = [
  { key: "rfc", label: "RFC" },
  { key: "razon_social", label: "Razón social / nombre" },
  { key: "personalidad", label: "Personalidad" },
  { key: "curp", label: "CURP" },
  { key: "domicilio", label: "Domicilio fiscal" },
];

/**
 * Nunca escribe solo. Muestra campo por campo lo que trae el CSF junto a lo
 * que hay capturado, y el usuario decide qué aplica: un domicilio mal leído
 * que se escribe en silencio termina impreso en un contrato firmado, y a esas
 * alturas ya nadie lo revisa.
 */
function RevisionCSF({ datos, archivo, actual, onAplicar, onCerrar }) {
  const cambios = CAMPOS_CSF.map((c) => ({
    ...c,
    nuevo: datos[c.key] || "",
    viejo: String(actual[c.key] || ""),
  })).filter((c) => c.nuevo);

  const [marcados, setMarcados] = useState(
    () => new Set(cambios.filter((c) => c.nuevo !== c.viejo).map((c) => c.key)));

  const alternar = (k) => {
    const s = new Set(marcados);
    if (s.has(k)) s.delete(k); else s.add(k);
    setMarcados(s);
  };

  const inactivo = datos._estatus && !/ACTIVO/i.test(datos._estatus);

  return (
    <div style={{ background: T.panel, border: `1px solid ${T.accent}`, borderRadius: 8, padding: 15, marginBottom: 14 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 4 }}>
        <span style={{ fontSize: 12.5, fontWeight: 700, color: T.text }}>Datos leídos del CSF</span>
        <span style={{ fontSize: 11, color: T.textFaint }}>{archivo}</span>
      </div>
      <div style={{ fontSize: 11.5, color: T.textDim, marginBottom: 12 }}>
        Revisa antes de aplicar. Lo que no marques se queda como está.
      </div>

      {inactivo && (
        <div style={{ fontSize: 12, color: T.amberDim, background: T.panelAlt, border: `1px solid ${T.amber}`, borderRadius: 6, padding: "8px 11px", marginBottom: 12 }}>
          El estatus en el padrón dice «{datos._estatus}», no ACTIVO. Vale la pena confirmarlo antes de contratar.
        </div>
      )}

      {cambios.map((c) => {
        const igual = c.nuevo === c.viejo;
        return (
          <div key={c.key} style={{
            display: "grid", gridTemplateColumns: "auto 1fr", gap: 11,
            padding: "8px 0", borderTop: `1px solid ${T.borderSoft}`, alignItems: "flex-start",
          }}>
            <input type="checkbox" checked={marcados.has(c.key)} disabled={igual}
              onChange={() => alternar(c.key)} style={{ marginTop: 3 }} />
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 11, color: T.textDim }}>{c.label}</div>
              <div style={{ fontSize: 12.5, color: T.text, marginTop: 2, wordBreak: "break-word" }}>{c.nuevo}</div>
              {igual ? (
                <div style={{ fontSize: 11, color: T.textFaint, marginTop: 2 }}>Ya coincide con lo capturado</div>
              ) : c.viejo ? (
                <div style={{ fontSize: 11, color: T.amberDim, marginTop: 2, wordBreak: "break-word" }}>
                  Reemplaza: {c.viejo}
                </div>
              ) : null}
            </div>
          </div>
        );
      })}

      <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
        <Button
          onClick={() => onAplicar(Object.fromEntries(
            cambios.filter((c) => marcados.has(c.key)).map((c) => [c.key, c.nuevo])))}
          disabled={!marcados.size}
        >
          Aplicar {marcados.size} campo(s)
        </Button>
        <Button variant="ghost" onClick={onCerrar}>Descartar</Button>
      </div>
    </div>
  );
}

function ProveedorLegalPanel({ unidad, provLegalApi, provUnidadApi, session, hayDatosUnidad }) {
  const [buscar, setBuscar] = useSessionState("ss-contratos-prov-buscar", "");
  const [editando, setEditando] = useState(null);
  const [guardando, setGuardando] = useState(false);
  const [csf, setCsf] = useState(null);
  const [leyendoCsf, setLeyendoCsf] = useState(false);
  const archivoCsfRef = useRef(null);

  const filas = provLegalApi.rows
    .slice()
    .sort((a, b) => String(a.razon_social || "").localeCompare(String(b.razon_social || "")));
  const q = buscar.trim().toLowerCase();
  const visibles = q
    ? filas.filter((p) => [p.razon_social, p.rfc, p.grupo_economico].some((v) => String(v || "").toLowerCase().includes(q)))
    : filas;

  const porUnidad = (rfc) =>
    provUnidadApi.rows.find((r) => r.unidad === unidad && normRfc(r.rfc) === normRfc(rfc)) || null;

  const vacio = {
    ...Object.fromEntries(CAMPOS_PROVEEDOR_LEGAL.map((c) => [c.key, ""])),
    personalidad: "Persona moral",
    repse_registro: "", repse_vigencia: "", opinion_32d_fecha: "", opinion_32d_sentido: "",
    grupo_economico: "", notas: "", nivel_dd: "estandar", beneficiario_ctrl: false,
  };

  const abrirNuevo = () => { setCsf(null); setEditando({ ...vacio, _id: null }); };
  const abrirEditar = (p) => {
    setCsf(null);
    const pu = porUnidad(p.rfc);
    setEditando({
      ...vacio,
      ...Object.fromEntries(Object.keys(vacio).map((k) => [k, p[k] ?? vacio[k]])),
      nivel_dd: pu?.nivel_dd || "estandar",
      beneficiario_ctrl: !!pu?.beneficiario_ctrl,
      _id: p.id,
      _puId: pu?.id || null,
    });
  };

  const cargarCsf = async (e) => {
    const archivo = e.target.files?.[0];
    e.target.value = "";               // permite volver a elegir el mismo archivo
    if (!archivo) return;
    setLeyendoCsf(true);
    try {
      const texto = await leerTextoPDF(archivo);
      setCsf({ datos: datosDesdeCSF(texto), archivo: archivo.name });
    } catch (err) {
      alert("No se pudo leer el CSF: " + (err.message || err));
    } finally {
      setLeyendoCsf(false);
    }
  };

  const guardar = async () => {
    const rfc = normRfc(editando.rfc);
    if (!rfc || !String(editando.razon_social || "").trim()) {
      alert("RFC y razón social son obligatorios.");
      return;
    }
    const choque = provLegalApi.rows.find((p) => normRfc(p.rfc) === rfc && p.id !== editando._id);
    if (choque) {
      alert(`El RFC ${rfc} ya está capturado como "${choque.razon_social}". Los datos legales se guardan una sola vez por RFC, no una por compañía.`);
      return;
    }
    setGuardando(true);
    try {
      const fila = { rfc, actualizado_en: new Date().toISOString() };
      const moral = esMoral(editando.personalidad);
      CAMPOS_PROVEEDOR_LEGAL.forEach((c) => {
        if (c.key === "rfc") return;
        /* Si cambia la personalidad, lo que dejó de aplicar se limpia: un
           representante legal heredado de cuando estaba marcada como moral
           acabaría impreso en el contrato de una persona física. */
        const aplica = !(c.soloMoral && !moral) && !(c.soloFisica && moral);
        fila[c.key] = aplica ? String(editando[c.key] || "").trim() : "";
      });
      fila.repse_registro = String(editando.repse_registro || "").trim();
      fila.repse_vigencia = editando.repse_vigencia || null;
      fila.opinion_32d_fecha = editando.opinion_32d_fecha || null;
      fila.opinion_32d_sentido = editando.opinion_32d_sentido || null;
      fila.grupo_economico = String(editando.grupo_economico || "").trim();
      fila.notas = String(editando.notas || "").trim();
      if (session?.user?.id) fila.actualizado_por = session.user.id;

      if (editando._id) await provLegalApi.update(editando._id, fila);
      else await provLegalApi.insert({ id: uid(), ...fila });

      const patchUnidad = {
        unidad, rfc,
        nivel_dd: editando.nivel_dd || "estandar",
        beneficiario_ctrl: !!editando.beneficiario_ctrl,
        actualizado_en: new Date().toISOString(),
        ...(session?.user?.id ? { actualizado_por: session.user.id } : {}),
      };
      if (editando._puId) await provUnidadApi.update(editando._puId, patchUnidad);
      else await provUnidadApi.insert({ id: uid(), ...patchUnidad });

      setEditando(null);
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally {
      setGuardando(false);
    }
  };

  const eliminar = async (p) => {
    if (!confirm(`¿Eliminar los datos legales de "${p.razon_social}"? Esto no se puede deshacer.`)) return;
    try {
      const pu = porUnidad(p.rfc);
      if (pu) await provUnidadApi.remove(pu.id);
      await provLegalApi.remove(p.id);
    } catch (err) {
      alert("No se pudo eliminar: " + (err.message || err));
    }
  };

  return (
    <Panel
      title="Proveedores — datos legales"
      subtitle="Lo que ASPEL no trae: representante, escritura, REPSE, opinión 32-D. Se capturan una vez por RFC, no una por compañía."
      right={<Button onClick={abrirNuevo} disabled={!hayDatosUnidad}>+ Nuevo</Button>}
    >
      {!hayDatosUnidad && (
        <div style={{ fontSize: 12, color: T.textDim, marginBottom: 12 }}>
          Captura primero los datos legales de {unidad}: el nivel de debida diligencia se guarda por compañía y depende de esa fila.
        </div>
      )}

      {editando && (
        <div style={{ background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8, padding: 16, marginBottom: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12, flexWrap: "wrap" }}>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: T.text }}>
              {editando._id ? "Editar proveedor" : "Nuevo proveedor"}
            </span>
            <Button variant="ghost" onClick={() => archivoCsfRef.current?.click()} disabled={leyendoCsf}
              style={{ padding: "5px 12px" }}>
              {leyendoCsf ? "Leyendo…" : "Cargar desde CSF"}
            </Button>
            <input ref={archivoCsfRef} type="file" accept="application/pdf,.pdf"
              onChange={cargarCsf} style={{ display: "none" }} />
            <span style={{ fontSize: 11, color: T.textFaint }}>
              RFC, razón social, personalidad y domicilio. El PDF no sale de tu equipo.
            </span>
          </div>

          {csf && (
            <RevisionCSF
              datos={csf.datos}
              archivo={csf.archivo}
              actual={editando}
              onCerrar={() => setCsf(null)}
              onAplicar={(campos) => { setEditando({ ...editando, ...campos }); setCsf(null); }}
            />
          )}
          {(() => {
            const moral = esMoral(editando.personalidad);
            const rfcLargo = normRfc(editando.rfc).length;
            const discrepa = (rfcLargo === 12 || rfcLargo === 13) && moralPorRfc(editando.rfc) !== moral;
            return discrepa ? (
              <div style={{ fontSize: 12, color: T.amberDim, background: T.panelAlt, border: `1px solid ${T.amber}`, borderRadius: 6, padding: "8px 11px", marginBottom: 12 }}>
                El RFC tiene {rfcLargo} caracteres, que corresponde a una persona{" "}
                {rfcLargo === 12 ? "moral" : "física"}, pero la personalidad dice {moral ? "moral" : "física"}.
                Revisa cuál de los dos está mal antes de guardar.
              </div>
            ) : null;
          })()}

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(230px, 1fr))", gap: 13 }}>
            {CAMPOS_PROVEEDOR_LEGAL
              .filter((c) => {
                const moral = esMoral(editando.personalidad);
                return !(c.soloMoral && !moral) && !(c.soloFisica && moral);
              })
              .map((c) => (
              <Field
                key={c.key}
                label={(() => {
                  const l = !esMoral(editando.personalidad) && c.labelFisica ? c.labelFisica : c.label;
                  return c.req ? `${l} *` : l;
                })()}
                style={c.ancho === 2 ? { gridColumn: "span 2" } : undefined}
              >
                {c.opciones ? (
                  <Select value={editando[c.key] || ""} onChange={(e) => setEditando({ ...editando, [c.key]: e.target.value })}>
                    <option value="">— elegir —</option>
                    {c.opciones.map((o) => <option key={o} value={o}>{o}</option>)}
                  </Select>
                ) : (
                  <TextInput
                    value={editando[c.key] || ""}
                    onChange={(e) => setEditando({ ...editando, [c.key]: c.upper ? e.target.value.toUpperCase() : e.target.value })}
                  />
                )}
                <MarcadorHint marcador={c.marcador} />
              </Field>
            ))}
            <Field label="Registro REPSE">
              <TextInput value={editando.repse_registro || ""} onChange={(e) => setEditando({ ...editando, repse_registro: e.target.value })} />
            </Field>
            <Field label="Vigencia REPSE">
              <TextInput type="date" value={editando.repse_vigencia || ""} onChange={(e) => setEditando({ ...editando, repse_vigencia: e.target.value })} />
            </Field>
            <Field label="Fecha opinión 32-D">
              <TextInput type="date" value={editando.opinion_32d_fecha || ""} onChange={(e) => setEditando({ ...editando, opinion_32d_fecha: e.target.value })} />
            </Field>
            <Field label="Sentido 32-D">
              <Select value={editando.opinion_32d_sentido || ""} onChange={(e) => setEditando({ ...editando, opinion_32d_sentido: e.target.value })}>
                {SENTIDOS_32D.map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
              </Select>
            </Field>
            <Field label="Grupo económico">
              <TextInput value={editando.grupo_economico || ""} onChange={(e) => setEditando({ ...editando, grupo_economico: e.target.value })} />
            </Field>
            <Field label="Notas" style={{ gridColumn: "span 2" }}>
              <TextInput value={editando.notas || ""} onChange={(e) => setEditando({ ...editando, notas: e.target.value })} />
            </Field>
          </div>

          <div style={{ marginTop: 16, paddingTop: 13, borderTop: `1px solid ${T.border}` }}>
            <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 3 }}>
              Solo para {unidad}
            </div>
            <div style={{ fontSize: 11, color: T.textFaint, marginBottom: 10 }}>
              Lo de arriba es del proveedor y lo comparten las tres compañías. Esto es criterio nuestro y se guarda por separado.
            </div>
            <div style={{ display: "flex", gap: 16, alignItems: "flex-end", flexWrap: "wrap" }}>
              <Field label="Nivel de debida diligencia" style={{ maxWidth: 230 }}>
                <Select value={editando.nivel_dd} onChange={(e) => setEditando({ ...editando, nivel_dd: e.target.value })}>
                  {NIVELES_DD.map((n) => <option key={n.value} value={n.value}>{n.label}</option>)}
                </Select>
              </Field>
              <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, color: T.textDim, paddingBottom: 9, cursor: "pointer" }}>
                <input
                  type="checkbox"
                  checked={!!editando.beneficiario_ctrl}
                  onChange={(e) => setEditando({ ...editando, beneficiario_ctrl: e.target.checked })}
                />
                Beneficiario controlador identificado
              </label>
            </div>
          </div>

          <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
            <Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Button>
            <Button variant="ghost" onClick={() => setEditando(null)}>Cancelar</Button>
          </div>
        </div>
      )}

      <div style={{ marginBottom: 12 }}>
        <TextInput
          placeholder="Buscar por razón social, RFC o grupo económico…"
          value={buscar}
          onChange={(e) => setBuscar(e.target.value)}
          style={{ maxWidth: 380 }}
        />
      </div>

      {!visibles.length ? (
        <EmptyState
          title={filas.length ? "Ningún proveedor coincide" : "Sin proveedores capturados"}
          body={filas.length
            ? "Prueba con otro término de búsqueda."
            : "Los datos legales que las plantillas necesitan no están en ASPEL: representante, escritura, personalidad jurídica."}
        />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 1, background: T.border, border: `1px solid ${T.border}`, borderRadius: 6, overflow: "hidden" }}>
          {visibles.map((p) => {
            const pu = porUnidad(p.rfc);
            const repseVencido = p.repse_vigencia && String(p.repse_vigencia) < hoyISO();
            return (
              <div key={p.id} style={{ display: "flex", alignItems: "center", gap: 12, background: T.panel, padding: "10px 12px" }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 12.5, color: T.text, fontWeight: 600 }}>{p.razon_social}</div>
                  <div style={{ fontSize: 11, color: T.textFaint, fontFamily: T.fontMono, marginTop: 2 }}>
                    {p.rfc}{p.grupo_economico ? ` · ${p.grupo_economico}` : ""}
                  </div>
                </div>
                <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                  <Pill>{esMoral(p.personalidad) ? "Moral" : "Física"}</Pill>
                  {p.repse_registro && <Pill>{repseVencido ? "REPSE vencido" : "REPSE"}</Pill>}
                  {p.opinion_32d_sentido && <Pill>32-D {p.opinion_32d_sentido}</Pill>}
                  <Pill>{(NIVELES_DD.find((n) => n.value === (pu?.nivel_dd || "estandar")) || {}).label}</Pill>
                </div>
                <Button variant="ghost" onClick={() => abrirEditar(p)} style={{ padding: "5px 11px" }}>Editar</Button>
                <Button variant="danger" onClick={() => eliminar(p)} style={{ padding: "5px 11px" }}>Eliminar</Button>
              </div>
            );
          })}
        </div>
      )}
    </Panel>
  );
}

/* ----------------------------------------------------------------------
   GENERADOR DE INSTRUMENTOS CONTRACTUALES
---------------------------------------------------------------------- */

/* Compuerta 1. Cualquier sí manda a contrato específico. El gatillo 2 además
   arrastra los anexos flow-down, porque son obligaciones que venimos
   obligados a trasladar por el contrato con el cliente final. */
const GATILLOS = [
  { id: "g1", texto: "El proveedor pone personal a disposición o presta servicios especializados (REPSE)." },
  { id: "g2", texto: "El proveedor ejecuta parte del alcance de un contrato con cliente final, o ingresa a sus instalaciones." },
  { id: "g3", texto: "El servicio es intangible: asesoría, consultoría, supervisión, servicios administrativos, publicidad." },
  { id: "g4", texto: "El proveedor tratará datos personales por cuenta nuestra." },
  { id: "g5", texto: "El entregable genera propiedad intelectual: software, ingeniería, diseño, documentación técnica." },
  { id: "g6", texto: "Es parte relacionada." },
  { id: "g7", texto: "Hay anticipo, garantía, comodato, consignación, exclusividad o arrendamiento." },
];

const RIESGOS = [
  { id: "r1", texto: "Está en ruta crítica de un contrato con cliente." },
  { id: "r2", texto: "Hay contacto con servidores públicos o gestoría ante autoridades." },
  { id: "r3", texto: "Es operación transfronteriza." },
  { id: "r4", texto: "El proveedor es de reciente creación o sin infraestructura demostrable." },
];

/* Las respuestas del árbol son "si" | "no" | sin responder. El tercer estado
   es el que faltaba: con casillas, "sin marcar" y "no" se veían igual, y el
   panel anunciaba un instrumento aunque nadie hubiera contestado nada. */
const esSi = (v) => v === "si";
const RESPUESTAS_ARBOL = [...GATILLOS.map((g) => g.id), "superaOperacion", "superaAcumulado",
  ...RIESGOS.map((r) => r.id)];

/* El ancho está acotado a 760px a propósito: sin tope, en pantalla ancha el
   par Sí/No termina contra el borde derecho y el ojo tiene que recorrer media
   pantalla para relacionarlo con la pregunta que contesta. */
const ANCHO_PREGUNTAS = 760;

function PreguntaSiNo({ numero, texto, valor, onChange, apagado, preestablecida }) {
  const sinResponder = valor !== "si" && valor !== "no";
  const barra = sinResponder ? "transparent" : valor === "si" ? T.accent : T.border;
  return (
    <div style={{
      display: "grid", gridTemplateColumns: "1fr auto", alignItems: "center", gap: 18,
      padding: "9px 12px 9px 11px", borderLeft: `3px solid ${barra}`,
      background: valor === "si" && !apagado ? T.accentBg : "transparent",
      borderRadius: 4, marginBottom: 2, transition: "background 120ms",
    }}>
      <div style={{ fontSize: 12.5, lineHeight: 1.5, color: sinResponder ? T.textDim : T.text }}>
        {numero ? <span style={{ color: T.textFaint, fontVariantNumeric: "tabular-nums" }}>{numero}. </span> : null}{texto}
        {preestablecida && (
          <span style={{ fontSize: 10.5, color: T.textFaint, marginLeft: 7, whiteSpace: "nowrap" }}>
            — la da por sentada la naturaleza
          </span>
        )}
      </div>
      <div style={{
        display: "flex", gap: 2, flexShrink: 0, padding: 2, borderRadius: 7,
        background: T.panel, border: `1px solid ${T.border}`,
      }}>
        {[["si", "Sí", T.accent], ["no", "No", T.textDim]].map(([v, etiqueta, fondo]) => (
          <button
            key={v} type="button" onClick={() => onChange(v)}
            style={{
              padding: "5px 17px", borderRadius: 5, border: "none", cursor: "pointer",
              background: valor === v ? fondo : "transparent",
              color: valor === v ? "#FFFFFF" : T.textFaint,
              fontWeight: 600, fontSize: 12, fontFamily: T.fontUI, lineHeight: 1.3,
            }}
          >{etiqueta}</button>
        ))}
      </div>
    </div>
  );
}

/**
 * Un bloque por compuerta. El estado no es decorativo: "decide" marca la que
 * determinó el instrumento, y "ya no se evalúa" atenúa las posteriores,
 * porque en una cascada literalmente dejan de correr. Siguen contestables
 * -- sirve dejar constancia -- pero no cambian el resultado.
 */
function BloqueCompuerta({ n, titulo, salida, estado, children }) {
  const decide = estado === "decide";
  const muerta = estado === "inerte";
  return (
    <div style={{
      border: `1px solid ${decide ? T.accent : T.border}`, borderRadius: 8,
      background: decide ? T.panel : muerta ? "transparent" : T.panel,
      padding: "13px 14px 9px", marginBottom: 12, maxWidth: ANCHO_PREGUNTAS,
      opacity: muerta ? 0.5 : 1,
    }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 9, marginBottom: 9 }}>
        <span style={{
          fontSize: 11, fontWeight: 700, color: decide ? "#FFFFFF" : T.textDim,
          background: decide ? T.accent : T.panelAlt, borderRadius: 4,
          padding: "2px 7px", flexShrink: 0,
        }}>{n}</span>
        <span style={{ fontSize: 13, fontWeight: 600, color: T.text }}>{titulo}</span>
        <span style={{ fontSize: 11.5, color: T.textFaint, marginLeft: "auto", textAlign: "right" }}>
          {decide ? `Determina: ${salida}` : muerta ? "Ya no se evalúa" : `Si hay un sí: ${salida}`}
        </span>
      </div>
      {children}
    </div>
  );
}

/* ----------------------------------------------------------------------
   NATURALEZA DE LA CONTRATACIÓN
---------------------------------------------------------------------- */

/**
 * El paso previo al árbol. No es una clasificación paralela: tres de las
 * cuatro naturalezas ya determinan respuestas del cuestionario, porque los
 * gatillos las nombran. Preguntarlas otra vez sería pedirle al usuario que
 * deduzca lo que la categoría ya dijo.
 *
 * `fija` son las respuestas que la naturaleza da por sentadas. Se marcan
 * como preestablecidas y se pueden cambiar: son el caso normal, no una regla
 * sin excepción. Un mantenimiento que el proveedor ejecute sin personal en
 * sitio no cae en el REPSE, y quien captura debe poder decirlo.
 */
const NATURALEZAS = [
  {
    id: "arrendamiento",
    label: "Arrendamiento de oficinas o bodegas",
    tipoContrato: "ARRENDAMIENTO",
    /* El árbol lo resuelve como contrato específico, pero el proemio y las
       declaraciones de un arrendamiento no caben en la plantilla de
       servicios: lleva la suya. */
    plantilla: "contrato_arrendamiento",
    fija: { g7: "si" },
    porque: "El gatillo 7 nombra el arrendamiento entre sus supuestos.",
  },
  {
    id: "servicios_fisica",
    label: "Servicios profesionales con persona física",
    tipoContrato: "PRESTACIÓN DE SERVICIOS PROFESIONALES",
    fija: { g3: "si" },
    porque: "Un servicio profesional es intangible por definición: gatillo 3.",
    alerta: "Con persona física, cuida que el contrato no describa horario, subordinación ni herramientas nuestras: es lo que convierte una prestación de servicios en una relación laboral.",
  },
  {
    id: "servicios_moral",
    label: "Servicios con persona moral",
    tipoContrato: "PRESTACIÓN DE SERVICIOS",
    fija: {},
    porque: "No predetermina ninguna compuerta: depende de si el servicio es intangible, si entra a instalaciones del cliente y del monto.",
  },
  {
    id: "obra",
    label: "Obra civil o mantenimiento industrial",
    tipoContrato: "EJECUCIÓN DE OBRA Y MANTENIMIENTO",
    fija: { g1: "si" },
    porque: "Obra y mantenimiento industrial son obras y servicios especializados, que es el supuesto del REPSE: gatillo 1.",
  },
];

const naturalezaDe = (id) => NATURALEZAS.find((n) => n.id === id) || null;

/* Las señales que pueden sugerir una cláusula: las once casillas del árbol
   más la naturaleza elegida. Se expresan igual —"si" o nada— para que la
   biblioteca no tenga que distinguirlas. */
const senalesDe = (resp, naturaleza) =>
  naturaleza ? { ...resp, ["nat_" + naturaleza]: "si" } : resp;

function NaturalezaPanel({ naturaleza, onElegir }) {
  const n = naturalezaDe(naturaleza);
  return (
    <Panel
      title="Naturaleza de la contratación"
      subtitle="Qué se va a contratar. Responde de entrada parte del árbol, porque los gatillos nombran varias de estas figuras."
    >
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 10, maxWidth: ANCHO_PREGUNTAS }}>
        {NATURALEZAS.map((o) => {
          const activa = o.id === naturaleza;
          return (
            <button
              key={o.id}
              type="button"
              onClick={() => onElegir(o.id)}
              style={{
                textAlign: "left", cursor: "pointer", borderRadius: 8, padding: "12px 13px",
                background: activa ? T.accentBg : T.panel,
                border: `1px solid ${activa ? T.accent : T.border}`,
                fontFamily: T.fontUI,
              }}
            >
              <div style={{ fontSize: 12.5, fontWeight: 600, color: T.text, lineHeight: 1.4 }}>{o.label}</div>
              <div style={{ fontSize: 11, color: T.textFaint, marginTop: 5 }}>
                {Object.keys(o.fija).length
                  ? `Deja resuelto: ${Object.keys(o.fija).map((k) => k.toUpperCase()).join(", ")}`
                  : "No resuelve ninguna compuerta"}
              </div>
            </button>
          );
        })}
      </div>

      {n && (
        <div style={{ marginTop: 14, maxWidth: ANCHO_PREGUNTAS, fontSize: 12, color: T.textDim, lineHeight: 1.55 }}>
          {n.porque}
          {Object.keys(n.fija).length > 0 && (
            <> Esas respuestas quedan marcadas abajo y se pueden cambiar si el caso concreto no encaja.</>
          )}
          {n.alerta && (
            <div style={{ marginTop: 10, color: T.amberDim, background: T.panelAlt, border: `1px solid ${T.amber}`, borderRadius: 6, padding: "9px 11px" }}>
              {n.alerta}
            </div>
          )}
        </div>
      )}

      {!n && (
        <div style={{ marginTop: 12, fontSize: 12, color: T.textFaint }}>
          Puedes saltarte este paso y responder el árbol completo a mano.
        </div>
      )}
    </Panel>
  );
}

/**
 * Los instrumentos, en un solo lugar.
 *
 * Había dos listas paralelas: una para el árbol, con plantilla y folio, y
 * otra para las cláusulas, con el estilo de numeración. Compartían las
 * etiquetas, así que renombrar un instrumento obligaba a acordarse de tocar
 * las dos, y la segunda tenía un tipo que a la primera le faltaba.
 *
 * `estructura` es el esqueleto que aporta la plantilla; de todo eso, lo único
 * que se arma desde la biblioteca es el clausulado.
 */
const INSTRUMENTOS = {
  contrato_especifico: {
    label: "Contrato específico", plantilla: "contrato_especifico",
    prefijo: "CE", marcadorFolio: "NUM_CONTRATO", numeracion: "ordinal",
    estructura: ["Proemio y comparecencia", "Declaraciones de las partes", "Clausulado", "Lugar, fecha y firmas"],
  },
  contrato_marco: {
    label: "Contrato marco", plantilla: "contrato_marco",
    prefijo: "CM", marcadorFolio: "NUM_CONTRATO_MARCO", numeracion: "ordinal",
    estructura: ["Proemio y comparecencia", "Declaraciones de las partes", "Clausulado", "Lugar, fecha y firmas", "Anexos A–D del marco"],
  },
  /* La orden de compra la emite Contabilidad desde el SAE. Sigue siendo una
     salida del árbol —hay que decirle a quien pregunta qué corresponde— pero
     la app no la genera. Por eso no tiene plantilla ni prefijo de folio. */
  orden_compra: {
    label: "Orden de compra", externo: "Se emite desde el SAE, en Contabilidad.",
  },
  /* No sale del árbol: acompaña al contrato específico cuando aplica el
     gatillo 2. Por eso no tiene prefijo de folio propio. */
  anexo_flowdown: {
    label: "Anexos flow-down", plantilla: "anexo_flowdown", numeracion: "letra",
    estructura: ["Encabezado con referencia al contrato principal", "Anexos aplicables", "Lugar, fecha y firmas"],
  },
};
/* Solo los que la app genera: la orden de compra no aparece como opción. */
const ORDEN_INSTRUMENTOS = ["contrato_especifico", "contrato_marco", "anexo_flowdown"];

/* Qué le toca capturar al usuario según el instrumento que resultó. Sale de
   leer los marcadores reales de cada plantilla: pedir de más es ruido, y
   pedir de menos deja {{MARCADOR}} impreso en el Word. */
const CAMPOS_FORM = [
  { key: "OBJETO",                 label: "Objeto del contrato",       tipo: "texto",  ancho: 2, en: ["contrato_especifico", "contrato_marco"] },
  { key: "TIPO_CONTRATO",          label: "Tipo",                      tipo: "texto",  en: ["contrato_especifico", "contrato_marco"], ayuda: "Va en el título: «Contrato marco de ___»" },
  { key: "MONTO_NUMERO",           label: "Monto sin IVA",             tipo: "monto",  en: ["contrato_especifico"] },
  { key: "MONTO_MAXIMO",           label: "Monto máximo sin IVA",      tipo: "monto",  en: ["contrato_marco"] },
  { key: "MONEDA",                 label: "Moneda",                    tipo: "moneda", en: ["contrato_especifico"] },
  { key: "LUGAR_ENTREGA",          label: "Lugar de entrega o ejecución", tipo: "texto", en: ["contrato_especifico"] },
  { key: "VIGENCIA_INICIO",        label: "Vigencia — inicio",         tipo: "fecha",  en: ["contrato_especifico", "contrato_marco"] },
  { key: "VIGENCIA_FIN",           label: "Vigencia — fin",            tipo: "fecha",  en: ["contrato_especifico", "contrato_marco"] },
  { key: "VIGENCIA_PRECIOS",       label: "Vigencia de precios",       tipo: "texto",  en: ["contrato_marco"], ayuda: "Ej. «los primeros 12 meses»" },
  { key: "TIPO_GARANTIA",          label: "Tipo de garantía",          tipo: "texto",  en: ["contrato_especifico"], ayuda: "Fianza, cheque, retención…" },
  { key: "ADMINISTRADOR_CONTRATO", label: "Administrador del contrato", tipo: "texto", en: ["contrato_especifico"] },
  { key: "DOMICILIO_INMUEBLE", label: "Domicilio del inmueble", tipo: "texto", ancho: 2, nat: "arrendamiento", en: ["contrato_especifico"] },
  { key: "CLAVE_CATASTRAL",    label: "Clave catastral o cuenta predial", tipo: "texto", nat: "arrendamiento", en: ["contrato_especifico"] },
  { key: "USO_CONVENIDO",      label: "Uso convenido", tipo: "texto", nat: "arrendamiento", en: ["contrato_especifico"],
    ayuda: "Oficinas administrativas, bodega, etc." },
  { key: "RENTA_MENSUAL",      label: "Renta mensual", tipo: "monto", nat: "arrendamiento", en: ["contrato_especifico"] },
  { key: "DIA_PAGO_RENTA",     label: "Se paga dentro de los primeros (días hábiles)", tipo: "texto", nat: "arrendamiento", en: ["contrato_especifico"] },
  { key: "DEPOSITO_GARANTIA",  label: "Depósito en garantía", tipo: "monto", nat: "arrendamiento", en: ["contrato_especifico"] },
  { key: "TOPE_SERVICIOS",     label: "Tope de servicios a cargo de la arrendadora", tipo: "monto", nat: "arrendamiento", en: ["contrato_especifico"],
    ayuda: "Solo si marcaste esa cláusula" },
  { key: "CLIENTE_FINAL",          label: "Cliente final",             tipo: "texto",  soloFlowdown: true, en: ["contrato_especifico"] },
  { key: "NUM_CONTRATO_PRINCIPAL", label: "No. del contrato principal", tipo: "texto", soloFlowdown: true, en: ["contrato_especifico"] },
];

/* ---------- Número a letra, en español ---------- */
const NL_UNI = ["", "UNO", "DOS", "TRES", "CUATRO", "CINCO", "SEIS", "SIETE", "OCHO", "NUEVE", "DIEZ",
  "ONCE", "DOCE", "TRECE", "CATORCE", "QUINCE", "DIECISÉIS", "DIECISIETE", "DIECIOCHO", "DIECINUEVE",
  "VEINTE", "VEINTIUNO", "VEINTIDÓS", "VEINTITRÉS", "VEINTICUATRO", "VEINTICINCO", "VEINTISÉIS",
  "VEINTISIETE", "VEINTIOCHO", "VEINTINUEVE"];
const NL_DEC = ["", "", "", "TREINTA", "CUARENTA", "CINCUENTA", "SESENTA", "SETENTA", "OCHENTA", "NOVENTA"];
const NL_CEN = ["", "CIENTO", "DOSCIENTOS", "TRESCIENTOS", "CUATROCIENTOS", "QUINIENTOS", "SEISCIENTOS",
  "SETECIENTOS", "OCHOCIENTOS", "NOVECIENTOS"];

function letrasHasta999(n) {
  if (n === 0) return "";
  if (n === 100) return "CIEN";
  const c = Math.floor(n / 100), r = n % 100;
  let s = c ? NL_CEN[c] : "";
  if (r) {
    if (s) s += " ";
    if (r < 30) s += NL_UNI[r];
    else {
      const d = Math.floor(r / 10), u = r % 10;
      s += NL_DEC[d] + (u ? " Y " + NL_UNI[u] : "");
    }
  }
  return s;
}

/* "UNO" apocopa cuando le sigue un sustantivo: VEINTIÚN MIL PESOS, no
   VEINTIUNO MIL PESOS. La tilde SOLO va en "veintiún", que es aguda; el resto
   es "un" sin acento — un peso, ciento un pesos, mil un pesos. */
const apocopar = (s) => /VEINTIUNO$/.test(s) ? s.replace(/VEINTIUNO$/, "VEINTIÚN") : s.replace(/UNO$/, "UN");

function numeroALetras(n) {
  n = Math.floor(Math.abs(Number(n) || 0));
  if (n === 0) return "CERO";
  if (n >= 1e12) return String(n);
  const millones = Math.floor(n / 1e6);
  const resto = n % 1e6;
  const miles = Math.floor(resto / 1000);
  const unidades = resto % 1000;
  let s = "";
  if (millones) s += millones === 1 ? "UN MILLÓN" : numeroALetras(millones) + " MILLONES";
  if (miles) s += (s ? " " : "") + (miles === 1 ? "MIL" : apocopar(letrasHasta999(miles)) + " MIL");
  if (unidades) s += (s ? " " : "") + letrasHasta999(unidades);
  return s;
}

function importeALetra(monto, moneda) {
  const n = Math.abs(Number(monto) || 0);
  const entero = Math.floor(n);
  const centavos = Math.round((n - entero) * 100);
  const letras = apocopar(numeroALetras(entero));
  const usd = moneda === "USD";
  const unidad = usd ? (entero === 1 ? "DÓLAR AMERICANO" : "DÓLARES AMERICANOS")
                     : (entero === 1 ? "PESO" : "PESOS");
  /* Cifra exacta en millones: "un millón DE pesos". Con algo después no lleva
     preposición — "dos millones quinientos mil pesos". */
  const de = entero >= 1e6 && entero % 1e6 === 0 ? "DE " : "";
  return `${letras} ${de}${unidad} ${String(centavos).padStart(2, "0")}/100 ${usd ? "USD" : "M.N."}`;
}

/* ---------- Formato para el documento ---------- */
const MESES_LARGO = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
  "agosto", "septiembre", "octubre", "noviembre", "diciembre"];

function fechaLarga(iso) {
  if (!iso) return "";
  const [a, m, d] = String(iso).slice(0, 10).split("-").map(Number);
  if (!a || !m || !d) return String(iso);
  return `${d} de ${MESES_LARGO[m - 1]} de ${a}`;
}
const dinero = (n) => `$${numMx(Number(n) || 0)}`;
/* MXP es el código interno de la app; en un contrato lo correcto es MXN. */
const monedaContrato = (m) => (m === "USD" ? "USD" : "MXN");
const escaparXml = (v) => String(v ?? "")
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/* ---------- El árbol ---------- */
/**
 * Cuatro compuertas en cascada. La primera afirmativa decide, y las
 * siguientes ni se evalúan: por eso la ruta que se guarda nombra UNA
 * compuerta, no todas las que hubieran aplicado.
 */
function decidirInstrumento(resp) {
  const gatillos = GATILLOS.filter((g) => esSi(resp[g.id]));
  if (gatillos.length) {
    const flowdown = esSi(resp.g2);
    const n = GATILLOS.findIndex((g) => g.id === gatillos[0].id) + 1;
    return {
      tipo: "contrato_especifico",
      flowdown,
      compuerta: 1,
      ruta: `Contrato específico. Compuerta 1, gatillo obligatorio ${n}: ${gatillos[0].texto}` +
        (gatillos.length > 1 ? ` (aplican ${gatillos.length} gatillos en total).` : "") +
        (flowdown ? " Se adjuntan los anexos flow-down por el gatillo 2." : ""),
    };
  }
  if (esSi(resp.superaOperacion)) {
    return {
      tipo: "contrato_especifico", flowdown: false, compuerta: 2,
      ruta: "Contrato específico. Compuerta 2: el monto de la operación supera el umbral individual.",
    };
  }
  if (esSi(resp.superaAcumulado)) {
    return {
      tipo: "contrato_marco", flowdown: false, compuerta: 3,
      ruta: "Contrato marco más órdenes al amparo. Compuerta 3: el acumulado con el proveedor supera el umbral anual.",
    };
  }
  const riesgos = RIESGOS.filter((r) => esSi(resp[r.id]));
  if (riesgos.length) {
    const n = RIESGOS.findIndex((r) => r.id === riesgos[0].id) + 1;
    return {
      tipo: "contrato_especifico", flowdown: false, compuerta: 4,
      ruta: `Contrato específico. Compuerta 4, riesgo agravante ${n}: ${riesgos[0].texto}`,
    };
  }
  return {
    tipo: "orden_compra", flowdown: false, compuerta: 0,
    ruta: "Orden de compra con condiciones generales. Ninguna compuerta resultó afirmativa. "
      + "La emite Contabilidad desde el SAE; esta herramienta no la genera.",
  };
}

/* ---------- Folio ---------- */
/**
 * El siguiente folio se confirma contra la base, no contra el estado local:
 * dos pestañas abiertas calcularían el mismo número. Si aun así chocan, el
 * índice único (unidad, folio) rebota el insert y se reintenta.
 */
async function maxFolioInstrumentoReal(prefijo) {
  const { data, error } = await supabase
    .from("contratos_instrumentos")
    .select("folio")
    .like("folio", `${prefijo}%`)
    .order("folio", { ascending: false })
    .limit(1);
  if (error || !data?.length) return 0;
  const n = parseInt(String(data[0].folio).slice(prefijo.length), 10);
  return isNaN(n) ? 0 : n;
}

async function insertarInstrumentoConReintento(instrumentosApi, fila, unidad, tipo) {
  const anio = new Date().getFullYear();
  const prefijo = `${unidad}-${INSTRUMENTOS[tipo].prefijo}-${anio}-`;
  const siguiente = (await maxFolioInstrumentoReal(prefijo)) + 1;
  const maxIntentos = 8;
  for (let intento = 0; intento < maxIntentos; intento++) {
    const folio = `${prefijo}${String(siguiente + intento).padStart(3, "0")}`;
    try {
      return await instrumentosApi.insert({ ...fila, id: uid(), folio });
    } catch (err) {
      const chocoPorFolio = /folio|contratos_instrumentos_folio_idx/i.test(err?.message || "");
      if (!chocoPorFolio || intento === maxIntentos - 1) throw err;
    }
  }
}

/* ---------- Llenado del .docx ---------- */
/**
 * Las plantillas se generaron con runs contiguos: cada {{MARCADOR}} existe
 * como cadena completa dentro del XML, así que basta un reemplazo de texto.
 * Verificado sobre los cinco archivos — cero marcadores partidos.
 *
 * Un marcador sin valor NO se vacía: se deja tal cual, para que el hueco se
 * vea en el Word en lugar de pasar inadvertido. La función devuelve cuáles
 * quedaron sin resolver para poder avisarlo antes de la descarga.
 */
/* Los contratos se emiten íntegramente en mayúscula. Se aplica sobre los
   nodos de texto del XML ya armado, de modo que cubra por igual los valores
   sustituidos, el clausulado de la biblioteca y el texto fijo de la
   plantilla: hacerlo solo en la parte generada dejaría el documento mitad y
   mitad. Las entidades XML se saltan — &amp; no puede volverse &AMP;. */
const CONTRATOS_EN_MAYUSCULAS = true;

function mayusculasXml(xml) {
  return xml.replace(/(<w:t\b[^>]*>)([\s\S]*?)(<\/w:t>)/g, (todo, ini, txt, fin) =>
    ini + txt.split(/(&[a-zA-Z]+;|&#\d+;)/)
             .map((p, i) => (i % 2 ? p : p.toLocaleUpperCase("es-MX")))
             .join("") + fin);
}

async function llenarPlantilla(storagePath, valores, clausuladoXML) {
  const { data, error } = await supabase.storage.from("contratos-plantillas").download(storagePath);
  if (error) throw new Error(`No se pudo descargar la plantilla (${storagePath}): ${error.message}`);

  const zip = await JSZip.loadAsync(data);
  const partes = Object.keys(zip.files).filter((n) =>
    /^word\/(document|header\d*|footer\d*|footnotes|endnotes)\.xml$/.test(n));
  const sinResolver = new Set();
  let huboClausulado = false;

  for (const parte of partes) {
    let xml = await zip.file(parte).async("string");

    /* El clausulado se inyecta ANTES de resolver marcadores, para que los
       {{MARCADORES}} que traen las cláusulas se sustituyan en la misma
       pasada que los de la plantilla. */
    if (clausuladoXML !== undefined) {
      const r = inyectarClausulado(xml, clausuladoXML);
      xml = r.xml;
      if (r.encontrado) huboClausulado = true;
    }

    const nuevo = xml.replace(/\{\{([A-Z_0-9]+)\}\}/g, (todo, clave) => {
      const v = valores[clave];
      if (v === undefined || v === null || v === "") { sinResolver.add(clave); return todo; }
      return escaparXml(v);
    });
    zip.file(parte, CONTRATOS_EN_MAYUSCULAS ? mayusculasXml(nuevo) : nuevo);
  }

  const blob = await zip.generateAsync({
    type: "blob",
    mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  });
  return { blob, sinResolver: [...sinResolver].sort(), huboClausulado };
}

function descargarBlob(blob, nombre) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = nombre;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1500);
}

function GeneradorPanel({ unidad, parametrosApi, provLegalApi, instrumentosApi, resp, setResp, naturaleza, setNaturaleza, objeto, setObjeto, itemsClausulado, itemsAnexo, session }) {
  const [datosUnidad, setDatosUnidad] = useState(null);
  const [cargando, setCargando] = useState(true);
  const [rfc, setRfc] = useState("");
  const [form, setForm] = useState({ MONEDA: "MXP" });
  const [trabajando, setTrabajando] = useState(false);
  const [resultado, setResultado] = useState(null);

  useEffect(() => {
    let vivo = true;
    (async () => {
      setCargando(true);
      try {
        const { data } = await supabase
          .from("contratos_datos_unidad").select("*").eq("unidad", unidad).maybeSingle();
        if (vivo) setDatosUnidad(data || null);
      } finally {
        if (vivo) setCargando(false);
      }
    })();
    return () => { vivo = false; };
  }, [unidad]);

  useEffect(() => { setRfc(""); setResultado(null); }, [unidad]);

  const hoy = hoyISO();
  const parametros = parametrosApi.rows
    .filter((p) => p.unidad === unidad && String(p.vigente_desde) <= hoy)
    .sort((a, b) => String(b.vigente_desde).localeCompare(String(a.vigente_desde)))[0] || null;

  const proveedor = provLegalApi.rows.find((p) => normRfc(p.rfc) === normRfc(rfc)) || null;
  const decision = decidirInstrumento(resp);
  const sinResponder = RESPUESTAS_ARBOL.filter((k) => resp[k] !== "si" && resp[k] !== "no");
  const fijasPorNaturaleza = naturalezaDe(naturaleza)?.fija || {};
  const estadoCompuerta = (n) =>
    decision.compuerta === n ? "decide"
    : decision.compuerta !== 0 && n > decision.compuerta ? "inerte"
    : "abierta";
  const meta = INSTRUMENTOS[decision.tipo];

  const campos = CAMPOS_FORM.filter(
    (c) => c.en.includes(decision.tipo)
      && (!c.soloFlowdown || decision.flowdown)
      /* Un campo marcado con `nat` solo existe para esa naturaleza: pedir el
         domicilio del inmueble en una prestación de servicios sería ruido. */
      && (!c.nat || c.nat === naturaleza)
      && !(naturaleza === "arrendamiento" && ["MONTO_NUMERO", "LUGAR_ENTREGA", "TIPO_GARANTIA"].includes(c.key)));

  const montoBase = Number(
    form[decision.tipo === "contrato_marco" ? "MONTO_MAXIMO" : "MONTO_NUMERO"]) || 0;

  const listo = !!datosUnidad && !!parametros && !!proveedor;

  const construirValores = (folio) => {
    const v = {
      CONTRATANTE: unidad,
      RAZON_SOCIAL_CONTRATANTE: datosUnidad.razon_social,
      RFC_CONTRATANTE: datosUnidad.rfc,
      DOMICILIO_CONTRATANTE: datosUnidad.domicilio,
      REPRESENTANTE_CONTRATANTE: datosUnidad.representante,
      ESCRITURA_CONTRATANTE: datosUnidad.escritura,
      NOTARIO_CONTRATANTE: datosUnidad.notario,
      CORREO_CONTRATANTE: datosUnidad.correo_notificaciones,
      CORREO_FACTURACION: datosUnidad.correo_facturacion,
      JURISDICCION: datosUnidad.jurisdiccion,
      LUGAR_SUSCRIPCION: datosUnidad.lugar_suscripcion || datosUnidad.jurisdiccion,

      RAZON_SOCIAL_PROVEEDOR: proveedor.razon_social,
      RFC_PROVEEDOR: proveedor.rfc,
      DOMICILIO_PROVEEDOR: proveedor.domicilio,
      /* Una persona física comparece por su propio derecho: el marcador se
         llena con su nombre, no queda hueco esperando un apoderado. */
      REPRESENTANTE_PROVEEDOR: esMoral(proveedor.personalidad)
        ? proveedor.representante
        : (proveedor.representante || proveedor.razon_social),
      ESCRITURA_PROVEEDOR: proveedor.escritura,
      /* La plantilla dice "Que es una persona {{PERSONALIDAD_PROVEEDOR}}", así
         que el valor va sin el prefijo: con "Persona moral" salía impreso
         "QUE ES UNA PERSONA PERSONA MORAL". */
      PERSONALIDAD_PROVEEDOR: String(proveedor.personalidad || "").replace(/^Persona\s+/i, ""),
      CORREO_PROVEEDOR: proveedor.correo,
      CONTACTO_PROVEEDOR: proveedor.contacto,

      /* Los porcentajes llevan el signo aquí: la plantilla dice "una pena de
         {{PENA_PORCENTAJE}} por cada día", sin % después del marcador. Los
         plazos NO lo llevan, porque la plantilla ya escribe "días naturales". */
      PENA_PORCENTAJE: `${parametros.pena_diaria_pct}%`,
      PENA_TOPE: `${parametros.pena_tope_pct}%`,
      GARANTIA_PORCENTAJE: `${parametros.garantia_pct}%`,
      PLAZO_PAGO_DIAS: parametros.plazo_pago_dias,
      PLAZO_ACEPTACION_DIAS: parametros.plazo_aceptacion_dias,
      DIAS_RECHAZO: parametros.dias_rechazo,
      PLAZO_GARANTIA_DIAS: parametros.garantia_plazo_dias,
      GARANTIA_VICIOS_MESES: parametros.garantia_vicios_meses,
      CONFIDENCIALIDAD_ANOS: parametros.confidencialidad_anos,
      AUDITORIA_ANOS: parametros.auditoria_anos,
      AVISO_TERMINACION_DIAS: parametros.aviso_terminacion_dias,
      AVISO_AJUSTE_DIAS: parametros.aviso_ajuste_dias,

      FECHA_SUSCRIPCION: fechaLarga(hoy),
      FECHA_ORDEN: fechaLarga(hoy),
      [meta.marcadorFolio]: folio,
    };

    campos.forEach((c) => {
      const crudo = c.key === "OBJETO" ? objeto : form[c.key];
      if (crudo === undefined || crudo === "") return;
      v[c.key] = c.tipo === "fecha" ? fechaLarga(crudo)
        : c.tipo === "monto" ? dinero(crudo)
        : c.tipo === "moneda" ? monedaContrato(crudo)
        : crudo;
    });

    /* Una persona física comparece por su propio derecho; una moral, por
       representante. Sin este marcador el proemio decía "GERARDO CELAYA,
       representada por GERARDO CELAYA". */
    v.COMPARECENCIA_ARRENDADORA = esMoral(proveedor.personalidad)
      ? `representada por ${proveedor.representante || "su representante legal"}`
      : "quien comparece por su propio derecho";

    if (naturaleza === "arrendamiento") {
      const renta = Number(form.RENTA_MENSUAL) || 0;
      const dep = Number(form.DEPOSITO_GARANTIA) || 0;
      if (renta) v.RENTA_LETRA = importeALetra(renta, form.MONEDA);
      if (dep) v.DEPOSITO_LETRA = importeALetra(dep, form.MONEDA);
    }

    if (decision.tipo === "contrato_especifico" && montoBase) {
      v.MONTO_LETRA = importeALetra(montoBase, form.MONEDA);
    }
    if (decision.tipo === "contrato_marco" && montoBase) {
      v.MONTO_MAXIMO_LETRA = importeALetra(montoBase, "MXP");
    }
    return v;
  };

  const generar = async () => {
    const faltan = campos.filter((c) => !String((c.key === "OBJETO" ? objeto : form[c.key]) ?? "").trim());
    if (faltan.length) {
      const seguir = confirm(
        `Faltan ${faltan.length} campo(s): ${faltan.map((c) => c.label).join(", ")}.\n\n` +
        `Sus marcadores van a quedar impresos en el Word como {{MARCADOR}}, para que el hueco se vea.\n\n¿Generar de todas formas?`);
      if (!seguir) return;
    }

    setTrabajando(true);
    setResultado(null);
    try {
      const { data: plantillas, error: ePlant } = await supabase
        .from("contratos_plantillas").select("*").eq("activa", true);
      if (ePlant) throw ePlant;

      const plantillaNat = naturalezaDe(naturaleza)?.plantilla;
      const tipoPlantilla = plantillaNat && decision.tipo === "contrato_especifico"
        ? plantillaNat : meta.plantilla;
      const principal = plantillas.find((p) => p.tipo === tipoPlantilla);
      if (!principal) throw new Error(`No hay plantilla activa de tipo "${tipoPlantilla}". Súbela y regístrala en contratos_plantillas.`);
      const anexo = decision.flowdown ? plantillas.find((p) => p.tipo === "anexo_flowdown") : null;
      if (decision.flowdown && !anexo) throw new Error('El gatillo 2 exige los anexos flow-down y no hay plantilla activa de tipo "anexo_flowdown".');

      const fila = {
        unidad,
        rfc_proveedor: normRfc(rfc),
        tipo: decision.tipo,
        flowdown: decision.flowdown,
        objeto: String(objeto || "").slice(0, 500) || "(sin objeto)",
        monto: montoBase || null,
        moneda: form.MONEDA === "USD" ? "USD" : "MXP",
        vigencia_inicio: form.VIGENCIA_INICIO || null,
        vigencia_fin: form.VIGENCIA_FIN || null,
        monto_maximo: decision.tipo === "contrato_marco" ? (montoBase || null) : null,
        respuestas: { ...resp, _compuerta: decision.compuerta, _naturaleza: naturaleza || null },
        ruta_decision: decision.ruta,
        parametros_id: parametros.id,
        estado: "generado",
        administrador: form.ADMINISTRADOR_CONTRATO || null,
        centro_costo: form.CENTRO_COSTO || null,
        archivo_path: principal.storage_path,
        ...(session?.user?.id ? { creado_por: session.user.id } : {}),
      };

      /* Se registra primero para que el folio quede reservado por el índice
         único. Si la descarga falla después, el instrumento existe y se puede
         volver a generar; al revés se emitirían dos papeles con el mismo
         número, que es el error caro. */
      const guardado = await insertarInstrumentoConReintento(instrumentosApi, fila, unidad, decision.tipo);
      const valores = construirValores(guardado.folio);

      const docs = [];
      const r1 = await llenarPlantilla(
        principal.storage_path, valores,
        construirClausuladoXML(itemsClausulado, meta.numeracion));
      descargarBlob(r1.blob, `${guardado.folio}.docx`);
      docs.push({
        nombre: `${guardado.folio}.docx`, sinResolver: r1.sinResolver,
        clausulas: itemsClausulado.length, conClausulado: r1.huboClausulado,
      });

      if (anexo) {
        const vAnexo = { ...valores, NUM_CONTRATO: guardado.folio };
        const r2 = await llenarPlantilla(
          anexo.storage_path, vAnexo,
          construirClausuladoXML(itemsAnexo, INSTRUMENTOS.anexo_flowdown.numeracion));
        descargarBlob(r2.blob, `${guardado.folio}-anexos-flow-down.docx`);
        docs.push({
          nombre: `${guardado.folio}-anexos-flow-down.docx`, sinResolver: r2.sinResolver,
          clausulas: itemsAnexo.length, conClausulado: r2.huboClausulado,
        });
      }

      setResultado({ folio: guardado.folio, docs });
    } catch (err) {
      alert("No se pudo generar: " + (err.message || err));
    } finally {
      setTrabajando(false);
    }
  };

  if (cargando) {
    return <Panel title="Generador"><div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div></Panel>;
  }

  const faltantesPrevios = [];
  if (!datosUnidad) faltantesPrevios.push(`los datos legales de ${unidad}`);
  if (!parametros) faltantesPrevios.push(`una versión de parámetros vigente para ${unidad}`);

  return (
    <>
      {faltantesPrevios.length > 0 && (
        <Panel title="Generador">
          <EmptyState
            title="Falta capturar datos recurrentes"
            body={`Sin ${faltantesPrevios.join(" y ")}, la mitad de los marcadores de cualquier plantilla se quedarían sin valor. Captúralos en Datos recurrentes.`}
          />
        </Panel>
      )}

      {!faltantesPrevios.length && (
        <>
          <Panel title="Proveedor" subtitle="Solo aparecen los que ya tienen datos legales capturados: son los que pueden llenar una plantilla.">
            <Field label="Proveedor *" style={{ maxWidth: 480 }}>
              <Select value={rfc} onChange={(e) => setRfc(e.target.value)}>
                <option value="">— elegir —</option>
                {provLegalApi.rows
                  .slice()
                  .sort((a, b) => String(a.razon_social || "").localeCompare(String(b.razon_social || "")))
                  .map((p) => <option key={p.id} value={p.rfc}>{p.razon_social} — {p.rfc}</option>)}
              </Select>
            </Field>
            {proveedor && (
              <div style={{ marginTop: 10, fontSize: 11.5, color: T.textFaint }}>
                {[proveedor.personalidad, proveedor.representante, proveedor.domicilio].filter(Boolean).join(" · ") || "Sin datos adicionales capturados."}
              </div>
            )}
            {!provLegalApi.rows.length && (
              <div style={{ marginTop: 10, fontSize: 12, color: T.textDim }}>
                No hay proveedores con datos legales. Captúralos en Datos recurrentes.
              </div>
            )}
          </Panel>

          <NaturalezaPanel
            naturaleza={naturaleza}
            onElegir={(id) => {
              setNaturaleza(id);
              const n = naturalezaDe(id);
              setResp({ ...resp, ...(n ? n.fija : {}) });
              const tc = n?.tipoContrato;
              if (tc) setForm((f) => ({ ...f, TIPO_CONTRATO: tc }));
            }}
          />

          <Panel
            title="Árbol de decisión"
            subtitle="Se evalúan en orden. La primera compuerta con un sí determina el instrumento y las siguientes ya no corren."
            right={
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 90, height: 5, background: T.panelAlt, borderRadius: 3, overflow: "hidden" }}>
                  <div style={{
                    width: `${((RESPUESTAS_ARBOL.length - sinResponder.length) / RESPUESTAS_ARBOL.length) * 100}%`,
                    height: "100%", background: sinResponder.length ? T.amber : T.teal,
                  }} />
                </div>
                <span style={{ fontSize: 11.5, color: T.textFaint, fontVariantNumeric: "tabular-nums" }}>
                  {RESPUESTAS_ARBOL.length - sinResponder.length} de {RESPUESTAS_ARBOL.length}
                </span>
              </div>
            }
          >
            <BloqueCompuerta n={1} titulo="Gatillos obligatorios" salida="contrato específico"
              estado={estadoCompuerta(1)}>
              {GATILLOS.map((g, i) => (
                <PreguntaSiNo key={g.id} numero={i + 1} texto={g.texto} apagado={estadoCompuerta(1) === "inerte"}
                  preestablecida={fijasPorNaturaleza[g.id] !== undefined && resp[g.id] === fijasPorNaturaleza[g.id]}
                  valor={resp[g.id]} onChange={(v) => setResp({ ...resp, [g.id]: v })} />
              ))}
            </BloqueCompuerta>

            <BloqueCompuerta n={2} titulo="Umbral por operación" salida="contrato específico"
              estado={estadoCompuerta(2)}>
              <PreguntaSiNo apagado={estadoCompuerta(2) === "inerte"}
                texto={<>¿Alguna operación con este proveedor supera <b>{dinero(parametros.umbral_operacion)}</b> sin IVA?</>}
                valor={resp.superaOperacion} onChange={(v) => setResp({ ...resp, superaOperacion: v })} />
            </BloqueCompuerta>

            <BloqueCompuerta n={3} titulo="Umbral acumulado" salida="contrato marco y órdenes"
              estado={estadoCompuerta(3)}>
              <PreguntaSiNo apagado={estadoCompuerta(3) === "inerte"}
                texto={<>¿El acumulado anual con este proveedor supera <b>{dinero(parametros.umbral_acumulado)}</b> sin IVA?</>}
                valor={resp.superaAcumulado} onChange={(v) => setResp({ ...resp, superaAcumulado: v })} />
            </BloqueCompuerta>

            <BloqueCompuerta n={4} titulo="Riesgos agravantes" salida="contrato específico"
              estado={estadoCompuerta(4)}>
              {RIESGOS.map((r, i) => (
                <PreguntaSiNo key={r.id} numero={i + 1} texto={r.texto} apagado={estadoCompuerta(4) === "inerte"}
                  valor={resp[r.id]} onChange={(v) => setResp({ ...resp, [r.id]: v })} />
              ))}
            </BloqueCompuerta>

            <div style={{
              maxWidth: ANCHO_PREGUNTAS, marginTop: 6, borderRadius: 8, padding: "16px 18px",
              background: sinResponder.length ? T.panelAlt : T.accentBg,
              border: `1px solid ${sinResponder.length ? T.amber : T.accent}`,
            }}>
              <div style={{ fontSize: 11.5, color: T.textDim }}>
                {sinResponder.length ? "Resultado preliminar" : "Corresponde emitir"}
              </div>
              <div style={{ fontSize: 21, fontWeight: 700, color: sinResponder.length ? T.textDim : T.text, marginTop: 3, letterSpacing: "-0.01em" }}>
                {meta.label}{decision.flowdown ? " + anexos flow-down" : ""}
              </div>
              {sinResponder.length > 0 && (
                <div style={{ fontSize: 12, color: T.amberDim, marginTop: 7, lineHeight: 1.5 }}>
                  Faltan {sinResponder.length} de {RESPUESTAS_ARBOL.length} preguntas. Una sin responder
                  cuenta como «no», así que esto todavía puede cambiar.
                </div>
              )}
              <div style={{ fontSize: 12.5, color: T.textDim, marginTop: 8, lineHeight: 1.55 }}>{decision.ruta}</div>
              <div style={{ fontSize: 11, color: T.textFaint, marginTop: 10 }}>
                Umbrales vigentes desde {parametros.vigente_desde}. Se guardan con el instrumento.
              </div>
            </div>
          </Panel>

          {meta.externo ? (
            <Panel title="Emisión">
              <EmptyState
                title={`${meta.label}: no se emite aquí`}
                body={`${meta.externo} Esta herramienta solo genera contratos específicos, marcos y sus anexos.`}
              />
            </Panel>
          ) : (
          <Panel
            title="Datos del instrumento"
            subtitle={`Solo lo que ${meta.label.toLowerCase()} necesita. Los campos cambian si cambia el resultado del árbol.`}
          >
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(230px, 1fr))", gap: 14 }}>
              {campos.map((c) => (
                <Field key={c.key} label={c.label} style={c.ancho === 2 ? { gridColumn: "span 2" } : undefined}>
                  {c.key === "OBJETO" ? (
                    /* Mismo dato que el de la pestaña de cláusulas, no una
                       copia: tenerlo dos veces garantizaba que tarde o
                       temprano dijeran cosas distintas. */
                    <TextInput value={objeto} onChange={(e) => setObjeto(e.target.value)} />
                  ) : c.tipo === "moneda" ? (
                    <Select value={form.MONEDA || "MXP"} onChange={(e) => setForm({ ...form, MONEDA: e.target.value })}>
                      <option value="MXP">MXN — peso mexicano</option>
                      <option value="USD">USD — dólar americano</option>
                    </Select>
                  ) : (
                    <TextInput
                      type={c.tipo === "fecha" ? "date" : c.tipo === "monto" ? "number" : "text"}
                      step={c.tipo === "monto" ? "0.01" : undefined}
                      value={form[c.key] ?? ""}
                      onChange={(e) => setForm({ ...form, [c.key]: e.target.value })}
                    />
                  )}
                  {c.ayuda
                    ? <span style={{ fontSize: 10.5, color: T.textFaint, marginTop: 3 }}>{c.ayuda}</span>
                    : <MarcadorHint marcador={c.key} />}
                </Field>
              ))}
            </div>

            {montoBase > 0 && (
              <div style={{ marginTop: 14, fontSize: 11.5, color: T.textFaint, fontFamily: T.fontMono }}>
                En letra: {importeALetra(montoBase, decision.tipo === "contrato_marco" ? "MXP" : form.MONEDA)}
              </div>
            )}

            <div style={{ display: "flex", gap: 10, alignItems: "center", marginTop: 18 }}>
              <Button onClick={generar} disabled={!listo || trabajando || !itemsClausulado.length}>
                {trabajando ? "Generando…" : "Generar y registrar"}
              </Button>
              {!proveedor && <span style={{ fontSize: 12, color: T.textDim }}>Elige un proveedor primero.</span>}
              {proveedor && !itemsClausulado.length && (
                <span style={{ fontSize: 12, color: T.textDim }}>
                  No hay cláusulas marcadas. Elígelas en «Objeto y cláusulas».
                </span>
              )}
              {proveedor && itemsClausulado.length > 0 && (
                <span style={{ fontSize: 12, color: T.textFaint }}>
                  {itemsClausulado.length} cláusula(s){itemsAnexo.length && decision.flowdown ? ` y ${itemsAnexo.length} anexo(s)` : ""}
                </span>
              )}
            </div>

            {resultado && (
              <div style={{ marginTop: 16, borderTop: `1px solid ${T.border}`, paddingTop: 13 }}>
                <div style={{ fontSize: 12.5, color: T.text, fontWeight: 600 }}>
                  Registrado como {resultado.folio}
                </div>
                {resultado.docs.map((d) => (
                  <div key={d.nombre} style={{ fontSize: 12, color: T.textDim, marginTop: 6 }}>
                    {d.nombre} — {d.clausulas} cláusula(s)
                    {!d.conClausulado && (
                      <div style={{ fontSize: 11, color: T.red, marginTop: 3 }}>
                        Esta plantilla no tiene {"{{CLAUSULADO}}"}: salió con el texto que trae escrito,
                        sin tu selección. Vuelve a subir la versión adelgazada.
                      </div>
                    )}
                    {d.sinResolver.length > 0 && (
                      <div style={{ fontSize: 11, color: T.red, marginTop: 3, fontFamily: T.fontMono }}>
                        {d.sinResolver.length} marcador(es) sin resolver, impresos en el documento:{" "}
                        {d.sinResolver.join(", ")}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </Panel>
          )}
        </>
      )}
    </>
  );
}

/* ----------------------------------------------------------------------
   BIBLIOTECA DE CLÁUSULAS
---------------------------------------------------------------------- */

const ORD_UNIDAD = ["PRIMERA", "SEGUNDA", "TERCERA", "CUARTA", "QUINTA", "SEXTA", "SÉPTIMA", "OCTAVA", "NOVENA"];
const ORD_DECENA = ["", "DÉCIMA", "VIGÉSIMA", "TRIGÉSIMA", "CUADRAGÉSIMA", "QUINCUAGÉSIMA"];

/* DÉCIMA PRIMERA, no UNDÉCIMA: es la forma que usa el clausulado mexicano y
   la que ya traían las plantillas. */
function ordinalEnLetra(n) {
  if (n < 1) return "";
  if (n <= 9) return ORD_UNIDAD[n - 1];
  const d = Math.floor(n / 10), u = n % 10;
  if (d >= ORD_DECENA.length) return `${n}ª`;
  return ORD_DECENA[d] + (u ? " " + ORD_UNIDAD[u - 1] : "");
}

function etiquetaNumero(i, modo) {
  if (modo === "numero") return `${i}.`;
  if (modo === "letra") return `ANEXO ${String.fromCharCode(64 + i)}.`;
  return `${ordinalEnLetra(i)}.`;
}

/* Una cláusula se puede amarrar a un gatillo, a un riesgo o directamente a
   la naturaleza de la contratación: un arrendamiento necesita cláusulas que
   una prestación de servicios no, y eso no depende de ningún gatillo. */
const TODAS_CASILLAS = [
  ...GATILLOS.map((g, i) => ({ id: g.id, etiqueta: `Gatillo ${i + 1}`, texto: g.texto })),
  ...RIESGOS.map((r, i) => ({ id: r.id, etiqueta: `Riesgo ${i + 1}`, texto: r.texto })),
  ...NATURALEZAS.map((n) => ({ id: "nat_" + n.id, etiqueta: "Naturaleza", texto: n.label })),
];

const slugClave = (t) =>
  String(t || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\{\{[A-Z_0-9]+\}\}/g, "")
    .toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/_+/g, "_")
    .replace(/^_|_$/g, "").slice(0, 40);

const parrafosDe = (cuerpo) =>
  String(cuerpo || "").split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);

/* ----------------------------------------------------------------------
   ARMADO DEL CLAUSULADO EN XML DE WORD
---------------------------------------------------------------------- */

/* Formato copiado de los párrafos que ya traían las plantillas: Arial 10,
   justificado. El encabezado lleva negrita y más aire arriba; el cuerpo, la
   interlínea de 276. Si se generara con otro formato, el documento se vería
   cosido de dos fuentes distintas. */
const RPR_BASE = '<w:rFonts w:ascii="Arial" w:cs="Arial" w:eastAsia="Arial" w:hAnsi="Arial"/><w:sz w:val="20"/><w:szCs w:val="20"/>';

function parrafoWord(texto, negrita) {
  const pPr = negrita
    ? '<w:spacing w:after="100" w:before="220"/><w:jc w:val="both"/>'
    : '<w:spacing w:after="120" w:line="276"/><w:jc w:val="both"/>';
  const rPr = negrita ? `<w:b/><w:bCs/>${RPR_BASE}` : RPR_BASE;
  return `<w:p><w:pPr>${pPr}</w:pPr><w:r><w:rPr>${rPr}</w:rPr>`
    + `<w:t xml:space="preserve">${escaparXml(texto)}</w:t></w:r></w:p>`;
}

/**
 * Convierte las cláusulas elegidas en párrafos de Word, numeradas en el
 * estilo que corresponda al instrumento. Los {{MARCADORES}} del cuerpo se
 * dejan crudos a propósito: la sustitución general corre después sobre todo
 * el documento, así que se resuelven junto con los de la plantilla.
 */
function construirClausuladoXML(items, modo) {
  let n = 0;
  return items.map((c) => {
    n += 1;
    const encabezado = `${etiquetaNumero(n, modo)} ${c.titulo}${/[.:]$/.test(c.titulo) ? "" : "."}`;
    return parrafoWord(encabezado, true)
      + parrafosDe(c.cuerpo).map((p) => parrafoWord(p, false)).join("");
  }).join("");
}

/* Sustituye el PÁRRAFO COMPLETO que contiene {{CLAUSULADO}}, no solo el
   texto: si únicamente se cambiara la cadena, las veinte cláusulas caerían
   dentro de un mismo párrafo, sin encabezados ni separación. */
function inyectarClausulado(xml, clausuladoXML) {
  const i = xml.indexOf("{{CLAUSULADO}}");
  if (i === -1) return { xml, encontrado: false };
  /* No sirve lastIndexOf("<w:p"): las propiedades del párrafo son <w:pPr>,
     que también empieza con esa cadena, así que el corte caería a media
     etiqueta y dejaría el <w:p> sin cerrar. Hay que exigir que lo que sigue
     sea un espacio o el cierre de la etiqueta. */
  const rx = /<w:p[ >]/g;
  let ini = -1, m;
  while ((m = rx.exec(xml)) !== null) {
    if (m.index >= i) break;
    ini = m.index;
  }
  const fin = xml.indexOf("</w:p>", i);
  if (ini === -1 || fin === -1) return { xml, encontrado: false };
  return { xml: xml.slice(0, ini) + clausuladoXML + xml.slice(fin + 6), encontrado: true };
}

function ClausulasPanel({ clausulasApi, resp, naturalezaSel, tipoSugerido, instrumento, setInstrumento, objeto, setObjeto, incluidas, setIncluidas, session }) {
  const [editando, setEditando] = useState(null);
  const [guardando, setGuardando] = useState(false);
  const [verCuerpo, setVerCuerpo] = useState(null);

  const modo = (INSTRUMENTOS[instrumento] || {}).numeracion || "ordinal";

  /* Una cláusula sin naturalezas sirve para todas; con naturalezas, solo
     para las que lista. Sin esto, un contrato de servicios arrastraría las
     cláusulas de arrendamiento y al revés. */
  const aplicaNaturaleza = (c) =>
    !c.naturalezas || !c.naturalezas.length || !naturalezaSel
      || c.naturalezas.includes(naturalezaSel);
  const items = clausulasApi.rows
    .filter((c) => c.instrumento === instrumento && c.activa !== false && aplicaNaturaleza(c))
    .sort((a, b) => (a.orden - b.orden) || String(a.titulo).localeCompare(String(b.titulo)));

  const sugerenciasDe = (c) => (c.sugerida_si || []).filter((k) => esSi(resp[k]));
  const estadoDe = (c) => c.obligatoria ? "obligatoria" : (sugerenciasDe(c).length ? "sugerida" : "opcional");

  /* La selección se recalcula cuando cambia el instrumento o las respuestas
     del árbol, pero respeta lo que el usuario ya marcó a mano: lo que se
     siembra es el default, no una imposición. */
  const claveAuto = `${instrumento}|${items.map((c) => c.id).join(",")}|${TODAS_CASILLAS.filter((k) => esSi(resp[k.id])).map((k) => k.id).join(",")}`;
  const autoRef = useRef(null);
  useEffect(() => {
    if (autoRef.current === claveAuto) return;
    autoRef.current = claveAuto;
    const base = new Set(items.filter((c) => estadoDe(c) !== "opcional").map((c) => c.id));
    setIncluidas(base);
  }, [claveAuto]);

  const marcadas = items.filter((c) => c.obligatoria || incluidas.has(c.id));
  let n = 0;
  const numeradas = items.map((c) => {
    const dentro = c.obligatoria || incluidas.has(c.id);
    if (dentro) n += 1;
    return { c, dentro, etiqueta: dentro ? etiquetaNumero(n, modo) : null };
  });

  const alternar = (c) => {
    if (c.obligatoria) return;
    const s = new Set(incluidas);
    if (s.has(c.id)) s.delete(c.id); else s.add(c.id);
    setIncluidas(s);
  };

  const nuevo = () => setEditando({
    _nuevo: true, instrumento, tipo_item: instrumento === "anexo_flowdown" ? "anexo" : "clausula",
    titulo: "", cuerpo: "", obligatoria: false, sugerida_si: [],
    orden: (items.length ? Math.max(...items.map((c) => c.orden)) : 0) + 10,
  });

  const guardar = async () => {
    const titulo = String(editando.titulo || "").trim();
    const cuerpo = String(editando.cuerpo || "").trim();
    if (!titulo || !cuerpo) { alert("El título y el cuerpo son obligatorios."); return; }
    setGuardando(true);
    try {
      const fila = {
        clave: editando.clave || `${editando.instrumento.slice(0, 3)}_${slugClave(titulo)}`,
        tipo_item: editando.tipo_item,
        instrumento: editando.instrumento,
        titulo, cuerpo,
        obligatoria: !!editando.obligatoria,
        sugerida_si: editando.sugerida_si || [],
        orden: Number(editando.orden) || 100,
        actualizado_en: new Date().toISOString(),
        ...(session?.user?.id ? { actualizado_por: session.user.id } : {}),
      };
      if (editando._nuevo) await clausulasApi.insert({ id: uid(), ...fila });
      else await clausulasApi.update(editando.id, fila);
      setEditando(null);
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally {
      setGuardando(false);
    }
  };

  const desactivar = async (c) => {
    if (!confirm(`¿Sacar "${c.titulo}" de la biblioteca?\n\nNo se borra: queda inactiva y deja de ofrecerse al armar contratos. Los que ya se generaron no cambian.`)) return;
    try { await clausulasApi.update(c.id, { activa: false, actualizado_en: new Date().toISOString() }); }
    catch (err) { alert("No se pudo: " + (err.message || err)); }
  };

  const casillasActivas = TODAS_CASILLAS.filter((k) => esSi(resp[k.id]));

  return (
    <>
      <Panel title="Instrumento y objeto" subtitle="Elige el instrumento que te indicó el árbol. La estructura y las cláusulas se acomodan a esa elección.">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 14 }}>
          <Field label="Tipo de instrumento">
            <Select value={instrumento} onChange={(e) => setInstrumento(e.target.value)}>
              {ORDEN_INSTRUMENTOS.map((id) => <option key={id} value={id}>{INSTRUMENTOS[id].label}</option>)}
            </Select>
            {instrumento !== tipoSugerido && (
              <span style={{ fontSize: 10.5, color: T.amberDim, marginTop: 3 }}>
                El árbol indicó {INSTRUMENTOS[tipoSugerido].label.toLowerCase()}.
              </span>
            )}
          </Field>
          <Field label="Objeto del contrato" style={{ gridColumn: "span 2" }}>
            <TextInput value={objeto} onChange={(e) => setObjeto(e.target.value)} placeholder="Suministro de…, prestación del servicio de…" />
            <MarcadorHint marcador="OBJETO" />
          </Field>
        </div>

        <div style={{ marginTop: 16, display: "flex", gap: 24, flexWrap: "wrap" }}>
          <div>
            <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 6 }}>
              Estructura del documento
            </div>
            {((INSTRUMENTOS[instrumento] || {}).estructura || []).map((s, i) => (
              <div key={s} style={{ fontSize: 12, color: s === "Clausulado" ? T.text : T.textFaint, fontWeight: s === "Clausulado" ? 600 : 400, padding: "2px 0" }}>
                {i + 1}. {s}{s === "Clausulado" ? `  ← ${marcadas.length} ítem(s) seleccionado(s)` : ""}
              </div>
            ))}
            <div style={{ fontSize: 11, color: T.textFaint, marginTop: 6, maxWidth: 340, lineHeight: 1.5 }}>
              Lo demás lo aporta la plantilla y no se elige aquí.
            </div>
          </div>

          <div style={{ flex: 1, minWidth: 260 }}>
            <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 6 }}>
              Respuestas del árbol que están sugiriendo
            </div>
            {casillasActivas.length ? casillasActivas.map((k) => (
              <div key={k.id} style={{ fontSize: 11.5, color: T.textDim, padding: "2px 0" }}>
                <b>{k.etiqueta}:</b> {k.texto}
              </div>
            )) : (
              <div style={{ fontSize: 11.5, color: T.textFaint, lineHeight: 1.5 }}>
                Ninguna casilla marcada. Respóndelas en Diagnóstico y las cláusulas que dependen de ellas
                se marcan solas; mientras tanto solo se preseleccionan las obligatorias.
              </div>
            )}
          </div>
        </div>
      </Panel>

      <Panel
        title={instrumento === "anexo_flowdown" ? "Anexos disponibles" : "Cláusulas"}
        subtitle="Las obligatorias van siempre. Las sugeridas se marcan solas por las respuestas del árbol; puedes desmarcarlas."
        right={<Button onClick={nuevo}>+ Nueva</Button>}
      >
        {editando && (
          <div style={{ background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8, padding: 16, marginBottom: 16 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: T.text, marginBottom: 12 }}>
              {editando._nuevo ? "Nueva cláusula" : `Editar — ${editando.titulo}`}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(210px, 1fr))", gap: 13 }}>
              <Field label="Título *" style={{ gridColumn: "span 2" }}>
                <TextInput value={editando.titulo} onChange={(e) => setEditando({ ...editando, titulo: e.target.value })} />
                <span style={{ fontSize: 10.5, color: T.textFaint, marginTop: 3 }}>
                  Sin el ordinal: se calcula al generar.
                </span>
              </Field>
              <Field label="Instrumento">
                <Select value={editando.instrumento} onChange={(e) => setEditando({ ...editando, instrumento: e.target.value })}>
                  {ORDEN_INSTRUMENTOS.map((id) => <option key={id} value={id}>{INSTRUMENTOS[id].label}</option>)}
                </Select>
              </Field>
              <Field label="Orden">
                <TextInput type="number" step="10" value={editando.orden}
                  onChange={(e) => setEditando({ ...editando, orden: e.target.value })} />
              </Field>
            </div>

            <Field label="Cuerpo *" style={{ marginTop: 13 }}>
              <textarea
                value={editando.cuerpo}
                onChange={(e) => setEditando({ ...editando, cuerpo: e.target.value })}
                rows={10}
                style={{
                  width: "100%", padding: "9px 11px", border: `1px solid ${T.border}`, borderRadius: 6,
                  background: T.panel, color: T.text, fontSize: 12.5, fontFamily: T.fontUI,
                  lineHeight: 1.55, resize: "vertical", boxSizing: "border-box",
                }}
              />
              <span style={{ fontSize: 10.5, color: T.textFaint, marginTop: 4 }}>
                Un renglón en blanco separa párrafos. Admite los mismos marcadores, por ejemplo {"{{PLAZO_PAGO_DIAS}}"}.
              </span>
            </Field>

            <div style={{ marginTop: 13 }}>
              <label style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 12.5, color: T.textDim, cursor: "pointer" }}>
                <input type="checkbox" checked={!!editando.obligatoria}
                  onChange={(e) => setEditando({ ...editando, obligatoria: e.target.checked })} />
                Obligatoria — va en todos los contratos de este tipo y no se puede desmarcar
              </label>
            </div>

            {!editando.obligatoria && (
              <div style={{ marginTop: 13 }}>
                <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 3 }}>
                  Se sugiere cuando se marca
                </div>
                <div style={{ fontSize: 11, color: T.textFaint, marginBottom: 8 }}>
                  Si no eliges ninguna, la cláusula queda como opcional y solo se incluye marcándola a mano.
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(270px, 1fr))", gap: 4 }}>
                  {TODAS_CASILLAS.map((k) => (
                    <label key={k.id} style={{ display: "flex", gap: 7, alignItems: "flex-start", fontSize: 11.5, color: T.textDim, cursor: "pointer", padding: "2px 0" }}>
                      <input
                        type="checkbox"
                        checked={(editando.sugerida_si || []).includes(k.id)}
                        onChange={(e) => {
                          const s = new Set(editando.sugerida_si || []);
                          if (e.target.checked) s.add(k.id); else s.delete(k.id);
                          setEditando({ ...editando, sugerida_si: [...s] });
                        }}
                        style={{ marginTop: 2 }}
                      />
                      <span><b>{k.etiqueta}.</b> {k.texto.slice(0, 64)}{k.texto.length > 64 ? "…" : ""}</span>
                    </label>
                  ))}
                </div>
              </div>
            )}

            <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
              <Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Button>
              <Button variant="ghost" onClick={() => setEditando(null)}>Cancelar</Button>
            </div>
          </div>
        )}

        {!items.length ? (
          <EmptyState
            title="Sin ítems para este instrumento"
            body="Si acabas de correr la migración 31, revisa que haya sembrado. Si no, crea el primero."
          />
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 1, background: T.border, border: `1px solid ${T.border}`, borderRadius: 6, overflow: "hidden" }}>
            {numeradas.map(({ c, dentro, etiqueta }) => {
              const estado = estadoDe(c);
              const sug = sugerenciasDe(c);
              const marcadores = [...new Set(String(c.cuerpo || "").match(/\{\{[A-Z_0-9]+\}\}/g) || [])];
              return (
                <div key={c.id} style={{ background: T.panel, padding: "10px 12px", opacity: dentro ? 1 : 0.55 }}>
                  <div style={{ display: "flex", alignItems: "flex-start", gap: 11 }}>
                    <input
                      type="checkbox"
                      checked={dentro}
                      disabled={c.obligatoria}
                      onChange={() => alternar(c)}
                      style={{ marginTop: 3, cursor: c.obligatoria ? "not-allowed" : "pointer" }}
                    />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12.5, color: T.text, fontWeight: 600 }}>
                        {etiqueta && <span style={{ fontFamily: T.fontMono, color: T.accent, marginRight: 7 }}>{etiqueta}</span>}
                        {c.titulo}
                      </div>
                      <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap", marginTop: 5 }}>
                        {estado === "obligatoria" && <Pill>obligatoria</Pill>}
                        {estado === "sugerida" && <Pill>sugerida por {sug.map((k) => (TODAS_CASILLAS.find((x) => x.id === k) || {}).etiqueta).join(", ")}</Pill>}
                        {estado === "opcional" && <Pill>opcional</Pill>}
                        <span style={{ fontSize: 10.5, color: T.textFaint }}>
                          {parrafosDe(c.cuerpo).length} párrafo(s)
                          {marcadores.length ? ` · ${marcadores.length} marcador(es)` : ""}
                        </span>
                      </div>
                      {verCuerpo === c.id && (
                        <div style={{ marginTop: 9, fontSize: 11.5, color: T.textDim, lineHeight: 1.6, background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 6, padding: "9px 11px" }}>
                          {parrafosDe(c.cuerpo).map((p, i) => <div key={i} style={{ marginBottom: 7 }}>{p}</div>)}
                        </div>
                      )}
                    </div>
                    <Button variant="ghost" onClick={() => setVerCuerpo(verCuerpo === c.id ? null : c.id)} style={{ padding: "4px 10px" }}>
                      {verCuerpo === c.id ? "Ocultar" : "Ver"}
                    </Button>
                    <Button variant="ghost" onClick={() => setEditando({ ...c })} style={{ padding: "4px 10px" }}>Editar</Button>
                    <Button variant="danger" onClick={() => desactivar(c)} style={{ padding: "4px 10px" }}>Quitar</Button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        <div style={{ marginTop: 13, fontSize: 12, color: T.textDim }}>
          {marcadas.length} de {items.length} seleccionados.
          {modo === "ordinal" && marcadas.length > 0 && ` Numerarán de PRIMERA a ${ordinalEnLetra(marcadas.length)}.`}
          {modo === "numero" && marcadas.length > 0 && ` Numerarán del 1 al ${marcadas.length}.`}
          {modo === "letra" && marcadas.length > 0 && ` Irán del ANEXO A al ANEXO ${String.fromCharCode(64 + marcadas.length)}.`}
        </div>
      </Panel>
    </>
  );
}

function ContratosTab({ unidad, parametrosApi, provLegalApi, provUnidadApi, instrumentosApi, clausulasApi, session }) {
  const [sub, setSub] = useSessionState("ss-contratos-sub", "datos");
  const [hayDatosUnidad, setHayDatosUnidad] = useState(false);
  /* Las respuestas del árbol se comparten: se capturan en Diagnóstico y de
     ellas dependen las cláusulas sugeridas. Si vivieran dentro de un solo
     panel, cambiar de pestaña las perdería. */
  const [resp, setResp] = useState({});
  const [naturaleza, setNaturaleza] = useState("");
  const [instrumento, setInstrumento] = useState("contrato_especifico");
  const [objeto, setObjeto] = useState("");
  const [incluidas, setIncluidas] = useState(() => new Set());

  /* El árbol es quien decide el instrumento; el selector de la pestaña de
     cláusulas solo lo refleja. Se puede cambiar a mano, pero si el árbol
     cambia de opinión, vuelve a mandar él. */
  /* La naturaleza viaja junto a las respuestas: para la biblioteca de
     cláusulas es una señal más, indistinguible de un gatillo. */
  const senales = senalesDe(resp, naturaleza);
  const tipoSugerido = decidirInstrumento(resp).tipo;
  useEffect(() => { setInstrumento(tipoSugerido); }, [tipoSugerido]);

  /* Las cláusulas que van en el documento, calculadas aquí para que la
     pestaña que las marca y la que genera lean exactamente lo mismo.
     OJO con el orden: esto lee `incluidas`, así que va DESPUÉS de su
     useState — si no, la zona muerta temporal revienta en cada render. */
  const ordenadas = (instr) => clausulasApi.rows
    .filter((c) => c.instrumento === instr && c.activa !== false
      && (!c.naturalezas || !c.naturalezas.length || !naturaleza || c.naturalezas.includes(naturaleza)))
    .sort((a, b) => (a.orden - b.orden) || String(a.titulo).localeCompare(String(b.titulo)));
  const itemsClausulado = ordenadas(instrumento)
    .filter((c) => c.obligatoria || incluidas.has(c.id));
  /* Los anexos flow-down no tienen pantalla de marcado propia: se toman las
     obligatorias más las que sugieran las respuestas del árbol. */
  const itemsAnexo = ordenadas("anexo_flowdown")
    .filter((c) => c.obligatoria || (c.sugerida_si || []).some((k) => esSi(resp[k])));

  /* El resto del panel depende de que exista la fila de la unidad: parámetros
     y nivel de debida diligencia la referencian por llave foránea. Se
     consulta aquí, una vez, en lugar de que cada panel lo averigüe. */
  useEffect(() => {
    let vivo = true;
    (async () => {
      try {
        const { data } = await supabase
          .from("contratos_datos_unidad").select("unidad").eq("unidad", unidad).maybeSingle();
        if (vivo) setHayDatosUnidad(!!data);
      } catch {
        if (vivo) setHayDatosUnidad(false);
      }
    })();
    return () => { vivo = false; };
  }, [unidad, sub]);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, padding: 3, alignSelf: "flex-start", flexWrap: "wrap" }}>
        {SUBS_CONTRATOS.map((sc) => (
          <button
            key={sc.id}
            onClick={() => setSub(sc.id)}
            style={{
              padding: "7px 16px", borderRadius: 6, border: "none", cursor: "pointer",
              background: sub === sc.id ? T.accent : "transparent",
              color: sub === sc.id ? "#FFFFFF" : T.textDim,
              fontWeight: 600, fontSize: 12.5, fontFamily: T.fontUI,
            }}
          >
            {sc.label}
          </button>
        ))}
      </div>

      {sub === "datos" && (
        <>
          <DatosUnidadPanel unidad={unidad} session={session} />
          <ParametrosPanel unidad={unidad} parametrosApi={parametrosApi} session={session} hayDatosUnidad={hayDatosUnidad} />
          <ProveedorLegalPanel
            unidad={unidad}
            provLegalApi={provLegalApi}
            provUnidadApi={provUnidadApi}
            session={session}
            hayDatosUnidad={hayDatosUnidad}
          />
        </>
      )}

      {sub === "generador" && (
        <GeneradorPanel
          unidad={unidad}
          parametrosApi={parametrosApi}
          provLegalApi={provLegalApi}
          instrumentosApi={instrumentosApi}
          resp={resp}
          setResp={setResp}
          naturaleza={naturaleza}
          setNaturaleza={setNaturaleza}
          objeto={objeto}
          setObjeto={setObjeto}
          itemsClausulado={itemsClausulado}
          itemsAnexo={itemsAnexo}
          session={session}
        />
      )}

      {sub === "clausulas" && (
        <ClausulasPanel
          clausulasApi={clausulasApi}
          resp={senales}
          naturalezaSel={naturaleza}
          tipoSugerido={tipoSugerido}
          instrumento={instrumento}
          setInstrumento={setInstrumento}
          objeto={objeto}
          setObjeto={setObjeto}
          incluidas={incluidas}
          setIncluidas={setIncluidas}
          session={session}
        />
      )}

      {sub === "expediente" && (
        <Panel title="Expediente" subtitle="Pendiente.">
          <EmptyState
            title="Sin instrumentos todavía"
            body="El listado se construye sobre lo que emita el generador."
          />
        </Panel>
      )}
    </div>
  );
}

/* ----------------------------------------------------------------------
   SOLICITUDES — PARÁMETROS
---------------------------------------------------------------------- */

const SUBS_SOLICITUDES = [
  { id: "bandeja",      label: "Bandeja" },
  { id: "solicitantes", label: "Solicitantes" },
  { id: "parametros",   label: "Parámetros" },
];

const MARCAS_FOLIO = [
  { marca: "{n}",      que: "el consecutivo" },
  { marca: "{aa}",     que: "año a dos dígitos" },
  { marca: "{aaaa}",   que: "año a cuatro dígitos" },
  { marca: "{mm}",     que: "mes a dos dígitos" },
  { marca: "{unidad}", que: "la compañía" },
];

/* El orden importa: {aaaa} debe resolverse antes que {aa}, o la primera se
   quedaría a medias y dejaría un "26" colgando. */
function armarFolioSolicitud(formato, consecutivo, ancho, unidad, fecha = new Date()) {
  const anio = String(fecha.getFullYear());
  return String(formato || "")
    .replace(/\{n\}/g, String(consecutivo).padStart(Math.max(1, Number(ancho) || 1), "0"))
    .replace(/\{aaaa\}/g, anio)
    .replace(/\{aa\}/g, anio.slice(-2))
    .replace(/\{mm\}/g, String(fecha.getMonth() + 1).padStart(2, "0"))
    .replace(/\{unidad\}/g, unidad || "");
}

function SolicitudesParametrosPanel({ unidad, session }) {
  const vacio = {
    formato_folio: "{n}P{aa}", ancho_consecutivo: 1, consecutivo_inicial: 1,
    reinicia_cada_anio: true, drive_carpeta_raiz: "", drive_carpeta_nombre: "",
  };
  const [form, setForm] = useState(vacio);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [existia, setExistia] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    let vivo = true;
    (async () => {
      setCargando(true);
      setError("");
      try {
        const { data, error: e } = await supabase
          .from("solicitudes_parametros").select("*").eq("unidad", unidad).maybeSingle();
        if (e) throw e;
        if (!vivo) return;
        setForm(data ? { ...vacio, ...data } : vacio);
        setExistia(!!data);
      } catch (err) {
        if (vivo) setError(err.message || String(err));
      } finally {
        if (vivo) setCargando(false);
      }
    })();
    return () => { vivo = false; };
  }, [unidad]);

  const n0 = Number(form.consecutivo_inicial) || 0;
  const ancho = Number(form.ancho_consecutivo) || 1;
  const ejemplos = [n0, n0 + 1, n0 + 2]
    .map((n) => armarFolioSolicitud(form.formato_folio, n, ancho, unidad));
  const sinConsecutivo = !/\{n\}/.test(String(form.formato_folio || ""));
  /* Sin año en el formato y con reinicio anual, el folio del año que viene
     chocaría contra el de éste. El índice único lo rebotaría, pero es mejor
     decirlo antes de capturar mil solicitudes. */
  const choqueAnual = form.reinicia_cada_anio
    && !/\{aa\}|\{aaaa\}/.test(String(form.formato_folio || ""));

  const guardar = async () => {
    if (sinConsecutivo) { alert("El formato tiene que incluir {n}, o todos los folios saldrían iguales."); return; }
    setGuardando(true);
    setError("");
    try {
      const fila = {
        unidad,
        formato_folio: String(form.formato_folio || "").trim(),
        ancho_consecutivo: ancho,
        consecutivo_inicial: n0,
        reinicia_cada_anio: !!form.reinicia_cada_anio,
        drive_carpeta_raiz: String(form.drive_carpeta_raiz || "").trim(),
        drive_carpeta_nombre: String(form.drive_carpeta_nombre || "").trim(),
        actualizado_en: new Date().toISOString(),
        ...(session?.user?.id ? { actualizado_por: session.user.id } : {}),
      };
      const { error: e } = await supabase
        .from("solicitudes_parametros").upsert(fila, { onConflict: "unidad" });
      if (e) throw e;
      setExistia(true);
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setGuardando(false);
    }
  };

  if (cargando) {
    return <Panel title="Parámetros"><div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div></Panel>;
  }

  return (
    <>
      <Panel
        title={`Folio de solicitudes — ${unidad}`}
        subtitle="Cómo se numeran las SMI. El formato no está en el código porque cada compañía puede llevar el suyo."
        right={<Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : existia ? "Guardar" : "Crear"}</Button>}
      >
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(210px, 1fr))", gap: 14, maxWidth: 780 }}>
          <Field label="Formato">
            <TextInput value={form.formato_folio}
              onChange={(e) => setForm({ ...form, formato_folio: e.target.value })} />
            {sinConsecutivo && (
              <span style={{ fontSize: 10.5, color: T.red, marginTop: 3 }}>Falta {"{n}"}</span>
            )}
          </Field>
          <Field label="Consecutivo inicial">
            <TextInput type="number" value={form.consecutivo_inicial}
              onChange={(e) => setForm({ ...form, consecutivo_inicial: e.target.value })} />
          </Field>
          <Field label="Dígitos del consecutivo">
            <TextInput type="number" min="1" max="8" value={form.ancho_consecutivo}
              onChange={(e) => setForm({ ...form, ancho_consecutivo: e.target.value })} />
            <span style={{ fontSize: 10.5, color: T.textFaint, marginTop: 3 }}>
              1 = sin ceros a la izquierda
            </span>
          </Field>
        </div>

        <label style={{ display: "flex", gap: 8, alignItems: "flex-start", marginTop: 14, fontSize: 12.5, color: T.textDim, cursor: "pointer", maxWidth: 780 }}>
          <input type="checkbox" checked={!!form.reinicia_cada_anio}
            onChange={(e) => setForm({ ...form, reinicia_cada_anio: e.target.checked })}
            style={{ marginTop: 2 }} />
          <span>
            Reiniciar el consecutivo cada año.
            <span style={{ color: T.textFaint }}> Sin esto, la serie es continua para siempre.</span>
          </span>
        </label>

        {choqueAnual && (
          <div style={{ marginTop: 12, maxWidth: 780, fontSize: 12, color: T.amberDim, background: T.panelAlt, border: `1px solid ${T.amber}`, borderRadius: 6, padding: "9px 11px", lineHeight: 1.5 }}>
            El consecutivo reinicia cada año pero el formato no incluye el año, así que el folio de
            enero próximo chocaría con el de este enero. Agrega {"{aa}"} o desactiva el reinicio.
          </div>
        )}

        <div style={{ marginTop: 16, maxWidth: 780, background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8, padding: "12px 14px" }}>
          <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 7 }}>
            Así saldrían los primeros
          </div>
          <div style={{ fontFamily: T.fontMono, fontSize: 15, color: T.text }}>
            {ejemplos.join("   ·   ")}
          </div>
          <div style={{ fontSize: 11, color: T.textFaint, marginTop: 8, lineHeight: 1.6 }}>
            {MARCAS_FOLIO.map((m) => (
              <span key={m.marca} style={{ marginRight: 14, whiteSpace: "nowrap" }}>
                <b style={{ fontFamily: T.fontMono }}>{m.marca}</b> {m.que}
              </span>
            ))}
          </div>
        </div>

        {error && <div style={{ marginTop: 12, fontSize: 12, color: T.red }}>No se pudo guardar: {error}</div>}
      </Panel>

      <Panel
        title="Carpeta en Drive"
        subtitle="La carpeta de esta compañía. Dentro, el proceso crea el año y luego una por solicitud. El id se toma de la URL de Drive, después de /folders/."
      >
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 14, maxWidth: 780 }}>
          <Field label="Id de la carpeta raíz">
            <TextInput value={form.drive_carpeta_raiz}
              onChange={(e) => setForm({ ...form, drive_carpeta_raiz: e.target.value })}
              placeholder="1AbC…" />
          </Field>
          <Field label="Nombre, solo para reconocerla">
            <TextInput value={form.drive_carpeta_nombre}
              onChange={(e) => setForm({ ...form, drive_carpeta_nombre: e.target.value })}
              placeholder="adm/osb/Compras/2026" />
          </Field>
        </div>
        <div style={{ marginTop: 12, maxWidth: 780, fontSize: 11.5, color: T.textFaint, lineHeight: 1.6 }}>
          Se guarda el id y no el enlace: el enlace se deriva del id, pero una carpeta movida o
          renombrada cambia de enlace y conserva el id.
        </div>
      </Panel>
    </>
  );
}

/* ----------------------------------------------------------------------
   SOLICITUDES — CAPTURA
---------------------------------------------------------------------- */

const TIPOS_SOLICITUD = [
  { value: "productos_servicios",     label: "Productos / Servicios" },
  { value: "mantenimiento_vehicular", label: "Mantenimiento vehicular" },
];

const TASAS_IVA_SOLICITUD = [
  { value: 16, label: "16%" },
  { value: 8,  label: "8% frontera" },
  { value: 0,  label: "0%" },
];

const conceptoBlank = () => ({
  _k: uid(), numero_parte: "", descripcion: "", notas: "", enlace: "",
  cantidad: "", unidad_medida: "Pza", precio_unitario: "",
});

const subtotalConcepto = (c) => (Number(c.cantidad) || 0) * (Number(c.precio_unitario) || 0);

/**
 * Totales de la solicitud.
 *
 * El total resta las retenciones porque es lo que se va a pagar: con una
 * retención de ISR capturada, el proveedor factura más de lo que cobra. Si
 * alguna vez hace falta el importe facturado sin retener, es subtotal + iva.
 */
function totalesSolicitud(conceptos, ivaTasa, sinImpuesto, retIsr, retIva) {
  const subtotal = conceptos.reduce((s, c) => s + subtotalConcepto(c), 0);
  const iva = sinImpuesto ? 0 : subtotal * (Number(ivaTasa) || 0) / 100;
  const total = subtotal + iva - (Number(retIsr) || 0) - (Number(retIva) || 0);
  return { subtotal, iva, total };
}

/**
 * El siguiente folio.
 *
 * El consecutivo se consulta contra la base y no contra el estado local: dos
 * pestañas abiertas calcularían el mismo número. Si aun así chocan, el índice
 * único (unidad, anio, consecutivo) rebota el insert y se reintenta.
 */
async function siguienteConsecutivoSolicitud(unidad, anio, inicial, reinicia) {
  let q = supabase.from("solicitudes").select("consecutivo")
    .eq("unidad", unidad).not("consecutivo", "is", null)
    .order("consecutivo", { ascending: false }).limit(1);
  if (reinicia) q = q.eq("anio", anio);
  const { data, error } = await q;
  if (error) throw error;
  const ultimo = data?.length ? Number(data[0].consecutivo) : null;
  return ultimo === null ? Number(inicial) || 1 : ultimo + 1;
}

/**
 * Alta y edición con el mismo formulario. Con dos, habría que mantener los
 * dos iguales cada vez que cambie un campo — y el día que dejaran de estarlo,
 * lo capturado y lo corregido empezarían a diferir sin que nadie lo note.
 */
function NuevaSolicitudPanel({ unidad, session, parametros, correos, proyectos, zonas, onGuardada, onCancelar, solicitud = null, conceptosIniciales = null }) {
  const hoy = hoyISO();
  const editando = !!solicitud;
  /* El id se genera al abrir la pantalla, no al guardar: es lo que permite
     adjuntar antes de enviar. Al insertar se usa este mismo, de modo que los
     archivos ya subidos queden colgando de la solicitud correcta. */
  const [solicitudId] = useState(() => solicitud?.id || uid());
  const [specs, setSpecs] = useState({});
  const [f, setF] = useState(() => solicitud ? ({
    correo_solicitante: solicitud.correo_solicitante || "",
    nombre_solicitante: solicitud.nombre_solicitante || "",
    zona: solicitud.zona || "", proyecto: solicitud.proyecto || "",
    tipo_solicitud: solicitud.tipo_solicitud || "productos_servicios",
    vehiculo: solicitud.vehiculo || "", kilometraje: solicitud.kilometraje ?? "",
    folio_usuario: solicitud.folio_usuario || "",
    descripcion_general: solicitud.descripcion_general || "",
    justificacion: solicitud.justificacion || "",
    proveedor_sugerido: solicitud.proveedor_sugerido || "",
    fecha_solicitud: String(solicitud.fecha_solicitud || hoy).slice(0, 10),
    divisa: solicitud.divisa || "MXP", iva_tasa: Number(solicitud.iva_tasa ?? 16),
    sin_impuesto: !!solicitud.sin_impuesto,
    ret_isr: Number(solicitud.ret_isr) || "", ret_iva: Number(solicitud.ret_iva) || "",
  }) : ({
    correo_solicitante: "", nombre_solicitante: "", zona: "", proyecto: "",
    tipo_solicitud: "productos_servicios", vehiculo: "", kilometraje: "",
    folio_usuario: "", descripcion_general: "", justificacion: "", proveedor_sugerido: "",
    fecha_solicitud: hoy, divisa: "MXP", iva_tasa: 16, sin_impuesto: false,
    ret_isr: "", ret_iva: "",
  }));
  /* `_id` recuerda de qué fila vino cada concepto: sin eso, guardar obligaría
     a borrar todos y reinsertarlos, y las transacciones que más adelante
     apunten a un concepto quedarían apuntando a un id que ya no existe. */
  const [conceptos, setConceptos] = useState(() =>
    (conceptosIniciales && conceptosIniciales.length)
      ? conceptosIniciales.map((c) => ({
          /* La clave de React es el id real: así las especificaciones se
             cuelgan del concepto correcto sin un segundo identificador. */
          _k: c.id, _id: c.id,
          numero_parte: c.numero_parte || "", descripcion: c.descripcion || "",
          notas: c.notas || "", enlace: c.enlace || "",
          cantidad: c.cantidad ?? "", unidad_medida: c.unidad_medida || "",
          precio_unitario: c.precio_unitario ?? "",
        }))
      : [conceptoBlank()]);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState("");

  const cargarSpecs = async () => {
    const ids = conceptos.map((c) => c._k);
    if (!ids.length) { setSpecs({}); return; }
    const { data } = await supabase.from("adjuntos").select("*")
      .eq("entidad", "solicitud_concepto").in("entidad_id", ids);
    setSpecs(Object.fromEntries((data || []).map((a) => [a.entidad_id, a])));
  };
  useEffect(() => { if (editando) cargarSpecs(); }, []);

  const vehicular = f.tipo_solicitud === "mantenimiento_vehicular";
  const tot = totalesSolicitud(conceptos, f.iva_tasa, f.sin_impuesto, f.ret_isr, f.ret_iva);

  const setC = (k, campo, valor) =>
    setConceptos(conceptos.map((c) => (c._k === k ? { ...c, [campo]: valor } : c)));

  const elegirCorreo = (correo) => {
    const a = correos.find((x) => x.correo === correo);
    setF({ ...f, correo_solicitante: correo, nombre_solicitante: a?.nombre || f.nombre_solicitante });
  };

  /* Al cancelar un alta, lo que ya se subió queda colgando de una solicitud
     que nunca existió: ni la app lo muestra ni el proceso puede moverlo a
     Drive. Se retira. En una edición no se toca nada, porque la solicitud
     sigue ahí. */
  const cancelar = async () => {
    if (editando) { onCancelar(); return; }
    const ids = [solicitudId, ...conceptos.map((c) => c._k)];
    const { data } = await supabase.from("adjuntos").select("*").in("entidad_id", ids);
    if (data && data.length) {
      if (!confirm(`Hay ${data.length} archivo(s) ya subidos. Al cancelar se descartan.\n\n¿Continuar?`)) return;
      for (const r of data) { try { await borrarAdjunto(r); } catch { /* se ignora */ } }
    }
    onCancelar();
  };

  const guardar = async () => {
    if (!f.correo_solicitante) { alert("Elige quién solicita."); return; }
    if (!String(f.descripcion_general).trim()) { alert("Falta la descripción general."); return; }
    const conValor = conceptos.filter((c) => String(c.descripcion).trim());
    if (!conValor.length) { alert("Captura al menos un concepto con descripción."); return; }

    setGuardando(true);
    setError("");
    try {
      const cabecera = {
        correo_solicitante: f.correo_solicitante,
        nombre_solicitante: String(f.nombre_solicitante).trim() || null,
        zona: f.zona || null, proyecto: f.proyecto || null,
        tipo_solicitud: f.tipo_solicitud,
        vehiculo: vehicular ? (String(f.vehiculo).trim() || null) : null,
        kilometraje: vehicular && f.kilometraje !== "" ? Number(f.kilometraje) : null,
        folio_usuario: String(f.folio_usuario).trim() || null,
        descripcion_general: String(f.descripcion_general).trim(),
        justificacion: String(f.justificacion).trim() || null,
        proveedor_sugerido: String(f.proveedor_sugerido).trim() || null,
        fecha_solicitud: f.fecha_solicitud,
        divisa: f.divisa, iva_tasa: Number(f.iva_tasa), sin_impuesto: !!f.sin_impuesto,
        ret_isr: Number(f.ret_isr) || 0, ret_iva: Number(f.ret_iva) || 0,
        subtotal: Number(tot.subtotal.toFixed(2)),
        iva: Number(tot.iva.toFixed(2)),
        total: Number(tot.total.toFixed(2)),
      };

      if (editando) {
        /* El folio y el consecutivo no se tocan: son la identidad de la
           solicitud y hay una carpeta de Drive nombrada con ellos. */
        const { data, error: e } = await supabase
          .from("solicitudes").update(cabecera).eq("id", solicitud.id).select().single();
        if (e) throw e;

        const vivos = conValor.filter((c) => c._id).map((c) => c._id);
        const borrar = (conceptosIniciales || []).filter((c) => !vivos.includes(c.id)).map((c) => c.id);
        if (borrar.length) {
          const { error: eb } = await supabase.from("solicitud_conceptos").delete().in("id", borrar);
          if (eb) throw eb;
        }
        for (let i = 0; i < conValor.length; i++) {
          const c = conValor[i];
          const fila = {
            orden: i + 1,
            numero_parte: String(c.numero_parte).trim() || null,
            descripcion: String(c.descripcion).trim(),
            notas: String(c.notas).trim() || null,
            enlace: String(c.enlace).trim() || null,
            cantidad: Number(c.cantidad) || 0,
            unidad_medida: String(c.unidad_medida).trim() || null,
            precio_unitario: Number(c.precio_unitario) || 0,
            subtotal: Number(subtotalConcepto(c).toFixed(2)),
          };
          const r = c._id
            ? await supabase.from("solicitud_conceptos").update(fila).eq("id", c._id)
            : await supabase.from("solicitud_conceptos").insert({ id: c._k, solicitud_id: solicitud.id, ...fila });
          if (r.error) throw r.error;
        }
        onGuardada(data);
        return;
      }

      const anio = Number(String(f.fecha_solicitud).slice(0, 4)) || new Date().getFullYear();
      const base = await siguienteConsecutivoSolicitud(
        unidad, anio, parametros.consecutivo_inicial, parametros.reinicia_cada_anio);

      let guardada = null;
      for (let intento = 0; intento < 8 && !guardada; intento++) {
        const consecutivo = base + intento;
        const folio = armarFolioSolicitud(
          parametros.formato_folio, consecutivo, parametros.ancho_consecutivo,
          unidad, new Date(`${f.fecha_solicitud}T12:00:00`));
        const fila = {
          id: solicitudId, folio, consecutivo, anio, unidad,
          folio_usuario: String(f.folio_usuario).trim() || null,
          correo_solicitante: f.correo_solicitante,
          nombre_solicitante: String(f.nombre_solicitante).trim() || null,
          zona: f.zona || null, proyecto: f.proyecto || null,
          tipo_solicitud: f.tipo_solicitud,
          vehiculo: vehicular ? (String(f.vehiculo).trim() || null) : null,
          kilometraje: vehicular && f.kilometraje !== "" ? Number(f.kilometraje) : null,
          descripcion_general: String(f.descripcion_general).trim(),
          justificacion: String(f.justificacion).trim() || null,
          proveedor_sugerido: String(f.proveedor_sugerido).trim() || null,
          fecha_solicitud: f.fecha_solicitud,
          divisa: f.divisa, iva_tasa: Number(f.iva_tasa), sin_impuesto: !!f.sin_impuesto,
          ret_isr: Number(f.ret_isr) || 0, ret_iva: Number(f.ret_iva) || 0,
          subtotal: Number(tot.subtotal.toFixed(2)),
          iva: Number(tot.iva.toFixed(2)),
          total: Number(tot.total.toFixed(2)),
          estado: "entrada",
        };
        const { data, error: e } = await supabase.from("solicitudes").insert(fila).select().single();
        if (!e) { guardada = data; break; }
        const choco = /solicitudes_consecutivo_idx|solicitudes_folio_idx|duplicate/i.test(e.message || "");
        if (!choco || intento === 7) throw e;
      }

      const lineas = conValor.map((c, i) => ({
        id: c._k, solicitud_id: guardada.id, orden: i + 1,
        numero_parte: String(c.numero_parte).trim() || null,
        descripcion: String(c.descripcion).trim(),
        notas: String(c.notas).trim() || null,
        enlace: String(c.enlace).trim() || null,
        cantidad: Number(c.cantidad) || 0,
        unidad_medida: String(c.unidad_medida).trim() || null,
        precio_unitario: Number(c.precio_unitario) || 0,
        subtotal: Number(subtotalConcepto(c).toFixed(2)),
      }));
      const { error: e2 } = await supabase.from("solicitud_conceptos").insert(lineas);
      if (e2) throw e2;

      onGuardada(guardada);
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setGuardando(false);
    }
  };

  const money = (n) => `$${numMx(n)} ${f.divisa === "USD" ? "USD" : "MXN"}`;

  return (
    <>
      <Panel
        title={editando ? `Editar ${solicitud.folio}` : "Nueva solicitud"}
        subtitle={editando
          ? "El folio no cambia: hay una carpeta de Drive nombrada con él."
          : `El folio se asigna al guardar, siguiendo la serie de ${unidad}.`}
        right={
          <div style={{ display: "flex", gap: 8 }}>
            <Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Button>
            <Button variant="ghost" onClick={cancelar}>Cancelar</Button>
          </div>
        }
      >
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 14 }}>
          <Field label="Solicitante *">
            <Select value={f.correo_solicitante} onChange={(e) => elegirCorreo(e.target.value)}>
              <option value="">— elegir —</option>
              {correos.map((c) => (
                <option key={c.correo} value={c.correo}>{c.nombre || c.correo}</option>
              ))}
            </Select>
            {!correos.length && (
              <span style={{ fontSize: 10.5, color: T.amberDim, marginTop: 3 }}>
                No hay correos autorizados. Cárgalos en solicitudes_correos_autorizados.
              </span>
            )}
          </Field>
          <Field label="Correo">
            <TextInput value={f.correo_solicitante} disabled />
          </Field>
          <Field label="Folio del solicitante">
            <TextInput value={f.folio_usuario} onChange={(e) => setF({ ...f, folio_usuario: e.target.value })}
              placeholder="REQ-DO-08-09092026" />
          </Field>

          <Field label="Tipo">
            <Select value={f.tipo_solicitud} onChange={(e) => setF({ ...f, tipo_solicitud: e.target.value })}>
              {TIPOS_SOLICITUD.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </Select>
          </Field>
          <Field label="Zona">
            <Select value={f.zona} onChange={(e) => setF({ ...f, zona: e.target.value })}>
              <option value="">— sin zona —</option>
              {zonas.map((z) => <option key={z} value={z}>{z}</option>)}
            </Select>
          </Field>
          <Field label="Proyecto">
            <Select value={f.proyecto} onChange={(e) => setF({ ...f, proyecto: e.target.value })}>
              <option value="">— sin proyecto —</option>
              {proyectos.map((p) => <option key={p} value={p}>{p}</option>)}
            </Select>
          </Field>

          {vehicular && (
            <>
              <Field label="Vehículo">
                <TextInput value={f.vehiculo} onChange={(e) => setF({ ...f, vehiculo: e.target.value })} />
              </Field>
              <Field label="Kilometraje">
                <TextInput type="number" value={f.kilometraje}
                  onChange={(e) => setF({ ...f, kilometraje: e.target.value })} />
              </Field>
            </>
          )}

          <Field label="Fecha de solicitud">
            <TextInput type="date" value={f.fecha_solicitud}
              onChange={(e) => setF({ ...f, fecha_solicitud: e.target.value })} />
          </Field>
          <Field label="Posible proveedor">
            <TextInput value={f.proveedor_sugerido}
              onChange={(e) => setF({ ...f, proveedor_sugerido: e.target.value })} />
          </Field>
        </div>

        <Field label="Descripción general *" style={{ marginTop: 14 }}>
          <TextInput value={f.descripcion_general}
            onChange={(e) => setF({ ...f, descripcion_general: e.target.value })} />
        </Field>
        <Field label="Justificación" style={{ marginTop: 14 }}>
          <textarea
            value={f.justificacion}
            onChange={(e) => setF({ ...f, justificacion: e.target.value })}
            rows={3}
            style={{
              width: "100%", padding: "9px 11px", border: `1px solid ${T.border}`, borderRadius: 6,
              background: T.panel, color: T.text, fontSize: 12.5, fontFamily: T.fontUI,
              lineHeight: 1.55, resize: "vertical", boxSizing: "border-box",
            }}
          />
        </Field>
      </Panel>

      <Panel
        title="Conceptos"
        subtitle="Lo que se pide. El formulario los llama partidas, pero aquí ese nombre ya es de las partidas presupuestales."
        right={<Button variant="ghost" onClick={() => setConceptos([...conceptos, conceptoBlank()])}>+ Concepto</Button>}
      >
        {conceptos.map((c, i) => (
          <div key={c._k} style={{
            background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8,
            padding: 13, marginBottom: 10,
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
              <span style={{ fontSize: 11.5, fontWeight: 700, color: T.textDim }}>#{i + 1}</span>
              <span style={{ marginLeft: "auto", fontSize: 12.5, fontFamily: T.fontMono, color: T.text }}>
                {money(subtotalConcepto(c))}
              </span>
              {conceptos.length > 1 && (
                <Button variant="danger" style={{ padding: "4px 10px" }}
                  onClick={async () => {
                    /* Sus especificaciones se van con él: si no, quedarían
                       colgando de un concepto que ya no existe. */
                    if (specs[c._k]) {
                      try { await borrarAdjunto(specs[c._k]); await cargarSpecs(); } catch { /* se ignora */ }
                    }
                    setConceptos(conceptos.filter((x) => x._k !== c._k));
                  }}>Quitar</Button>
              )}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 11 }}>
              <Field label="Descripción *" style={{ gridColumn: "span 2" }}>
                <TextInput value={c.descripcion} onChange={(e) => setC(c._k, "descripcion", e.target.value)} />
              </Field>
              <Field label="No. de parte">
                <TextInput value={c.numero_parte} onChange={(e) => setC(c._k, "numero_parte", e.target.value)} />
              </Field>
              <Field label="Cantidad">
                <TextInput type="number" step="0.001" value={c.cantidad}
                  onChange={(e) => setC(c._k, "cantidad", e.target.value)} />
              </Field>
              <Field label="Unidad">
                <TextInput value={c.unidad_medida} onChange={(e) => setC(c._k, "unidad_medida", e.target.value)} />
              </Field>
              <Field label="Precio unitario">
                <TextInput type="number" step="0.0001" value={c.precio_unitario}
                  onChange={(e) => setC(c._k, "precio_unitario", e.target.value)} />
              </Field>
              <Field label="Notas" style={{ gridColumn: "span 2" }}>
                <TextInput value={c.notas} onChange={(e) => setC(c._k, "notas", e.target.value)} />
              </Field>
              <Field label="Enlace">
                <TextInput value={c.enlace} onChange={(e) => setC(c._k, "enlace", e.target.value)} />
              </Field>
            </div>
            <SpecsConcepto
              concepto={{ id: c._k }}
              unidad={unidad}
              carpeta={solicitudId}
              adjunto={specs[c._k] || null}
              onCambio={cargarSpecs}
            />
          </div>
        ))}
      </Panel>

      <AdjuntosPanel
        entidad="solicitud"
        entidadId={solicitudId}
        unidad={unidad}
        carpeta={solicitudId}
      />

      <Panel title="Impuestos y total" subtitle="Aplican a toda la solicitud, no a cada concepto.">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(170px, 1fr))", gap: 14, maxWidth: 780 }}>
          <Field label="Divisa">
            <Select value={f.divisa} onChange={(e) => setF({ ...f, divisa: e.target.value })}>
              <option value="MXP">MXN</option>
              <option value="USD">USD</option>
            </Select>
          </Field>
          <Field label="IVA">
            <Select value={f.iva_tasa} disabled={f.sin_impuesto}
              onChange={(e) => setF({ ...f, iva_tasa: Number(e.target.value) })}>
              {TASAS_IVA_SOLICITUD.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </Select>
          </Field>
          <Field label="Retención ISR">
            <TextInput type="number" step="0.01" value={f.ret_isr}
              onChange={(e) => setF({ ...f, ret_isr: e.target.value })} />
          </Field>
          <Field label="Retención IVA">
            <TextInput type="number" step="0.01" value={f.ret_iva}
              onChange={(e) => setF({ ...f, ret_iva: e.target.value })} />
          </Field>
        </div>

        <label style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 12, fontSize: 12.5, color: T.textDim, cursor: "pointer" }}>
          <input type="checkbox" checked={f.sin_impuesto}
            onChange={(e) => setF({ ...f, sin_impuesto: e.target.checked })} />
          Sin impuesto — exento, que no es lo mismo que gravado a tasa cero
        </label>

        <div style={{ marginTop: 16, maxWidth: 380, fontSize: 13, fontFamily: T.fontMono }}>
          {[["Subtotal", tot.subtotal], ["IVA", tot.iva],
            ...(Number(f.ret_isr) ? [["Ret. ISR", -Number(f.ret_isr)]] : []),
            ...(Number(f.ret_iva) ? [["Ret. IVA", -Number(f.ret_iva)]] : [])
          ].map(([k, v]) => (
            <div key={k} style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", color: T.textDim }}>
              <span>{k}</span><span>{money(v)}</span>
            </div>
          ))}
          <div style={{ display: "flex", justifyContent: "space-between", padding: "8px 0 0",
                        borderTop: `1px solid ${T.border}`, marginTop: 6, fontWeight: 700, color: T.text, fontSize: 15 }}>
            <span>Total</span><span>{money(tot.total)}</span>
          </div>
          {(Number(f.ret_isr) || Number(f.ret_iva)) ? (
            <div style={{ fontSize: 10.5, color: T.textFaint, marginTop: 8, fontFamily: T.fontUI, lineHeight: 1.5 }}>
              El total va neto de retenciones: es lo que se paga. El proveedor factura {money(tot.subtotal + tot.iva)}.
            </div>
          ) : null}
        </div>

        {error && <div style={{ marginTop: 14, fontSize: 12, color: T.red }}>No se pudo guardar: {error}</div>}
      </Panel>
    </>
  );
}

/* ----------------------------------------------------------------------
   ADJUNTOS
---------------------------------------------------------------------- */

/**
 * Genera el PDF de la solicitud y lo deja en el búfer para que el proceso lo
 * lleve a Drive, junto al resto del expediente.
 *
 * Reemplaza el anterior en vez de acumular: el PDF refleja el estado de la
 * solicitud, así que uno viejo al lado del nuevo solo sirve para que alguien
 * imprima el equivocado.
 */
async function guardarPdfEnDrive(solicitud, conceptos, centroCosto) {
  const previos = await supabase.from("adjuntos").select("*")
    .eq("entidad", "solicitud").eq("entidad_id", solicitud.id).eq("categoria", "smi");
  for (const p of (previos.data || [])) {
    try { await borrarAdjunto(p); } catch { /* si ya estaba en Drive, se queda el viejo allá */ }
  }

  const blob = pdfSolicitud(solicitud, conceptos, centroCosto).output("blob");
  const archivo = new File([blob], `${solicitud.folio}.pdf`, { type: "application/pdf" });
  await subirAdjunto({
    archivo, entidad: "solicitud", entidadId: solicitud.id,
    categoria: "smi", unidad: solicitud.unidad, carpeta: solicitud.id,
  });
}

const CATEGORIAS_ADJUNTO = [
  { value: "cotizacion",  label: "Cotización o factura" },
  { value: "soporte",     label: "Soporte" },
  { value: "relacionado", label: "Relacionado" },
  { value: "smi",         label: "PDF de la solicitud" },
  { value: "otro",        label: "Otro" },
];
const etiquetaCategoria = (v) =>
  (CATEGORIAS_ADJUNTO.find((c) => c.value === v) || { label: v || "Sin categoría" }).label;

const pesoLegible = (b) => {
  const n = Number(b) || 0;
  if (n < 1024) return `${n} B`;
  if (n < 1048576) return `${(n / 1024).toFixed(0)} KB`;
  return `${(n / 1048576).toFixed(1)} MB`;
};

/* Las claves de Storage no admiten acentos ni espacios sin darle problemas a
   la URL firmada. Se limpia el nombre para la ruta y el original se conserva
   en la tabla, que es el que ve la gente. */
const nombreParaRuta = (n) =>
  String(n || "archivo").normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Za-z0-9._-]+/g, "_").replace(/_+/g, "_").slice(0, 80);

const BUCKET_ADJUNTOS = "solicitudes-adjuntos";

/**
 * Sube un archivo al búfer y registra su fila. Compartida entre los adjuntos
 * de la solicitud y las especificaciones de cada concepto: si la copiara,
 * acabaría manteniendo dos versiones de lo mismo y divergirían.
 *
 * Si la fila falla después de subir, el objeto se retira del bucket. Sin eso
 * quedaría huérfano y nadie sabría de dónde salió.
 */
async function subirAdjunto({ archivo, entidad, entidadId, categoria, unidad, carpeta, subcarpeta }) {
  const id = uid();
  /* La carpeta del búfer es el ID de la solicitud, no su folio. El folio se
     asigna al guardar, y quien llena un formulario espera adjuntar la
     cotización ANTES de enviar, no después. El id existe desde que se abre
     la pantalla.

     Se pierde poder navegar el bucket a ojo, pero el búfer es de paso: en
     Drive la carpeta sigue llevando el folio, que es donde la gente busca. */
  const ruta = [unidad, carpeta, subcarpeta, `${id}-${nombreParaRuta(archivo.name)}`]
    .filter(Boolean).join("/");

  const up = await supabase.storage.from(BUCKET_ADJUNTOS)
    .upload(ruta, archivo, { contentType: archivo.type || undefined, upsert: false });
  if (up.error) throw up.error;

  const ins = await supabase.from("adjuntos").insert({
    id, entidad, entidad_id: entidadId, categoria,
    nombre: archivo.name, mime: archivo.type || null, tamano: archivo.size,
    storage_path: ruta, estado: "en_transito",
  });
  if (ins.error) {
    await supabase.storage.from(BUCKET_ADJUNTOS).remove([ruta]);
    throw ins.error;
  }
  return id;
}

/* Borra el objeto del búfer y su fila. Si el archivo ya está en Drive no hay
   objeto que borrar: solo se retira la referencia, y el archivo se queda allá.
   Borrarlo de Drive desde aquí sería destruir el expediente. */
async function borrarAdjunto(r) {
  if (r.storage_path) {
    const { error } = await supabase.storage.from(BUCKET_ADJUNTOS).remove([r.storage_path]);
    if (error) throw error;
  }
  const { error: e2 } = await supabase.from("adjuntos").delete().eq("id", r.id);
  if (e2) throw e2;
}

async function abrirAdjunto(r) {
  if (r.drive_link) { window.open(r.drive_link, "_blank"); return; }
  if (!r.storage_path) throw new Error("Este adjunto no tiene archivo ni enlace.");
  const { data, error } = await supabase.storage.from(BUCKET_ADJUNTOS)
    .createSignedUrl(r.storage_path, 60);
  if (error) throw error;
  window.open(data.signedUrl, "_blank");
}

/**
 * Las especificaciones de un concepto: un solo archivo, no una lista.
 * Reemplazar borra el anterior antes de subir el nuevo, para que no se
 * acumulen dos versiones sin saber cuál rige.
 */
function SpecsConcepto({ concepto, unidad, carpeta, adjunto, onCambio }) {
  const [trabajando, setTrabajando] = useState(false);
  const ref = useRef(null);

  const elegir = async (e) => {
    const archivo = e.target.files?.[0];
    e.target.value = "";
    if (!archivo) return;
    setTrabajando(true);
    try {
      if (adjunto) await borrarAdjunto(adjunto);
      await subirAdjunto({
        archivo, entidad: "solicitud_concepto", entidadId: concepto.id,
        categoria: "specs", unidad, carpeta, subcarpeta: "specs",
      });
      await onCambio();
    } catch (err) {
      alert("No se pudo: " + (err.message || err));
    } finally {
      setTrabajando(false);
    }
  };

  const quitar = async () => {
    if (!confirm(`¿Quitar "${adjunto.nombre}"?`)) return;
    setTrabajando(true);
    try { await borrarAdjunto(adjunto); await onCambio(); }
    catch (err) { alert("No se pudo: " + (err.message || err)); }
    finally { setTrabajando(false); }
  };

  return (
    <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 7, flexWrap: "wrap" }}>
      <span style={{ fontSize: 10.5, textTransform: "uppercase", letterSpacing: "0.05em", color: T.textDim }}>
        Especificaciones
      </span>
      {adjunto ? (
        <>
          <span style={{ fontSize: 11.5, color: T.text, wordBreak: "break-word" }}>{adjunto.nombre}</span>
          <Pill>{adjunto.estado === "en_drive" ? "En Drive" : "En tránsito"}</Pill>
          <Button variant="ghost" style={{ padding: "3px 9px" }}
            onClick={() => abrirAdjunto(adjunto).catch((e) => alert(e.message))}>Abrir</Button>
          <Button variant="ghost" style={{ padding: "3px 9px" }} disabled={trabajando}
            onClick={() => ref.current?.click()}>Reemplazar</Button>
          <Button variant="danger" style={{ padding: "3px 9px" }} disabled={trabajando}
            onClick={quitar}>Quitar</Button>
        </>
      ) : (
        <Button variant="ghost" style={{ padding: "3px 9px" }} disabled={trabajando}
          onClick={() => ref.current?.click()}>
          {trabajando ? "Subiendo…" : "+ Adjuntar"}
        </Button>
      )}
      <input ref={ref} type="file" onChange={elegir} style={{ display: "none" }} />
    </div>
  );
}

/**
 * Los archivos entran aquí, a un búfer en Supabase, y de aquí los recoge el
 * proceso que los lleva a Drive. Mientras `storage_path` tenga valor y
 * `drive_file_id` no, el archivo está en tránsito — y eso se ve en la lista,
 * para que nadie suponga que ya está archivado donde debe.
 */
function AdjuntosPanel({ entidad, entidadId, unidad, carpeta }) {
  const [filas, setFilas] = useState(null);
  const [categoria, setCategoria] = useState("cotizacion");
  const [subiendo, setSubiendo] = useState(false);
  const [progreso, setProgreso] = useState("");
  const [error, setError] = useState("");
  const refArchivo = useRef(null);

  const cargar = async () => {
    const { data, error: e } = await supabase
      .from("adjuntos").select("*")
      .eq("entidad", entidad).eq("entidad_id", entidadId)
      .order("subido_en");
    if (e) setError(e.message); else setFilas(data || []);
  };
  useEffect(() => { cargar(); }, [entidad, entidadId]);

  const subir = async (e) => {
    const archivos = [...(e.target.files || [])];
    e.target.value = "";
    if (!archivos.length) return;

    setSubiendo(true);
    setError("");
    try {
      for (let i = 0; i < archivos.length; i++) {
        const a = archivos[i];
        setProgreso(`${i + 1} de ${archivos.length}: ${a.name}`);
        await subirAdjunto({ archivo: a, entidad, entidadId, categoria, unidad, carpeta });
      }
      await cargar();
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setSubiendo(false);
      setProgreso("");
    }
  };

  const abrir = (r) => abrirAdjunto(r).catch((e) => setError(e.message || String(e)));

  const eliminar = async (r) => {
    if (!confirm(`¿Quitar "${r.nombre}"?`)) return;
    try { await borrarAdjunto(r); await cargar(); }
    catch (err) { setError(err.message || String(err)); }
  };

  const enTransito = (filas || []).filter((r) => r.estado === "en_transito").length;

  return (
    <Panel
      title="Adjuntos"
      subtitle="Se guardan aquí y de aquí pasan a Drive. Mientras tanto viven en Supabase."
    >
      {/* Los controles van en el cuerpo y no en el encabezado: ahí el bloque
          del título no tiene tope de ancho y con un subtítulo largo los
          empuja fuera de la vista. */}
      <div style={{
        display: "flex", gap: 10, alignItems: "flex-end", flexWrap: "wrap",
        background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8,
        padding: "12px 14px", marginBottom: 14,
      }}>
        <Field label="Categoría" style={{ maxWidth: 230, flex: "0 0 230px" }}>
          <Select value={categoria} onChange={(e) => setCategoria(e.target.value)}>
            {CATEGORIAS_ADJUNTO.map((c) => <option key={c.value} value={c.value}>{c.label}</option>)}
          </Select>
        </Field>
        <Button onClick={() => refArchivo.current?.click()} disabled={subiendo}>
          {subiendo ? "Subiendo…" : "+ Adjuntar archivos"}
        </Button>
        <input ref={refArchivo} type="file" multiple onChange={subir} style={{ display: "none" }} />
        <span style={{ fontSize: 11, color: T.textFaint, paddingBottom: 9 }}>
          Se pueden elegir varios a la vez. Máximo 25 MB por archivo.
        </span>
      </div>

      {progreso && <div style={{ fontSize: 12, color: T.textDim, marginBottom: 10 }}>{progreso}</div>}

      {filas === null ? (
        <div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div>
      ) : !filas.length ? (
        <EmptyState title="Sin adjuntos" body="Cotizaciones, soporte o cualquier archivo que acompañe a la solicitud." />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 1, background: T.border, border: `1px solid ${T.border}`, borderRadius: 6, overflow: "hidden" }}>
          {filas.map((r) => (
            <div key={r.id} style={{ display: "flex", gap: 12, alignItems: "center", background: T.panel, padding: "10px 12px" }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12.5, color: T.text, wordBreak: "break-word" }}>{r.nombre}</div>
                <div style={{ fontSize: 11, color: T.textFaint, marginTop: 2 }}>
                  {[etiquetaCategoria(r.categoria), pesoLegible(r.tamano), formatFechaHora(r.subido_en)]
                    .filter(Boolean).join("  ·  ")}
                </div>
              </div>
              <Pill>{r.estado === "en_drive" ? "En Drive" : r.estado === "en_transito" ? "En tránsito" : r.estado}</Pill>
              <Button variant="ghost" onClick={() => abrir(r)} style={{ padding: "4px 10px" }}>Abrir</Button>
              <Button variant="danger" onClick={() => eliminar(r)} style={{ padding: "4px 10px" }}>Quitar</Button>
            </div>
          ))}
        </div>
      )}

      {enTransito > 0 && (
        <div style={{ marginTop: 12, fontSize: 11.5, color: T.textFaint, lineHeight: 1.5 }}>
          {enTransito} archivo(s) siguen en Supabase. Pasarán a Drive cuando exista el proceso que los mueve;
          hasta entonces ocupan el espacio de la base.
        </div>
      )}
      {error && <div style={{ marginTop: 12, fontSize: 12, color: T.red }}>{error}</div>}
    </Panel>
  );
}

/* ----------------------------------------------------------------------
   PDF DE LA SOLICITUD
---------------------------------------------------------------------- */

/* Datos de control del formato. No cambian por solicitud: describen el
   documento, no su contenido. Si Calidad emite una revisión nueva, es aquí. */
const SMI_FORMATO = {
  titulo: "Solicitud de Servicios o Insumos",
  codificacion: "COM-FR-01-7",
  proceso: "Formato",
  consecutivo: "7",
  sistema: "Compras",
  disciplina: "ADMON",
  elaboracion: "19/OCT/2024",
};

const SMI_RAZON_SOCIAL = {
  OSB: "OSBOG SA DE CV",
  CTM: "CHAMPION TECHNOLOGIES DE MEXICO SA DE CV",
  ISE: "ISE",
};

/* El logo va incrustado en el archivo y no como URL: el PDF tiene que verse
   igual abierto desde cualquier lado, sin depender de que una imagen siga
   publicada en algún servidor. Son 28 KB. */
const LOGO_OSBOG = "data:image/png;base64,";

const ROJO = [200, 30, 30];
const GRIS = [235, 235, 235];

/**
 * Arma el PDF oficial de la SMI, el que pide el área de Pagos.
 *
 * Replica el formato que venía de Zoho porque Pagos ya lo reconoce: cambiar
 * el diseño obligaría a que alguien más aprenda a leer otro documento, sin
 * ganar nada.
 *
 * Dos diferencias a propósito: se imprime la cantidad, que en el original
 * salía en blanco aunque el subtotal dependiera de ella, y el estado se
 * muestra en español en vez de "Pending".
 */
function pdfSolicitud(solicitud, conceptos, centroCosto) {
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const M = 12;
  const ancho = doc.internal.pageSize.getWidth() - M * 2;
  const money = (n) => `$ ${numMx(n)}`;

  // ---- Encabezado con los datos de control del formato ----
  autoTable(doc, {
    startY: M,
    margin: { left: M, right: M },
    theme: "grid",
    styles: { fontSize: 7.5, cellPadding: 1.6, lineColor: [40, 40, 40], lineWidth: 0.2, valign: "middle" },
    body: [
      [
        { content: "", rowSpan: 4, styles: { halign: "center", valign: "middle", minCellHeight: 22 } },
        { content: SMI_FORMATO.titulo, colSpan: 2, styles: { halign: "center", fontSize: 11 } },
        { content: `CODIFICACIÓN:\n${SMI_FORMATO.codificacion}`, colSpan: 2, styles: { halign: "center" } },
      ],
      [
        { content: "PROCESO", styles: { halign: "center", fontStyle: "bold" } },
        { content: "CONSECUTIVO", styles: { halign: "center", fontStyle: "bold" } },
        { content: "SISTEMA/SUBTEMA", styles: { halign: "center", fontStyle: "bold" } },
        { content: "DISCIPLINA", styles: { halign: "center", fontStyle: "bold" } },
      ],
      [
        { content: SMI_FORMATO.proceso, styles: { halign: "center" } },
        { content: SMI_FORMATO.consecutivo, styles: { halign: "center" } },
        { content: SMI_FORMATO.sistema, styles: { halign: "center" } },
        { content: SMI_FORMATO.disciplina, styles: { halign: "center" } },
      ],
      [
        { content: `Fecha de Elaboración: ${SMI_FORMATO.elaboracion}`, colSpan: 2, styles: { halign: "center" } },
        { content: "Página 1 de 1", colSpan: 2, styles: { halign: "center" } },
      ],
    ],
    columnStyles: { 0: { cellWidth: 38 } },
    /* La imagen se dibuja encima de la celda que se dejó vacía: autoTable no
       pinta imágenes, solo texto. */
    didDrawCell: (d) => {
      if (d.section === "body" && d.row.index === 0 && d.column.index === 0) {
        const w = 32, h = w * 136 / 520;
        doc.addImage(LOGO_OSBOG, "PNG",
          d.cell.x + (d.cell.width - w) / 2,
          d.cell.y + (d.cell.height - h) / 2, w, h);
      }
    },
  });

  const linea = (y) => {
    doc.setDrawColor(...ROJO); doc.setLineWidth(0.7);
    doc.line(M, y, M + ancho, y);
    doc.setDrawColor(40, 40, 40); doc.setLineWidth(0.2);
  };
  linea(doc.lastAutoTable.finalY + 2.5);

  // ---- Identificación, en tres bloques ----
  const et = { fontStyle: "bold", fillColor: [252, 238, 238], cellWidth: 20 };
  autoTable(doc, {
    startY: doc.lastAutoTable.finalY + 5,
    margin: { left: M, right: M },
    theme: "grid",
    styles: { fontSize: 8, cellPadding: 1.6, lineColor: [150, 150, 150], lineWidth: 0.1, valign: "middle" },
    body: [
      [{ content: "Solicita", styles: et }, solicitud.nombre_solicitante || "",
       { content: "Zona", styles: et }, solicitud.zona || "",
       { content: "Vehículo", styles: et }, solicitud.vehiculo || ""],
      [{ content: "Fecha", styles: et }, solicitud.fecha_solicitud || "",
       { content: "Correo", styles: et }, solicitud.correo_solicitante || "",
       { content: "Kilometraje", styles: et }, solicitud.kilometraje ? numMx(solicitud.kilometraje) : ""],
      [{ content: "CC", styles: et }, centroCosto || "",
       { content: "Folio Usuario", styles: et }, solicitud.folio_usuario || "",
       { content: "Moneda", styles: et }, solicitud.divisa === "USD" ? "USD" : "MXP"],
      [{ content: "Proyecto", styles: et }, solicitud.proyecto || "",
       { content: "Folio Compras", styles: et }, { content: solicitud.folio, styles: { fontStyle: "bold" } },
       "", ""],
      [{ content: "Tipo", styles: et },
       solicitud.tipo_solicitud === "mantenimiento_vehicular" ? "Mantenimiento vehicular" : "Productos / Servicios",
       "", "", "", ""],
    ],
  });
  linea(doc.lastAutoTable.finalY + 2.5);

  // ---- Descripción y justificación ----
  autoTable(doc, {
    startY: doc.lastAutoTable.finalY + 5,
    margin: { left: M, right: M },
    theme: "plain",
    styles: { fontSize: 8.5, cellPadding: 1.5, valign: "top" },
    body: [
      [{ content: "Descripción General del Requerimiento:", styles: { fontStyle: "bold", fontSize: 10 } },
       { content: "Justificación:", styles: { fontStyle: "bold", fontSize: 10 } }],
      [solicitud.descripcion_general || "", solicitud.justificacion || ""],
    ],
    columnStyles: { 0: { cellWidth: ancho / 2 }, 1: { cellWidth: ancho / 2 } },
  });
  linea(doc.lastAutoTable.finalY + 2.5);

  // ---- Conceptos ----
  autoTable(doc, {
    startY: doc.lastAutoTable.finalY + 5,
    margin: { left: M, right: M },
    theme: "grid",
    styles: { fontSize: 7.5, cellPadding: 1.4, lineColor: [40, 40, 40], lineWidth: 0.15, valign: "middle" },
    headStyles: { fillColor: GRIS, textColor: [20, 20, 20], fontStyle: "bold", halign: "center" },
    head: [["No Parte", "Cnt", "Unit", "Descripción", "Notas", "Precio", "SubTotal"]],
    body: (conceptos || []).map((c) => [
      c.numero_parte || "NA",
      numMx(c.cantidad),                 // en el formato viejo salía en blanco
      c.unidad_medida || "",
      c.descripcion || "",
      c.notas || "",
      money(c.precio_unitario),
      money(c.subtotal),
    ]),
    columnStyles: {
      0: { cellWidth: 22, halign: "center" },
      1: { cellWidth: 14, halign: "center" },
      2: { cellWidth: 13, halign: "center" },
      3: { cellWidth: "auto", halign: "center" },
      4: { cellWidth: 26, halign: "center" },
      5: { cellWidth: 22, halign: "right" },
      6: { cellWidth: 24, halign: "right" },
    },
  });

  // ---- Estado y totales ----
  const yTot = doc.lastAutoTable.finalY + 6;
  const estado = etiquetaEstado(solicitud.estado).toUpperCase();
  doc.setDrawColor(...ROJO); doc.setLineWidth(0.6);
  doc.roundedRect(M + 6, yTot, 62, 12, 6, 6);
  doc.setTextColor(...ROJO); doc.setFont(undefined, "bold"); doc.setFontSize(12);
  doc.text(estado, M + 37, yTot + 8, { align: "center" });
  doc.setTextColor(20, 20, 20); doc.setFont(undefined, "normal");

  const filas = [
    ["SubTotal:", money(solicitud.subtotal)],
    [solicitud.sin_impuesto ? "IVA (exento):" : `IVA ${numMx(solicitud.iva_tasa)}%:`, money(solicitud.iva)],
    ["Ret IVA:", Number(solicitud.ret_iva) ? money(solicitud.ret_iva) : "$"],
    ["Ret ISR:", Number(solicitud.ret_isr) ? money(solicitud.ret_isr) : "$"],
    [{ content: "Total Estimado:", styles: { fontStyle: "bold" } },
     { content: money(solicitud.total), styles: { fontStyle: "bold" } }],
  ];
  autoTable(doc, {
    startY: yTot,
    margin: { left: M + ancho - 78, right: M },
    theme: "grid",
    styles: { fontSize: 8.5, cellPadding: 1.4, lineColor: [40, 40, 40], lineWidth: 0.15 },
    body: filas,
    columnStyles: { 0: { cellWidth: 38, halign: "right", fontStyle: "bold" }, 1: { cellWidth: 40, halign: "left" } },
  });

  // ---- Pie ----
  const alto = doc.internal.pageSize.getHeight();
  doc.setFontSize(7); doc.setFont(undefined, "bold");
  doc.text(SMI_RAZON_SOCIAL[solicitud.unidad] || solicitud.unidad, M + ancho / 2, alto - 10, { align: "center" });

  return doc;
}

/* ----------------------------------------------------------------------
   SOLICITUDES — DETALLE
---------------------------------------------------------------------- */

const ESTADOS_SOLICITUD = [
  { value: "entrada",     label: "Entrada" },
  { value: "en_revision", label: "En revisión" },
  { value: "cotizando",   label: "Cotizando" },
  { value: "autorizada",  label: "Autorizada" },
  { value: "rechazada",   label: "Rechazada" },
  { value: "convertida",  label: "Convertida" },
  { value: "cancelada",   label: "Cancelada" },
];
const etiquetaEstado = (v) =>
  (ESTADOS_SOLICITUD.find((e) => e.value === v) || { label: v }).label;

function SolicitudDetallePanel({ solicitud, session, onVolver, onCambiada, onEditar }) {
  const [conceptos, setConceptos] = useState(null);
  const [specs, setSpecs] = useState({});
  /* El centro de costo no está en la solicitud: vive en el catálogo de
     proyectos, y la solicitud guarda el nombre del proyecto como texto. Se
     resuelve al abrir para poder imprimirlo. */
  const [centroCosto, setCentroCosto] = useState("");
  const [guardandoPdf, setGuardandoPdf] = useState(false);
  const [estado, setEstado] = useState(solicitud.estado);
  const [notas, setNotas] = useState(solicitud.notas_revision || "");
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState("");

  /* Las specs de todos los conceptos se traen en UNA consulta y no una por
     concepto: con doce líneas serían doce viajes para mostrar una pantalla. */
  const cargarSpecs = async (ids) => {
    if (!ids.length) { setSpecs({}); return; }
    const { data } = await supabase.from("adjuntos").select("*")
      .eq("entidad", "solicitud_concepto").in("entidad_id", ids);
    setSpecs(Object.fromEntries((data || []).map((a) => [a.entidad_id, a])));
  };

  const cargarConceptos = async () => {
    const { data, error: e } = await supabase
      .from("solicitud_conceptos").select("*")
      .eq("solicitud_id", solicitud.id).order("orden");
    if (e) { setError(e.message); return; }
    setConceptos(data || []);
    await cargarSpecs((data || []).map((c) => c.id));
  };

  useEffect(() => { cargarConceptos(); }, [solicitud.id]);

  useEffect(() => {
    let vivo = true;
    (async () => {
      if (!solicitud.proyecto) { setCentroCosto(""); return; }
      const { data } = await supabase.from("proyectos").select("centro_costo")
        .eq("unidad", solicitud.unidad).eq("nombre", solicitud.proyecto).maybeSingle();
      if (vivo) setCentroCosto(data?.centro_costo || "");
    })();
    return () => { vivo = false; };
  }, [solicitud.id, solicitud.proyecto, solicitud.unidad]);

  const money = (n) => `$${numMx(n)} ${solicitud.divisa === "USD" ? "USD" : "MXN"}`;
  const cambio = estado !== solicitud.estado || notas !== (solicitud.notas_revision || "");

  /* La suma de los conceptos debe dar el subtotal guardado. Si no, alguien
     editó la solicitud por fuera o hubo un redondeo distinto al capturar, y
     conviene verlo aquí y no cuando el importe llegue a un reporte. */
  const sumaConceptos = (conceptos || []).reduce((s, c) => s + Number(c.subtotal || 0), 0);
  const descuadre = conceptos && Math.abs(sumaConceptos - Number(solicitud.subtotal || 0)) > 0.01;

  const guardar = async () => {
    setGuardando(true);
    setError("");
    try {
      const patch = {
        estado, notas_revision: notas.trim() || null,
        revisado_en: new Date().toISOString(),
        ...(session?.user?.id ? { revisado_por: session.user.id } : {}),
      };
      const { data, error: e } = await supabase
        .from("solicitudes").update(patch).eq("id", solicitud.id).select().single();
      if (e) throw e;
      onCambiada(data);
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setGuardando(false);
    }
  };

  const dato = (k, v) => v ? (
    <div key={k}>
      <div style={{ fontSize: 10.5, textTransform: "uppercase", letterSpacing: "0.05em", color: T.textDim }}>{k}</div>
      <div style={{ fontSize: 12.5, color: T.text, marginTop: 2 }}>{v}</div>
    </div>
  ) : null;

  return (
    <>
      <Panel
        title={solicitud.folio}
        subtitle={solicitud.descripcion_general}
        right={
          <div style={{ display: "flex", gap: 8 }}>
            {/* Una solicitud ya convertida no se edita: sus importes viven en
                transacciones y cambiarlos aquí las dejaría desfasadas. */}
            <Button
              onClick={() => onEditar(conceptos || [])}
              disabled={!conceptos || solicitud.estado === "convertida"}
              title={solicitud.estado === "convertida" ? "Ya se convirtió en transacciones" : undefined}
            >Editar</Button>
            <Button
              variant="ghost"
              disabled={!conceptos}
              onClick={() => pdfSolicitud(solicitud, conceptos, centroCosto).save(`${solicitud.folio}.pdf`)}
            >Descargar PDF</Button>
            <Button
              variant="ghost"
              disabled={!conceptos || guardandoPdf}
              onClick={async () => {
                setGuardandoPdf(true);
                try {
                  await guardarPdfEnDrive(solicitud, conceptos, centroCosto);
                  alert("El PDF quedó en el expediente. Pasa a Drive en la siguiente corrida del proceso.");
                } catch (err) { alert("No se pudo: " + (err.message || err)); }
                finally { setGuardandoPdf(false); }
              }}
            >{guardandoPdf ? "Guardando…" : "PDF al expediente"}</Button>
            <Button variant="ghost" onClick={onVolver}>Volver a la lista</Button>
          </div>
        }
      >
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(170px, 1fr))", gap: 16 }}>
          {dato("Solicitante", solicitud.nombre_solicitante || solicitud.correo_solicitante)}
          {dato("Correo", solicitud.correo_solicitante)}
          {dato("Folio del solicitante", solicitud.folio_usuario)}
          {dato("Tipo", solicitud.tipo_solicitud === "mantenimiento_vehicular"
            ? "Mantenimiento vehicular" : "Productos / Servicios")}
          {dato("Zona", solicitud.zona)}
          {dato("Proyecto", solicitud.proyecto)}
          {dato("Vehículo", solicitud.vehiculo)}
          {dato("Kilometraje", solicitud.kilometraje ? numMx(solicitud.kilometraje) : null)}
          {dato("Fecha", solicitud.fecha_solicitud)}
          {dato("Posible proveedor", solicitud.proveedor_sugerido)}
        </div>

        {solicitud.justificacion && (
          <div style={{ marginTop: 16, paddingTop: 13, borderTop: `1px solid ${T.border}` }}>
            <div style={{ fontSize: 10.5, textTransform: "uppercase", letterSpacing: "0.05em", color: T.textDim }}>Justificación</div>
            <div style={{ fontSize: 12.5, color: T.textDim, marginTop: 4, lineHeight: 1.6 }}>{solicitud.justificacion}</div>
          </div>
        )}
      </Panel>

      <Panel title="Conceptos" subtitle={conceptos ? `${conceptos.length} en total` : ""}>
        {!conceptos ? (
          <div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div>
        ) : !conceptos.length ? (
          <EmptyState title="Sin conceptos" body="La solicitud se guardó sin líneas de detalle." />
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 1, background: T.border, border: `1px solid ${T.border}`, borderRadius: 6, overflow: "hidden" }}>
            {conceptos.map((c) => (
              <div key={c.id} style={{ background: T.panel, padding: "11px 13px" }}>
                <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
                  <span style={{ fontSize: 11.5, color: T.textFaint, fontVariantNumeric: "tabular-nums", minWidth: 20 }}>{c.orden}</span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 12.5, color: T.text }}>{c.descripcion}</div>
                    <div style={{ fontSize: 11, color: T.textFaint, marginTop: 3 }}>
                      {[c.numero_parte && `Parte ${c.numero_parte}`,
                        `${numMx(c.cantidad)} ${c.unidad_medida || ""}`.trim(),
                        `× $${numMx(c.precio_unitario)}`].filter(Boolean).join("  ·  ")}
                    </div>
                    {c.notas && <div style={{ fontSize: 11, color: T.textDim, marginTop: 4 }}>{c.notas}</div>}
                    {c.enlace && (
                      <a href={c.enlace} target="_blank" rel="noreferrer"
                        style={{ fontSize: 11, color: T.accent, marginTop: 4, display: "inline-block" }}>{c.enlace}</a>
                    )}
                    <SpecsConcepto
                      concepto={c}
                      unidad={solicitud.unidad}
                      carpeta={solicitud.id}
                      adjunto={specs[c.id] || null}
                      onCambio={() => cargarSpecs(conceptos.map((x) => x.id))}
                    />
                  </div>
                  <span style={{ fontFamily: T.fontMono, fontSize: 12.5, color: T.text, whiteSpace: "nowrap" }}>
                    {money(c.subtotal)}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}

        <div style={{ marginTop: 16, maxWidth: 360, fontSize: 13, fontFamily: T.fontMono, marginLeft: "auto" }}>
          {[["Subtotal", solicitud.subtotal],
            [solicitud.sin_impuesto ? "IVA (exento)" : `IVA ${numMx(solicitud.iva_tasa)}%`, solicitud.iva],
            ...(Number(solicitud.ret_isr) ? [["Ret. ISR", -Number(solicitud.ret_isr)]] : []),
            ...(Number(solicitud.ret_iva) ? [["Ret. IVA", -Number(solicitud.ret_iva)]] : []),
          ].map(([k, v]) => (
            <div key={k} style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", color: T.textDim }}>
              <span>{k}</span><span>{money(v)}</span>
            </div>
          ))}
          <div style={{ display: "flex", justifyContent: "space-between", padding: "8px 0 0",
                        borderTop: `1px solid ${T.border}`, marginTop: 6, fontWeight: 700, color: T.text, fontSize: 15 }}>
            <span>Total</span><span>{money(solicitud.total)}</span>
          </div>
        </div>

        {descuadre && (
          <div style={{ marginTop: 14, fontSize: 12, color: T.amberDim, background: T.panelAlt, border: `1px solid ${T.amber}`, borderRadius: 6, padding: "9px 11px", lineHeight: 1.5 }}>
            Los conceptos suman {money(sumaConceptos)} pero el subtotal guardado dice {money(solicitud.subtotal)}.
            Algo se editó por fuera o hubo un redondeo distinto al capturar.
          </div>
        )}
      </Panel>

      <AdjuntosPanel
        entidad="solicitud"
        entidadId={solicitud.id}
        unidad={solicitud.unidad}
        carpeta={solicitud.id}
      />

      <Panel title="Revisión" subtitle="Dónde va la solicitud en el proceso.">
        <div style={{ display: "flex", gap: 14, alignItems: "flex-end", flexWrap: "wrap" }}>
          <Field label="Estado" style={{ maxWidth: 220 }}>
            <Select value={estado} onChange={(e) => setEstado(e.target.value)}>
              {ESTADOS_SOLICITUD.map((e) => <option key={e.value} value={e.value}>{e.label}</option>)}
            </Select>
          </Field>
          <Field label="Notas de revisión" style={{ flex: 1, minWidth: 260 }}>
            <TextInput value={notas} onChange={(e) => setNotas(e.target.value)} />
          </Field>
          <Button onClick={guardar} disabled={!cambio || guardando} style={{ marginBottom: 1 }}>
            {guardando ? "Guardando…" : "Guardar"}
          </Button>
        </div>

        {solicitud.revisado_en && (
          <div style={{ fontSize: 11, color: T.textFaint, marginTop: 10 }}>
            Última revisión: {formatFechaHora(solicitud.revisado_en)}
          </div>
        )}
        {error && <div style={{ marginTop: 12, fontSize: 12, color: T.red }}>No se pudo guardar: {error}</div>}
      </Panel>
    </>
  );
}

/* ----------------------------------------------------------------------
   SOLICITUDES — SOLICITANTES AUTORIZADOS
---------------------------------------------------------------------- */

/**
 * La lista blanca que la base hace cumplir.
 *
 * No es una comodidad de la interfaz: la política de `solicitudes` rechaza un
 * insert cuyo correo no esté aquí y activo. Quitar a alguien de esta lista lo
 * deja fuera del formulario público de inmediato, sin desplegar nada.
 */
function SolicitantesPanel({ unidad, unidades = [] }) {
  const [filas, setFilas] = useState(null);
  const [editando, setEditando] = useState(null);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState("");

  const cargar = async () => {
    setError("");
    const { data, error: e } = await supabase
      .from("solicitudes_correos_autorizados").select("*").order("nombre");
    if (e) setError(e.message); else setFilas(data || []);
  };
  useEffect(() => { cargar(); }, []);

  /* Se muestran los de la unidad activa y los que no tienen unidad, que son
     los que pueden solicitar en cualquiera. Es el mismo criterio que usa el
     selector de la bandeja. */
  const visibles = (filas || []).filter((r) => !r.unidad || r.unidad === unidad);
  const deOtras = (filas || []).length - visibles.length;

  const nuevo = () => setEditando({ _nuevo: true, correo: "", nombre: "", unidad, area: "", activo: true });

  const guardar = async () => {
    const correo = String(editando.correo || "").trim().toLowerCase();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(correo)) { alert("El correo no tiene forma válida."); return; }
    setGuardando(true);
    setError("");
    try {
      const fila = {
        correo,
        nombre: String(editando.nombre || "").trim() || null,
        unidad: editando.unidad || null,
        area: String(editando.area || "").trim() || null,
        activo: !!editando.activo,
      };
      const r = editando._nuevo
        ? await supabase.from("solicitudes_correos_autorizados").insert(fila)
        : await supabase.from("solicitudes_correos_autorizados").update(fila).eq("correo", editando.correo);
      if (r.error) {
        if (/duplicate|correos_autorizados_pkey/i.test(r.error.message || "")) {
          throw new Error(`${correo} ya está en la lista. Búscalo abajo y edítalo en vez de agregarlo otra vez.`);
        }
        throw r.error;
      }
      setEditando(null);
      await cargar();
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setGuardando(false);
    }
  };

  const alternarActivo = async (r) => {
    const { error: e } = await supabase.from("solicitudes_correos_autorizados")
      .update({ activo: !r.activo }).eq("correo", r.correo);
    if (e) setError(e.message); else cargar();
  };

  /* Borrar es distinto de desactivar. Las solicitudes guardan el correo como
     texto, sin llave foránea, así que borrarlo no rompe nada visiblemente —
     pero deja registros apuntando a alguien que ya no está en la lista y no
     hay forma de reconstruir quién era. Desactivar cumple el mismo propósito
     y conserva el nombre. */
  const eliminar = async (r) => {
    const { count, error: e } = await supabase
      .from("solicitudes").select("id", { count: "exact", head: true })
      .ilike("correo_solicitante", r.correo);
    if (e) { setError(e.message); return; }
    if (count) {
      alert(`${r.correo} tiene ${count} solicitud(es) a su nombre.\n\nDesactívalo en vez de borrarlo: deja de poder enviar, y las solicitudes conservan a quién pertenecen.`);
      return;
    }
    if (!confirm(`¿Quitar a ${r.correo} de la lista?`)) return;
    const { error: e2 } = await supabase
      .from("solicitudes_correos_autorizados").delete().eq("correo", r.correo);
    if (e2) setError(e2.message); else cargar();
  };

  return (
    <Panel
      title="Quién puede levantar solicitudes"
      subtitle="Esta lista la hace cumplir la base: un envío con un correo que no esté aquí y activo se rechaza, aunque alguien llame a la API directo."
      right={<Button onClick={nuevo}>+ Agregar</Button>}
    >
      {editando && (
        <div style={{ background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8, padding: 15, marginBottom: 16 }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: T.text, marginBottom: 12 }}>
            {editando._nuevo ? "Nuevo solicitante" : editando.correo}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: 13 }}>
            <Field label="Correo *">
              <TextInput
                value={editando.correo}
                disabled={!editando._nuevo}
                onChange={(e) => setEditando({ ...editando, correo: e.target.value })}
              />
              {!editando._nuevo && (
                <span style={{ fontSize: 10.5, color: T.textFaint, marginTop: 3 }}>
                  No se cambia: las solicitudes lo guardan como texto y quedarían huérfanas.
                </span>
              )}
            </Field>
            <Field label="Nombre">
              <TextInput value={editando.nombre}
                onChange={(e) => setEditando({ ...editando, nombre: e.target.value })} />
            </Field>
            <Field label="Compañía">
              <Select value={editando.unidad || ""}
                onChange={(e) => setEditando({ ...editando, unidad: e.target.value })}>
                <option value="">Todas</option>
                {(unidades.length ? unidades : [unidad]).map((u) => <option key={u} value={u}>{u}</option>)}
              </Select>
              <span style={{ fontSize: 10.5, color: T.textFaint, marginTop: 3 }}>
                Una persona aparece una sola vez: o es de una compañía, o es de todas.
              </span>
            </Field>
            <Field label="Área">
              <TextInput value={editando.area}
                onChange={(e) => setEditando({ ...editando, area: e.target.value })} />
            </Field>
          </div>
          <label style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 13, fontSize: 12.5, color: T.textDim, cursor: "pointer" }}>
            <input type="checkbox" checked={!!editando.activo}
              onChange={(e) => setEditando({ ...editando, activo: e.target.checked })} />
            Activo — puede enviar solicitudes
          </label>
          <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
            <Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Button>
            <Button variant="ghost" onClick={() => setEditando(null)}>Cancelar</Button>
          </div>
        </div>
      )}

      {filas === null ? (
        <div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div>
      ) : !visibles.length ? (
        <EmptyState
          title="Nadie autorizado para esta compañía"
          body="Sin al menos un correo aquí, la bandeja no deja capturar y el formulario público rechazaría todo."
        />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 1, background: T.border, border: `1px solid ${T.border}`, borderRadius: 6, overflow: "hidden" }}>
          {visibles.map((r) => (
            <div key={r.correo} style={{ display: "flex", gap: 12, alignItems: "center", background: T.panel, padding: "10px 12px", opacity: r.activo ? 1 : 0.55 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12.5, color: T.text, fontWeight: 600 }}>{r.nombre || r.correo}</div>
                <div style={{ fontSize: 11, color: T.textFaint, fontFamily: T.fontMono, marginTop: 2 }}>{r.correo}</div>
              </div>
              {r.area && <Pill>{r.area}</Pill>}
              <Pill>{r.unidad || "Todas"}</Pill>
              <Pill>{r.activo ? "Activo" : "Inactivo"}</Pill>
              <Button variant="ghost" onClick={() => alternarActivo(r)} style={{ padding: "4px 10px" }}>
                {r.activo ? "Desactivar" : "Activar"}
              </Button>
              <Button variant="ghost" onClick={() => setEditando({ ...r })} style={{ padding: "4px 10px" }}>Editar</Button>
              <Button variant="danger" onClick={() => eliminar(r)} style={{ padding: "4px 10px" }}>Quitar</Button>
            </div>
          ))}
        </div>
      )}

      {deOtras > 0 && (
        <div style={{ marginTop: 12, fontSize: 11.5, color: T.textFaint }}>
          Hay {deOtras} más asignados a otras compañías. Cambia de compañía arriba para verlos.
        </div>
      )}
      {error && <div style={{ marginTop: 12, fontSize: 12, color: T.red }}>{error}</div>}
    </Panel>
  );
}

/* ----------------------------------------------------------------------
   FORMULARIO PÚBLICO DE SOLICITUDES
---------------------------------------------------------------------- */

/**
 * La pantalla que llena quien pide, sin cuenta ni sesión.
 *
 * `anon` solo puede insertar: no lee solicitudes, ni la lista de correos, ni
 * los parámetros. Por eso todo lo que necesita saber viene de funciones de la
 * base —identificar el correo, listar catálogos— y el alta la hace
 * solicitud_crear, que calcula el folio del lado del servidor.
 *
 * Los archivos se acumulan en el navegador y se suben AL ENVIAR. Subirlos
 * antes dejaría archivos colgando de solicitudes abandonadas, y `anon` no
 * puede borrarlos: serían basura permanente en el búfer.
 */
function SolicitudPublicaPage() {
  const [paso, setPaso] = useState("correo");
  const [correo, setCorreo] = useState("");
  const [ident, setIdent] = useState(null);
  const [unidad, setUnidad] = useState("");
  const [unidades, setUnidades] = useState([]);
  const [catalogos, setCatalogos] = useState({ proyectos: [], zonas: [] });
  const [buscando, setBuscando] = useState(false);
  const [error, setError] = useState("");

  const hoy = hoyISO();
  const [f, setF] = useState({
    zona: "", proyecto: "", tipo_solicitud: "productos_servicios",
    vehiculo: "", kilometraje: "", folio_usuario: "",
    descripcion_general: "", justificacion: "", proveedor_sugerido: "",
    fecha_solicitud: hoy, divisa: "MXP", iva_tasa: 16, sin_impuesto: false,
    ret_isr: "", ret_iva: "",
  });
  const [conceptos, setConceptos] = useState([conceptoBlank()]);
  const [archivos, setArchivos] = useState([]);   // { _k, file, categoria }
  const [enviando, setEnviando] = useState(false);
  const [folioAsignado, setFolioAsignado] = useState("");
  const refArchivos = useRef(null);

  const vehicular = f.tipo_solicitud === "mantenimiento_vehicular";
  const tot = totalesSolicitud(conceptos, f.iva_tasa, f.sin_impuesto, f.ret_isr, f.ret_iva);
  const money = (n) => `$${numMx(n)} ${f.divisa === "USD" ? "USD" : "MXN"}`;

  const cargarCatalogos = async (u) => {
    const { data } = await supabase.rpc("solicitud_catalogos", { p_unidad: u });
    setCatalogos({
      proyectos: (data || []).filter((r) => r.tipo === "proyecto").map((r) => r.nombre),
      zonas: (data || []).filter((r) => r.tipo === "zona").map((r) => r.nombre),
    });
  };

  const identificar = async () => {
    const c = correo.trim().toLowerCase();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c)) { setError("El correo no tiene forma válida."); return; }
    setBuscando(true);
    setError("");
    try {
      const { data, error: e } = await supabase.rpc("solicitud_identificar", { p_correo: c });
      if (e) throw e;
      if (!data || !data.length) {
        setError("Ese correo no está autorizado para levantar solicitudes. Pídele a administración que te dé de alta.");
        return;
      }
      const yo = data[0];
      setIdent(yo);
      if (yo.unidad) {
        setUnidad(yo.unidad);
        await cargarCatalogos(yo.unidad);
      } else {
        /* Sin compañía asignada, puede solicitar en cualquiera: hay que
           preguntarle en cuál. */
        const { data: us } = await supabase.rpc("solicitud_unidades");
        setUnidades((us || []).map((r) => r.unidad));
      }
      setPaso("forma");
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setBuscando(false);
    }
  };

  const elegirUnidad = async (u) => { setUnidad(u); if (u) await cargarCatalogos(u); };

  const agregarArchivos = (e) => {
    const nuevos = [...(e.target.files || [])].map((file) => ({ _k: uid(), file, categoria: "cotizacion" }));
    e.target.value = "";
    const grandes = nuevos.filter((a) => a.file.size > 25 * 1024 * 1024);
    if (grandes.length) {
      alert(`Estos pasan de 25 MB y no se pueden subir:\n\n${grandes.map((a) => a.file.name).join("\n")}`);
    }
    setArchivos([...archivos, ...nuevos.filter((a) => a.file.size <= 25 * 1024 * 1024)]);
  };

  const enviar = async () => {
    if (!unidad) { setError("Elige la compañía."); return; }
    if (!String(f.descripcion_general).trim()) { setError("Falta la descripción general."); return; }
    const conValor = conceptos.filter((c) => String(c.descripcion).trim());
    if (!conValor.length) { setError("Captura al menos un concepto con descripción."); return; }

    setEnviando(true);
    setError("");
    const idSolicitud = uid();
    try {
      const { data, error: e } = await supabase.rpc("solicitud_crear", {
        p_id: idSolicitud,
        p_correo: correo.trim().toLowerCase(),
        p_cabecera: {
          unidad,
          nombre_solicitante: ident?.nombre || null,
          zona: f.zona || null, proyecto: f.proyecto || null,
          tipo_solicitud: f.tipo_solicitud,
          vehiculo: vehicular ? f.vehiculo : null,
          kilometraje: vehicular && f.kilometraje !== "" ? f.kilometraje : null,
          folio_usuario: f.folio_usuario || null,
          descripcion_general: String(f.descripcion_general).trim(),
          justificacion: f.justificacion || null,
          proveedor_sugerido: f.proveedor_sugerido || null,
          fecha_solicitud: f.fecha_solicitud,
          divisa: f.divisa, iva_tasa: f.iva_tasa, sin_impuesto: f.sin_impuesto,
          ret_isr: Number(f.ret_isr) || 0, ret_iva: Number(f.ret_iva) || 0,
        },
        p_conceptos: conValor.map((c) => ({
          id: c._k,
          numero_parte: c.numero_parte, descripcion: String(c.descripcion).trim(),
          notas: c.notas, enlace: c.enlace,
          cantidad: Number(c.cantidad) || 0,
          unidad_medida: c.unidad_medida,
          precio_unitario: Number(c.precio_unitario) || 0,
        })),
      });
      if (e) throw e;
      const folio = data?.[0]?.folio || "";

      /* Los archivos se suben DESPUÉS de que la solicitud existe. Si alguno
         falla, la solicitud ya está registrada: se le dice a quien envió, en
         vez de perder todo lo capturado. */
      const fallidos = [];
      for (const a of archivos) {
        try {
          await subirAdjunto({
            archivo: a.file, entidad: "solicitud", entidadId: idSolicitud,
            categoria: a.categoria, unidad, carpeta: idSolicitud,
          });
        } catch { fallidos.push(a.file.name); }
      }
      for (const c of conValor) {
        if (!c._spec) continue;
        try {
          await subirAdjunto({
            archivo: c._spec, entidad: "solicitud_concepto", entidadId: c._k,
            categoria: "specs", unidad, carpeta: idSolicitud, subcarpeta: "specs",
          });
        } catch { fallidos.push(c._spec.name); }
      }

      /* El PDF se genera aquí mismo: si esperara a que alguien pulse un botón
         en la bandeja, el expediente quedaría incompleto justo cuando Pagos
         lo pide. Los datos que necesita son los que se acaban de enviar. */
      try {
        await guardarPdfEnDrive(
          {
            id: idSolicitud, folio, unidad,
            nombre_solicitante: ident?.nombre || "", correo_solicitante: correo.trim().toLowerCase(),
            fecha_solicitud: f.fecha_solicitud, zona: f.zona, proyecto: f.proyecto,
            folio_usuario: f.folio_usuario, tipo_solicitud: f.tipo_solicitud,
            vehiculo: f.vehiculo, kilometraje: f.kilometraje,
            descripcion_general: f.descripcion_general, justificacion: f.justificacion,
            divisa: f.divisa, iva_tasa: f.iva_tasa, sin_impuesto: f.sin_impuesto,
            ret_isr: Number(f.ret_isr) || 0, ret_iva: Number(f.ret_iva) || 0,
            subtotal: tot.subtotal, iva: tot.iva, total: tot.total,
            estado: "entrada",
          },
          conValor.map((c, i) => ({
            orden: i + 1, numero_parte: c.numero_parte, descripcion: c.descripcion,
            notas: c.notas, cantidad: Number(c.cantidad) || 0, unidad_medida: c.unidad_medida,
            precio_unitario: Number(c.precio_unitario) || 0, subtotal: subtotalConcepto(c),
          })),
          ""   // el centro de costo lo resuelve la bandeja al regenerarlo
        );
      } catch { fallidos.push(`${folio}.pdf`); }

      setFolioAsignado(folio);
      setPaso("listo");
      if (fallidos.length) {
        alert(`La solicitud ${folio} quedó registrada, pero estos archivos no se pudieron subir:\n\n${fallidos.join("\n")}\n\nAvísale a administración para adjuntarlos.`);
      }
    } catch (err) {
      setError(err.message || String(err));
    } finally {
      setEnviando(false);
    }
  };

  const marco = (hijos) => (
    <div style={{ minHeight: "100vh", background: T.bg, fontFamily: T.fontUI, padding: "28px 18px" }}>
      <div style={{ maxWidth: 940, margin: "0 auto" }}>
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 11, letterSpacing: "0.14em", color: T.textFaint, textTransform: "uppercase" }}>
            Control de Presupuestos
          </div>
          <div style={{ fontSize: 24, fontWeight: 700, color: T.text, marginTop: 3 }}>
            Solicitud de compra
          </div>
        </div>
        {hijos}
      </div>
    </div>
  );

  if (paso === "correo") {
    return marco(
      <Panel title="¿Quién solicita?" subtitle="Escribe tu correo de la empresa para empezar.">
        <div style={{ display: "flex", gap: 10, alignItems: "flex-end", flexWrap: "wrap", maxWidth: 520 }}>
          <Field label="Correo" style={{ flex: 1, minWidth: 250 }}>
            <TextInput value={correo} autoFocus
              onChange={(e) => { setCorreo(e.target.value); setError(""); }}
              onKeyDown={(e) => { if (e.key === "Enter") identificar(); }} />
          </Field>
          <Button onClick={identificar} disabled={buscando} style={{ marginBottom: 1 }}>
            {buscando ? "Buscando…" : "Continuar"}
          </Button>
        </div>
        {error && <div style={{ marginTop: 14, fontSize: 12.5, color: T.red, lineHeight: 1.5, maxWidth: 520 }}>{error}</div>}
      </Panel>
    );
  }

  if (paso === "listo") {
    return marco(
      <Panel title="Solicitud enviada">
        <div style={{ fontSize: 13, color: T.textDim, lineHeight: 1.7 }}>
          Quedó registrada con el folio
        </div>
        <div style={{ fontSize: 30, fontWeight: 700, color: T.accent, fontFamily: T.fontMono, margin: "8px 0 14px" }}>
          {folioAsignado}
        </div>
        <div style={{ fontSize: 12.5, color: T.textDim, lineHeight: 1.7, maxWidth: 560 }}>
          Anótalo: es con el que se le da seguimiento. Administración la revisará y te buscará si
          hace falta algo más.
        </div>
        <div style={{ marginTop: 18 }}>
          <Button onClick={() => window.location.reload()}>Levantar otra</Button>
        </div>
      </Panel>
    );
  }

  return marco(
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <Panel title={ident?.nombre || correo} subtitle={correo}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(210px, 1fr))", gap: 14 }}>
          {!ident?.unidad && (
            <Field label="Compañía *">
              <Select value={unidad} onChange={(e) => elegirUnidad(e.target.value)}>
                <option value="">— elegir —</option>
                {unidades.map((u) => <option key={u} value={u}>{u}</option>)}
              </Select>
            </Field>
          )}
          <Field label="Tipo">
            <Select value={f.tipo_solicitud} onChange={(e) => setF({ ...f, tipo_solicitud: e.target.value })}>
              {TIPOS_SOLICITUD.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </Select>
          </Field>
          <Field label="Zona">
            <Select value={f.zona} onChange={(e) => setF({ ...f, zona: e.target.value })}>
              <option value="">— sin zona —</option>
              {catalogos.zonas.map((z) => <option key={z} value={z}>{z}</option>)}
            </Select>
          </Field>
          <Field label="Proyecto">
            <Select value={f.proyecto} onChange={(e) => setF({ ...f, proyecto: e.target.value })}>
              <option value="">— sin proyecto —</option>
              {catalogos.proyectos.map((p) => <option key={p} value={p}>{p}</option>)}
            </Select>
          </Field>
          <Field label="Tu folio o referencia">
            <TextInput value={f.folio_usuario} onChange={(e) => setF({ ...f, folio_usuario: e.target.value })} />
          </Field>
          {vehicular && (
            <>
              <Field label="Vehículo">
                <TextInput value={f.vehiculo} onChange={(e) => setF({ ...f, vehiculo: e.target.value })} />
              </Field>
              <Field label="Kilometraje">
                <TextInput type="number" value={f.kilometraje}
                  onChange={(e) => setF({ ...f, kilometraje: e.target.value })} />
              </Field>
            </>
          )}
          <Field label="Posible proveedor">
            <TextInput value={f.proveedor_sugerido}
              onChange={(e) => setF({ ...f, proveedor_sugerido: e.target.value })} />
          </Field>
        </div>

        <Field label="¿Qué necesitas? *" style={{ marginTop: 14 }}>
          <TextInput value={f.descripcion_general}
            onChange={(e) => setF({ ...f, descripcion_general: e.target.value })} />
        </Field>
        <Field label="¿Para qué?" style={{ marginTop: 14 }}>
          <textarea value={f.justificacion} rows={3}
            onChange={(e) => setF({ ...f, justificacion: e.target.value })}
            style={{
              width: "100%", padding: "9px 11px", border: `1px solid ${T.border}`, borderRadius: 6,
              background: T.panel, color: T.text, fontSize: 12.5, fontFamily: T.fontUI,
              lineHeight: 1.55, resize: "vertical", boxSizing: "border-box",
            }} />
        </Field>
      </Panel>

      <Panel
        title="¿Qué se pide?"
        right={<Button variant="ghost" onClick={() => setConceptos([...conceptos, conceptoBlank()])}>+ Agregar</Button>}
      >
        {conceptos.map((c, i) => (
          <div key={c._k} style={{ background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8, padding: 13, marginBottom: 10 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
              <span style={{ fontSize: 11.5, fontWeight: 700, color: T.textDim }}>#{i + 1}</span>
              <span style={{ marginLeft: "auto", fontSize: 12.5, fontFamily: T.fontMono, color: T.text }}>
                {money(subtotalConcepto(c))}
              </span>
              {conceptos.length > 1 && (
                <Button variant="danger" style={{ padding: "4px 10px" }}
                  onClick={() => setConceptos(conceptos.filter((x) => x._k !== c._k))}>Quitar</Button>
              )}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 11 }}>
              <Field label="Descripción *" style={{ gridColumn: "span 2" }}>
                <TextInput value={c.descripcion}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, descripcion: e.target.value } : x))} />
              </Field>
              <Field label="No. de parte">
                <TextInput value={c.numero_parte}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, numero_parte: e.target.value } : x))} />
              </Field>
              <Field label="Cantidad">
                <TextInput type="number" step="0.001" value={c.cantidad}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, cantidad: e.target.value } : x))} />
              </Field>
              <Field label="Unidad">
                <TextInput value={c.unidad_medida}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, unidad_medida: e.target.value } : x))} />
              </Field>
              <Field label="Precio estimado">
                <TextInput type="number" step="0.0001" value={c.precio_unitario}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, precio_unitario: e.target.value } : x))} />
              </Field>
              <Field label="Notas" style={{ gridColumn: "span 2" }}>
                <TextInput value={c.notas}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, notas: e.target.value } : x))} />
              </Field>
              <Field label="Enlace">
                <TextInput value={c.enlace}
                  onChange={(e) => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, enlace: e.target.value } : x))} />
              </Field>
            </div>
            <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 8, flexWrap: "wrap" }}>
              <span style={{ fontSize: 10.5, textTransform: "uppercase", letterSpacing: "0.05em", color: T.textDim }}>
                Especificaciones
              </span>
              {c._spec ? (
                <>
                  <span style={{ fontSize: 11.5, color: T.text }}>{c._spec.name}</span>
                  <Button variant="danger" style={{ padding: "3px 9px" }}
                    onClick={() => setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, _spec: null } : x))}>Quitar</Button>
                </>
              ) : (
                <label style={{ cursor: "pointer", fontSize: 11.5, color: T.accent }}>
                  + Adjuntar archivo
                  <input type="file" style={{ display: "none" }}
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      e.target.value = "";
                      if (file) setConceptos(conceptos.map((x) => x._k === c._k ? { ...x, _spec: file } : x));
                    }} />
                </label>
              )}
            </div>
          </div>
        ))}
      </Panel>

      <Panel title="Cotizaciones y documentos" subtitle="Se suben al enviar la solicitud.">
        <div style={{ marginBottom: 12 }}>
          <Button variant="ghost" onClick={() => refArchivos.current?.click()}>+ Adjuntar archivos</Button>
          <input ref={refArchivos} type="file" multiple onChange={agregarArchivos} style={{ display: "none" }} />
          <span style={{ fontSize: 11, color: T.textFaint, marginLeft: 10 }}>Máximo 25 MB por archivo.</span>
        </div>
        {!archivos.length ? (
          <div style={{ fontSize: 12, color: T.textFaint }}>Sin archivos.</div>
        ) : archivos.map((a) => (
          <div key={a._k} style={{ display: "flex", gap: 10, alignItems: "center", padding: "6px 0", borderTop: `1px solid ${T.borderSoft}` }}>
            <span style={{ flex: 1, fontSize: 12.5, color: T.text, wordBreak: "break-word" }}>{a.file.name}</span>
            <span style={{ fontSize: 11, color: T.textFaint }}>{pesoLegible(a.file.size)}</span>
            <Select value={a.categoria} style={{ maxWidth: 180 }}
              onChange={(e) => setArchivos(archivos.map((x) => x._k === a._k ? { ...x, categoria: e.target.value } : x))}>
              {CATEGORIAS_ADJUNTO.map((c) => <option key={c.value} value={c.value}>{c.label}</option>)}
            </Select>
            <Button variant="danger" style={{ padding: "4px 10px" }}
              onClick={() => setArchivos(archivos.filter((x) => x._k !== a._k))}>Quitar</Button>
          </div>
        ))}
      </Panel>

      <Panel title="Importe estimado" subtitle="Si no lo conoces, déjalo en cero: administración lo cotiza.">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 14, maxWidth: 620 }}>
          <Field label="Divisa">
            <Select value={f.divisa} onChange={(e) => setF({ ...f, divisa: e.target.value })}>
              <option value="MXP">MXN</option>
              <option value="USD">USD</option>
            </Select>
          </Field>
          <Field label="IVA">
            <Select value={f.iva_tasa} disabled={f.sin_impuesto}
              onChange={(e) => setF({ ...f, iva_tasa: Number(e.target.value) })}>
              {TASAS_IVA_SOLICITUD.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </Select>
          </Field>
        </div>
        <div style={{ marginTop: 14, maxWidth: 340, fontSize: 13, fontFamily: T.fontMono }}>
          <div style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", color: T.textDim }}>
            <span>Subtotal</span><span>{money(tot.subtotal)}</span>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", color: T.textDim }}>
            <span>IVA</span><span>{money(tot.iva)}</span>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", padding: "8px 0 0", borderTop: `1px solid ${T.border}`, marginTop: 6, fontWeight: 700, color: T.text, fontSize: 15 }}>
            <span>Total</span><span>{money(tot.total)}</span>
          </div>
        </div>

        {error && <div style={{ marginTop: 14, fontSize: 12.5, color: T.red, lineHeight: 1.5 }}>{error}</div>}

        <div style={{ display: "flex", gap: 10, marginTop: 20 }}>
          <Button onClick={enviar} disabled={enviando}>
            {enviando ? "Enviando…" : "Enviar solicitud"}
          </Button>
        </div>
      </Panel>
    </div>
  );
}

function SolicitudesTab({ unidad, session, unidades = [], proyectos = [], zonas = [] }) {
  const [sub, setSub] = useSessionState("ss-solicitudes-sub", "bandeja");
  const [capturando, setCapturando] = useState(false);
  const [abierta, setAbierta] = useState(null);
  const [editando, setEditando] = useState(null);
  const [parametros, setParametros] = useState(null);
  const [correos, setCorreos] = useState([]);
  const [recientes, setRecientes] = useState([]);
  const [cargando, setCargando] = useState(false);
  const [busca, setBusca] = useSessionState("ss-sol-busca", "");
  const [filtroEstado, setFiltroEstado] = useSessionState("ss-sol-estado", "");
  const [desde, setDesde] = useSessionState("ss-sol-desde", "");
  const [hasta, setHasta] = useSessionState("ss-sol-hasta", "");

  const recargar = async () => {
    setCargando(true);
    try {
      const [p, c, r] = await Promise.all([
        supabase.from("solicitudes_parametros").select("*").eq("unidad", unidad).maybeSingle(),
        supabase.from("solicitudes_correos_autorizados").select("*")
          .or(`unidad.eq.${unidad},unidad.is.null`).eq("activo", true).order("nombre"),
        /* Mil alcanza para varios años de solicitudes. Si algún día no
           alcanzara, el síntoma sería que las más viejas dejan de aparecer
           en la búsqueda, no un error. */
        supabase.from("solicitudes").select("*").eq("unidad", unidad)
          .order("creado_en", { ascending: false }).limit(1000),
      ]);
      setParametros(p.data || null);
      setCorreos(c.data || []);
      setRecientes(r.data || []);
    } finally {
      setCargando(false);
    }
  };
  useEffect(() => { if (sub === "bandeja") recargar(); }, [sub, unidad]);
  useEffect(() => { setAbierta(null); setCapturando(false); setEditando(null); }, [unidad]);

  /* La búsqueda cubre folio, folio del solicitante, descripción, quién pidió,
     proyecto y zona: es lo que alguien recuerda cuando viene a preguntar por
     una solicitud, y rara vez es el folio. */
  const q = busca.trim().toLowerCase();
  const enRango = (s) => (!desde || String(s.fecha_solicitud) >= desde)
                      && (!hasta || String(s.fecha_solicitud) <= hasta);
  const visibles = recientes.filter((s) =>
    (!filtroEstado || s.estado === filtroEstado)
    && enRango(s)
    && (!q || [s.folio, s.folio_usuario, s.descripcion_general, s.nombre_solicitante,
               s.correo_solicitante, s.proyecto, s.zona]
              .some((v) => String(v || "").toLowerCase().includes(q))));

  const porEstado = ESTADOS_SOLICITUD.map((e) => ({
    ...e, n: recientes.filter((s) => s.estado === e.value && enRango(s)).length,
  }));
  const sumaVisible = visibles.reduce((a, s) => a + (Number(s.total) || 0), 0);
  const hayFiltro = !!(q || filtroEstado || desde || hasta);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, padding: 3, alignSelf: "flex-start" }}>
        {SUBS_SOLICITUDES.map((s) => (
          <button
            key={s.id}
            onClick={() => setSub(s.id)}
            style={{
              padding: "7px 16px", borderRadius: 6, border: "none", cursor: "pointer",
              background: sub === s.id ? T.accent : "transparent",
              color: sub === s.id ? "#FFFFFF" : T.textDim,
              fontWeight: 600, fontSize: 12.5, fontFamily: T.fontUI,
            }}
          >{s.label}</button>
        ))}
      </div>

      {sub === "parametros" && <SolicitudesParametrosPanel unidad={unidad} session={session} />}

      {sub === "solicitantes" && <SolicitantesPanel unidad={unidad} unidades={unidades} />}

      {sub === "bandeja" && editando && parametros && (
        <NuevaSolicitudPanel
          unidad={unidad} session={session} parametros={parametros}
          correos={correos} proyectos={proyectos} zonas={zonas}
          solicitud={editando.solicitud} conceptosIniciales={editando.conceptos}
          onCancelar={() => setEditando(null)}
          onGuardada={(s) => {
            setEditando(null);
            setAbierta(s);
            setRecientes((r) => r.map((x) => (x.id === s.id ? s : x)));
          }}
        />
      )}

      {sub === "bandeja" && !editando && abierta && (
        <SolicitudDetallePanel
          solicitud={abierta}
          session={session}
          onVolver={() => setAbierta(null)}
          onEditar={(cs) => setEditando({ solicitud: abierta, conceptos: cs })}
          onCambiada={(s) => {
            setAbierta(s);
            setRecientes((r) => r.map((x) => (x.id === s.id ? s : x)));
          }}
        />
      )}

      {sub === "bandeja" && !editando && !abierta && capturando && parametros && (
        <NuevaSolicitudPanel
          unidad={unidad} session={session} parametros={parametros}
          correos={correos} proyectos={proyectos} zonas={zonas}
          onCancelar={() => setCapturando(false)}
          onGuardada={(s) => { setCapturando(false); recargar(); alert(`Guardada como ${s.folio}.`); }}
        />
      )}

      {sub === "bandeja" && !editando && !abierta && !capturando && (
        <Panel
          title={`Solicitudes de ${unidad}`}
          subtitle={`${visibles.length}${hayFiltro ? ` de ${recientes.length}` : ""} · $${numMx(sumaVisible)}`}
          right={
            <Button onClick={() => setCapturando(true)} disabled={!parametros}>+ Nueva solicitud</Button>
          }
        >
          {/* Los estados son botones y no un desplegable: el conteo de cada
              uno es la primera pregunta de quien abre esta pantalla —cuántas
              hay esperando— y en un desplegable no se ve sin abrirlo. */}
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
            <button
              onClick={() => setFiltroEstado("")}
              style={{
                padding: "5px 12px", borderRadius: 14, cursor: "pointer", fontFamily: T.fontUI,
                fontSize: 12, fontWeight: 600,
                border: `1px solid ${!filtroEstado ? T.accent : T.border}`,
                background: !filtroEstado ? T.accent : T.panel,
                color: !filtroEstado ? "#FFFFFF" : T.textDim,
              }}
            >Todas {recientes.filter(enRango).length}</button>
            {porEstado.filter((e) => e.n > 0 || e.value === filtroEstado).map((e) => (
              <button
                key={e.value}
                onClick={() => setFiltroEstado(filtroEstado === e.value ? "" : e.value)}
                style={{
                  padding: "5px 12px", borderRadius: 14, cursor: "pointer", fontFamily: T.fontUI,
                  fontSize: 12, fontWeight: 600,
                  border: `1px solid ${filtroEstado === e.value ? T.accent : T.border}`,
                  background: filtroEstado === e.value ? T.accent : T.panel,
                  color: filtroEstado === e.value ? "#FFFFFF" : T.textDim,
                }}
              >{e.label} {e.n}</button>
            ))}
          </div>

          <div style={{ display: "flex", gap: 10, alignItems: "flex-end", flexWrap: "wrap", marginBottom: 14 }}>
            <Field label="Buscar" style={{ flex: 1, minWidth: 220 }}>
              <TextInput value={busca} onChange={(e) => setBusca(e.target.value)}
                placeholder="Folio, descripción, quién pidió, proyecto…" />
            </Field>
            <Field label="Desde" style={{ maxWidth: 160 }}>
              <TextInput type="date" value={desde} onChange={(e) => setDesde(e.target.value)} />
            </Field>
            <Field label="Hasta" style={{ maxWidth: 160 }}>
              <TextInput type="date" value={hasta} onChange={(e) => setHasta(e.target.value)} />
            </Field>
            {hayFiltro && (
              <Button variant="ghost" style={{ marginBottom: 1 }}
                onClick={() => { setBusca(""); setFiltroEstado(""); setDesde(""); setHasta(""); }}>
                Limpiar
              </Button>
            )}
          </div>

          {!parametros ? (
            <EmptyState
              title={`${unidad} no tiene parámetros`}
              body="Define el formato del folio en la pestaña de Parámetros antes de capturar."
            />
          ) : cargando ? (
            <div style={{ fontSize: 12.5, color: T.textFaint }}>Cargando…</div>
          ) : !recientes.length ? (
            <EmptyState
              title="Todavía no hay solicitudes"
              body="Las que lleguen por el formulario público aparecen aquí, y también puedes capturarlas a mano."
            />
          ) : !visibles.length ? (
            <EmptyState
              title="Ninguna coincide"
              body="Prueba con otro término o quita los filtros."
            />
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 1, background: T.border, border: `1px solid ${T.border}`, borderRadius: 6, overflow: "hidden" }}>
              {visibles.map((s) => (
                <div key={s.id}
                  onClick={() => setAbierta(s)}
                  style={{ display: "flex", gap: 12, alignItems: "center", background: T.panel, padding: "10px 12px", cursor: "pointer" }}>
                  <span style={{ fontFamily: T.fontMono, fontSize: 12.5, color: T.accent, minWidth: 110 }}>{s.folio}</span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 12.5, color: T.text }}>{s.descripcion_general}</div>
                    <div style={{ fontSize: 11, color: T.textFaint, marginTop: 2 }}>
                      {[s.nombre_solicitante || s.correo_solicitante, s.zona, s.proyecto, s.fecha_solicitud]
                        .filter(Boolean).join(" · ")}
                    </div>
                  </div>
                  <Pill>{etiquetaEstado(s.estado)}</Pill>
                  <span style={{ fontFamily: T.fontMono, fontSize: 12.5, color: T.text, whiteSpace: "nowrap" }}>
                    ${numMx(s.total)} {s.divisa === "USD" ? "USD" : "MXN"}
                  </span>
                </div>
              ))}
            </div>
          )}
        </Panel>
      )}
    </div>
  );
}

function CatalogoTab({ unidad, unidades, proyectosApi, zonasApi, rubrosApi, categoriasApi, partidas = [], transacciones = [], proveedoresApi, cuentasApi, perfilesApi }) {
  const proyectosUnidad = unidades[unidad]?.proyectos || [];
  const [sub, setSub] = useSessionState("ss-catalogo-sub", "proyectos");
  const [nuevo, setNuevo] = useState({ nombre: "", grupo: "", pct: "", centro_costo: "" });
  const [editingId, setEditingId] = useState(null);
  const [draft, setDraft] = useState({ nombre: "", grupo: "", pct: "", centro_costo: "" });
  const [guardandoId, setGuardandoId] = useState(null);

  const empezarEditar = (p) => {
    setEditingId(p.id);
    setDraft({ nombre: p.nombre || "", grupo: p.grupo || "", pct: p.pct ?? "", centro_costo: p.centro_costo || "" });
  };
  const cancelarEditar = () => { setEditingId(null); setDraft({ nombre: "", grupo: "", pct: "" }); };
  const guardarEditar = async (id) => {
    setGuardandoId(id);
    try {
      await proyectosApi.update(id, { nombre: draft.nombre, grupo: draft.grupo, pct: Number(draft.pct) || 0, centro_costo: draft.centro_costo.trim() });
      cancelarEditar();
    } catch (err) {
      alert("No se pudo actualizar: " + (err.message || err));
    } finally {
      setGuardandoId(null);
    }
  };
  const removeProyecto = (id) => {
    const p = proyectosApi.rows.find((x) => x.id === id);
    if (!confirm(`¿Eliminar el proyecto "${p?.nombre || id}" del catálogo? Esto no se puede deshacer.`)) return;
    proyectosApi.remove(id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
  };
  const addProyecto = () => {
    if (!nuevo.nombre) return;
    proyectosApi.insert({ id: uid(), unidad, nombre: nuevo.nombre, grupo: nuevo.grupo || "General", pct: Number(nuevo.pct) || 0, centro_costo: nuevo.centro_costo.trim() })
      .catch((err) => alert("No se pudo agregar: " + (err.message || err)));
    setNuevo({ nombre: "", grupo: "", pct: "" });
  };

  const totalPct = proyectosUnidad.reduce((s, p) => s + Number(p.pct || 0), 0);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {/* Sub-pestañas en vez de seis paneles apilados. Se prefirió esto a
          secciones plegables: con seis encabezados que atravesar el recorrido
          sigue existiendo, y el estado de plegado se olvida entre visitas. */}
      <div style={{ display: "flex", background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, padding: 3, alignSelf: "flex-start", flexWrap: "wrap" }}>
        {SUBS_CATALOGO.map((sc) => (
          <button
            key={sc.id}
            onClick={() => setSub(sc.id)}
            style={{
              padding: "7px 16px", borderRadius: 6, border: "none", cursor: "pointer",
              background: sub === sc.id ? T.accent : "transparent",
              color: sub === sc.id ? "#FFFFFF" : T.textDim,
              fontWeight: 600, fontSize: 12.5, fontFamily: T.fontUI,
            }}
          >
            {sc.label}
          </button>
        ))}
      </div>

      {sub === "proyectos" && (
      <Panel
        title={`Proyectos y % de prorrateo — ${unidad}`}
        subtitle="El % se usa para repartir gastos compartidos marcados como “Todos” o “<Grupo> Gral”"
        right={<Pill tone={Math.abs(totalPct - 100) < 0.01 ? "teal" : "red"}>{totalPct.toFixed(1)}% asignado</Pill>}
      >
        <div style={{ overflowX: "auto" }}>
          <table style={tableStyle}>
            <thead>
              <tr>{["Proyecto","Grupo","% Administrativos","Centro de costo",""].map((h) => <th key={h} style={thStyle}>{h}</th>)}</tr>
            </thead>
            <tbody>
              {proyectosUnidad.map((p) => {
                const editando = editingId === p.id;
                return (
                  <tr key={p.id}>
                    {editando ? (
                      <>
                        <td style={tdStyle}><TextInput autoFocus value={draft.nombre} onChange={(e) => setDraft({ ...draft, nombre: e.target.value })} /></td>
                        <td style={tdStyle}><TextInput value={draft.grupo} onChange={(e) => setDraft({ ...draft, grupo: e.target.value })} placeholder="Desh / Prod / IMP" /></td>
                        <td style={tdStyle}><TextInput type="number" value={draft.pct} onChange={(e) => setDraft({ ...draft, pct: e.target.value })} style={{ width: 90 }} /></td>
                        <td style={tdStyle}><TextInput value={draft.centro_costo} onChange={(e) => setDraft({ ...draft, centro_costo: e.target.value.toUpperCase() })} placeholder="CC-015" style={{ width: 100 }} /></td>
                        <td style={tdStyle}>
                          <div style={{ display: "flex", gap: 6 }}>
                            <Button onClick={() => guardarEditar(p.id)} disabled={guardandoId === p.id}>{guardandoId === p.id ? "Guardando…" : "Guardar"}</Button>
                            <Button variant="ghost" onClick={cancelarEditar}>Cancelar</Button>
                          </div>
                        </td>
                      </>
                    ) : (
                      <>
                        <td style={tdStyle}>{p.nombre}</td>
                        <td style={{ ...tdStyle, color: T.textDim }}>{p.grupo || "—"}</td>
                        <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{p.pct ?? 0}%</td>
                        {/* Sin centro de costo la Solicitud de Pago sale incompleta, así que
                            el hueco se marca en vez de mostrarse como un guion cualquiera. */}
                        <td style={{ ...tdStyle, fontFamily: T.fontMono }}>
                          {p.centro_costo || <span style={{ color: T.amber }}>falta</span>}
                        </td>
                        <td style={tdStyle}>
                          <div style={{ display: "flex", gap: 6 }}>
                            <Button variant="ghost" onClick={() => empezarEditar(p)}>Editar</Button>
                            <Button variant="danger" onClick={() => removeProyecto(p.id)}>Eliminar</Button>
                          </div>
                        </td>
                      </>
                    )}
                  </tr>
                );
              })}
              <tr>
                <td style={tdStyle}><TextInput placeholder="Nuevo proyecto" value={nuevo.nombre} onChange={(e) => setNuevo({ ...nuevo, nombre: e.target.value })} /></td>
                <td style={tdStyle}><TextInput placeholder="Grupo" value={nuevo.grupo} onChange={(e) => setNuevo({ ...nuevo, grupo: e.target.value })} /></td>
                <td style={tdStyle}><TextInput type="number" placeholder="%" value={nuevo.pct} onChange={(e) => setNuevo({ ...nuevo, pct: e.target.value })} style={{ width: 90 }} /></td>
                <td style={tdStyle}><TextInput placeholder="CC-015" value={nuevo.centro_costo} onChange={(e) => setNuevo({ ...nuevo, centro_costo: e.target.value.toUpperCase() })} style={{ width: 100 }} /></td>
                <td style={tdStyle}><Button onClick={addProyecto}>Agregar</Button></td>
              </tr>
            </tbody>
          </table>
        </div>
        {Math.abs(totalPct - 100) > 0.01 && proyectosUnidad.length > 0 && (
          <div style={{ marginTop: 10, fontSize: 11.5, color: T.amber }}>
            El % total no suma 100 — el prorrateo bajo el marcador “Todos” se renormaliza automáticamente, pero conviene que sí sumen 100 para que el % represente lo real.
          </div>
        )}
      </Panel>
      )}

      {sub === "rubros" && (
        <RubrosPanel rubrosApi={rubrosApi} categoriasApi={categoriasApi} partidas={partidas} transacciones={transacciones} />
      )}
      {sub === "zonas" && <ZonasPanel zonasApi={zonasApi} transacciones={transacciones} unidad={unidad} />}
      {sub === "proveedores" && (
        <ProveedoresPanel unidad={unidad} proveedoresApi={proveedoresApi} cuentasApi={cuentasApi} perfilesApi={perfilesApi} />
      )}
      {sub === "solicitudes" && <ConfigCompaniaPanel unidad={unidad} />}
    </div>
  );
}

function ImportarProveedoresPanel({ proveedoresApi, cuentasApi }) {
  const inputRef = useRef(null);
  /* Plantilla de carga masiva. Faltaba: había importador pero no había de
     dónde sacar el formato, así que la única forma de saber qué columnas
     espera era exportar el catálogo existente — que no sirve si aún no hay
     proveedores capturados. */
  const descargarPlantilla = async () => {
    const headers = ["Compañía", "Nombre", "RFC", "ID SAE", "Referencia", "Notas",
      "Banco", "Sucursal", "SWIFT", "CLABE", "Numero de Cuenta", "Divisa"];
    const anchos = [12, 40, 16, 12, 18, 30, 20, 12, 14, 24, 20, 9];
    const ejemplos = {
      OSB: ["OSB", "Ejemplo: Comisión Federal de Electricidad", "CFE370814QI0", "", "", "", "BANORTE", "", "", "072680013482913231", "", "MXP"],
      CTM: ["CTM", "Ejemplo: Servicio de Gasolinería Lepacaba SA de CV", "SGL010203AB1", "", "", "", "BBVA", "", "", "012680001234567890", "", "MXP"],
      ISE: ["ISE", "Ejemplo: Champion X", "", "", "", "Proveedor extranjero", "CITIBANK", "", "CITIUS33", "", "1234567890", "USD"],
    };

    const wbx = new ExcelJS.Workbook();
    UNIDAD_KEYS.forEach((u) => {
      const ws = wbx.addWorksheet(u);
      ws.columns = anchos.map((w) => ({ width: w }));
      const headerRow = ws.addRow(headers);
      formatearHojaDatos(ws, headerRow, headers.length);
      const ejemploRow = ws.addRow(ejemplos[u]);
      ejemploRow.eachCell((cell) => { cell.font = { italic: true, color: { argb: "FF8B99A6" } }; });
    });

    const notas = wbx.addWorksheet("Instrucciones");
    notas.columns = [{ width: 100 }];
    [
      "CÓMO LLENAR ESTA PLANTILLA",
      "",
      "1. Borra la fila de ejemplo (va en gris cursiva) antes de importar.",
      "2. Compañía: OSB, CTM o ISE. Si la dejas vacía se usa el nombre de la hoja.",
      "3. Nombre: obligatorio. Es lo que empareja con los proveedores que ya existen,",
      "   junto con el RFC. Si el RFC coincide, se ACTUALIZA el proveedor en vez de",
      "   duplicarlo.",
      "4. Un proveedor con VARIAS cuentas bancarias va en varias filas: repite el",
      "   nombre y el RFC, y cambia solo los datos de la cuenta.",
      "5. CLABE y Número de Cuenta: escríbelos como TEXTO, no como número.",
      "   Excel convierte una CLABE de 18 dígitos a notación científica y se pierden",
      "   los últimos dígitos y el cero inicial. Si la celda muestra 7.26801E+17,",
      "   el dato ya se corrompió: da formato de texto a la columna ANTES de pegar.",
      "6. Divisa: MXP o USD. Determina con qué cuenta se paga cada transacción,",
      "   así que una cuenta en dólares mal marcada manda el pago a la cuenta",
      "   equivocada.",
      "7. SWIFT: solo para transferencias internacionales.",
      "8. ID SAE: el identificador del proveedor en ASPEL. Sirve para empatar por id",
      "   en vez de por nombre, que es mucho más confiable.",
    ].forEach((t) => notas.addRow([t]));
    notas.getRow(1).font = { bold: true, size: 13 };

    const buf = await wbx.xlsx.writeBuffer();
    const blob = new Blob([buf], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "Plantilla-Proveedores.xlsx";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };


  const [preview, setPreview] = useState(null);
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const [importing, setImporting] = useState(false);

  const onFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(""); setStatus(""); setPreview(null);
    try {
      const buf = await file.arrayBuffer();
      const { rows, sheetsFound, nuevas, actualizaciones, sinCompania } = parseProveedoresWorkbook(buf, proveedoresApi.rows);
      if (!rows.length) {
        setError('No encontré filas con Nombre y Compañía (OSB/CTM/ISE) reconocible en este archivo.');
        return;
      }
      setPreview({ rows, sheetsFound, nuevas, actualizaciones, sinCompania, fileName: file.name });
    } catch (err) {
      setError("No pude leer el archivo. Verifica que sea un .xlsx válido.");
    } finally {
      if (inputRef.current) inputRef.current.value = "";
    }
  };

  const confirmar = async () => {
    if (!preview) return;
    setImporting(true);
    try {
      const cuentasAInsertar = []; // { proveedor_id, ...cuenta } — se llena después de saber el id real de cada proveedor

      const nuevasFilas = preview.rows.filter((r) => !r._existenteId);
      const actualizacionesFilas = preview.rows.filter((r) => r._existenteId);

      if (nuevasFilas.length) {
        const payload = nuevasFilas.map(({ _existenteId, _cuentas, ...rest }) => rest);
        const creados = await proveedoresApi.bulkInsert(payload);
        creados.forEach((c, i) => {
          (nuevasFilas[i]._cuentas || []).forEach((cuenta) => {
            cuentasAInsertar.push({ id: uid(), proveedor_id: c.id, ...cuenta });
          });
        });
      }
      for (const r of actualizacionesFilas) {
        const { id, _existenteId, _cuentas, ...patch } = r;
        await proveedoresApi.update(_existenteId, patch);
        (_cuentas || []).forEach((cuenta) => {
          cuentasAInsertar.push({ id: uid(), proveedor_id: _existenteId, ...cuenta });
        });
      }
      if (cuentasAInsertar.length) await cuentasApi.bulkInsert(cuentasAInsertar);

      setStatus(`${nuevasFilas.length} nuevos, ${actualizacionesFilas.length} actualizados, ${cuentasAInsertar.length} cuenta(s) agregadas.`);
      setPreview(null);
    } catch (err) {
      setError("Ocurrió un error al importar en Supabase: " + (err.message || err));
    } finally {
      setImporting(false);
    }
  };

  return (
    <Panel
      title="Carga masiva de proveedores"
      subtitle='Una fila por proveedor, con una columna "Compañía" (OSB/CTM/ISE) que dice a cuál pertenece — o usa hojas llamadas OSB/CTM/ISE como respaldo'
      right={<Button variant="ghost" onClick={descargarPlantilla}>Descargar plantilla</Button>}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <input ref={inputRef} type="file" accept=".xlsx" onChange={onFile} style={{ fontSize: 12, color: T.textDim }} />
        {status && <Pill tone="teal">{status}</Pill>}
      </div>
      {error && <div style={{ marginTop: 10, fontSize: 12, color: T.red }}>{error}</div>}

      {preview && (
        <div style={{ marginTop: 16, borderTop: `1px solid ${T.borderSoft}`, paddingTop: 14 }}>
          <div style={{ fontSize: 12.5, color: T.text, marginBottom: 8 }}>
            <strong>{preview.fileName}</strong> — {preview.rows.length} proveedores detectados
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
            {preview.sheetsFound.map((s) => (
              <Pill key={s.sheetName} tone="accent">{s.sheetName}: {s.count} filas</Pill>
            ))}
            <Pill tone="teal">{preview.nuevas} nuevos</Pill>
            {preview.actualizaciones > 0 && <Pill tone="amber">{preview.actualizaciones} actualizan uno existente</Pill>}
            {preview.sinCompania > 0 && <Pill tone="red">{preview.sinCompania} ignoradas — sin Compañía reconocible</Pill>}
          </div>
          {preview.sinCompania > 0 && (
            <div style={{ fontSize: 11.5, color: T.amber, marginBottom: 12 }}>
              {preview.sinCompania} fila(s) no se van a importar porque la columna "Compañía" viene vacía o con un valor distinto a OSB/CTM/ISE,
              y la hoja tampoco se llama así. Corrígelo en el Excel y vuelve a subirlo.
            </div>
          )}

          <div style={{ overflowX: "auto", maxHeight: 260, overflowY: "auto", border: `1px solid ${T.borderSoft}`, borderRadius: 6 }}>
            <table style={tableStyle}>
              <thead>
                <tr>{["","Unidad","Nombre","RFC","Cuentas"].map((h) => <th key={h} style={thStyle}>{h}</th>)}</tr>
              </thead>
              <tbody>
                {preview.rows.slice(0, 15).map((r) => (
                  <tr key={r.id}>
                    <td style={tdStyle}>{r._existenteId ? <Pill tone="amber">Actualiza</Pill> : <Pill tone="teal">Nuevo</Pill>}</td>
                    <td style={tdStyle}>{r.unidad}</td>
                    <td style={tdStyle}>{r.nombre}</td>
                    <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{r.rfc || "—"}</td>
                    <td style={tdStyle}>
                      {r._cuentas.length
                        ? r._cuentas.map((c) => c.banco || c.divisa).filter(Boolean).join(", ")
                        : "—"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {preview.rows.length > 15 && (
            <div style={{ fontSize: 11, color: T.textFaint, marginTop: 6 }}>… y {preview.rows.length - 15} más</div>
          )}

          <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
            <Button onClick={confirmar} disabled={importing}>{importing ? "Importando…" : "Confirmar importación"}</Button>
            <Button variant="ghost" onClick={() => setPreview(null)}>Cancelar</Button>
          </div>
        </div>
      )}
    </Panel>
  );
}

/* ----------------------------------------------------------------------
   BAJA DE PROVEEDOR CON REASIGNACIÓN
---------------------------------------------------------------------- */

/* Los nombres pueden traer % o _ , que en ILIKE son comodines. Sin escapar,
   un proveedor llamado "100% NATURAL" empataría con cualquier cosa. */
const escaparLike = (s) => String(s || "").replace(/[\\%_]/g, (c) => "\\" + c);

/**
 * Cuenta de cuántas formas se está usando un proveedor.
 *
 * Son dos vínculos distintos y hay que contar los dos: `proveedor_id`, que es
 * el formal, y el texto de `proveedor`, que es el que quedó en las
 * transacciones importadas cuyo nombre no empató contra el catálogo. Mirar
 * solo el id diría que el proveedor está libre cuando en realidad tiene
 * decenas de movimientos a su nombre.
 */
async function usoDeProveedor(proveedor) {
  const id = proveedor.id;
  const nombre = escaparLike(proveedor.nombre);

  const porId = await supabase
    .from("transacciones").select("id", { count: "exact", head: true })
    .eq("proveedor_id", id);

  const porNombre = await supabase
    .from("transacciones").select("id", { count: "exact", head: true })
    .ilike("proveedor", nombre)
    .or(`proveedor_id.is.null,proveedor_id.neq.${id}`);

  if (porId.error) throw porId.error;
  if (porNombre.error) throw porNombre.error;

  return {
    porId: porId.count || 0,
    porNombre: porNombre.count || 0,
    total: (porId.count || 0) + (porNombre.count || 0),
  };
}

function EliminarProveedorModal({ proveedor, alternativos, cuentas, uso, onCerrar, onHecho }) {
  const [destinoId, setDestinoId] = useState("");
  const [moverCuentas, setMoverCuentas] = useState(false);
  const [trabajando, setTrabajando] = useState(false);

  const destino = alternativos.find((p) => p.id === destinoId) || null;
  const cuentasDestino = destino ? cuentas.filter((c) => c.proveedor_id === destino.id) : [];
  const clabesPropias = [...new Set(cuentas.map((c) => (c.clabe || "").trim()).filter(Boolean))];
  const clabesDestino = [...new Set(cuentasDestino.map((c) => (c.clabe || "").trim()).filter(Boolean))];
  const chocanClabes = moverCuentas && clabesPropias.some((c) => clabesDestino.length && !clabesDestino.includes(c))
    && clabesDestino.length > 0;

  const ejecutar = async () => {
    if (!destino) { alert("Elige a qué proveedor se reasignan los movimientos."); return; }
    setTrabajando(true);
    try {
      // 1. Las que apuntan por id
      const r1 = await supabase.from("transacciones")
        .update({ proveedor_id: destino.id, proveedor: destino.nombre })
        .eq("proveedor_id", proveedor.id);
      if (r1.error) throw r1.error;

      // 2. Las que solo traen el nombre en texto
      const r2 = await supabase.from("transacciones")
        .update({ proveedor_id: destino.id, proveedor: destino.nombre })
        .ilike("proveedor", escaparLike(proveedor.nombre))
        .or(`proveedor_id.is.null,proveedor_id.neq.${destino.id}`);
      if (r2.error) throw r2.error;

      // 3. Cuentas bancarias, solo si se pidió
      if (moverCuentas && cuentas.length) {
        const r3 = await supabase.from("proveedor_cuentas")
          .update({ proveedor_id: destino.id })
          .eq("proveedor_id", proveedor.id);
        if (r3.error) throw r3.error;
      }

      await onHecho(destino);
    } catch (err) {
      alert("No se pudo reasignar: " + (err.message || err));
    } finally {
      setTrabajando(false);
    }
  };

  return (
    <Modal onClose={onCerrar} title={`Eliminar «${proveedor.nombre}»`}>
      <div style={{ fontSize: 12.5, color: T.textDim, lineHeight: 1.6, marginBottom: 14 }}>
        Este proveedor está en uso. Antes de borrarlo hay que decir a quién pasan sus movimientos,
        o quedarían apuntando a un proveedor que ya no existe.
      </div>

      <div style={{ background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 6, padding: "10px 12px", marginBottom: 16 }}>
        <div style={{ fontSize: 12, color: T.text }}>
          <b>{uso.total}</b> transacción(es) lo usan
        </div>
        <div style={{ fontSize: 11.5, color: T.textFaint, marginTop: 4, lineHeight: 1.6 }}>
          {uso.porId} ligada(s) por catálogo
          {uso.porNombre > 0 && <> · {uso.porNombre} solo por el nombre, sin vínculo formal</>}
          {cuentas.length > 0 && <> · {cuentas.length} cuenta(s) bancaria(s)</>}
        </div>
      </div>

      <Field label="Los movimientos pasan a *">
        <Select value={destinoId} onChange={(e) => setDestinoId(e.target.value)}>
          <option value="">— elegir proveedor —</option>
          {alternativos.map((p) => (
            <option key={p.id} value={p.id}>
              {p.nombre}{p.rfc ? ` — ${p.rfc}` : ""}
            </option>
          ))}
        </Select>
      </Field>

      {cuentas.length > 0 && (
        <div style={{ marginTop: 16, borderTop: `1px solid ${T.border}`, paddingTop: 13 }}>
          <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", color: T.textDim, marginBottom: 7 }}>
            Sus cuentas bancarias
          </div>
          {cuentas.map((c) => (
            <div key={c.id} style={{ fontSize: 11.5, color: T.textDim, fontFamily: T.fontMono, padding: "2px 0" }}>
              {(c.banco || "?")} · {c.clabe || c.numero_cuenta || "(sin datos)"} · {c.divisa || ""}
            </div>
          ))}
          <label style={{ display: "flex", gap: 8, alignItems: "flex-start", marginTop: 10, fontSize: 12.5, color: T.textDim, cursor: "pointer" }}>
            <input type="checkbox" checked={moverCuentas} onChange={(e) => setMoverCuentas(e.target.checked)} style={{ marginTop: 2 }} />
            <span>
              Moverlas también al proveedor elegido.
              {!moverCuentas && <span style={{ color: T.amberDim }}> Si no, se borran junto con el proveedor.</span>}
            </span>
          </label>
          {chocanClabes && (
            <div style={{ fontSize: 12, color: T.red, marginTop: 9, lineHeight: 1.5 }}>
              El proveedor elegido ya tiene una cuenta con CLABE distinta. Si mueves estas, va a
              quedar con varias y elegir la correcta al pagar deja de ser evidente. Revísalo antes.
            </div>
          )}
        </div>
      )}

      <div style={{ display: "flex", gap: 10, marginTop: 20 }}>
        <Button onClick={ejecutar} disabled={!destino || trabajando}>
          {trabajando ? "Reasignando…" : `Reasignar ${uso.total} y eliminar`}
        </Button>
        <Button variant="ghost" onClick={onCerrar}>Cancelar</Button>
      </div>
    </Modal>
  );
}

function ProveedoresPanel({ unidad, proveedoresApi, cuentasApi, perfilesApi }) {
  const proveedoresUnidad = proveedoresApi.rows.filter((p) => p.unidad === unidad);
  const blank = { nombre: "", rfc: "", id_sae: "", referencia: "", notas: "" };
  const [form, setForm] = useState(blank);
  const [editId, setEditId] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [buscar, setBuscar] = useState("");

  const cuentaBlank = { banco: "", sucursal: "", swift: "", clabe: "", numero_cuenta: "", divisa: "MXP" };
  const [nuevaCuenta, setNuevaCuenta] = useState(cuentaBlank);
  const cuentasDelProveedor = editId ? cuentasApi.rows.filter((c) => c.proveedor_id === editId) : [];

  const contarCuentas = (proveedorId) => cuentasApi.rows.filter((c) => c.proveedor_id === proveedorId).length;

  const filtrados = proveedoresUnidad.filter((p) => {
    if (!buscar.trim()) return true;
    const q = buscar.trim().toLowerCase();
    return [p.nombre, p.rfc, p.id_sae, p.referencia, p.notas].some((v) => (v || "").toLowerCase().includes(q));
  });

  const openNew = () => { setForm(blank); setEditId(null); setNuevaCuenta(cuentaBlank); setModalOpen(true); };
  const startEdit = (p) => { setForm(p); setEditId(p.id); setNuevaCuenta(cuentaBlank); setModalOpen(true); };
  const closeModal = () => { setModalOpen(false); setEditId(null); setForm(blank); setNuevaCuenta(cuentaBlank); };
  /* Antes se borraba de una: la confirmación advertía de las cuentas
     bancarias, pero no de las transacciones. Borrar un proveedor con
     movimientos dejaba esas filas apuntando a un id inexistente, y el
     Reporte de Pagos las mostraba sin proveedor sin explicar por qué. */
  const [baja, setBaja] = useState(null);
  const [revisandoUso, setRevisandoUso] = useState(null);

  const remove = async (id) => {
    const p = proveedoresApi.rows.find((x) => x.id === id);
    if (!p) return;
    setRevisandoUso(id);
    let uso;
    try {
      uso = await usoDeProveedor(p);
    } catch (err) {
      alert("No se pudo revisar si está en uso: " + (err.message || err));
      setRevisandoUso(null);
      return;
    }
    setRevisandoUso(null);

    const cuentasDeEste = cuentasApi.rows.filter((c) => c.proveedor_id === id);

    if (uso.total === 0) {
      const aviso = cuentasDeEste.length
        ? `\n\nNo tiene transacciones, pero se borrarán sus ${cuentasDeEste.length} cuenta(s) bancaria(s).`
        : "\n\nNo tiene transacciones ni cuentas.";
      if (!confirm(`¿Eliminar al proveedor "${p.nombre}"?${aviso}`)) return;
      proveedoresApi.remove(id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
      return;
    }

    const alternativos = proveedoresApi.rows
      .filter((x) => x.unidad === unidad && x.id !== id)
      .sort((a, b) => String(a.nombre).localeCompare(String(b.nombre)));
    if (!alternativos.length) {
      alert(`"${p.nombre}" tiene ${uso.total} transacción(es) y no hay otro proveedor en ${unidad} al cual reasignarlas. Da de alta el sustituto primero.`);
      return;
    }
    setBaja({ proveedor: p, uso, cuentas: cuentasDeEste, alternativos });
  };

  const submit = async (e) => {
    e.preventDefault();
    if (!form.nombre.trim()) return;
    const { id, ...rest } = form;
    setSaving(true);
    try {
      if (editId) {
        await proveedoresApi.update(editId, rest);
      } else {
        const nuevo = await proveedoresApi.insert({ ...rest, id: uid(), unidad });
        setEditId(nuevo.id); // dejamos el modal abierto para poder agregar cuentas al que se acaba de crear
        return;
      }
      closeModal();
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally {
      setSaving(false);
    }
  };

  const agregarCuenta = async () => {
    if (!editId) return;
    if (!nuevaCuenta.banco.trim() && !nuevaCuenta.clabe.trim() && !nuevaCuenta.numero_cuenta.trim()) return;
    try {
      await cuentasApi.insert({ id: uid(), proveedor_id: editId, ...nuevaCuenta });
      setNuevaCuenta(cuentaBlank);
    } catch (err) {
      alert("No se pudo agregar la cuenta: " + (err.message || err));
    }
  };
  const eliminarCuenta = (id) => eliminarCuentaBancaria(cuentasApi, id);

  // Exporta las tres compañías con UNA FILA POR CUENTA BANCARIA (un proveedor
  // con dos cuentas ocupa dos renglones). Así el preparador de transacciones
  // puede comparar la CLABE que viene en el correo contra la registrada.
  const exportarProveedores = async () => {
    const COLS = [
      { header: "Unidad",     width: 9,  get: (p, c) => p.unidad },
      { header: "Proveedor",  width: 38, get: (p, c) => p.nombre || "" },
      { header: "RFC",        width: 16, get: (p, c) => p.rfc || "" },
      { header: "Id SAE",     width: 11, get: (p, c) => p.id_sae || "" },
      { header: "Banco",      width: 20, get: (p, c) => c?.banco || "" },
      { header: "CLABE",      width: 22, get: (p, c) => c?.clabe || "" },
      { header: "No. Cuenta", width: 18, get: (p, c) => c?.numero_cuenta || "" },
      { header: "SWIFT",      width: 12, get: (p, c) => c?.swift || "" },
      { header: "Divisa",     width: 9,  get: (p, c) => c?.divisa || "" },
      { header: "Cuentas",    width: 9,  get: (p, c, n) => n },
    ];
    const wbx = new ExcelJS.Workbook();
    UNIDAD_KEYS.forEach((u) => {
      const delaUnidad = proveedoresApi.rows.filter((p) => p.unidad === u);
      if (!delaUnidad.length) return;
      const ws = wbx.addWorksheet(`Proveedores-${u}`);
      ws.columns = COLS.map((c) => ({ width: c.width }));
      const hr = ws.addRow(COLS.map((c) => c.header));
      formatearHojaDatos(ws, hr, COLS.length);
      delaUnidad.forEach((p) => {
        const ctas = cuentasApi.rows.filter((c) => c.proveedor_id === p.id);
        // Sin cuentas se escribe un renglón igual, para que el preparador
        // pueda marcar "este proveedor no tiene cuenta registrada".
        (ctas.length ? ctas : [null]).forEach((c) => {
          const row = ws.addRow(COLS.map((col) => col.get(p, c, ctas.length)));
          COLS.forEach((col, ci) => {
            const cell = row.getCell(ci + 1);
            cell.font = { name: "Calibri", size: 11 };
            // CLABE y cuenta SIEMPRE como texto: si Excel las toma por número,
            // pierde el cero inicial y los últimos dígitos.
            if (col.header === "CLABE" || col.header === "No. Cuenta") {
              cell.numFmt = "@";
              cell.alignment = { horizontal: "left" };
            }
          });
        });
      });
    });
    if (!wbx.worksheets.length) { alert("No hay proveedores que exportar."); return; }
    const buf = await wbx.xlsx.writeBuffer();
    const blob = new Blob([buf], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Proveedores_OSB-CTM-ISE_${new Date().toISOString().slice(0, 10)}.xlsx`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
    <Panel
      title={`Catálogo de proveedores — ${unidad}`}
      subtitle={`${proveedoresUnidad.length} registrados — cada compañía tiene el suyo. Un proveedor puede tener varias cuentas bancarias`}
      right={
        <div style={{ display: "flex", gap: 8 }}>
          <Button variant="ghost" onClick={exportarProveedores} title="Las tres compañías con sus cuentas bancarias, para el preparador de transacciones">Exportar las 3</Button>
          <Button onClick={openNew}>+ Nuevo proveedor</Button>
        </div>
      }
    >
      <div style={{ marginBottom: 14 }}>
        <Field label="Buscar">
          <TextInput value={buscar} onChange={(e) => setBuscar(e.target.value)} placeholder="Nombre, RFC, Id SAE…" style={{ width: 280 }} />
        </Field>
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={tableStyle}>
          <thead>
            <tr>{["Nombre","RFC","Id SAE","Referencia","Notas","Cuentas",""].map((h) => <th key={h} style={thStyle}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {filtrados.map((p) => (
              <tr key={p.id}>
                <td style={tdStyle}>{p.nombre}</td>
                <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{p.rfc || "—"}</td>
                <td style={{ ...tdStyle, fontFamily: T.fontMono, color: T.textDim }}>{p.id_sae || "—"}</td>
                <td style={tdStyle}>{p.referencia || "—"}</td>
                <td style={{ ...tdStyle, color: T.textDim }}>{p.notas || "—"}</td>
                <td style={tdStyle}><Pill tone={contarCuentas(p.id) ? "teal" : "dim"}>{contarCuentas(p.id)} cuenta(s)</Pill></td>
                <td style={tdStyle}>
                  <div style={{ display: "flex", gap: 6 }}>
                    <Button variant="ghost" onClick={() => startEdit(p)}>Editar</Button>
                    <Button variant="danger" onClick={() => remove(p.id)} disabled={revisandoUso === p.id}>
                      {revisandoUso === p.id ? "Revisando…" : "Eliminar"}
                    </Button>
                  </div>
                </td>
              </tr>
            ))}
            {!proveedoresUnidad.length && (
              <tr><td colSpan={7} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>Sin proveedores aún</td></tr>
            )}
            {proveedoresUnidad.length > 0 && !filtrados.length && (
              <tr><td colSpan={7} style={{ ...tdStyle, textAlign: "center", color: T.textFaint }}>Ningún proveedor coincide con la búsqueda</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {baja && (
        <EliminarProveedorModal
          proveedor={baja.proveedor}
          alternativos={baja.alternativos}
          cuentas={baja.cuentas}
          uso={baja.uso}
          onCerrar={() => setBaja(null)}
          onHecho={async (destino) => {
            await proveedoresApi.remove(baja.proveedor.id);
            const n = baja.uso.total;
            setBaja(null);
            alert(`Listo. ${n} transacción(es) quedaron a nombre de "${destino.nombre}".`);
          }}
        />
      )}

      {modalOpen && (
        <Modal title={editId ? "Editar proveedor" : "Nuevo proveedor"} subtitle={`Catálogo de ${unidad}`} onClose={closeModal} width={820} cerrarAlHacerClicFuera={false}>
          <AutoriaCaption record={form} perfilesApi={perfilesApi} />
          <form onSubmit={submit} style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12, marginBottom: 20 }}>
            <Field label="Nombre" style={{ gridColumn: "span 3" }}>
              <TextInput value={form.nombre} onChange={(e) => setForm({ ...form, nombre: e.target.value })} />
            </Field>
            <Field label="RFC">
              <TextInput value={form.rfc} onChange={(e) => setForm({ ...form, rfc: e.target.value.toUpperCase() })} />
            </Field>
            <Field label="Id SAE">
              <TextInput value={form.id_sae} onChange={(e) => setForm({ ...form, id_sae: e.target.value })} />
            </Field>
            <Field label="Referencia">
              <TextInput value={form.referencia} onChange={(e) => setForm({ ...form, referencia: e.target.value })} />
            </Field>
            <Field label="Notas" style={{ gridColumn: "span 3" }}>
              <TextInput value={form.notas} onChange={(e) => setForm({ ...form, notas: e.target.value })} />
            </Field>
            <div style={{ gridColumn: "span 3", display: "flex", gap: 10, marginTop: 4 }}>
              <Button type="submit" disabled={saving}>{saving ? "Guardando…" : editId ? "Guardar cambios" : "Crear y agregar cuentas"}</Button>
              <Button type="button" variant="ghost" onClick={closeModal}>Cerrar</Button>
            </div>
          </form>

          {editId ? (
            <div style={{ borderTop: `1px solid ${T.borderSoft}`, paddingTop: 16 }}>
              <div style={{ fontSize: 12.5, fontWeight: 600, color: T.text, marginBottom: 10 }}>
                Cuentas bancarias ({cuentasDelProveedor.length})
              </div>
              {cuentasDelProveedor.length > 0 && (
                <table style={{ ...tableStyle, marginBottom: 12 }}>
                  <thead>
                    <tr>{["Banco","Sucursal","SWIFT","CLABE","No. Cuenta","Divisa",""].map((h) => <th key={h} style={thStyle}>{h}</th>)}</tr>
                  </thead>
                  <tbody>
                    {cuentasDelProveedor.map((c) => (
                      <tr key={c.id}>
                        <td style={tdStyle}>{c.banco || "—"}</td>
                        <td style={tdStyle}>{c.sucursal || "—"}</td>
                        <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{c.swift || "—"}</td>
                        <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{c.clabe || "—"}</td>
                        <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{c.numero_cuenta || "—"}</td>
                        <td style={tdStyle}><Pill>{c.divisa || "MXP"}</Pill></td>
                        <td style={tdStyle}><Button variant="danger" onClick={() => eliminarCuenta(c.id)}>Eliminar</Button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 8 }}>
                <Field label="Banco">
                  <TextInput value={nuevaCuenta.banco} onChange={(e) => setNuevaCuenta({ ...nuevaCuenta, banco: e.target.value })} />
                </Field>
                <Field label="Sucursal">
                  <TextInput value={nuevaCuenta.sucursal} onChange={(e) => setNuevaCuenta({ ...nuevaCuenta, sucursal: e.target.value })} />
                </Field>
                <Field label="SWIFT">
                  <TextInput value={nuevaCuenta.swift} onChange={(e) => setNuevaCuenta({ ...nuevaCuenta, swift: e.target.value })} />
                </Field>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8, alignItems: "end" }}>
                <Field label="CLABE">
                  <TextInput value={nuevaCuenta.clabe} onChange={(e) => setNuevaCuenta({ ...nuevaCuenta, clabe: e.target.value })} placeholder="18 dígitos" />
                </Field>
                <Field label="No. Cuenta">
                  <TextInput value={nuevaCuenta.numero_cuenta} onChange={(e) => setNuevaCuenta({ ...nuevaCuenta, numero_cuenta: e.target.value })} />
                </Field>
                <Field label="Divisa">
                  <Select value={nuevaCuenta.divisa} onChange={(e) => setNuevaCuenta({ ...nuevaCuenta, divisa: e.target.value })}>
                    {MONEDAS.map((m) => <option key={m}>{m}</option>)}
                  </Select>
                </Field>
                <Button type="button" onClick={agregarCuenta}>+ Agregar cuenta</Button>
              </div>
            </div>
          ) : (
            <div style={{ fontSize: 11.5, color: T.textFaint, borderTop: `1px solid ${T.borderSoft}`, paddingTop: 16 }}>
              Guarda el proveedor primero (botón "Crear y agregar cuentas") para poder capturarle sus cuentas bancarias.
            </div>
          )}
        </Modal>
      )}
    </Panel>

    <ImportarProveedoresPanel proveedoresApi={proveedoresApi} cuentasApi={cuentasApi} />
    </div>
  );
}

/* ----------------------------------------------------------------------
   ROOT APP
---------------------------------------------------------------------- */
// Sesión de Supabase Auth — undefined mientras carga, null si no hay sesión.
// `recovery` se activa cuando la sesión viene de un link de "olvidé mi
// contraseña" — en ese caso hay que pedir la contraseña nueva antes de
// dejar entrar a la app normal.
function useAuth() {
  const [session, setSession] = useState(undefined);
  const [recovery, setRecovery] = useState(false);
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: listener } = supabase.auth.onAuthStateChange((event, s) => {
      setSession(s);
      if (event === "PASSWORD_RECOVERY") setRecovery(true);
    });
    return () => listener.subscription.unsubscribe();
  }, []);
  return { session, recovery, clearRecovery: () => setRecovery(false) };
}

function SetNewPasswordScreen({ onDone }) {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setError("");
    if (password.length < 6) { setError("La contraseña debe tener al menos 6 caracteres."); return; }
    if (password !== confirm) { setError("Las contraseñas no coinciden."); return; }
    setLoading(true);
    try {
      const { error: err } = await supabase.auth.updateUser({ password });
      if (err) { setError(err.message); return; }
      onDone();
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: T.bg, fontFamily: T.fontUI }}>
      <form onSubmit={submit} style={{ ...panelStyle, width: 340 }}>
        <div style={{ fontSize: 10.5, color: T.accent, letterSpacing: "0.14em", textTransform: "uppercase", fontFamily: T.fontMono, marginBottom: 4 }}>
          Control de presupuestos
        </div>
        <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 18 }}>Elige tu nueva contraseña</div>
        <Field label="Nueva contraseña" style={{ marginBottom: 12 }}>
          <TextInput type="password" autoFocus value={password} onChange={(e) => setPassword(e.target.value)} required />
        </Field>
        <Field label="Confirmar contraseña" style={{ marginBottom: 16 }}>
          <TextInput type="password" value={confirm} onChange={(e) => setConfirm(e.target.value)} required />
        </Field>
        {error && <div style={{ fontSize: 12, color: T.red, marginBottom: 12 }}>{error}</div>}
        <Button type="submit" disabled={loading} style={{ width: "100%", justifyContent: "center" }}>
          {loading ? "Guardando…" : "Guardar contraseña"}
        </Button>
      </form>
    </div>
  );
}

function LoginScreen() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [aviso, setAviso] = useState("");
  const [loading, setLoading] = useState(false);
  const [modoOlvido, setModoOlvido] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setError(""); setLoading(true);
    try {
      const { error: err } = await supabase.auth.signInWithPassword({ email: email.trim(), password });
      if (err) setError(err.message === "Invalid login credentials" ? "Correo o contraseña incorrectos." : err.message);
    } finally {
      setLoading(false);
    }
  };

  const enviarRecuperacion = async (e) => {
    e.preventDefault();
    setError(""); setAviso(""); setLoading(true);
    try {
      const { error: err } = await supabase.auth.resetPasswordForEmail(email.trim(), { redirectTo: window.location.origin });
      if (err) setError(err.message);
      else setAviso("Si ese correo tiene cuenta, te llegó un link para elegir una contraseña nueva.");
    } finally {
      setLoading(false);
    }
  };

  if (modoOlvido) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: T.bg, fontFamily: T.fontUI }}>
        <form onSubmit={enviarRecuperacion} style={{ ...panelStyle, width: 340 }}>
          <div style={{ fontSize: 10.5, color: T.accent, letterSpacing: "0.14em", textTransform: "uppercase", fontFamily: T.fontMono, marginBottom: 4 }}>
            Control de presupuestos
          </div>
          <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 8 }}>Recuperar contraseña</div>
          <div style={{ fontSize: 12, color: T.textFaint, marginBottom: 16 }}>Te mandamos un link a tu correo para elegir una nueva.</div>
          <Field label="Correo" style={{ marginBottom: 16 }}>
            <TextInput type="email" autoFocus value={email} onChange={(e) => setEmail(e.target.value)} required />
          </Field>
          {error && <div style={{ fontSize: 12, color: T.red, marginBottom: 12 }}>{error}</div>}
          {aviso && <div style={{ fontSize: 12, color: T.teal, marginBottom: 12 }}>{aviso}</div>}
          <Button type="submit" disabled={loading} style={{ width: "100%", justifyContent: "center" }}>
            {loading ? "Enviando…" : "Enviar link"}
          </Button>
          <button
            type="button"
            onClick={() => { setModoOlvido(false); setError(""); setAviso(""); }}
            style={{ background: "none", border: "none", color: T.accent, fontSize: 11.5, cursor: "pointer", padding: 0, marginTop: 14 }}
          >
            ← Volver a iniciar sesión
          </button>
        </form>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: T.bg, fontFamily: T.fontUI }}>
      <form onSubmit={submit} style={{ ...panelStyle, width: 340 }}>
        <div style={{ fontSize: 10.5, color: T.accent, letterSpacing: "0.14em", textTransform: "uppercase", fontFamily: T.fontMono, marginBottom: 4 }}>
          Control de presupuestos
        </div>
        <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 18 }}>Iniciar sesión</div>
        <Field label="Correo" style={{ marginBottom: 12 }}>
          <TextInput type="email" autoFocus value={email} onChange={(e) => setEmail(e.target.value)} required />
        </Field>
        <Field label="Contraseña" style={{ marginBottom: 16 }}>
          <TextInput type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />
        </Field>
        {error && <div style={{ fontSize: 12, color: T.red, marginBottom: 12 }}>{error}</div>}
        <Button type="submit" disabled={loading} style={{ width: "100%", justifyContent: "center" }}>
          {loading ? "Entrando…" : "Entrar"}
        </Button>
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 14 }}>
          <span style={{ fontSize: 11, color: T.textFaint }}>
            ¿No tienes cuenta? Pídele a tu administrador que te dé de alta.
          </span>
        </div>
        <button
          type="button"
          onClick={() => { setModoOlvido(true); setError(""); }}
          style={{ background: "none", border: "none", color: T.accent, fontSize: 11.5, cursor: "pointer", padding: 0, marginTop: 10 }}
        >
          ¿Olvidaste tu contraseña?
        </button>
      </form>
    </div>
  );
}

/* ----------------------------------------------------------------------
   TAB: VEHÍCULOS  (flotilla + mantenimientos + dashboard)
---------------------------------------------------------------------- */

// Devuelve los vehículos ya filtrados por la barra de filtros compartida.
function filtrarVehiculos(vehiculos, f) {
  return vehiculos.filter((v) => {
    if (f.companias.length && !f.companias.includes(v.compania || SIN_DATO)) return false;
    if (f.ubicaciones.length && !f.ubicaciones.includes(v.ubicacion || SIN_DATO)) return false;
    if (f.funcional.length && !f.funcional.includes(v.estatus_funcional || SIN_DATO)) return false;
    if (f.admin.length && !f.admin.includes(v.estatus_administrativo || SIN_DATO)) return false;
    if (f.tipos.length && !f.tipos.includes(v.tipo || SIN_DATO)) return false;
    if (f.proyectos.length) {
      const ps = v.proyectos && v.proyectos.length ? v.proyectos : [SIN_DATO];
      if (!ps.some((p) => f.proyectos.includes(p))) return false;
    }
    return true;
  });
}

// Busca coincidencias en los campos de texto del vehículo (económico, placas,
// VIN, motor, modelo, responsables, notas).
function coincideBusqueda(v, q) {
  if (!q) return true;
  const t = q.toLowerCase();
  const campos = [
    v.no_economico, v.placas, v.vin, v.no_motor, v.fabricante,
    v.tipo, v.subtipo, v.modelo, v.notas, v.compania,
    ...(v.responsables || []), ...(v.proyectos || []),
  ];
  return campos.some((c) => c && String(c).toLowerCase().includes(t));
}

const VEH_COL_ESTATUS = {
  "Funcional": T.teal,
  "En Mtto": T.amber,
  "Mtto Requerido": T.amber,
  "Fuera de Servicio": T.red,
  "No Encontrado": T.red,
};

function tonoFuncional(e) {
  if (e === "Funcional") return "teal";
  if (e === "En Mtto" || e === "Mtto Requerido") return "amber";
  if (e === "Fuera de Servicio" || e === "No Encontrado") return "red";
  return "dim";
}
function tonoAdmin(e) {
  if (e === "Activa") return "teal";
  if (e === "Vendida") return "accent";
  if (e === "Baja") return "dim";
  return "red";
}
function tonoMtto(e) {
  if (e === "Concluido") return "teal";
  if (e === "En proceso") return "amber";
  if (e === "Cancelado") return "dim";
  return "red";
}

// Detecta el mismo VIN / placas / no. de motor en económicos distintos —
// son los registros que hay que revisar a mano antes de confiar en los conteos.
function posiblesDuplicados(vehiculos) {
  const salida = [];
  [["vin", "VIN"], ["placas", "Placas"], ["no_motor", "No. Motor"]].forEach(([campo, etiqueta]) => {
    const mapa = {};
    vehiculos.forEach((v) => {
      const val = (v[campo] || "").trim();
      if (!val) return;
      (mapa[val] = mapa[val] || []).push(v.no_economico);
    });
    Object.entries(mapa).forEach(([valor, ecos]) => {
      if (ecos.length > 1) salida.push({ campo: etiqueta, valor, economicos: ecos.sort() });
    });
  });
  return salida;
}

/* ------------------------------- DASHBOARD ------------------------------- */

function VehiculosDashboard({ vehiculos, mantenimientos, ubicaciones, onVerVehiculo }) {
  const nombreUbic = (cod) => (ubicaciones.find((u) => u.codigo === cod) || {}).nombre || cod || SIN_DATO;

  const activos = vehiculos.filter((v) => v.estatus_administrativo === "Activa");
  const cuenta = (pred) => activos.filter(pred).length;
  const funcionales = cuenta((v) => v.estatus_funcional === "Funcional");
  const enMtto = cuenta((v) => v.estatus_funcional === "En Mtto" || v.estatus_funcional === "Mtto Requerido");
  const fueraServicio = cuenta((v) => v.estatus_funcional === "Fuera de Servicio");
  const noEncontrados = cuenta((v) => v.estatus_funcional === "No Encontrado");
  const disponibilidad = activos.length ? (funcionales / activos.length) * 100 : 0;

  const idsVisibles = new Set(vehiculos.map((v) => v.id));
  const mttosVisibles = mantenimientos.filter((m) => idsVisibles.has(m.vehiculo_id));
  const mttosAbiertos = mttosVisibles.filter((m) => m.estatus === "Solicitado" || m.estatus === "En proceso");

  // Costo capturado de mantenimientos, separado por moneda.
  const costos = sumaPorMoneda(mttosVisibles, "costo", "moneda");

  // Barras apiladas: estatus funcional por compañía.
  const porCompania = useMemo(() => {
    const mapa = {};
    activos.forEach((v) => {
      const c = v.compania || SIN_DATO;
      mapa[c] = mapa[c] || { compania: c };
      const e = v.estatus_funcional || SIN_DATO;
      mapa[c][e] = (mapa[c][e] || 0) + 1;
    });
    return Object.values(mapa).sort((a, b) => a.compania.localeCompare(b.compania));
  }, [vehiculos]);

  const estatusPresentes = useMemo(() => {
    const s = new Set();
    activos.forEach((v) => s.add(v.estatus_funcional || SIN_DATO));
    return [...s].sort();
  }, [vehiculos]);

  const porTipo = useMemo(() => {
    const mapa = {};
    activos.forEach((v) => {
      const t = v.tipo || SIN_DATO;
      mapa[t] = (mapa[t] || 0) + 1;
    });
    return Object.entries(mapa).map(([tipo, n]) => ({ tipo, n })).sort((a, b) => b.n - a.n);
  }, [vehiculos]);

  const porUbicacion = useMemo(() => {
    const mapa = {};
    activos.forEach((v) => {
      const u = v.ubicacion || SIN_DATO;
      mapa[u] = mapa[u] || { ubicacion: u, total: 0, funcional: 0, mtto: 0, fuera: 0 };
      mapa[u].total += 1;
      if (v.estatus_funcional === "Funcional") mapa[u].funcional += 1;
      else if (v.estatus_funcional === "En Mtto" || v.estatus_funcional === "Mtto Requerido") mapa[u].mtto += 1;
      else mapa[u].fuera += 1;
    });
    return Object.values(mapa).sort((a, b) => b.total - a.total);
  }, [vehiculos]);

  // Vehículos con más SMI abiertas — los que están costando más atención.
  const rankingMtto = useMemo(() => {
    const mapa = {};
    mttosAbiertos.forEach((m) => { mapa[m.vehiculo_id] = (mapa[m.vehiculo_id] || 0) + 1; });
    return Object.entries(mapa)
      .map(([id, n]) => ({ vehiculo: vehiculos.find((v) => v.id === id), n }))
      .filter((r) => r.vehiculo)
      .sort((a, b) => b.n - a.n)
      .slice(0, 12);
  }, [mantenimientos, vehiculos]);

  const duplicados = useMemo(() => posiblesDuplicados(vehiculos), [vehiculos]);

  if (!vehiculos.length) {
    return <EmptyState title="Sin vehículos que mostrar" body="Ajusta los filtros de arriba, o carga la flotilla corriendo los scripts de migración en Supabase." />;
  }

  return (
    <div style={{ display: "grid", gap: 18 }}>
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "stretch" }}>
        <KpiCard label="Flotilla activa" value={activos.length} />
        <KpiCard label="Funcionales" value={funcionales} accent={T.teal} />
        <KpiCard label="Requieren / en mtto" value={enMtto} accent={T.amber} />
        <KpiCard label="Fuera de servicio" value={fueraServicio} accent={T.red} />
        <KpiCard label="No encontrados" value={noEncontrados} accent={T.red} />
        <KpiCard label="SMI abiertas" value={mttosAbiertos.length} accent={T.blue} />
        <div style={{ ...panelStyle, padding: "10px 20px", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontSize: 10.5, color: T.textDim, textTransform: "uppercase", letterSpacing: "0.06em" }}>Disponibilidad</div>
          <Gauge pct={disponibilidad} size={86} />
        </div>
      </div>

      {duplicados.length > 0 && (
        <Panel title="Posibles duplicados" subtitle="Mismo VIN, placas o número de motor en económicos distintos — revisa si son la misma unidad capturada dos veces">
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {duplicados.map((d, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 12, color: T.text }}>
                <Pill tone="amber">{d.campo}</Pill>
                <span style={{ fontFamily: T.fontMono, color: T.textDim }}>{d.valor}</span>
                <span style={{ color: T.textFaint }}>→</span>
                {d.economicos.map((e) => (
                  <button
                    key={e}
                    type="button"
                    onClick={() => onVerVehiculo && onVerVehiculo(e)}
                    style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: T.accent, fontFamily: T.fontMono, fontSize: 12, textDecoration: "underline" }}
                  >
                    {e}
                  </button>
                ))}
              </div>
            ))}
          </div>
        </Panel>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(420px, 1fr))", gap: 18 }}>
        <Panel title="Estatus funcional por compañía" subtitle="Solo unidades activas">
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={porCompania} margin={{ top: 8, right: 8, left: -18, bottom: 4 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.borderSoft} vertical={false} />
              <XAxis dataKey="compania" tick={{ fontSize: 11, fill: T.textDim }} axisLine={{ stroke: T.border }} tickLine={false} />
              <YAxis tick={{ fontSize: 11, fill: T.textDim }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip content={<ChartTooltip />} />
              <Legend wrapperStyle={{ fontSize: 11 }} />
              {estatusPresentes.map((e) => (
                <Bar key={e} dataKey={e} stackId="a" fill={VEH_COL_ESTATUS[e] || T.textFaint} />
              ))}
            </BarChart>
          </ResponsiveContainer>
        </Panel>

        <Panel title="Composición de la flotilla" subtitle="Unidades activas por tipo">
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={porTipo} layout="vertical" margin={{ top: 8, right: 24, left: 30, bottom: 4 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.borderSoft} horizontal={false} />
              <XAxis type="number" tick={{ fontSize: 11, fill: T.textDim }} axisLine={{ stroke: T.border }} tickLine={false} allowDecimals={false} />
              <YAxis type="category" dataKey="tipo" tick={{ fontSize: 11, fill: T.textDim }} axisLine={false} tickLine={false} width={90} />
              <Tooltip content={<ChartTooltip />} />
              <Bar dataKey="n" name="Unidades" fill={T.accent} radius={[0, 3, 3, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </Panel>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(420px, 1fr))", gap: 18 }}>
        <Panel title="Distribución por ubicación" subtitle="Dónde está parada la flotilla activa">
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
            <thead>
              <tr>
                <th style={thStyle}>Ubicación</th>
                <th style={{ ...thStyle, textAlign: "right" }}>Total</th>
                <th style={{ ...thStyle, textAlign: "right" }}>Funcional</th>
                <th style={{ ...thStyle, textAlign: "right" }}>En mtto</th>
                <th style={{ ...thStyle, textAlign: "right" }}>Otros</th>
              </tr>
            </thead>
            <tbody>
              {porUbicacion.map((u) => (
                <tr key={u.ubicacion}>
                  <td style={tdStyle}>{nombreUbic(u.ubicacion)}</td>
                  <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono, fontWeight: 600 }}>{u.total}</td>
                  <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono, color: T.teal }}>{u.funcional || "—"}</td>
                  <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono, color: T.amber }}>{u.mtto || "—"}</td>
                  <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono, color: T.textFaint }}>{u.fuera || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Panel>

        <Panel
          title="Unidades con más SMI abiertas"
          subtitle="Solicitadas o en proceso"
          right={costos.length > 0 && (
            <div style={{ textAlign: "right" }}>
              <div style={{ fontSize: 10, color: T.textFaint, textTransform: "uppercase", letterSpacing: "0.06em" }}>Costo capturado</div>
              {costos.map((c, i) => (
                <div key={i} style={{ fontSize: 12.5, fontFamily: T.fontMono, color: T.text }}>{c}</div>
              ))}
            </div>
          )}
        >
          {rankingMtto.length === 0 ? (
            <div style={{ fontSize: 12.5, color: T.textFaint, padding: "18px 0", textAlign: "center" }}>
              No hay SMI abiertas con los filtros actuales.
            </div>
          ) : (
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
              <thead>
                <tr>
                  <th style={thStyle}>Económico</th>
                  <th style={thStyle}>Compañía</th>
                  <th style={thStyle}>Estatus</th>
                  <th style={{ ...thStyle, textAlign: "right" }}>SMI</th>
                </tr>
              </thead>
              <tbody>
                {rankingMtto.map(({ vehiculo, n }) => (
                  <tr key={vehiculo.id}>
                    <td style={tdStyle}>
                      <button
                        type="button"
                        onClick={() => onVerVehiculo && onVerVehiculo(vehiculo.no_economico)}
                        style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: T.accent, fontFamily: T.fontMono, fontSize: 12.5, textDecoration: "underline" }}
                      >
                        {vehiculo.no_economico}
                      </button>
                    </td>
                    <td style={tdStyle}>{vehiculo.compania || "—"}</td>
                    <td style={tdStyle}><Pill tone={tonoFuncional(vehiculo.estatus_funcional)}>{vehiculo.estatus_funcional || "—"}</Pill></td>
                    <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono, fontWeight: 600 }}>{n}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </Panel>
      </div>
    </div>
  );
}

/* ------------------------------- FORMULARIO ------------------------------ */

const VEH_FORM_VACIO = {
  no_economico: "", compania: "", proyectos: [], estatus_administrativo: "Activa",
  estatus_funcional: "", estatus_operacional: "", ubicacion: "", placas: "", vin: "",
  no_motor: "", fabricante: "", tipo: "", subtipo: "", modelo: "", anio: "",
  responsables: [], gps: "", notas: "",
};

function VehiculoModal({ inicial, ubicaciones, proyectosOpciones, companiasOpciones, onGuardar, onClose, perfilesApi, registro }) {
  const [f, setF] = useState({ ...VEH_FORM_VACIO, ...(inicial || {}), anio: inicial && inicial.anio != null ? String(inicial.anio) : "" });
  const [guardando, setGuardando] = useState(false);
  const set = (k, v) => setF((prev) => ({ ...prev, [k]: v }));

  const toggleProyecto = (p) =>
    set("proyectos", f.proyectos.includes(p) ? f.proyectos.filter((x) => x !== p) : [...f.proyectos, p]);

  const guardar = async () => {
    if (!f.no_economico.trim()) { alert("El número económico es obligatorio."); return; }
    setGuardando(true);
    try {
      await onGuardar({
        no_economico: f.no_economico.trim(),
        compania: f.compania || null,
        proyectos: f.proyectos,
        estatus_administrativo: f.estatus_administrativo || "Activa",
        estatus_funcional: f.estatus_funcional || null,
        estatus_operacional: f.estatus_operacional || null,
        ubicacion: f.ubicacion || null,
        placas: f.placas.trim() || null,
        vin: f.vin.trim().toUpperCase() || null,
        no_motor: f.no_motor.trim() || null,
        fabricante: f.fabricante.trim() || null,
        tipo: f.tipo || null,
        subtipo: f.subtipo.trim() || null,
        modelo: f.modelo.trim() || null,
        anio: f.anio && /^\d{4}$/.test(f.anio) ? Number(f.anio) : null,
        responsables: f.responsables,
        gps: f.gps || null,
        notas: f.notas.trim() || null,
      });
      onClose();
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally {
      setGuardando(false);
    }
  };

  return (
    <Modal
      title={inicial && inicial.id ? `Editar ${inicial.no_economico}` : "Nuevo vehículo"}
      subtitle={inicial && inicial.id ? "Los cambios quedan registrados con tu usuario" : "Alta manual de una unidad"}
      onClose={onClose}
      width={860}
      cerrarAlHacerClicFuera={false}
    >
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 14 }}>
        <Field label="No. Económico *">
          <TextInput value={f.no_economico} onChange={(e) => set("no_economico", e.target.value)} placeholder="CTM-V001" />
        </Field>
        <Field label="Compañía">
          <Select value={f.compania} onChange={(e) => set("compania", e.target.value)}>
            <option value="">— Sin asignar —</option>
            {companiasOpciones.map((c) => <option key={c} value={c}>{c}</option>)}
          </Select>
        </Field>
        <Field label="Estatus administrativo">
          <Select value={f.estatus_administrativo} onChange={(e) => set("estatus_administrativo", e.target.value)}>
            {VEH_EST_ADMIN.map((e) => <option key={e} value={e}>{e}</option>)}
          </Select>
        </Field>
        <Field label="Estatus funcional">
          <Select value={f.estatus_funcional} onChange={(e) => set("estatus_funcional", e.target.value)}>
            <option value="">— Sin dato —</option>
            {VEH_EST_FUNCIONAL.map((e) => <option key={e} value={e}>{e}</option>)}
          </Select>
        </Field>
        <Field label="Estatus operacional">
          <Select value={f.estatus_operacional} onChange={(e) => set("estatus_operacional", e.target.value)}>
            <option value="">— Sin dato —</option>
            {VEH_EST_OPERACIONAL.map((e) => <option key={e} value={e}>{e}</option>)}
          </Select>
        </Field>
        <Field label="Ubicación">
          <Select value={f.ubicacion} onChange={(e) => set("ubicacion", e.target.value)}>
            <option value="">— Sin dato —</option>
            {ubicaciones.map((u) => <option key={u.codigo} value={u.codigo}>{u.codigo} · {u.nombre}</option>)}
          </Select>
        </Field>
        <Field label="Placas">
          <TextInput value={f.placas} onChange={(e) => set("placas", e.target.value)} />
        </Field>
        <Field label="VIN">
          <TextInput value={f.vin} onChange={(e) => set("vin", e.target.value)} />
        </Field>
        <Field label="No. Motor">
          <TextInput value={f.no_motor} onChange={(e) => set("no_motor", e.target.value)} />
        </Field>
        <Field label="Fabricante">
          <TextInput value={f.fabricante} onChange={(e) => set("fabricante", e.target.value)} placeholder="Toyota" />
        </Field>
        <Field label="Tipo">
          <Select value={f.tipo} onChange={(e) => set("tipo", e.target.value)}>
            <option value="">— Sin dato —</option>
            {VEH_TIPOS.map((t) => <option key={t} value={t}>{t}</option>)}
          </Select>
        </Field>
        <Field label="Subtipo">
          <TextInput value={f.subtipo} onChange={(e) => set("subtipo", e.target.value)} placeholder="Plataforma" />
        </Field>
        <Field label="Modelo">
          <TextInput value={f.modelo} onChange={(e) => set("modelo", e.target.value)} placeholder="Hilux Doble Cabina" />
        </Field>
        <Field label="Año">
          <TextInput value={f.anio} onChange={(e) => set("anio", e.target.value.replace(/\D/g, "").slice(0, 4))} placeholder="2019" />
        </Field>
        <Field label="GPS">
          <Select value={f.gps} onChange={(e) => set("gps", e.target.value)}>
            <option value="">— Sin GPS —</option>
            {VEH_GPS.map((g) => <option key={g} value={g}>{g}</option>)}
          </Select>
        </Field>
      </div>

      <div style={{ marginTop: 16 }}>
        <div style={{ textTransform: "uppercase", letterSpacing: "0.06em", fontSize: 10.5, color: T.textDim, marginBottom: 8 }}>Proyectos</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
          {proyectosOpciones.map((p) => (
            <label key={p} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12.5, color: T.text, cursor: "pointer" }}>
              <input type="checkbox" checked={f.proyectos.includes(p)} onChange={() => toggleProyecto(p)} />
              {p}
            </label>
          ))}
        </div>
      </div>

      <div style={{ marginTop: 16, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        <Field label="Responsables (separados por coma)">
          <TextInput
            value={f.responsables.join(", ")}
            onChange={(e) => set("responsables", e.target.value.split(",").map((s) => s.trim()).filter(Boolean))}
            placeholder="Juan Pérez, María López"
          />
        </Field>
        <Field label="Notas generales">
          <TextInput value={f.notas} onChange={(e) => set("notas", e.target.value)} />
        </Field>
      </div>

      {registro && <div style={{ marginTop: 14 }}><AutoriaCaption record={registro} perfilesApi={perfilesApi} /></div>}

      <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 20 }}>
        <Button variant="ghost" onClick={onClose}>Cancelar</Button>
        <Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Button>
      </div>
    </Modal>
  );
}

function MantenimientoModal({ inicial, vehiculos, onGuardar, onClose, perfilesApi }) {
  const [f, setF] = useState({
    folio: "", vehiculo_id: "", zona: "", anio: "", fecha: "", tipo_mtto: "",
    descripcion: "", estatus: "Solicitado", proveedor: "", costo: "", moneda: "MXP", notas: "",
    ...(inicial || {}),
    anio: inicial && inicial.anio != null ? String(inicial.anio) : "",
    costo: inicial && inicial.costo != null ? String(inicial.costo) : "",
  });
  const [guardando, setGuardando] = useState(false);
  const set = (k, v) => setF((prev) => ({ ...prev, [k]: v }));

  const guardar = async () => {
    if (!f.folio.trim()) { alert("El folio de la SMI es obligatorio."); return; }
    if (!f.vehiculo_id) { alert("Elige a qué vehículo pertenece."); return; }
    setGuardando(true);
    try {
      await onGuardar({
        folio: f.folio.trim().toUpperCase(),
        vehiculo_id: f.vehiculo_id,
        zona: f.zona.trim() || null,
        anio: f.anio && /^\d{4}$/.test(f.anio) ? Number(f.anio) : null,
        fecha: f.fecha || null,
        tipo_mtto: f.tipo_mtto || null,
        descripcion: f.descripcion.trim() || null,
        estatus: f.estatus,
        proveedor: f.proveedor.trim() || null,
        costo: f.costo !== "" && !isNaN(Number(f.costo)) ? Number(f.costo) : null,
        moneda: f.moneda || "MXP",
        notas: f.notas.trim() || null,
      });
      onClose();
    } catch (err) {
      alert("No se pudo guardar: " + (err.message || err));
    } finally {
      setGuardando(false);
    }
  };

  const ordenados = [...vehiculos].sort((a, b) => a.no_economico.localeCompare(b.no_economico));

  return (
    <Modal
      title={inicial && inicial.id ? `Editar ${inicial.folio}` : "Nueva SMI"}
      subtitle="Solicitud de mantenimiento"
      onClose={onClose}
      width={780}
      cerrarAlHacerClicFuera={false}
    >
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 14 }}>
        <Field label="Folio *">
          <TextInput value={f.folio} onChange={(e) => set("folio", e.target.value)} placeholder="MTTO-PR-2026-001" />
        </Field>
        <Field label="Vehículo *">
          <Select value={f.vehiculo_id} onChange={(e) => set("vehiculo_id", e.target.value)}>
            <option value="">— Elegir —</option>
            {ordenados.map((v) => (
              <option key={v.id} value={v.id}>{v.no_economico}{v.compania ? ` · ${v.compania}` : ""}</option>
            ))}
          </Select>
        </Field>
        <Field label="Zona">
          <TextInput value={f.zona} onChange={(e) => set("zona", e.target.value)} placeholder="PR-UP" />
        </Field>
        <Field label="Año">
          <TextInput value={f.anio} onChange={(e) => set("anio", e.target.value.replace(/\D/g, "").slice(0, 4))} placeholder="2026" />
        </Field>
        <Field label="Fecha">
          <TextInput type="date" value={f.fecha || ""} onChange={(e) => set("fecha", e.target.value)} />
        </Field>
        <Field label="Tipo">
          <Select value={f.tipo_mtto} onChange={(e) => set("tipo_mtto", e.target.value)}>
            <option value="">— Sin dato —</option>
            {MTTO_TIPOS.map((t) => <option key={t} value={t}>{t}</option>)}
          </Select>
        </Field>
        <Field label="Estatus">
          <Select value={f.estatus} onChange={(e) => set("estatus", e.target.value)}>
            {MTTO_ESTATUS.map((e) => <option key={e} value={e}>{e}</option>)}
          </Select>
        </Field>
        <Field label="Proveedor / taller">
          <TextInput value={f.proveedor} onChange={(e) => set("proveedor", e.target.value)} />
        </Field>
        <Field label="Costo">
          <TextInput value={f.costo} onChange={(e) => set("costo", e.target.value)} placeholder="0.00" />
        </Field>
        <Field label="Moneda">
          <Select value={f.moneda} onChange={(e) => set("moneda", e.target.value)}>
            {MONEDAS.map((m) => <option key={m} value={m}>{m}</option>)}
          </Select>
        </Field>
      </div>

      <div style={{ marginTop: 14, display: "grid", gap: 14 }}>
        <Field label="Descripción del trabajo">
          <TextInput value={f.descripcion} onChange={(e) => set("descripcion", e.target.value)} placeholder="Cambio de balatas y rectificado de discos" />
        </Field>
        <Field label="Notas">
          <TextInput value={f.notas} onChange={(e) => set("notas", e.target.value)} />
        </Field>
      </div>

      {inicial && inicial.id && <div style={{ marginTop: 14 }}><AutoriaCaption record={inicial} perfilesApi={perfilesApi} /></div>}

      <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 20 }}>
        <Button variant="ghost" onClick={onClose}>Cancelar</Button>
        <Button onClick={guardar} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Button>
      </div>
    </Modal>
  );
}

/* --------------------------------- FLOTILLA ------------------------------- */

const COLUMNAS_VEHICULOS = [
  { key: "no_economico", label: "No. Económico" },
  { key: "compania", label: "Compañía" },
  { key: "proyectos", label: "Proyectos" },
  { key: "estatus_funcional", label: "Est. Funcional" },
  { key: "estatus_operacional", label: "Est. Operacional" },
  { key: "estatus_administrativo", label: "Est. Administrativo" },
  { key: "ubicacion", label: "Ubicación" },
  { key: "tipo", label: "Tipo" },
  { key: "subtipo", label: "Subtipo" },
  { key: "fabricante", label: "Fabricante" },
  { key: "modelo", label: "Modelo" },
  { key: "anio", label: "Año" },
  { key: "placas", label: "Placas" },
  { key: "vin", label: "VIN" },
  { key: "no_motor", label: "No. Motor" },
  { key: "gps", label: "GPS" },
  { key: "responsables", label: "Responsables" },
  { key: "smi", label: "SMI abiertas" },
  { key: "notas", label: "Notas" },
];

function FlotillaPanel({ vehiculos, vehiculosApi, mantenimientos, ubicaciones, proyectosOpciones, companiasOpciones, perfilesApi, expandido, setExpandido }) {
  const [busqueda, setBusqueda] = useSessionState("veh:busqueda", "");
  const [sort, setSort] = usePrefState("pref-veh-sort", { key: "no_economico", dir: "asc" }, sanearSort(["no_economico","compania","estatus_funcional","estatus_operacional","estatus_administrativo","ubicacion","placas","vin","marca","modelo","anio","tipo"]));
  const [editando, setEditando] = useState(null); // objeto vehículo, o {} para nuevo
  const { visible, hidden, toggle, showAll } = useColumnVisibility("veh:columnas", COLUMNAS_VEHICULOS);

  const nombreUbic = (cod) => (ubicaciones.find((u) => u.codigo === cod) || {}).nombre || cod;

  const smiPorVehiculo = useMemo(() => {
    const mapa = {};
    mantenimientos.forEach((m) => { (mapa[m.vehiculo_id] = mapa[m.vehiculo_id] || []).push(m); });
    return mapa;
  }, [mantenimientos]);

  const filas = useMemo(() => {
    const buscados = vehiculos.filter((v) => coincideBusqueda(v, busqueda));
    return sortRows(buscados, sort, {
      proyectos: (v) => (v.proyectos || []).join(", "),
      responsables: (v) => (v.responsables || []).join(", "),
      ubicacion: (v) => nombreUbic(v.ubicacion) || "",
      smi: (v) => (smiPorVehiculo[v.id] || []).filter((m) => m.estatus === "Solicitado" || m.estatus === "En proceso").length,
      anio: (v) => v.anio || 0,
    });
  }, [vehiculos, busqueda, sort, smiPorVehiculo, ubicaciones]);

  const guardar = async (datos) => {
    if (editando && editando.id) await vehiculosApi.update(editando.id, datos);
    else await vehiculosApi.insert({ id: uid(), ...datos });
  };

  const eliminar = (v) => {
    if (!confirm(`¿Eliminar ${v.no_economico}? También se borran sus SMI asociadas.`)) return;
    vehiculosApi.remove(v.id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
  };

  const celda = (v, key) => {
    switch (key) {
      case "no_economico":
        return <span style={{ fontFamily: T.fontMono, fontWeight: 600 }}>{v.no_economico}</span>;
      case "proyectos":
        return (v.proyectos || []).length
          ? <span style={{ display: "inline-flex", gap: 4, flexWrap: "wrap" }}>{v.proyectos.map((p) => <Pill key={p} tone="dim">{p}</Pill>)}</span>
          : <span style={{ color: T.textFaint }}>—</span>;
      case "estatus_funcional":
        return v.estatus_funcional ? <Pill tone={tonoFuncional(v.estatus_funcional)}>{v.estatus_funcional}</Pill> : <span style={{ color: T.textFaint }}>—</span>;
      case "estatus_administrativo":
        return <Pill tone={tonoAdmin(v.estatus_administrativo)}>{v.estatus_administrativo}</Pill>;
      case "ubicacion":
        return v.ubicacion ? nombreUbic(v.ubicacion) : <span style={{ color: T.textFaint }}>—</span>;
      case "responsables":
        return (v.responsables || []).length ? v.responsables.join(", ") : <span style={{ color: T.textFaint }}>—</span>;
      case "smi": {
        const abiertas = (smiPorVehiculo[v.id] || []).filter((m) => m.estatus === "Solicitado" || m.estatus === "En proceso").length;
        return abiertas ? <Pill tone="amber">{abiertas}</Pill> : <span style={{ color: T.textFaint }}>—</span>;
      }
      case "vin":
      case "no_motor":
      case "placas":
        return v[key] ? <span style={{ fontFamily: T.fontMono, fontSize: 11.5 }}>{v[key]}</span> : <span style={{ color: T.textFaint }}>—</span>;
      default:
        return v[key] != null && v[key] !== "" ? v[key] : <span style={{ color: T.textFaint }}>—</span>;
    }
  };

  return (
    <div style={{ display: "grid", gap: 14 }}>
      <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
        <TextInput
          value={busqueda}
          onChange={(e) => setBusqueda(e.target.value)}
          placeholder="Buscar económico, placas, VIN, modelo, responsable…"
          style={{ width: 340 }}
        />
        <span style={{ fontSize: 12, color: T.textDim }}>
          {filas.length} {filas.length === 1 ? "unidad" : "unidades"}
        </span>
        <div style={{ flex: 1 }} />
        <ColumnVisibilityControl columns={COLUMNAS_VEHICULOS} hidden={hidden} onToggle={toggle} onShowAll={showAll} />
        <Button onClick={() => setEditando({})}>Nuevo vehículo</Button>
      </div>

      {filas.length === 0 ? (
        <EmptyState title="Sin resultados" body="Ningún vehículo coincide con los filtros y la búsqueda actuales." />
      ) : (
        <div style={{ ...panelStyle, padding: 0, overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
            <thead>
              <tr>
                <th style={{ ...thStyle, width: 34 }}></th>
                <th style={{ ...thStyle, width: 40 }}>#</th>
                {visible.map((c) => (
                  <SortableTh key={c.key} label={c.label} sortKey={c.key} sort={sort} setSort={setSort} />
                ))}
                <th style={{ ...thStyle, width: 76 }}>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {filas.map((v, i) => {
                const smis = (smiPorVehiculo[v.id] || []).slice().sort((a, b) => (a.folio || "").localeCompare(b.folio || ""));
                const abierto = expandido === v.id;
                return (
                  <React.Fragment key={v.id}>
                    <tr>
                      <td style={{ ...tdStyle, textAlign: "center" }}>
                        {smis.length > 0 && (
                          <button
                            type="button"
                            onClick={() => setExpandido(abierto ? null : v.id)}
                            style={{ background: "none", border: "none", cursor: "pointer", color: T.textDim, fontSize: 11, padding: 0 }}
                            title={abierto ? "Ocultar SMI" : "Ver SMI"}
                          >
                            {abierto ? "▾" : "▸"}
                          </button>
                        )}
                      </td>
                      <td style={{ ...tdStyle, color: T.textFaint, fontFamily: T.fontMono, fontSize: 11 }}>{i + 1}</td>
                      {visible.map((c) => <td key={c.key} style={tdStyle}>{celda(v, c.key)}</td>)}
                      <td style={tdStyle}>
                        <div style={{ display: "flex", gap: 5 }}>
                          <IconButton icon="✎" label="Editar" onClick={() => setEditando(v)} />
                          <IconButton icon="✕" label="Eliminar" tone={T.red} onClick={() => eliminar(v)} />
                        </div>
                      </td>
                    </tr>
                    {abierto && (
                      <tr>
                        <td colSpan={visible.length + 3} style={{ padding: "10px 18px 16px 52px", background: T.panelAlt, borderBottom: `1px solid ${T.borderSoft}` }}>
                          <div style={{ fontSize: 10.5, color: T.textDim, textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 8 }}>
                            SMI de mantenimiento · {smis.length}
                          </div>
                          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                            <thead>
                              <tr>
                                <th style={thStyle}>Folio</th>
                                <th style={thStyle}>Estatus</th>
                                <th style={thStyle}>Tipo</th>
                                <th style={thStyle}>Fecha</th>
                                <th style={thStyle}>Descripción</th>
                                <th style={{ ...thStyle, textAlign: "right" }}>Costo</th>
                              </tr>
                            </thead>
                            <tbody>
                              {smis.map((m) => (
                                <tr key={m.id}>
                                  <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{m.folio}</td>
                                  <td style={tdStyle}><Pill tone={tonoMtto(m.estatus)}>{m.estatus}</Pill></td>
                                  <td style={tdStyle}>{m.tipo_mtto || <span style={{ color: T.textFaint }}>—</span>}</td>
                                  <td style={tdStyle}>{m.fecha || <span style={{ color: T.textFaint }}>—</span>}</td>
                                  <td style={tdStyle}>{m.descripcion || <span style={{ color: T.textFaint }}>Pendiente de capturar</span>}</td>
                                  <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono }}>
                                    {m.costo != null ? money(m.costo, m.moneda || "MXP") : <span style={{ color: T.textFaint }}>—</span>}
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {editando && (
        <VehiculoModal
          inicial={editando.id ? editando : null}
          registro={editando.id ? editando : null}
          ubicaciones={ubicaciones}
          proyectosOpciones={proyectosOpciones}
          companiasOpciones={companiasOpciones}
          perfilesApi={perfilesApi}
          onGuardar={guardar}
          onClose={() => setEditando(null)}
        />
      )}
    </div>
  );
}

/* ------------------------------ MANTENIMIENTOS ---------------------------- */

function MantenimientosPanel({ vehiculos, mantenimientos, mantenimientosApi, perfilesApi }) {
  const [estatusFiltro, setEstatusFiltro] = useSessionSetState("veh:mtto:estatus", []);
  const [aniosFiltro, setAniosFiltro] = useSessionSetState("veh:mtto:anios", []);
  const [sort, setSort] = usePrefState("pref-veh-mtto-sort", { key: "folio", dir: "asc" }, sanearSort(["folio","vehiculo","zona","anio","fecha","tipo_mtto","estatus","taller","costo"]));
  const [editando, setEditando] = useState(null);

  const porId = useMemo(() => {
    const m = {};
    vehiculos.forEach((v) => { m[v.id] = v; });
    return m;
  }, [vehiculos]);

  const aniosDisponibles = useMemo(
    () => [...new Set(mantenimientos.map((m) => m.anio).filter(Boolean))].sort((a, b) => b - a).map(String),
    [mantenimientos]
  );

  const filas = useMemo(() => {
    const f = mantenimientos.filter((m) => {
      if (estatusFiltro.size && !estatusFiltro.has(m.estatus)) return false;
      if (aniosFiltro.size && !aniosFiltro.has(String(m.anio))) return false;
      return true;
    });
    return sortRows(f, sort, {
      vehiculo: (m) => (porId[m.vehiculo_id] || {}).no_economico || "",
      compania: (m) => (porId[m.vehiculo_id] || {}).compania || "",
      costo: (m) => Number(m.costo) || 0,
    });
  }, [mantenimientos, estatusFiltro, aniosFiltro, sort, porId]);

  const totales = sumaPorMoneda(filas, "costo", "moneda");

  const guardar = async (datos) => {
    if (editando && editando.id) await mantenimientosApi.update(editando.id, datos);
    else await mantenimientosApi.insert({ id: uid(), ...datos });
  };

  const eliminar = (m) => {
    if (!confirm(`¿Eliminar la SMI ${m.folio}?`)) return;
    mantenimientosApi.remove(m.id).catch((err) => alert("No se pudo eliminar: " + (err.message || err)));
  };

  return (
    <div style={{ display: "grid", gap: 14 }}>
      <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
        <MultiSelect
          opciones={MTTO_ESTATUS}
          seleccionados={[...estatusFiltro]}
          onChange={(vals) => setEstatusFiltro(new Set(vals))}
          todosLabel="Todos los estatus"
          unidadLabel=" estatus"
        />
        <MultiSelect
          opciones={aniosDisponibles}
          seleccionados={[...aniosFiltro]}
          onChange={(vals) => setAniosFiltro(new Set(vals))}
          todosLabel="Todos los años"
          unidadLabel=" años"
        />
        <span style={{ fontSize: 12, color: T.textDim }}>{filas.length} SMI</span>
        {totales.length > 0 && (
          <span style={{ fontSize: 12, color: T.teal, fontFamily: T.fontMono }}>Σ {totales.join(" · ")}</span>
        )}
        <div style={{ flex: 1 }} />
        <Button onClick={() => setEditando({})}>Nueva SMI</Button>
      </div>

      {filas.length === 0 ? (
        <EmptyState title="Sin SMI" body="No hay solicitudes de mantenimiento con los filtros actuales." />
      ) : (
        <div style={{ ...panelStyle, padding: 0, overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
            <thead>
              <tr>
                <th style={{ ...thStyle, width: 40 }}>#</th>
                <SortableTh label="Folio" sortKey="folio" sort={sort} setSort={setSort} />
                <SortableTh label="Vehículo" sortKey="vehiculo" sort={sort} setSort={setSort} />
                <SortableTh label="Compañía" sortKey="compania" sort={sort} setSort={setSort} />
                <SortableTh label="Zona" sortKey="zona" sort={sort} setSort={setSort} />
                <SortableTh label="Año" sortKey="anio" sort={sort} setSort={setSort} />
                <SortableTh label="Fecha" sortKey="fecha" sort={sort} setSort={setSort} />
                <SortableTh label="Tipo" sortKey="tipo_mtto" sort={sort} setSort={setSort} />
                <SortableTh label="Estatus" sortKey="estatus" sort={sort} setSort={setSort} />
                <SortableTh label="Descripción" sortKey="descripcion" sort={sort} setSort={setSort} />
                <SortableTh label="Proveedor" sortKey="proveedor" sort={sort} setSort={setSort} />
                <SortableTh label="Costo" sortKey="costo" sort={sort} setSort={setSort} sumLabel={totales} />
                <th style={{ ...thStyle, width: 76 }}>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {filas.map((m, i) => {
                const v = porId[m.vehiculo_id];
                return (
                  <tr key={m.id}>
                    <td style={{ ...tdStyle, color: T.textFaint, fontFamily: T.fontMono, fontSize: 11 }}>{i + 1}</td>
                    <td style={{ ...tdStyle, fontFamily: T.fontMono, fontWeight: 600 }}>{m.folio}</td>
                    <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{v ? v.no_economico : <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={tdStyle}>{(v && v.compania) || <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={tdStyle}>{m.zona || <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={{ ...tdStyle, fontFamily: T.fontMono }}>{m.anio || <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={tdStyle}>{m.fecha || <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={tdStyle}>{m.tipo_mtto || <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={tdStyle}><Pill tone={tonoMtto(m.estatus)}>{m.estatus}</Pill></td>
                    <td style={tdStyle}>{m.descripcion || <span style={{ color: T.textFaint }}>Pendiente de capturar</span>}</td>
                    <td style={tdStyle}>{m.proveedor || <span style={{ color: T.textFaint }}>—</span>}</td>
                    <td style={{ ...tdStyle, textAlign: "right", fontFamily: T.fontMono }}>
                      {m.costo != null ? money(m.costo, m.moneda || "MXP") : <span style={{ color: T.textFaint }}>—</span>}
                    </td>
                    <td style={tdStyle}>
                      <div style={{ display: "flex", gap: 5 }}>
                        <IconButton icon="✎" label="Editar" onClick={() => setEditando(m)} />
                        <IconButton icon="✕" label="Eliminar" tone={T.red} onClick={() => eliminar(m)} />
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {editando && (
        <MantenimientoModal
          inicial={editando.id ? editando : null}
          vehiculos={vehiculos}
          perfilesApi={perfilesApi}
          onGuardar={guardar}
          onClose={() => setEditando(null)}
        />
      )}
    </div>
  );
}

/* --------------------------------- TAB RAÍZ ------------------------------- */

function VehiculosTab({ vehiculos, vehiculosApi, mantenimientos, mantenimientosApi, ubicaciones, perfilesApi, unidadesPermitidas }) {
  const [sub, setSub] = useSessionState("veh:sub", "dashboard");
  const [companias, setCompanias] = useSessionSetState("veh:f:companias", []);
  const [ubics, setUbics] = useSessionSetState("veh:f:ubicaciones", []);
  const [funcional, setFuncional] = useSessionSetState("veh:f:funcional", []);
  const [admin, setAdmin] = useSessionSetState("veh:f:admin", ["Activa"]);
  const [tipos, setTipos] = useSessionSetState("veh:f:tipos", []);
  const [proyectos, setProyectos] = useSessionSetState("veh:f:proyectos", []);
  const [expandido, setExpandido] = useState(null);

  // Solo las compañías que este usuario tiene permitido ver. Si no tiene
  // restricción, ve las 5 (incluidas IZ2 y JEF, que no existen en el selector
  // global de unidad de negocio pero sí tienen vehículos).
  const companiasOpciones = useMemo(() => {
    const permitidas = unidadesPermitidas && unidadesPermitidas.length ? unidadesPermitidas : null;
    return VEH_COMPANIAS.filter((c) => !permitidas || permitidas.includes(c));
  }, [unidadesPermitidas]);

  const proyectosOpciones = useMemo(() => {
    const s = new Set();
    vehiculos.forEach((v) => (v.proyectos || []).forEach((p) => s.add(p)));
    return [...s].sort();
  }, [vehiculos]);

  const ubicacionesOpciones = useMemo(
    () => ubicaciones.slice().sort((a, b) => a.nombre.localeCompare(b.nombre)),
    [ubicaciones]
  );

  const filtrados = useMemo(
    () => filtrarVehiculos(vehiculos, {
      companias: [...companias], ubicaciones: [...ubics], funcional: [...funcional],
      admin: [...admin], tipos: [...tipos], proyectos: [...proyectos],
    }),
    [vehiculos, companias, ubics, funcional, admin, tipos, proyectos]
  );

  const idsFiltrados = useMemo(() => new Set(filtrados.map((v) => v.id)), [filtrados]);
  const mttosFiltrados = useMemo(
    () => mantenimientos.filter((m) => idsFiltrados.has(m.vehiculo_id)),
    [mantenimientos, idsFiltrados]
  );

  // Desde el Dashboard se puede saltar a una unidad concreta: cambia a Flotilla
  // y la deja expandida.
  const verVehiculo = (economico) => {
    const v = vehiculos.find((x) => x.no_economico === economico);
    setSub("flotilla");
    if (v) setExpandido(v.id);
  };

  const SUBS = [
    { id: "dashboard", label: "Dashboard" },
    { id: "flotilla", label: "Flotilla" },
    { id: "mantenimientos", label: "Mantenimientos" },
  ];

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
        <div style={{ display: "flex", background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, padding: 3 }}>
          {SUBS.map((s) => (
            <button
              key={s.id}
              onClick={() => setSub(s.id)}
              style={{
                padding: "7px 16px", borderRadius: 6, border: "none", cursor: "pointer",
                background: sub === s.id ? T.accent : "transparent",
                color: sub === s.id ? "#FFFFFF" : T.textDim,
                fontWeight: 600, fontSize: 12.5, fontFamily: T.fontUI,
              }}
            >
              {s.label}
            </button>
          ))}
        </div>

        <div style={{ flex: 1 }} />

        <MultiSelect opciones={companiasOpciones} seleccionados={[...companias]} onChange={(v) => setCompanias(new Set(v))} todosLabel="Todas las compañías" unidadLabel=" compañías" />
        <MultiSelect opciones={proyectosOpciones} seleccionados={[...proyectos]} onChange={(v) => setProyectos(new Set(v))} todosLabel="Todos los proyectos" unidadLabel=" proyectos" />
        <MultiSelect opciones={ubicacionesOpciones.map((u) => u.codigo)} seleccionados={[...ubics]} onChange={(v) => setUbics(new Set(v))} todosLabel="Todas las ubicaciones" unidadLabel=" ubic." />
        <MultiSelect opciones={VEH_TIPOS} seleccionados={[...tipos]} onChange={(v) => setTipos(new Set(v))} todosLabel="Todos los tipos" unidadLabel=" tipos" />
        <MultiSelect opciones={VEH_EST_FUNCIONAL} seleccionados={[...funcional]} onChange={(v) => setFuncional(new Set(v))} todosLabel="Todo est. funcional" unidadLabel=" estatus" />
        <MultiSelect opciones={VEH_EST_ADMIN} seleccionados={[...admin]} onChange={(v) => setAdmin(new Set(v))} todosLabel="Todo est. admin." unidadLabel=" estatus" />
      </div>

      {sub === "dashboard" && (
        <VehiculosDashboard
          vehiculos={filtrados}
          mantenimientos={mttosFiltrados}
          ubicaciones={ubicaciones}
          onVerVehiculo={verVehiculo}
        />
      )}
      {sub === "flotilla" && (
        <FlotillaPanel
          vehiculos={filtrados}
          vehiculosApi={vehiculosApi}
          mantenimientos={mttosFiltrados}
          ubicaciones={ubicaciones}
          proyectosOpciones={proyectosOpciones}
          companiasOpciones={companiasOpciones}
          perfilesApi={perfilesApi}
          expandido={expandido}
          setExpandido={setExpandido}
        />
      )}
      {sub === "mantenimientos" && (
        <MantenimientosPanel
          vehiculos={filtrados}
          mantenimientos={mttosFiltrados}
          mantenimientosApi={mantenimientosApi}
          perfilesApi={perfilesApi}
        />
      )}
    </div>
  );
}

export default function App() {
  const { session, recovery, clearRecovery } = useAuth();
  const proyectosApi = useCollection("proyectos");
  const zonasApi = useCollection("zonas");
  const rubrosApi = useCollection("rubros");
  const categoriasApi = useCollection("categorias");
  // Al cambiar el catálogo se reconstruye la variable de módulo y se fuerza
  // un render, para que los selectores muestren lo nuevo sin recargar.
  const [catalogoVersion, setCatalogoVersion] = useState(0);
  useEffect(() => {
    aplicarCatalogo(rubrosApi.rows, categoriasApi.rows);
    setCatalogoVersion((v) => v + 1);
  }, [rubrosApi.rows, categoriasApi.rows]);
  const partidasApi = useCollection("partidas", "created_at", { withAudit: true });
  const transaccionesApi = useCollection("transacciones", "created_at", { withAudit: true });
  const proveedoresApi = useCollection("proveedores", "created_at", { withAudit: true });
  const cuentasApi = useCollection("proveedor_cuentas", "created_at", { withAudit: true });
  const perfilesApi = useCollection("perfiles");
  const notasApi = useCollection("transaccion_notas");
  const vehiculosApi = useCollection("vehiculos", "no_economico", { withAudit: true });
  const vehMantenimientosApi = useCollection("vehiculo_mantenimientos", "folio", { withAudit: true });
  const vehUbicacionesApi = useCollection("vehiculo_ubicaciones", "nombre");
  const contratosParametrosApi = useCollection("contratos_parametros", "vigente_desde");
  const contratosProvLegalApi = useCollection("contratos_proveedor_legal", "razon_social");
  const contratosProvUnidadApi = useCollection("contratos_proveedor_unidad", "rfc");
  const contratosInstrumentosApi = useCollection("contratos_instrumentos", "folio");
  const contratosClausulasApi = useCollection("contratos_clausulas", "orden");
  const [unidad, setUnidad] = useState("CTM");
  const [tab, setTab] = useState("dashboard");
  // Puente entre pestañas: al crear una transacción a partir de una
  // partida, el dato precargado viaja aquí mientras se cambia de tab.
  // Transacciones lo consume una sola vez y lo limpia, para que volver a
  // cambiar de tab después no reabra el formulario con datos viejos.
  const [seedTransaccion, setSeedTransaccion] = useState(null);

  const miPerfil = session ? perfilesApi.rows.find((p) => p.id === session.user.id) : null;
  const unidadesPermitidas = (miPerfil?.unidades_permitidas && miPerfil.unidades_permitidas.length)
    ? miPerfil.unidades_permitidas
    : UNIDAD_KEYS;

  // Si la unidad activa no está entre las permitidas (primera carga, o a alguien
  // le acaban de restringir el acceso), se cambia sola a la primera que sí puede ver.
  useEffect(() => {
    if (unidadesPermitidas.length && !unidadesPermitidas.includes(unidad)) {
      setUnidad(unidadesPermitidas[0]);
    }
  }, [unidadesPermitidas.join(","), unidad]);

  const unidades = useMemo(() => {
    const map = {};
    UNIDADES_BASE.filter((u) => unidadesPermitidas.includes(u)).forEach((u) => { map[u] = { proyectos: [] }; });
    proyectosApi.rows.forEach((p) => {
      if (!map[p.unidad]) return; // fuera del alcance permitido, se ignora
      map[p.unidad].proyectos.push(p);
    });
    return map;
  }, [proyectosApi.rows, unidadesPermitidas.join(",")]);

  const partidas = partidasApi.rows;
  // Solo las activas, en el orden del catálogo. Si la tabla no responde
  // —migración pendiente— se cae al respaldo en vez de quedarse en blanco.
  /* Dirección conoce las zonas agrupadas —Poza Rica, Altamira y Cerro Azul
     son "Zona Norte" para ellos— así que el reporte mensual oficial debe
     hablar en esos términos. El mapa se arma aquí y viaja a Partidas. */
  const gruposZona = {};
  zonasApi.rows
    .filter((z) => z.unidad === unidad || !z.unidad)
    .forEach((z) => { if (z.grupo) gruposZona[String(z.nombre).trim().toLowerCase()] = z.grupo; });

  /* Solo las zonas de la compañía activa. Un selector con las de las tres
     ofrecía lugares donde esa compañía no opera. */
  const zonasDeLaUnidad = zonasApi.rows.filter((z) => z.unidad === unidad || !z.unidad);
  const zonas = zonasDeLaUnidad.length
    ? zonasDeLaUnidad.filter((z) => z.activa !== false)
        .sort((a, b) => (a.orden ?? 999) - (b.orden ?? 999) || String(a.nombre).localeCompare(String(b.nombre)))
        .map((z) => z.nombre)
    : ZONAS_RESPALDO;
  const transacciones = transaccionesApi.rows;
  const ready = proyectosApi.ready && partidasApi.ready && transaccionesApi.ready;

  const TABS = [
    { id: "dashboard", label: "Dashboard" },
    { id: "partidas", label: "Partidas" },
    { id: "transacciones", label: "Transacciones" },
    { id: "reporte", label: "Reporte de Pagos" },
    { id: "reporte-direccion", label: "Reporte Pagos Dirección" },
    { id: "reportes-direccion", label: "Reportes a Dirección" },
    { id: "vehiculos", label: "Vehículos" },
    { id: "solicitudes", label: "Solicitudes" },
    { id: "contratos", label: "Contratos" },
    { id: "catalogo", label: "Catálogo" },
  ];

  if (session === undefined) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: T.bg, fontFamily: T.fontUI, color: T.textFaint, fontSize: 13 }}>
        Cargando…
      </div>
    );
  }
  if (recovery) {
    return <SetNewPasswordScreen onDone={clearRecovery} />;
  }
  /* El formulario público va antes del login: quien entra a levantar una
     solicitud no tiene cuenta, y pedirle una sería el problema que este
     camino evita. Es el único punto donde este módulo toca la raíz de la
     app, y solo agrega una condición. */
  if (typeof window !== "undefined" && /^\/solicitud\/?$/i.test(window.location.pathname)) {
    return <SolicitudPublicaPage />;
  }

  if (!session) {
    return <LoginScreen />;
  }

  return (
    <div style={{ background: T.bg, minHeight: "100%", fontFamily: T.fontUI, color: T.text, padding: 24 }}>
      <style>{`
        * { box-sizing: border-box; }
        table { font-family: ${T.fontUI}; }
        details > summary { list-style: none; }
        details > summary::-webkit-details-marker { display: none; }
        details > summary:before { content: '▸ '; color: ${T.textFaint}; }
        details[open] > summary:before { content: '▾ '; }
        select, input { color-scheme: light; }
        ::selection { background: ${T.accentBg}; }
        table tbody tr:nth-child(even) > td { background-color: ${T.bg}; }
      `}</style>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 22, flexWrap: "wrap", gap: 14 }}>
        <div>
          <div style={{ fontSize: 10.5, color: T.accent, letterSpacing: "0.14em", textTransform: "uppercase", fontFamily: T.fontMono, marginBottom: 4 }}>
            Control de presupuestos · prototipo
          </div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
            <div style={{ fontSize: 24, fontWeight: 700 }}>Panel de gasto</div>
            <details style={{ position: "relative" }}>
              <summary style={{ display: "inline-flex" }}>
                <Pill tone="dim">v{APP_VERSION}</Pill>
              </summary>
              <div style={{
                position: "absolute", top: "calc(100% + 6px)", left: 0, zIndex: 50,
                background: T.panelAlt, border: `1px solid ${T.border}`, borderRadius: 8,
                padding: 12, minWidth: 280, boxShadow: "0 8px 24px rgba(0,0,0,0.4)",
              }}>
                <div style={{ fontSize: 10.5, color: T.textFaint, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 8 }}>Historial de versiones</div>
                {CHANGELOG.map((c) => (
                  <div key={c.v} style={{ display: "flex", gap: 8, fontSize: 11.5, marginBottom: 5 }}>
                    <span style={{ fontFamily: T.fontMono, color: T.accent, minWidth: 44 }}>v{c.v}</span>
                    <span style={{ color: T.textDim }}>{c.desc}</span>
                  </div>
                ))}
              </div>
            </details>
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          <span style={{ fontSize: 11, color: T.textDim }}>Unidad de negocio</span>
          <div style={{ display: "flex", background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, padding: 3 }}>
            {Object.keys(unidades).map((u) => (
              <button
                key={u}
                onClick={() => setUnidad(u)}
                style={{
                  padding: "7px 16px", borderRadius: 6, border: "none", cursor: "pointer",
                  background: unidad === u ? T.accent : "transparent",
                  color: unidad === u ? "#FFFFFF" : T.textDim,
                  fontWeight: 700, fontSize: 12.5, fontFamily: T.fontMono,
                }}
              >
                {u}
              </button>
            ))}
          </div>
        </div>
        <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
          <span style={{ fontSize: 11.5, color: T.textFaint }}>
            {perfilesApi.rows.find((p) => p.id === session.user.id)?.nombre || session.user.email}
          </span>
          <Button variant="ghost" onClick={() => supabase.auth.signOut()}>Cerrar sesión</Button>
        </div>
      </div>

      <div style={{ display: "flex", gap: 4, borderBottom: `1px solid ${T.border}`, marginBottom: 22 }}>
        {TABS.map((t) => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            style={{
              background: "transparent", border: "none", cursor: "pointer",
              padding: "10px 16px", fontSize: 12.5, fontWeight: 600,
              color: tab === t.id ? T.text : T.textFaint,
              borderBottom: tab === t.id ? `2px solid ${T.accent}` : "2px solid transparent",
              marginBottom: -1,
            }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {!ready ? (
        <div style={{ color: T.textDim, fontSize: 13 }}>Cargando datos compartidos…</div>
      ) : (
        <>
          {tab === "dashboard" && <Dashboard unidad={unidad} unidades={unidades} partidas={partidas} transacciones={transacciones} />}
          {tab === "partidas" && <PartidasTab zonas={zonas} gruposZona={gruposZona} unidad={unidad} unidades={unidades} partidas={partidas} partidasApi={partidasApi} perfilesApi={perfilesApi} transacciones={transacciones} transaccionesApi={transaccionesApi} proveedoresApi={proveedoresApi} cuentasApi={cuentasApi} onCrearTransaccion={(seed) => { setSeedTransaccion(seed); setTab("transacciones"); }} />}
          {tab === "transacciones" && <TransaccionesTab zonas={zonas} gruposZona={gruposZona} unidad={unidad} unidades={unidades} partidas={partidas} partidasApi={partidasApi} transacciones={transacciones} transaccionesApi={transaccionesApi} proveedoresApi={proveedoresApi} cuentasApi={cuentasApi} perfilesApi={perfilesApi} notasApi={notasApi} session={session} seedTransaccion={seedTransaccion} onSeedConsumido={() => setSeedTransaccion(null)} />}
          {tab === "reporte" && <ReportePagosTab gruposZona={gruposZona} unidad={unidad} partidas={partidas} transacciones={transacciones} transaccionesApi={transaccionesApi} proveedoresApi={proveedoresApi} cuentasApi={cuentasApi} />}
          {tab === "reporte-direccion" && <ReportePagosDireccionTab unidad={unidad} partidas={partidas} transacciones={transacciones} transaccionesApi={transaccionesApi} proveedoresApi={proveedoresApi} />}
          {tab === "reportes-direccion" && <ReportesDireccionTab unidad={unidad} partidas={partidas} transacciones={transacciones} session={session} gruposZona={gruposZona} />}
          {tab === "vehiculos" && (
            <VehiculosTab
              vehiculos={vehiculosApi.rows}
              vehiculosApi={vehiculosApi}
              mantenimientos={vehMantenimientosApi.rows}
              mantenimientosApi={vehMantenimientosApi}
              ubicaciones={vehUbicacionesApi.rows}
              perfilesApi={perfilesApi}
              unidadesPermitidas={miPerfil?.unidades_permitidas || []}
            />
          )}
          {tab === "solicitudes" && <SolicitudesTab unidad={unidad} session={session} unidades={unidades} proyectos={proyectosApi.rows.filter((p) => p.unidad === unidad || !p.unidad).map((p) => p.nombre).sort()} zonas={zonas.map((z) => (typeof z === "string" ? z : z.nombre))} />}
          {tab === "contratos" && <ContratosTab unidad={unidad} parametrosApi={contratosParametrosApi} provLegalApi={contratosProvLegalApi} provUnidadApi={contratosProvUnidadApi} instrumentosApi={contratosInstrumentosApi} clausulasApi={contratosClausulasApi} session={session} />}
          {tab === "catalogo" && <CatalogoTab key={catalogoVersion} unidad={unidad} unidades={unidades} proyectosApi={proyectosApi} zonasApi={zonasApi} rubrosApi={rubrosApi} categoriasApi={categoriasApi} partidas={partidas} transacciones={transacciones} proveedoresApi={proveedoresApi} cuentasApi={cuentasApi} perfilesApi={perfilesApi} />}
        </>
      )}
    </div>
  );
}